sources["components/button"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Button = {}
Button.__index = Button
Button.__type = "Button"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

function Button.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Button",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        compact = tab.compact or false, -- true when the host is a Row
        locked = properties.locked or properties.Locked or false,

        callback = properties.callback or properties.Callback or function() end,

        -- Cheap destructive-action confirm: the first click just arms it (title flips to a
        -- "Are you sure?" prompt for a moment) and the callback only actually fires on a second
        -- click within confirmWindow seconds. No modal/extra frame needed for a "click twice to
        -- delete" style button.
        doubleClick = properties.doubleClick or properties.DoubleClick or false,
        confirmText = properties.confirmText or properties.ConfirmText or "Click again to confirm",
        _armed = false,
    }, Button)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self.lockIcon = self.window:_buildLockIcon(self.main)
    -- compact mode has no separate self.container - icon/title parent straight to self.interact
    self.prohibitedIcon = self.window:_buildProhibitedIcon(self.container or self.interact)
    self:_applyLocked(false)
    self.window:_wireTooltip(self)

    -- Descriptions don't belong on a compact row element.
    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- how long an armed double-click button waits for its confirming second click before
-- reverting to its normal title
local confirmWindow = 3

-- callback + red error-flash, shared by both layouts. A plain button just runs the callback; a
-- doubleClick button's first click only arms it (see _arm) and returns without calling out -
-- the second click within confirmWindow disarms it and runs the callback like normal.
function Button:_runCallback()
    if self.doubleClick and not self._armed then
        self:_arm()
        return
    end
    if self.doubleClick then
        self:_disarm()
    end
    self.window:_runGuarded(self, self.callback)
end

-- Swaps the title to confirmText and starts the revert timer. Generation-stamped so an earlier
-- arm's delayed revert can't fire late and stomp a disarm/re-arm that happened after it.
function Button:_arm()
    self._armed = true
    self._originalTitle = self.title.Text
    self.title.Text = locale.resolve(self.confirmText)
    self._armGeneration = (self._armGeneration or 0) + 1
    local generation = self._armGeneration
    task.delay(confirmWindow, function()
        if self._armed and self._armGeneration == generation then
            self:_disarm()
        end
    end)
end

function Button:_disarm()
    if not self._armed then
        return
    end
    self._armed = false
    if self._originalTitle then
        self.title.Text = self._originalTitle
        self._originalTitle = nil
    end
end

-- full-width: title/icon left, width-bounce on press
function Button:_buildFull()
    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 43),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        -- Animation
        BackgroundTransparency = 1, -- In = 0

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)

    self.container = self.window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.main,
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.containerLayout = self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            -- Animations
            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),

        Size = UDim2.fromOffset(250, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        -- Animation
        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        TextTransparency = 1,

        Parent = self.main,
    })

    self.window:_wireElementHover(self)

    -- press: ghost the stroke + squeeze the width around the callback
    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        if self.locked then
            return
        end
        hapticEngine.click()
        soundEngine.click()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()
        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -26, 0, 43) }
            )
            :Play()

        self:_runCallback()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -20, 0, 43) }
            )
            :Play()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- compact (row): content-sized, centred icon+title, no width-bounce
function Button:_buildCompact()
    local window = self.window

    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name)
    self.hoverOverlay = self.interact

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 16),
        PaddingRight = UDim.new(0, 16),

        Parent = self.interact,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        Padding = UDim.new(0, 6),

        Parent = self.interact,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.interact,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.interact,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- grows to its text, shrinks + ellipsizes when the row's tight
    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    self.window:_wireElementHover(self)

    -- press: ghost the stroke around the callback
    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        if self.locked then
            return
        end
        hapticEngine.click()
        soundEngine.click()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()

        self:_runCallback()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

function Button:_applyLocked(animate)
    self.window:_applyLockedVisual(self, animate)
end

function Button:SetLocked(locked)
    locked = locked and true or false
    if locked == self.locked then
        return
    end
    self.locked = locked
    self:_applyLocked(true)
end

-- Lock/Unlock/IsLocked: the shared naming lockable.luau gives every other locking-capable
-- element - aliased into this component's own pre-existing SetLocked/padlock-icon dimming
-- rather than the mixin's scrim (see lockable.luau's own header comment). `reason` isn't
-- supported here.
function Button:Lock()
    self:SetLocked(true)
end
function Button:Unlock()
    self:SetLocked(false)
end
function Button:IsLocked(): boolean
    return self.locked == true
end

function Button:_setShown(shown, animate)
    if shown then
        -- _revealCommon is locked-aware (see window.luau) - it already dims title/icon
        -- correctly by itself, no second tween needed to fix it up afterward
        self.window:_revealCommon(self, animate)
    else
        self.window:_hideCommon(self, animate)
    end
end

-- Room the compact button needs before its label would clip: side padding + icon
-- (and its gap) if shown + the title text. A horizontal group uses this to wrap.
function Button:_minWidth()
    local w = 32 -- interact padding, 16 each side
    if self.icon then
        w += 22 -- 16 icon + 6 gap to title
    end
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

-- Live status line - see Toggle:SetStatus's own comment, same reasoning and same reused
-- descriptor slot, just for a button (e.g. "Import" reporting "Imported 12/12" after it runs).
function Button:SetStatus(text)
    if self.compact then
        return -- no room for a status line in a row layout
    end
    if not self.descriptor then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = text })
        self.descriptor.main.LayoutOrder = self.main.LayoutOrder + 1
        if not self.window.hidden then
            self.window:_reveal(self.descriptor.titleLabel, { TextTransparency = 0.7 }, false)
        end
    else
        self.descriptor.description = text
        self.descriptor.titleLabel.Text = text
    end
end

moveable(Button)

return Button
]=====]

sources["components/changelog"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 6: an inline "Update Log" card - a title + version/date header, a divider, then a list
-- of entries each tagged ADDED/FIXED/CHANGED/REMOVED (or any custom tag) in a semantic colour.
-- Static once built (no add/remove API) - it's meant to be authored once per release, the same
-- way the devlog text itself is.

local Changelog = {}
Changelog.__index = Changelog
Changelog.__type = "Changelog"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local moveable = require(utility.moveable)
local locale = require(utility.locale)

-- Semantic tag colours, git-status-log convention: green add, blue fix, amber change, red remove.
-- Kept soft/pastel on purpose - the original fully-saturated set read as neon against the card.
-- A custom tag not in this table falls back to the theme's own accent colour.
local tagColors = {
    ADDED = Color3.fromRGB(125, 209, 155),
    FIXED = Color3.fromRGB(130, 179, 235),
    CHANGED = Color3.fromRGB(230, 178, 110),
    REMOVED = Color3.fromRGB(224, 130, 128),
}

local rowGap = 10
local entryGap = 14
local prefixWidth = 80
local dotSize = 6

function Changelog.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Update Log",
        version = properties.version or properties.Version,
        date = properties.date or properties.Date,
        entries = properties.entries or properties.Entries or {},
    }, Changelog)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)

    self.window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 20),
        PaddingRight = UDim.new(0, 20),
        PaddingTop = UDim.new(0, 16),
        PaddingBottom = UDim.new(0, 16),

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, rowGap),

        Parent = self.main,
    })

    self:_buildHeader()
    self:_buildDivider()
    self._rows = {}
    for index, entry in self.entries do
        self:_buildEntry(entry, index)
    end

    return self
end

function Changelog:_buildHeader()
    local header = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 22),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 1,

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,

        Parent = header,
    })

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 22),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 18,
        TextXAlignment = Enum.TextXAlignment.Left,

        TextTransparency = 1, -- In = 0

        Parent = header,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    if (self.version and self.version ~= "") or (self.date and self.date ~= "") then
        local parts = {}
        if self.version and self.version ~= "" then
            table.insert(parts, self.version)
        end
        if self.date and self.date ~= "" then
            table.insert(parts, self.date)
        end
        self.meta = self.window:Create("TextLabel", {
            Text = locale.t(table.concat(parts, "  \u{00B7}  ")),
            Size = UDim2.fromOffset(0, 16),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 13,
            TextXAlignment = Enum.TextXAlignment.Right,

            TextTransparency = 1, -- In = 0.5

            Parent = header,
        }, { TextColor3 = "PlaceholderColor", FontFace = "Font" })
    end
end

function Changelog:_buildDivider()
    self.divider = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 1),
        BorderSizePixel = 0,
        LayoutOrder = 2,

        BackgroundTransparency = 1, -- In = 0.9

        Parent = self.main,
    }, { BackgroundColor3 = "SurfaceStroke" })
end

-- One row: a fixed-width colour tag left, the description filling the rest. Wraps onto its own
-- height if the description needs more than one line.
function Changelog:_buildEntry(entry, order)
    entry = if typeof(entry) == "table" then entry else { text = tostring(entry) }
    local tag = string.upper(tostring(entry.tag or entry.Tag or ""))
    local color = tagColors[tag] or self.window.theme.AccentColor
    local text = entry.text or entry.Text or entry.description or entry.Description or ""

    local row = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 20),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 2 + order,

        Parent = self.main,
    })

    -- fixed-width prefix so every row's description starts at the same x regardless of how
    -- long its own tag word is - dot + tag flow left inside it via their own mini row
    local prefix = self.window:Create("Frame", {
        Size = UDim2.fromOffset(prefixWidth, 20),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = row,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 6),

        Parent = prefix,
    })

    local dot = self.window:Create("Frame", {
        Size = UDim2.fromOffset(dotSize, dotSize),
        BackgroundColor3 = color,
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- In = 0

        Parent = prefix,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = dot })

    local tagLabel = self.window:Create("TextLabel", {
        Text = locale.t(tag),
        Size = UDim2.fromOffset(0, 20),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 12,
        Font = Enum.Font.GothamBold,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextColor3 = color,

        TextTransparency = 1, -- In = 0

        Parent = prefix,
    })

    local desc = self.window:Create("TextLabel", {
        Text = locale.t(text),
        Position = UDim2.fromOffset(prefixWidth + entryGap, 0),
        Size = UDim2.new(1, -(prefixWidth + entryGap), 0, 20),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 14,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,

        TextTransparency = 1, -- In = 0

        Parent = row,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    table.insert(self._rows, { row = row, dot = dot, tagLabel = tagLabel, desc = desc })
end

function Changelog:_setShown(shown, animate)
    local w = self.window
    w:_reveal(self.stroke, { Transparency = if shown then w.theme.ElementStrokeTransparency else 1 }, animate)
    w:_reveal(self.main, { BackgroundTransparency = if shown then (w.theme.ElementTransparency or 0) else 1 }, animate)
    w:_reveal(self.title, { TextTransparency = if shown then 0 else 1 }, animate)
    if self.meta then
        w:_reveal(self.meta, { TextTransparency = if shown then 0.5 else 1 }, animate)
    end
    w:_reveal(self.divider, { BackgroundTransparency = if shown then 0.9 else 1 }, animate)
    for _, entry in self._rows do
        w:_reveal(entry.dot, { BackgroundTransparency = if shown then 0 else 1 }, animate)
        w:_reveal(entry.tagLabel, { TextTransparency = if shown then 0 else 1 }, animate)
        w:_reveal(entry.desc, { TextTransparency = if shown then 0 else 1 }, animate)
    end
end

moveable(Changelog)

return Changelog
]=====]

sources["components/checkbox"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A compact alternative to Toggle: same flag/config/description contract and the same
-- full/compact scaffolding, just a small check box instead of a pill + knob.

local Checkbox = {}
Checkbox.__index = Checkbox
Checkbox.__type = "Checkbox"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local checkIcon = constants.icons.check
local boxSize = 22

function Checkbox.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Checkbox",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,
        compact = tab.compact or false,

        flag = properties.flag
            or properties.Flag
            or (
                not (properties.forgetState or properties.ForgetState or tab.forgetState)
                    and functions.deriveFlagFromName(properties.name or properties.Name or "Checkbox")
                or nil
            ),

        callback = properties.callback or properties.Callback or function() end,

        value = if (properties.value or properties.Value) ~= nil then (properties.value or properties.Value) else false,
    }, Checkbox)

    self.window:_registerControl(self)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self.window:_wireTooltip(self)

    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- the box + checkmark. same in both layouts; caller places it (pinned right / flex item)
function Checkbox:_buildBox(parent)
    local window = self.window

    self.box = window:Create("Frame", {
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(boxSize, boxSize),
        BackgroundColor3 = self.value and self.window.theme.AccentColor or self.window.theme.ToggleKnobOff,

        BackgroundTransparency = 1, -- In = 0 (checked) / ToggleKnobOffTransparency (unchecked)

        Parent = parent,
    })

    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 6),
        Parent = self.box,
    })

    self.boxStroke = window:Create("UIStroke", {
        Color = self.value and self.window.theme.AccentStroke or Color3.fromRGB(255, 255, 255),
        Transparency = 1, -- In = 0 (checked) / 0.7 (unchecked)
        Parent = self.box,
    })

    -- Accent glow behind the box; hidden until checked
    self.boxGlow = window:CreateGlow(self.box, "AccentColor", 16, 1)

    self.checkIcon = window:Create("ImageLabel", {
        Image = checkIcon,
        Size = UDim2.fromOffset(14, 14),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        ImageColor3 = Color3.fromRGB(255, 255, 255),

        -- Animation: scale-pops in with a check, fades out when unchecked
        ImageTransparency = self.value and 0 or 1,
        Parent = self.box,
    })

    self.checkIconScale = window:Create("UIScale", {
        Scale = self.value and 1 or 0.4,
        Parent = self.checkIcon,
    })

    return self.box
end

-- flip, animate, run callback (error-flash on fail), autosave. press anim is per-layout
function Checkbox:_performCheck()
    hapticEngine.click()
    soundEngine.click()
    self.value = not self.value
    self:_animateBox()

    self.window:_runGuarded(self, self.callback, self.value)
    self.window:_persist(self)
end

-- full-width: title/icon left, box pinned right, width-bounce
function Checkbox:_buildFull()
    local window = self.window

    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 41),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)
    self.hoverOverlay = window:CreateHoverOverlay(self.main)

    self.container = window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.main,
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.containerLayout = window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(250, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.interact = window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 1, 0),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(1, 0.5),
        AnchorPoint = Vector2.new(1, 0.5),
        TextTransparency = 1,
        ZIndex = 10,

        Parent = self.main,
    })

    -- box pinned to the right edge
    self:_buildBox(self.main)
    self.box.Position = UDim2.new(1, -20, 0, 20)
    self.box.AnchorPoint = Vector2.new(1, 0.5)

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()
        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -26, 0, 41) }
            )
            :Play()

        self:_performCheck()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -20, 0, 41) }
            )
            :Play()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- compact (row): title left, box right (SpaceBetween)
function Checkbox:_buildCompact()
    local window = self.window

    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name, 10)
    self.hoverOverlay = self.interact

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 15),
        PaddingRight = UDim.new(0, 15),

        Parent = self.interact,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,
        Padding = UDim.new(0, 10),

        Parent = self.interact,
    })

    self.container = window:Create("Frame", {
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 0,

        Parent = self.interact,
    })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.container,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    self:_buildBox(self.interact)
    self.box.LayoutOrder = 1

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()

        self:_performCheck()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- checked pops with a slight overshoot; unchecked settles back flat
local checkPopIn = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local checkFadeOut = TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local boxColorInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

function Checkbox:_animateBox()
    local ts = variables.tweenService
    if self.boxGlow then
        ts:Create(self.boxGlow, boxColorInfo, { Transparency = self.value and self.window.theme.AccentGlow or 1 })
            :Play()
    end
    if self.value then
        ts:Create(self.box, boxColorInfo, {
            BackgroundColor3 = self.window.theme.AccentColor,
            BackgroundTransparency = 0,
        }):Play()
        ts:Create(self.boxStroke, boxColorInfo, { Color = self.window.theme.AccentStroke, Transparency = 0 }):Play()
        ts:Create(self.checkIcon, checkPopIn, { ImageTransparency = 0 }):Play()
        ts:Create(self.checkIconScale, checkPopIn, { Scale = 1 }):Play()
    else
        ts:Create(self.box, boxColorInfo, {
            BackgroundColor3 = self.window.theme.ToggleKnobOff,
            BackgroundTransparency = self.window.theme.ToggleKnobOffTransparency,
        }):Play()
        ts:Create(self.boxStroke, boxColorInfo, { Color = Color3.fromRGB(255, 255, 255), Transparency = 0.7 }):Play()
        ts:Create(self.checkIcon, checkFadeOut, { ImageTransparency = 1 }):Play()
        ts:Create(self.checkIconScale, checkFadeOut, { Scale = 0.4 }):Play()
    end
end

local checkboxReveal = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local checkboxGlowReveal = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out, 0, false, 0.35)
-- Live-caught: same ordering fix as toggle.luau's own toggleStateReveal - the box's checked-state
-- colour/checkmark faded in on the same beat as the row it sits on, so it could read as "there"
-- before the row itself looked like a real card yet. Delayed after the row (checkboxReveal via
-- _revealCommon, no delay) but before the glow (checkboxGlowReveal, 0.35s).
local checkboxStateReveal = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out, 0, false, 0.12)

function Checkbox:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.box, {
            BackgroundColor3 = self.value and w.theme.AccentColor or w.theme.ToggleKnobOff,
            BackgroundTransparency = self.value and 0 or w.theme.ToggleKnobOffTransparency,
        }, animate, checkboxStateReveal)
        w:_reveal(self.boxStroke, {
            Color = self.value and w.theme.AccentStroke or Color3.fromRGB(255, 255, 255),
            Transparency = self.value and 0 or 0.7,
        }, animate, checkboxStateReveal)
        w:_reveal(self.boxGlow, { Transparency = self.value and w.theme.AccentGlow or 1 }, animate, checkboxGlowReveal)
        w:_reveal(self.checkIcon, { ImageTransparency = self.value and 0 or 1 }, animate, checkboxStateReveal)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.box, { BackgroundTransparency = 1 }, animate, checkboxReveal)
        w:_reveal(self.boxStroke, { Transparency = 1 }, animate, checkboxReveal)
        w:_reveal(self.boxGlow, { Transparency = 1 }, animate, checkboxGlowReveal)
        w:_reveal(self.checkIcon, { ImageTransparency = 1 }, animate, checkboxReveal)
    end
end

-- Re-apply the visuals that aren't plain themeProperties, so a runtime ChangeTheme reaches
-- the box. Called on the visible tab only.
function Checkbox:_refreshTheme()
    local t = self.window.theme
    local info = TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local ts = variables.tweenService
    ts:Create(self.box, info, {
        BackgroundColor3 = self.value and t.AccentColor or t.ToggleKnobOff,
        BackgroundTransparency = self.value and 0 or t.ToggleKnobOffTransparency,
    }):Play()
    ts:Create(self.boxStroke, info, {
        Color = self.value and t.AccentStroke or Color3.fromRGB(255, 255, 255),
    }):Play()
    if self.boxGlow then
        ts:Create(self.boxGlow, info, { Transparency = self.value and t.AccentGlow or 1 }):Play()
    end
end

-- Room the compact checkbox needs: side padding + icon (and gap) if shown + title text
-- + the gap to the box + the box itself. Lets a horizontal group wrap sensibly.
function Checkbox:_minWidth()
    local w = 30 + 10 + boxSize -- 15+15 padding, 10 gap to box, box itself
    if self.icon then
        w += 21 -- 16 icon + 5 gap
    end
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

moveable(Checkbox)
lockable(Checkbox)

function Checkbox:Set(value, skipCallback)
    local changed = self.value ~= value
    self.value = value

    if changed then
        self:_animateBox()
    end

    -- fire even when unchanged: config load calls Set and relies on the callback to apply
    if not skipCallback then
        self.window:_runGuarded(self, self.callback, self.value)
        self.window:_persist(self)
    end
end

return Checkbox
]=====]

sources["components/chrome"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Window furniture: the collapsed "Show" face main wears while hidden (window.collapsed*
-- fields), plus the first-open new-user check. The welcome greeting itself is just a toast now.

local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local filesystem = require(utility.filesystem)
local constants = require(utility.constants)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local chrome = {}

local collapsedDragThreshold = 6

-- Same half-extent clamp _clampedPosition (windowMethods.luau) uses for a real drag, just
-- against the pill's own current AbsoluteSize instead of the full window's self.size - main is
-- tiny while collapsed, so clamping against the expanded window's own half-extents would either
-- refuse to let the pill reach the real screen edges or let it hang off them, depending on which
-- is bigger.
local function clampCollapsedPosition(window, position: UDim2): UDim2
    if not (window.settings and window.settings.keepOnScreen) then
        return position
    end
    if position.X.Scale ~= 0 or position.Y.Scale ~= 0 then
        return position -- on-scale positions recentre on their own; nothing to clamp
    end
    local size = window.main.AbsoluteSize
    local screen = window.screenGui.AbsoluteSize
    local margin = 8
    local halfX, halfY = size.X / 2, size.Y / 2
    local x = math.clamp(position.X.Offset, halfX + margin, math.max(halfX + margin, screen.X - halfX - margin))
    local y = math.clamp(position.Y.Offset, halfY + margin, math.max(halfY + margin, screen.Y - halfY - margin))
    return UDim2.fromOffset(x, y)
end

-- Drag the collapsed pill around the screen (e.g. out from under something else on screen it
-- happens to land on) - a plain tap still restores the window; a real drag doesn't also fire
-- that. MouseButton1Click alone can't tell those apart (Roblox fires it on any mouse-up over the
-- button regardless of movement in between), so this tracks the raw input itself and only calls
-- ToggleHide() when the pointer never moved past a small threshold - the same click-vs-drag
-- shape a real drag handle would use, just with the "was this actually a drag" check added on
-- top.
local function wireCollapsedDrag(window)
    local uis = variables.userInputService
    local dragging, dragged = false, false
    local startMouse, startMainPos = Vector2.zero, UDim2.new()

    window:Connect(window.collapsedInteract.InputBegan, function(input, processed)
        if processed then
            return
        end
        local t = input.UserInputType
        if t ~= Enum.UserInputType.MouseButton1 and t ~= Enum.UserInputType.Touch then
            return
        end
        dragging = true
        dragged = false
        startMouse = uis:GetMouseLocation()
        startMainPos = window.main.Position
    end)

    window:Connect(variables.runService.RenderStepped, function()
        if not dragging then
            return
        end
        local delta = uis:GetMouseLocation() - startMouse
        if not dragged and delta.Magnitude > collapsedDragThreshold then
            dragged = true
        end
        if dragged then
            local target = UDim2.new(
                startMainPos.X.Scale,
                startMainPos.X.Offset + delta.X,
                startMainPos.Y.Scale,
                startMainPos.Y.Offset + delta.Y
            )
            window.main.Position = clampCollapsedPosition(window, target)
        end
    end)

    local function release(input)
        local t = input.UserInputType
        if t ~= Enum.UserInputType.MouseButton1 and t ~= Enum.UserInputType.Touch then
            return
        end
        if not dragging then
            return
        end
        dragging = false
        if dragged then
            -- the pill actually moved: Show() grows the window back from here, not from
            -- wherever it sat before it was ever collapsed (see Window:Hide's own
            -- _restorePosition capture) - otherwise reopening would visibly teleport the window
            -- away from the pill the player just moved it to.
            window._restorePosition = window.main.Position
            window:_syncDragBar()
        else
            hapticEngine.click()
            soundEngine.click()
            window:ToggleHide()
        end
    end
    window:Connect(uis.InputEnded, release)
    window:Connect(uis.WindowFocusReleased, function()
        dragging = false
    end)
end

-- The face main wears once collapsed: an icon + "name"/"Tap to show", drawn straight onto
-- the window frame itself. main already carries the pill's background (its own WindowColor
-- gradient reads the same as the old standalone pill), so shrinking main IS becoming the
-- pill - nothing to hand off to, nothing to swap.
function chrome.buildCollapsedFace(window)
    window.collapsedIcon = window:Create("ImageLabel", {
        Name = "CollapsedIcon",
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.new(0, 16, 0.5, 0),
        Size = UDim2.fromOffset(24, 24),
        BackgroundTransparency = 1,
        -- raw value: Create routes Image through image.resolve (concat would double the prefix)
        Image = window.showIcon,
        ZIndex = constants.zIndex.restoreContent,

        ImageTransparency = 1, -- shown = 0, set by chrome.setCollapsedShown

        Parent = window.main,
    }, { ImageColor3 = "TitlingColor" })

    window:Create("UICorner", {
        Parent = window.collapsedIcon,
    }, { CornerRadius = "PillCornerRadius" })

    local textContainer = window:Create("Frame", {
        Name = "CollapsedText",
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.new(0, 50, 0.5, 0),
        Size = UDim2.new(1, -60, 0, 32),
        BackgroundTransparency = 1,
        ZIndex = constants.zIndex.restoreContent,

        Parent = window.main,
    })

    window:Create("UIListLayout", {
        Padding = UDim.new(0, 1),
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = textContainer,
    })

    window.collapsedTitle = window:Create("TextLabel", {
        Name = "Title",
        Text = window.showName,
        Size = UDim2.new(1, 0, 0, 16),
        BackgroundTransparency = 1,
        FontFace = variables.brandFont(Enum.FontWeight.Medium),
        RichText = true,
        TextSize = 16,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 1,
        ZIndex = constants.zIndex.restoreContent,

        TextTransparency = 1, -- shown = 0, set by chrome.setCollapsedShown

        Parent = textContainer,
    }, { TextColor3 = "TitlingColor" })

    window.collapsedSubtitle = window:Create("TextLabel", {
        Name = "Subtitle",
        Text = locale.t("Tap to show"),
        Size = UDim2.new(1, 0, 0, 14),
        BackgroundTransparency = 1,
        FontFace = variables.brandFont(Enum.FontWeight.Medium),
        TextSize = 14,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 2,
        ZIndex = constants.zIndex.restoreContent,

        TextTransparency = 1, -- shown = 0.5, set by chrome.setCollapsedShown

        Parent = textContainer,
    }, { TextColor3 = "TitlingColor" })

    -- covers the whole window but only takes clicks while collapsed - Window:Hide/Show flip
    -- Visible as the morph starts/settles so it can never eat a click mid-animation or while
    -- the window is fully open. Active alone doesn't stop a GuiButton from still receiving
    -- clicks here, so Visible is what actually keeps it out of hit-testing.
    window.collapsedInteract = window:Create("TextButton", {
        Name = "CollapsedInteract",
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        Text = "",
        TextTransparency = 1,
        Visible = false,
        ZIndex = constants.zIndex.restoreInteract,

        Parent = window.main,
    })

    -- Drag the collapsed pill around the screen (e.g. out from under something else on screen
    -- it happens to land on) - a plain tap still restores the window; a real drag doesn't also
    -- fire that. MouseButton1Click alone can't tell those apart (Roblox fires it on any
    -- mouse-up over the button regardless of movement in between), so this tracks the raw
    -- input itself and only calls ToggleHide() when the pointer never moved past a small
    -- threshold - the same click-vs-drag shape a real drag handle would use, just with the
    -- "was this actually a drag" check added on top.
    wireCollapsedDrag(window)
end

function chrome.isNewUser()
    local localPlayer = variables.localPlayer
    if not localPlayer then
        return false
    end

    -- No filesystem available - just show the banner every launch.
    if typeof(filesystem.isfile) ~= "function" or typeof(filesystem.writefile) ~= "function" then
        return true
    end

    local path = variables.fileSystemManager:getPath("lastuser.txt")
    local currentId = tostring(localPlayer.UserId)
    local isNew = true

    pcall(function()
        if filesystem.isfile(path) then
            isNew = filesystem.readfile(path) ~= currentId
        end
    end)

    pcall(function()
        filesystem.writefile(path, currentId)
    end)

    return isNew
end

-- Fade the collapsed face (icon + labels) in or out as main morphs into/out of the pill.
-- When tweenInfo is nil the values snap instantly.
function chrome.setCollapsedShown(window, shown, tweenInfo)
    local targets = {
        [window.collapsedIcon] = { ImageTransparency = if shown then 0 else 1 },
        [window.collapsedTitle] = { TextTransparency = if shown then 0 else 1 },
        [window.collapsedSubtitle] = { TextTransparency = if shown then 0.5 else 1 },
    }

    for instance, props in targets do
        if tweenInfo then
            variables.tweenService:Create(instance, tweenInfo, props):Play()
        else
            for property, value in props do
                instance[property] = value
            end
        end
    end
end

return chrome
]=====]

sources["components/collapsible"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 6: a clickable header (title + a chevron that rotates) that expands to reveal its own
-- children, collapsing their height smoothly instead of a hard cut. Doesn't reimplement element
-- building itself - it hosts an internal column Group (group.luau) and forwards every CreateX
-- call to it, exposing the same Tab-like surface (window/tabPage/elements/compact/direction)
-- Group itself expects from its own host. tabPage points at this collapsible's own inner frame,
-- so the group's normal full-width column just becomes this section's expandable content.

local Collapsible = {}
Collapsible.__index = Collapsible
Collapsible.__type = "Collapsible"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local moveable = require(utility.moveable)
local locale = require(utility.locale)
local constants = require(utility.constants)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local heightInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
local chevronInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)

local headerHeight = 43

-- breathing room around the nested group: without it, the first child sits glued to the header
-- and the last one gets squeezed against the clip's bottom edge the instant the section opens
local contentPadTop = 8
local contentPadBottom = 8

function Collapsible.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Section",
        icon = properties.icon or properties.Icon,
        forgetState = tab.forgetState,
        compact = false,
        direction = nil,
        elements = {}, -- the inner group's own elements list (Group fills this in)

        expanded = if properties.expanded ~= nil
            then properties.expanded
            elseif properties.Expanded ~= nil then properties.Expanded
            else false,
    }, Collapsible)

    -- the -20 inset happens once here (matches every other tabPage-level card, e.g.
    -- colorpicker.luau's own outer main) - header/contentWrapper below are full width of this.
    -- No AutomaticSize here on purpose: confirmed live that main's AutomaticSize.Y doesn't
    -- reliably follow a *tweened* child Size change on this executor (same class of bug as
    -- UIListLayout never writing back a tweened child's Position) - main sat stuck at whatever
    -- height it last was, collapsed or not, leaving dead space below the header forever. main's
    -- own height is driven explicitly instead, in lockstep with contentWrapper's, by _setHeight
    -- below - every call site that used to resize just contentWrapper resizes both together now.
    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, headerHeight),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Name = self.name,

        Parent = self.tab.tabPage,
    })

    self:_buildHeader()

    -- content: clips so the collapse never shows a half-cut child, height tweens between 0 and
    -- the inner group's own real AbsoluteSize.Y
    self.contentWrapper = self.window:Create("Frame", {
        Position = UDim2.fromOffset(0, headerHeight),
        Size = UDim2.new(1, 0, 0, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ClipsDescendants = true,

        Parent = self.main,
    })

    self.window:Create("UIPadding", {
        PaddingTop = UDim.new(0, contentPadTop),
        PaddingBottom = UDim.new(0, contentPadBottom),

        Parent = self.contentWrapper,
    })

    self.tabPage = self.contentWrapper

    -- children build through here - see file header. Requiring by relative path (not a name
    -- string) since this isn't Group's own _add dispatch table.
    self._group = require(script.Parent.group).new(self, { direction = "column" })

    self.window:ConnectFor(self, self._group.main:GetPropertyChangedSignal("AbsoluteSize"), function()
        if self.expanded then
            self:_setHeight(self:_contentHeight(), true)
        end
    end)

    -- start at the right height instantly - no animating in from 0 on first build
    if self.expanded then
        self:_setHeight(self:_contentHeight(), false)
        self.chevron.Rotation = 0
    end

    -- Tracked per-window (same shape as window.tabs) so the guided tour can find whichever
    -- collapsible actually owns a step's target and force it open - see tour.luau's own
    -- expandAncestors. No corresponding removal on teardown: nothing in this file destroys a
    -- Collapsible outright today, matching that this list is only ever appended to for the same
    -- reason window.tabs itself doesn't need pruning until Tab:Remove exists on this too.
    self.window.collapsibles = self.window.collapsibles or {}
    table.insert(self.window.collapsibles, self)

    return self
end

-- the group's own real height plus the breathing room above/below it (UIPadding doesn't count
-- toward a sibling's AbsoluteSize, so it has to be added back in by hand here)
function Collapsible:_contentHeight()
    return self._group.main.AbsoluteSize.Y + contentPadTop + contentPadBottom
end

-- Drives contentWrapper's height AND main's own height together (see the comment on self.main's
-- own Create() call above for why main can't just auto-follow this itself). targetContentHeight
-- is contentWrapper's own target - main's is headerHeight taller, header + content stacked.
function Collapsible:_setHeight(targetContentHeight, animate)
    local contentSize = UDim2.new(1, 0, 0, targetContentHeight)
    local mainSize = UDim2.new(1, -20, 0, headerHeight + targetContentHeight)
    if animate then
        variables.tweenService:Create(self.contentWrapper, heightInfo, { Size = contentSize }):Play()
        variables.tweenService:Create(self.main, heightInfo, { Size = mainSize }):Play()
    else
        self.contentWrapper.Size = contentSize
        self.main.Size = mainSize
    end
end

function Collapsible:_buildHeader()
    self.header = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 43),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.main,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.header)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.header)

    self.container = self.window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.header,
        Size = UDim2.new(1, -70, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- chevron: 180deg = closed (matches dropdown.luau's own convention), tweens to 0 on open
    self.chevron = self.window:Create("ImageLabel", {
        Image = constants.icons.chevron,
        Size = UDim2.fromOffset(12, 12),
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -20, 0.5, 0),
        Rotation = 180,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,

        ImageTransparency = 1, -- In = 0.4

        Parent = self.header,
    }, { ImageColor3 = "ContentColor" })

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Text = "",
        AutoButtonColor = false,
        ZIndex = 10,

        Parent = self.header,
    })

    self.window:_wireElementHover({ main = self.header, stroke = self.stroke, title = self.title, hoverOverlay = self.hoverOverlay })

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        self:Toggle()
    end)
end

function Collapsible:Toggle()
    self:SetExpanded(not self.expanded)
end

-- skipAnimation: snap straight to the target height/chevron angle instead of tweening - the
-- guided tour uses this (see tour.luau's own expandAncestors) to force a closed section open
-- without its own 0.3s motion competing with the tour's ring/bubble reveal for attention.
function Collapsible:SetExpanded(expanded, skipAnimation: boolean?)
    expanded = expanded and true or false
    if expanded == self.expanded then
        return
    end
    self.expanded = expanded

    self:_setHeight(if expanded then self:_contentHeight() else 0, not skipAnimation)
    if skipAnimation then
        self.chevron.Rotation = if expanded then 0 else 180
    else
        variables.tweenService:Create(self.chevron, chevronInfo, { Rotation = if expanded then 0 else 180 }):Play()
    end
end

-- Forward every CreateX to the inner column group, so a Collapsible reads exactly like a Tab
-- or Group to a dev using it. Kept in sync with Group's own CreateX list (see group.luau) -
-- anything Group can host, a Collapsible's own content column can too, since it's just another
-- Group underneath.
for _, name in {
    "CreateButton", "CreateFlipButton", "CreateCopyButton", "CreateRippleButton", "CreateToggle",
    "CreateSwitch", "CreateCheckbox", "CreateStat", "CreateStatusCard", "CreateSlider", "CreateDropdown", "CreateSection",
    "CreateLabel", "CreateParagraph", "CreateDivider", "CreateGroup", "CreateProgressBar",
    "CreateScrollHint", "CreateSegmentedPicker", "CreateShimmerLabel", "CreateInput", "CreateKeybind",
    "CreateColorPicker", "CreateGradientPicker", "CreateHoldButton", "CreateChangelog", "CreateSpacer",
    "CreateTabbox", "CreateConsole",
} do
    Collapsible[name] = function(self, properties)
        return self._group[name](self._group, properties)
    end
end

function Collapsible:_setShown(shown, animate)
    local w = self.window
    local proxy = { stroke = self.stroke, title = self.title, main = self.header, iconLabel = self.iconLabel }
    if shown then
        w:_revealCommon(proxy, animate)
        w:_reveal(self.chevron, { ImageTransparency = 0.4 }, animate)
    else
        w:_hideCommon(proxy, animate)
        w:_reveal(self.chevron, { ImageTransparency = 1 }, animate)
    end
    self._group:_setShown(shown, animate)
end

function Collapsible:_refreshTheme()
    self._group:_refreshTheme()
end

moveable(Collapsible)

return Collapsible
]=====]

sources["components/colorpicker"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 5 rebuild: a collapsed header row (name + a live colour swatch pill) that taps open
-- into a hex field, RGB number boxes, a big swatch bar and quick-pick presets on the left, and a
-- Saturation/Value square + horizontal Hue rail (hsvEditor.luau, shared with GradientPicker) on
-- the right - same open/close shape as GradientPicker so the two pickers behave identically.
-- Reflows to a single stacked column under narrowWidth.

local ColorPicker = {}
ColorPicker.__index = ColorPicker
ColorPicker.__type = "ColorPicker"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local hsvEditor = require(utility.hsvEditor)

local headerHeight = 44
local squareSize = 150
local rowGap = 8
local narrowWidth = 380
local glowOnTransparency = 0.55

local fadeInfo = TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
-- closing fades faster than it opens, and faster than the card shrinks, so the content is
-- gone before (or right as) the height tween finishes instead of visibly cutting off mid-fade
local closeFadeInfo = TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
-- closing height: Quart out, quick and clean, no overshoot
local heightInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
-- opening height: Back out - grows slightly past the final height then eases back, matching
-- GradientPicker's own open bounce
local heightOpenInfo = TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local chevronInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
-- header swatch "pop" on click
local popOutInfo = TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local popBackInfo = TweenInfo.new(0.28, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
-- glow pulse on open: flashes brighter than the steady-state glow, then relaxes back down to it
local glowPulseInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local glowRelaxInfo = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
-- delay between each staggered reveal group when opening
local staggerStep = 0.05
local swatchSize = UDim2.fromOffset(40, 22)

local function clampByte(n)
    return math.clamp(math.round(n), 0, 255)
end

local function clamp01(n)
    return math.clamp(n, 0, 1)
end

-- named colours accepted by the smart hex field
local namedColors = {
    black = Color3.fromRGB(0, 0, 0),
    white = Color3.fromRGB(255, 255, 255),
    red = Color3.fromRGB(255, 0, 0),
    green = Color3.fromRGB(0, 255, 0),
    blue = Color3.fromRGB(0, 0, 255),
    yellow = Color3.fromRGB(255, 255, 0),
    cyan = Color3.fromRGB(0, 255, 255),
    magenta = Color3.fromRGB(255, 0, 255),
    orange = Color3.fromRGB(255, 165, 0),
    purple = Color3.fromRGB(128, 0, 128),
    pink = Color3.fromRGB(255, 105, 180),
    brown = Color3.fromRGB(139, 69, 19),
    gray = Color3.fromRGB(128, 128, 128),
    grey = Color3.fromRGB(128, 128, 128),
}

local function numbersIn(s)
    local out = {}
    for n in s:gmatch("[%d%.]+") do
        table.insert(out, tonumber(n))
    end
    return out
end

-- Smart, forgiving colour parse: hex (#fff, ffffff, 0xffffff), rgb("255,0,0"), 0..1 float
-- triplets, or a named colour. Returns a Color3 or nil.
local function parseColor(input)
    if typeof(input) ~= "string" then
        return nil
    end
    local s = (input:lower():match("^%s*(.-)%s*$")) or ""
    if s == "" then
        return nil
    end

    if namedColors[s] then
        return namedColors[s]
    end

    local model = s:match("^(%a+)")
    local nums = numbersIn(s)

    if (model == "rgb" or model == "rgba") and #nums >= 3 then
        return Color3.fromRGB(clampByte(nums[1]), clampByte(nums[2]), clampByte(nums[3]))
    end

    local hex = s:match("^#?(%x%x%x%x%x%x)$") or s:match("^#?(%x%x%x)$") or s:match("^0x(%x%x%x%x%x%x)$")
    if hex then
        local ok, color = pcall(Color3.fromHex, hex)
        if ok then
            return color
        end
    end

    if #nums >= 3 and not model then
        if nums[1] <= 1 and nums[2] <= 1 and nums[3] <= 1 then
            return Color3.new(clamp01(nums[1]), clamp01(nums[2]), clamp01(nums[3]))
        end
        return Color3.fromRGB(clampByte(nums[1]), clampByte(nums[2]), clampByte(nums[3]))
    end

    return nil
end

local function coerceColor(value, fallback)
    if typeof(value) == "Color3" then
        return value
    end
    if typeof(value) == "string" then
        return parseColor(value) or fallback
    end
    return fallback
end

local defaultPresets = {
    Color3.fromRGB(255, 255, 255),
    Color3.fromRGB(255, 59, 48),
    Color3.fromRGB(255, 149, 0),
    Color3.fromRGB(255, 214, 10),
    Color3.fromRGB(52, 199, 89),
    Color3.fromRGB(10, 132, 255),
    Color3.fromRGB(175, 82, 222),
}

function ColorPicker.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Color Picker",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,
        presets = properties.presets or properties.Presets or defaultPresets,

        callback = properties.callback or properties.Callback or function() end,

        _isOpen = false,
        showGlow = if properties.glow ~= nil
            then properties.glow
            elseif properties.Glow ~= nil then properties.Glow
            else true,
    }, ColorPicker)

    self.value = coerceColor(
        properties.color or properties.Color or properties.value or properties.Value or properties.default,
        Color3.fromRGB(255, 255, 255)
    )
    self.hue, self.sat, self.val = self.value:ToHSV()

    local a = properties.alpha or properties.Alpha
    self.alpha = if type(a) == "number" then clamp01(a) else 1

    self.flag = properties.flag
        or properties.Flag
        or (not self.forgetState and functions.deriveFlagFromName(self.name) or nil)
    self.window:_registerControl(self)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, headerHeight),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)
    self.previewGlow = self.window:CreateGlow(self.main, self.value, 26, 1) -- In = glowOnTransparency (if showGlow)

    self:_buildHeader()
    self:_buildBody()

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        self:_popSwatch()
        if self._isOpen then
            self:_close()
        else
            self:_open()
        end
    end)

    self.window:ConnectFor(self, self.main.MouseEnter, function()
        if self._isOpen or not self.window:_interactive() then
            return
        end
        local theme = self.window.theme
        variables.tweenService
            :Create(self.stroke, fadeInfo, { Transparency = theme.ElementStrokeHoverTransparency, Color = theme.ElementStrokeHover })
            :Play()
        variables.tweenService:Create(self.title, fadeInfo, { TextColor3 = theme.ElementTextHoverColor }):Play()
        variables.tweenService:Create(self.hoverOverlay, fadeInfo, { BackgroundTransparency = 0.97 }):Play()
    end)

    self.window:ConnectFor(self, self.main.MouseLeave, function()
        local theme = self.window.theme
        variables.tweenService
            :Create(self.stroke, fadeInfo, { Transparency = theme.ElementStrokeTransparency, Color = theme.ElementStroke })
            :Play()
        variables.tweenService:Create(self.title, fadeInfo, { TextColor3 = theme.ContentColor }):Play()
        variables.tweenService:Create(self.hoverOverlay, fadeInfo, { BackgroundTransparency = 1 }):Play()
    end)

    self.window:ConnectFor(self, self.main:GetPropertyChangedSignal("AbsoluteSize"), function()
        if self.window.animating or (self.window.hidden and self.window.hasShownOnce) then
            return
        end
        self:_applyLayout()
    end)
    self:_applyLayout()

    self.window:_wireTooltip(self)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    self:_applyBodyVisibility(false, false)
    self:_setControlsVisible(false)

    self:_render("instant")

    return self
end

function ColorPicker:_buildHeader()
    local container = self.window:Create("Frame", {
        Size = UDim2.new(1, -90, 0, 16),
        Position = UDim2.new(0, 20, 0, headerHeight / 2),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ZIndex = 5,

            ImageTransparency = 1, -- In = 0

            Parent = container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 1,
        ZIndex = 5,

        TextTransparency = 1, -- In = 0

        Parent = container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- small always-on colour pill in the header, live even while collapsed - mirrors
    -- GradientPicker's header swatch so both pickers read the same way at a glance
    self.swatch = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -16, 0, headerHeight / 2),
        Size = swatchSize,
        BackgroundColor3 = self.value,
        BorderSizePixel = 0,
        ZIndex = 3,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = self.swatch })

    -- chevron: 180deg = closed (matches dropdown.luau's own convention), tweens to 0 on open
    self.chevron = self.window:Create("ImageLabel", {
        Image = constants.icons.chevron,
        Size = UDim2.fromOffset(12, 12),
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -64, 0, headerHeight / 2),
        Rotation = 180,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        ZIndex = 3,

        ImageTransparency = 1, -- In = 0.4

        Parent = self.main,
    }, { ImageColor3 = "ContentColor" })

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, headerHeight),
        BorderSizePixel = 0,
        Text = "",
        AutoButtonColor = false,
        ZIndex = 10,

        Parent = self.main,
    })
end

-- A small rounded field: an optional single-letter label (R/G/B) left, a TextBox filling the
-- rest. Used for the hex box (no label) and the three RGB channel boxes.
function ColorPicker:_buildField(label, placeholder)
    local box = self.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 34),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 2,

        BackgroundTransparency = 1, -- Open = 0.85

        Parent = self.main,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = box })
    local stroke = self.window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),

        Transparency = 1, -- Open = 0.75

        Parent = box,
    })

    local padLeft = if label then 30 else 12
    local input = self.window:Create("TextBox", {
        PlaceholderText = placeholder or "",
        Size = UDim2.new(1, -(padLeft + 10), 1, 0),
        Position = UDim2.new(0, padLeft, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        ClearTextOnFocus = false,
        ZIndex = 3,

        TextTransparency = 1, -- Open = 0

        Parent = box,
    }, { TextColor3 = "ContentColor", FontFace = "Font", PlaceholderColor3 = "PlaceholderColor" })

    local text = nil
    if label then
        text = self.window:Create("TextLabel", {
            Text = label,
            Size = UDim2.fromOffset(16, 34),
            Position = UDim2.new(0, 10, 0.5, 0),
            AnchorPoint = Vector2.new(0, 0.5),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 13,
            ZIndex = 3,

            TextTransparency = 1, -- Open = 0.4

            Parent = box,
        }, { TextColor3 = "PlaceholderColor", FontFace = "Font" })
    end

    return box, input, stroke, text
end

function ColorPicker:_buildBody()
    -- hex field
    self.hexBox, self.hexInput, self.hexBoxStroke = self:_buildField(nil, "Hex")
    self.hexInput.Text = "#" .. self.value:ToHex():upper()
    self.hexInput.TextXAlignment = Enum.TextXAlignment.Center

    -- RGB row: three equal fields sharing one flex-filled row
    self.rgbRow = self.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 34),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 2,

        Parent = self.main,
    })
    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        HorizontalFlex = Enum.UIFlexAlignment.Fill,
        Padding = UDim.new(0, 8),

        Parent = self.rgbRow,
    })

    self.rBox, self.rInput, self.rBoxStroke, self.rBoxText = self:_buildRgbField("R")
    self.gBox, self.gInput, self.gBoxStroke, self.gBoxText = self:_buildRgbField("G")
    self.bBox, self.bInput, self.bBoxStroke, self.bBoxText = self:_buildRgbField("B")

    -- big live swatch bar
    self.swatchBar = self.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 34),
        BackgroundColor3 = self.value,
        BorderSizePixel = 0,
        ZIndex = 2,

        BackgroundTransparency = 1, -- Open = 0

        Parent = self.main,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = self.swatchBar })

    -- preset swatches row
    self.presetsRow = self.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 26),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 2,

        Parent = self.main,
    })
    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 8),

        Parent = self.presetsRow,
    })

    self.presetButtons = {}
    for _, color in self.presets do
        local dot = self.window:Create("TextButton", {
            Size = UDim2.fromOffset(26, 26),
            BackgroundColor3 = color,
            BorderSizePixel = 0,
            Text = "",
            AutoButtonColor = false,
            ZIndex = 2,

            BackgroundTransparency = 1, -- Open = 0

            Parent = self.presetsRow,
        })
        self.window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = dot })
        local ring = self.window:Create("UIStroke", {
            Color = Color3.fromRGB(255, 255, 255),
            Thickness = 2,
            Transparency = 1, -- managed by _render (selection ring), forced shut while closed

            Parent = dot,
        })
        table.insert(self.presetButtons, { color = color, dot = dot, ring = ring })

        self.window:ConnectFor(self, dot.MouseButton1Click, function()
            hapticEngine.click()
            soundEngine.click()
            self:Set(color)
            self.window:_persist(self)
        end)
    end

    -- shared HSV editor, right column
    self.hsv = hsvEditor.build(self.window, self, self.main, {
        squareSize = squareSize,
        hueHeight = 14,
        gap = 14,
        hue = self.hue,
        sat = self.sat,
        val = self.val,
        onChange = function(h, s, v)
            self.hue, self.sat, self.val = h, s, v
            self.value = Color3.fromHSV(h, s, v)
            self:_render("drag")
            self:_fireCallback()
        end,
        onCommit = function()
            self.window:_persist(self)
        end,
    })

    self.window:ConnectFor(self, self.hexInput.FocusLost, function()
        local color = parseColor(self.hexInput.Text)
        if color then
            self:Set(color)
            self.window:_persist(self)
        else
            self.hexInput.Text = "#" .. self.value:ToHex():upper()
        end
    end)

    local function commitRgb()
        local r = tonumber(self.rInput.Text) or self.value.R * 255
        local g = tonumber(self.gInput.Text) or self.value.G * 255
        local b = tonumber(self.bInput.Text) or self.value.B * 255
        self:Set(Color3.fromRGB(clampByte(r), clampByte(g), clampByte(b)))
        self.window:_persist(self)
    end
    self.window:ConnectFor(self, self.rInput.FocusLost, commitRgb)
    self.window:ConnectFor(self, self.gInput.FocusLost, commitRgb)
    self.window:ConnectFor(self, self.bInput.FocusLost, commitRgb)
end

function ColorPicker:_buildRgbField(label)
    local box = self.window:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 2,

        BackgroundTransparency = 1, -- Open = 0.85

        Parent = self.rgbRow,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = box })
    local stroke = self.window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),

        Transparency = 1, -- Open = 0.75

        Parent = box,
    })

    local text = self.window:Create("TextLabel", {
        Text = label,
        Size = UDim2.fromOffset(14, 34),
        Position = UDim2.new(0, 8, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 13,
        ZIndex = 3,

        TextTransparency = 1, -- Open = 0.4

        Parent = box,
    }, { TextColor3 = "PlaceholderColor", FontFace = "Font" })

    local input = self.window:Create("TextBox", {
        Size = UDim2.new(1, -28, 1, 0),
        Position = UDim2.new(0, 24, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        ClearTextOnFocus = false,
        ZIndex = 3,

        TextTransparency = 1, -- Open = 0

        Parent = box,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    return box, input, stroke, text
end

function ColorPicker:_render(mode)
    self.swatch.BackgroundColor3 = self.value
    self.swatchBar.BackgroundColor3 = self.value
    self.hsv:SetColor(self.hue, self.sat, self.val, mode ~= "instant")

    if not self.hexInput:IsFocused() then
        self.hexInput.Text = "#" .. self.value:ToHex():upper()
    end
    if not self.rInput:IsFocused() then
        self.rInput.Text = tostring(math.round(self.value.R * 255))
    end
    if not self.gInput:IsFocused() then
        self.gInput.Text = tostring(math.round(self.value.G * 255))
    end
    if not self.bInput:IsFocused() then
        self.bInput.Text = tostring(math.round(self.value.B * 255))
    end

    self.previewGlow.Color = self.value
    for _, entry in self.presetButtons do
        entry.ring.Transparency = if entry.color == self.value and self._isOpen then 0 else 1
    end
end

function ColorPicker:_fireCallback()
    self.window:_runGuarded(self, self.callback, self.value, self.alpha)
end

-- Quick tactile feedback on the header swatch the instant it's clicked, independent of (and
-- faster than) the open/close animation that follows - squashes narrower, then springs back
-- past its resting width before settling (Back easing) for a little bounce.
function ColorPicker:_popSwatch()
    local squashed = UDim2.fromOffset(swatchSize.X.Offset * 0.85, swatchSize.Y.Offset * 0.85)
    local outTween = variables.tweenService:Create(self.swatch, popOutInfo, { Size = squashed })
    outTween:Play()
    local connection
    connection = outTween.Completed:Connect(function()
        connection:Disconnect()
        variables.tweenService:Create(self.swatch, popBackInfo, { Size = swatchSize }):Play()
    end)
end

function ColorPicker:_open()
    if self._isOpen then
        return
    end
    self._isOpen = true
    self._openSeq = (self._openSeq or 0) + 1
    local seq = self._openSeq
    self:_setControlsVisible(true)

    if self._outsideClickConn then
        self.window:Disconnect(self._outsideClickConn)
    end
    self._outsideClickConn = self.window:Connect(variables.userInputService.InputBegan, function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end
        local pos = input.Position
        local mainPos = self.main.AbsolutePosition
        local mainSize = self.main.AbsoluteSize
        if pos.X < mainPos.X or pos.X > mainPos.X + mainSize.X or pos.Y < mainPos.Y or pos.Y > mainPos.Y + mainSize.Y then
            self:_close()
        end
    end)

    -- card grows with a slight bounce past its final height instead of a flat stop
    variables.tweenService:Create(self.main, heightOpenInfo, { Size = UDim2.new(1, -20, 0, self._openHeight) }):Play()
    variables.tweenService:Create(self.chevron, chevronInfo, { Rotation = 0 }):Play()

    -- glow pulse: flashes past its steady-state glow, then relaxes back down to it
    if self.showGlow then
        variables.tweenService:Create(self.previewGlow, glowPulseInfo, { Transparency = math.max(0, glowOnTransparency - 0.3) }):Play()
        task.delay(glowPulseInfo.Time, function()
            if self._isOpen and self._openSeq == seq then
                variables.tweenService:Create(self.previewGlow, glowRelaxInfo, { Transparency = glowOnTransparency }):Play()
            end
        end)
    end

    -- staggered reveal: hex first, then RGB, then swatch+presets, then the HSV editor
    self:_revealHex(true, fadeInfo)
    task.delay(staggerStep, function()
        if self._isOpen and self._openSeq == seq then
            self:_revealRgb(true, fadeInfo)
        end
    end)
    task.delay(staggerStep * 2, function()
        if self._isOpen and self._openSeq == seq then
            self:_revealSwatchAndPresets(true, fadeInfo)
        end
    end)
    task.delay(staggerStep * 3, function()
        if self._isOpen and self._openSeq == seq then
            self.hsv:SetVisible(true, true)
        end
    end)

    self:_render("animate")
end

function ColorPicker:_close()
    if not self._isOpen then
        return
    end
    self._isOpen = false
    self._openSeq = (self._openSeq or 0) + 1 -- invalidates any staggered/delayed open steps still pending

    if self._outsideClickConn then
        self.window:Disconnect(self._outsideClickConn)
        self._outsideClickConn = nil
    end
    if self.hexInput:IsFocused() then
        self.hexInput:ReleaseFocus()
    end

    -- everything fades out together (no stagger) on the quicker closeFadeInfo, so the content
    -- is gone before (or right as) the height tween below finishes instead of cutting off mid-fade
    self:_applyBodyVisibility(false, closeFadeInfo)
    self.hsv:SetVisible(false, true)
    self:_render("animate") -- also drops the preset ring now that _isOpen is false
    variables.tweenService:Create(self.main, heightInfo, { Size = UDim2.new(1, -20, 0, headerHeight) }):Play()
    variables.tweenService:Create(self.chevron, chevronInfo, { Rotation = 180 }):Play()

    task.delay(closeFadeInfo.Time, function()
        if not self._isOpen then
            self:_setControlsVisible(false)
        end
    end)
end

-- Wide: hex/RGB/swatch/presets left, square+hue right, side by side.
-- Narrow: same stack, full width, with the editor centred underneath.
function ColorPicker:_applyLayout()
    local width = self.main.AbsoluteSize.X
    local mode = if width > 0 and width < narrowWidth then "narrow" else "wide"
    if mode == self._layoutMode then
        return
    end
    self._layoutMode = mode

    local leftWidth = if mode == "wide" then UDim.new(1, -(20 + squareSize + 16 + 20)) else UDim.new(1, -40)
    local y = headerHeight
    self.hexBox.Position = UDim2.new(0, 20, 0, y)
    self.hexBox.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 34)
    y += 34 + rowGap

    self.rgbRow.Position = UDim2.new(0, 20, 0, y)
    self.rgbRow.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 34)
    y += 34 + rowGap

    self.swatchBar.Position = UDim2.new(0, 20, 0, y)
    self.swatchBar.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 34)
    y += 34 + rowGap + 2

    self.presetsRow.Position = UDim2.new(0, 20, 0, y)
    self.presetsRow.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 26)
    local leftBottom = y + 26

    if mode == "wide" then
        self.hsv.root.Position = UDim2.new(1, -20 - squareSize, 0, headerHeight)
        self._openHeight = math.max(leftBottom, headerHeight + squareSize + 14 + 14) + 20
    else
        local hsvY = leftBottom + 16
        self.hsv.root.Position = UDim2.new(0.5, -squareSize / 2, 0, hsvY)
        self._openHeight = hsvY + squareSize + 14 + 14 + 20
    end

    if self._isOpen then
        variables.tweenService:Create(self.main, heightInfo, { Size = UDim2.new(1, -20, 0, self._openHeight) }):Play()
    end
end

function ColorPicker:Set(color, skipCallback)
    self.value = coerceColor(color, self.value)
    self.hue, self.sat, self.val = self.value:ToHSV()
    self:_render(if skipCallback then "instant" else "animate")

    if not skipCallback then
        self:_fireCallback()
        self.window:_persist(self)
    end
end

function ColorPicker:SetAlpha(alpha, skipCallback)
    self.alpha = clamp01(if type(alpha) == "number" then alpha else self.alpha)

    if not skipCallback then
        self:_fireCallback()
        self.window:_persist(self)
    end
end

-- Toggle the ambient glow behind the card at runtime.
function ColorPicker:SetGlow(shown)
    self.showGlow = shown and true or false
    variables.tweenService
        :Create(self.previewGlow, fadeInfo, { Transparency = if self.showGlow then glowOnTransparency else 1 })
        :Play()
end

-- Persistence: RRGGBB plus an alpha byte (AA) so alpha round-trips even though this layout has
-- no alpha control of its own - a dev can still drive SetAlpha() from code.
function ColorPicker:_serialize()
    return self.value:ToHex() .. string.format("%02x", math.clamp(math.round((self.alpha or 1) * 255), 0, 255))
end

function ColorPicker:_deserialize(raw)
    local hex = tostring(raw)
    if #hex >= 8 then
        self:SetAlpha((tonumber(hex:sub(7, 8), 16) or 255) / 255, true)
        hex = hex:sub(1, 6)
    end
    self:Set(Color3.fromHex(hex))
end

local function applySet(set, animate)
    for instance, props in set do
        if animate then
            variables.tweenService:Create(instance, animate, props):Play()
        else
            for prop, value in props do
                instance[prop] = value
            end
        end
    end
end

function ColorPicker:_revealHex(open, animate)
    applySet({
        [self.hexBox] = { BackgroundTransparency = if open then 0.85 else 1 },
        [self.hexBoxStroke] = { Transparency = if open then 0.75 else 1 },
        [self.hexInput] = { TextTransparency = if open then 0 else 1 },
    }, animate)
end

function ColorPicker:_revealRgb(open, animate)
    local set = {}
    for _, field in { { self.rBox, self.rBoxStroke, self.rBoxText, self.rInput },
        { self.gBox, self.gBoxStroke, self.gBoxText, self.gInput },
        { self.bBox, self.bBoxStroke, self.bBoxText, self.bInput } } do
        local box, stroke, text, input = field[1], field[2], field[3], field[4]
        set[box] = { BackgroundTransparency = if open then 0.85 else 1 }
        set[stroke] = { Transparency = if open then 0.75 else 1 }
        set[text] = { TextTransparency = if open then 0.4 else 1 }
        set[input] = { TextTransparency = if open then 0 else 1 }
    end
    applySet(set, animate)
end

function ColorPicker:_revealSwatchAndPresets(open, animate)
    local set = { [self.swatchBar] = { BackgroundTransparency = if open then 0 else 1 } }
    for _, entry in self.presetButtons do
        set[entry.dot] = { BackgroundTransparency = if open then 0 else 1 }
        if not open then
            set[entry.ring] = { Transparency = 1 }
        end
    end
    applySet(set, animate)
end

-- Every OPEN-only body part (hex/RGB fields, swatch bar, presets), all pulled from the same
-- three group methods above so both the initial hidden state at build and a plain (non-
-- staggered) open/close use exactly the same values the staggered _open() sequence does. The
-- header swatch pill is NOT in here since it stays visible whether the card is open or closed.
-- hsvEditor manages its own instances.
function ColorPicker:_applyBodyVisibility(open, animate)
    self:_revealHex(open, animate)
    self:_revealRgb(open, animate)
    self:_revealSwatchAndPresets(open, animate)
end

-- The open-only controls sit below the header even while collapsed (the card doesn't clip), so
-- a transparent TextBox/button down there would still catch the cursor. Toggling them off drops
-- the whole cluster out of input while closed - the header swatch pill is separate, stays put.
function ColorPicker:_setControlsVisible(visible)
    for _, frame in { self.hexBox, self.rgbRow, self.swatchBar, self.presetsRow, self.hsv.root } do
        frame.Visible = visible
    end
end

function ColorPicker:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.swatch, { BackgroundTransparency = 0 }, animate)
        w:_reveal(self.chevron, { ImageTransparency = 0.4 }, animate)
        w:_reveal(self.previewGlow, { Transparency = if self.showGlow then glowOnTransparency else 1 }, animate)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.swatch, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.chevron, { ImageTransparency = 1 }, animate)
        w:_reveal(self.previewGlow, { Transparency = 1 }, animate)
        if self._isOpen then
            self:_close()
        end
    end
end

moveable(ColorPicker)
lockable(ColorPicker)

return ColorPicker
]=====]

sources["components/console"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A monospaced block for code or log output. It holds the height it's given and scrolls inside
-- itself, so a console that fills up doesn't push the rest of the page down the screen. Ported
-- from upstream Rayfield Gen2 1.2's own Console element.
--
-- One label per line, not one label for the whole body: a single auto-sized label inside a
-- fixed-height scroller gets clamped to one viewport, and the canvas then has nothing to
-- scroll. A row each keeps every label short enough that its own height is never the thing
-- being clamped, and the list layout measures the canvas for us.

local Console = {}
Console.__index = Console
Console.__type = "Console"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local moveable = require(utility.moveable)
local locale = require(utility.locale)

local defaultHeight = 120
local minHeight = 48
local titleHeight = 24 -- the row the name sits on, when there is one
local padding = 17
local textPadding = 12 -- inside the panel; log output sits close to its edge
local textSize = 12
local lineHeight = 1.25 -- dense, the way a real log reads

-- How many lines the block keeps. Past this the oldest roll off the top, so a console left
-- running all session cant grow without end.
local defaultMaxLines = 200

-- Monospace, so columns line up. Not the brand font: this is output, not copy.
local monoFont = Font.fromEnum(Enum.Font.Code)

function Console.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name,
        description = properties.description or properties.Description,

        height = math.max(tonumber(properties.height or properties.Height) or defaultHeight, minHeight),
        -- a log pins itself to the newest line; a code sample stays where you left it
        follow = properties.follow or properties.Follow or false,
        maxLines = math.max(tonumber(properties.maxLines or properties.MaxLines) or defaultMaxLines, 1),

        lines = {},
        -- Pooled and recycled in a ring. Appending at capacity rewrites one label and gives it
        -- the next LayoutOrder, so a line costs the same whether the buffer holds ten or a
        -- thousand - rewriting every row on every append is what makes a console crawl.
        lineLabels = {},
        head = 1, -- the pooled label holding the oldest line
        nextOrder = 1,
        textDirty = true,
    }, Console)

    self:_build()
    self:_setLines(properties.text or properties.Text or "")

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- The body as one string. Built on demand: joining every line on each append would put an O(n)
-- cost on the one path that has to stay cheap.
function Console:Get(): string
    if self.textDirty then
        self.text = table.concat(self.lines, "\n")
        self.textDirty = false
    end
    return self.text
end

-- Split a body into lines and keep only the newest maxLines of them.
function Console:_setLines(text)
    text = if type(text) == "string" then text else tostring(text)

    table.clear(self.lines)
    if text ~= "" then
        for line in string.gmatch(text .. "\n", "([^\n]*)\n") do
            table.insert(self.lines, line)
        end
    end
    self:_trim()
    self:_flush()
end

-- Drop from the front until the buffer fits. table.move rather than repeated table.remove, so
-- a burst of output doesn't turn into a quadratic shuffle.
function Console:_trim()
    local excess = #self.lines - self.maxLines
    if excess <= 0 then
        return
    end
    table.move(self.lines, excess + 1, #self.lines, 1)
    for index = #self.lines, #self.lines - excess + 1, -1 do
        self.lines[index] = nil
    end
end

-- A row for a line. Created once and then recycled; the pool never exceeds maxLines.
function Console:_makeLabel()
    return self.window:Create("TextLabel", {
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        FontFace = monoFont,
        TextSize = textSize,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        TextWrapped = true,
        LineHeight = lineHeight,
        RichText = false, -- it's output; angle brackets are text, not markup

        -- a line added after the reveal comes in at whatever the rest are already at
        TextTransparency = self._textTransparency or 1,

        Parent = self.scroll,
    }, { TextColor3 = "ContentColor" })
end

-- a blank line still has to take a row, and an empty label collapses to nothing
local function rowText(line: string): string
    return if line == "" then " " else line
end

-- Rebuild every row from the buffer. Only the paths that replace the whole body use this;
-- Append has its own O(1) route below.
function Console:_flush()
    self.textDirty = true

    for index, line in self.lines do
        local label = self.lineLabels[index]
        if not label then
            label = self:_makeLabel()
            self.lineLabels[index] = label
        end
        label.LayoutOrder = index
        label.Text = rowText(line)
        label.Visible = true
    end

    for index = #self.lines + 1, #self.lineLabels do
        self.lineLabels[index].Visible = false
    end

    self.head = 1
    self.nextOrder = #self.lines + 1
    self:_follow()
end

-- One line, one label write. At capacity the oldest row is recycled into the newest position
-- rather than every row shuffling up, so the cost doesn't grow with the buffer.
function Console:_pushLine(line: string)
    self.textDirty = true

    if #self.lines < self.maxLines then
        table.insert(self.lines, line)
        local index = #self.lines
        local label = self.lineLabels[index]
        if not label then
            label = self:_makeLabel()
            self.lineLabels[index] = label
        end
        label.LayoutOrder = self.nextOrder
        label.Text = rowText(line)
        label.Visible = true
        self.nextOrder += 1
        return
    end

    -- full: drop the oldest line and hand its row to the newest one. table.move rather than
    -- table.remove so the shift is one bulk copy instead of a per-element slide.
    table.move(self.lines, 2, #self.lines, 1)
    self.lines[#self.lines] = line

    local label = self.lineLabels[self.head]
    label.LayoutOrder = self.nextOrder
    label.Text = rowText(line)
    label.Visible = true

    self.nextOrder += 1
    self.head = (self.head % #self.lineLabels) + 1
end

function Console:_build()
    local top = if self.name then titleHeight else 0

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, self.height + top + padding * 2),
        BorderSizePixel = 0,
        Name = self.name or "Console",
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        -- Animation
        BackgroundTransparency = 1, -- In = 0

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)

    if self.name then
        self.container = self.window:Create("Frame", {
            Size = UDim2.new(1, -padding * 2, 0, 16),
            Position = UDim2.new(0, padding, 0, padding),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,

            Parent = self.main,
        })

        self.title = self.window:Create("TextLabel", {
            Text = locale.t(self.name),

            Size = UDim2.fromScale(1, 1),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            TextSize = 16,
            TextXAlignment = Enum.TextXAlignment.Left,

            -- Animation
            TextTransparency = 1, -- In = 0

            Parent = self.container,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })
    end

    -- The inset panel the text scrolls inside. Darker than the element it sits on, the way a
    -- terminal reads against the window around it.
    self.panel = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 1),
        Position = UDim2.new(0.5, 0, 1, -padding),
        Size = UDim2.new(1, -padding * 2, 0, self.height),
        BorderSizePixel = 0,
        ClipsDescendants = true,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    }, { BackgroundColor3 = "StatBackground" })

    self.window:Create("UICorner", {
        Parent = self.panel,
    }, { CornerRadius = "ElementCornerRadius" })

    self.panelStroke = self.window:Create("UIStroke", {
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,

        -- Animation
        Transparency = 1, -- In = 0.9

        Parent = self.panel,
    }, { Color = "SurfaceStroke" })

    self.scroll = self.window:Create("ScrollingFrame", {
        Size = UDim2.new(1, -textPadding * 2, 1, -textPadding * 2),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        ScrollBarThickness = 0,
        ScrollingDirection = Enum.ScrollingDirection.Y,

        Parent = self.panel,
    })

    -- the layout is what measures the canvas, so the rows themselves can stay simple
    self.scrollLayout = self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        VerticalAlignment = Enum.VerticalAlignment.Top,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.scroll,
    })

    self:_watchCanvas()
end

-- Pin to the bottom. Asking for a position past the end is fine: Roblox clamps it to the real
-- maximum, which saves working out the viewport height ourselves.
function Console:_pin()
    local scroll = self.scroll
    if not scroll or not scroll.Parent then
        return
    end
    scroll.CanvasPosition = Vector2.new(0, scroll.AbsoluteCanvasSize.Y)
end

function Console:_follow()
    if not self.follow then
        return
    end
    self:_pin()
    task.defer(function()
        self:_pin()
    end)
end

-- The canvas only settles a frame or two after the rows change, so pinning once on Append is a
-- race. The layout's content size is the thing that actually moves, so follow that instead.
function Console:_watchCanvas()
    self.window:ConnectFor(self, self.scrollLayout:GetPropertyChangedSignal("AbsoluteContentSize"), function()
        if self.follow then
            self:_pin()
        end
    end)
end

-- Replace the whole body.
function Console:Set(text)
    self:_setLines(text)
end

-- Add a line to the end, the way a console does. Once the buffer is full the oldest line rolls
-- off the top, so what you see is always the newest output.
function Console:Append(line)
    line = if type(line) == "string" then line else tostring(line)
    for part in string.gmatch(line .. "\n", "([^\n]*)\n") do
        self:_pushLine(part)
    end
    self:_follow()
end

function Console:Clear()
    table.clear(self.lines)
    self:_flush()
end

-- Put the body on the clipboard, where the executor gives us one. Returns whether it landed.
function Console:Copy(): boolean
    local clipboard = (getgenv and getgenv().setclipboard) or setclipboard
    if typeof(clipboard) ~= "function" then
        return false
    end
    return (pcall(clipboard, self:Get()))
end

-- Change how tall the block stands. The panel takes the height; the element grows around it.
function Console:SetHeight(height)
    self.height = math.max(tonumber(height) or defaultHeight, minHeight)
    local top = if self.name then titleHeight else 0
    self.panel.Size = UDim2.new(1, -padding * 2, 0, self.height)
    self.main.Size = UDim2.new(1, -20, 0, self.height + top + padding * 2)
end

function Console:_setShown(shown, animate)
    local w = self.window

    -- no icon and (usually) no title, so the shared reveal doesn't fit; drive the parts directly
    w:_reveal(self.main, { BackgroundTransparency = if shown then w.theme.ElementTransparency or 0 else 1 }, animate)
    w:_reveal(self.stroke, { Transparency = if shown then w.theme.ElementStrokeTransparency else 1 }, animate)
    w:_reveal(self.panel, { BackgroundTransparency = if shown then 0 else 1 }, animate)
    w:_reveal(self.panelStroke, { Transparency = if shown then 0.9 else 1 }, animate)

    self._textTransparency = if shown then 0.15 else 1
    for _, label in self.lineLabels do
        w:_reveal(label, { TextTransparency = self._textTransparency }, animate)
    end

    if self.title then
        w:_reveal(self.title, { TextTransparency = if shown then 0 else 1 }, animate)
    end
    if self.descriptor then
        w:_reveal(self.descriptor.titleLabel, { TextTransparency = if shown then 0.7 else 1 }, animate)
    end
end

function Console:Remove()
    if self.descriptor then
        self.descriptor:Remove()
    end
    self.main:Destroy()
end

moveable(Console)

return Console
]=====]

sources["components/copybutton"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Copies a string to the clipboard in one click. Title/icon left like Button; the pinned-right
-- "well" is the copy control itself - it pops, squishes, and swaps its icon for a checkmark that
-- reverts after 2s. Falls back gracefully (no error, just no copy) when the executor exposes no
-- clipboard writer.

local CopyButton = {}
CopyButton.__index = CopyButton
CopyButton.__type = "CopyButton"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
local clipboard = require(utility.clipboard)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local log = require(utility.log)

local checkIcon = constants.icons.check
local wellSize = 28
local revertDelay = 2 -- seconds the checkmark holds before reverting

function CopyButton.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Copy",
        icon = properties.icon or properties.Icon, -- shown inside the well
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        compact = tab.compact or false,

        text = tostring(properties.text or properties.Text or properties.value or properties.Value or ""),

        callback = properties.callback or properties.Callback or function() end,

        _copyToken = 0, -- bumped per press so a rapid re-click restarts the revert cleanly
    }, CopyButton)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self.window:_wireTooltip(self)

    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- the icon well: a round field with the dev's icon, swappable for a checkmark. same in both
-- layouts; caller places it (pinned right / flex item)
function CopyButton:_buildWell(parent)
    local window = self.window

    self.well = window:Create("Frame", {
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(wellSize, wellSize),

        BackgroundTransparency = 1, -- In = FieldTransparency
        Parent = parent,
    }, { BackgroundColor3 = "FieldBackground" })

    window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),
        Parent = self.well,
    })

    self.wellStroke = window:Create("UIStroke", {
        Transparency = 1, -- In = 0.85
        Parent = self.well,
    }, { Color = "SurfaceStroke" })

    self.wellGlow = window:CreateGlow(self.well, "FieldGlow", 18, 1)

    self.wellScale = window:Create("UIScale", {
        Scale = 1,
        Parent = self.well,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            Position = UDim2.fromScale(0.5, 0.5),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0
            Parent = self.well,
        }, { ImageColor3 = "ContentColor" })
    end

    self.checkIcon = window:Create("ImageLabel", {
        Image = checkIcon,
        Size = UDim2.fromOffset(16, 16),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        ImageColor3 = Color3.fromRGB(255, 255, 255),

        ImageTransparency = 1, -- swapped in on a successful copy
        Parent = self.well,
    })

    return self.well
end

-- pop -> squish -> swap to the checkmark -> settle. the swap lands at the bottom of the
-- squish, where it's smallest and the crossfade reads as one motion instead of two. Kept snappy
-- end to end (checkmark lands well under a quarter second after the press) - only the 2s hold
-- before revert is meant to read as a deliberate pause.
local popInfo = TweenInfo.new(0.06, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local squishInfo = TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
local settleInfo = TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local crossfadeInfo = TweenInfo.new(0.06, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local revertInfo = TweenInfo.new(0.12, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

function CopyButton:_playSuccess()
    local ts = variables.tweenService
    self._copyToken += 1
    local token = self._copyToken

    ts:Create(self.wellScale, popInfo, { Scale = 1.12 }):Play()
    task.delay(popInfo.Time, function()
        if self._copyToken ~= token then
            return
        end
        ts:Create(self.wellScale, squishInfo, { Scale = 0.82 }):Play()
        task.delay(squishInfo.Time, function()
            if self._copyToken ~= token then
                return
            end
            -- swap at the squish's low point
            if self.iconLabel then
                ts:Create(self.iconLabel, crossfadeInfo, { ImageTransparency = 1 }):Play()
            end
            ts:Create(self.checkIcon, crossfadeInfo, { ImageTransparency = 0 }):Play()
            ts:Create(self.wellScale, settleInfo, { Scale = 1 }):Play()

            task.delay(revertDelay, function()
                if self._copyToken ~= token then
                    return -- a newer press already owns the well
                end
                if self.iconLabel then
                    ts:Create(self.iconLabel, revertInfo, { ImageTransparency = 0 }):Play()
                end
                ts:Create(self.checkIcon, revertInfo, { ImageTransparency = 1 }):Play()
            end)
        end)
    end)
end

-- a copy that found no clipboard function still gets a press acknowledgement, just no checkmark
function CopyButton:_playMiss()
    local ts = variables.tweenService
    self._copyToken += 1
    local token = self._copyToken

    ts:Create(self.wellScale, popInfo, { Scale = 1.08 }):Play()
    task.delay(popInfo.Time, function()
        if self._copyToken ~= token then
            return
        end
        ts:Create(self.wellScale, squishInfo, { Scale = 0.88 }):Play()
        task.delay(squishInfo.Time, function()
            if self._copyToken ~= token then
                return
            end
            ts:Create(self.wellScale, settleInfo, { Scale = 1 }):Play()
        end)
    end)
end

function CopyButton:_performCopy()
    hapticEngine.click()
    soundEngine.click()
    local ok = clipboard.copy(self.text)

    if ok then
        self:_playSuccess()
    else
        self:_playMiss()
        -- once per button, not once per click - an impatient user mashing it shouldn't spam the console
        if not self._warnedNoClipboard then
            self._warnedNoClipboard = true
            log.warn(
                `Rayfield: no clipboard function exposed by this executor, the CopyButton '{self.name}' couldn't copy.`
            )
        end
    end

    self.window:_runGuarded(self, self.callback, ok)
end

-- full-width: title/description left, well pinned right, width-bounce (matches button.luau)
function CopyButton:_buildFull()
    local window = self.window

    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 43),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)
    self.hoverOverlay = window:CreateHoverOverlay(self.main)

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(250, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,

        TextTransparency = 1, -- In = 0

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.interact = window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        TextTransparency = 1,

        Parent = self.main,
    })

    self:_buildWell(self.main)
    self.well.Position = UDim2.new(1, -18, 0, 21)
    self.well.AnchorPoint = Vector2.new(1, 0.5)

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()
        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -26, 0, 43) }
            )
            :Play()

        self:_performCopy()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -20, 0, 43) }
            )
            :Play()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- compact (row): title left, well right (SpaceBetween)
function CopyButton:_buildCompact()
    local window = self.window

    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name, 10)
    self.hoverOverlay = self.interact

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 15),
        PaddingRight = UDim.new(0, 15),

        Parent = self.interact,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,
        Padding = UDim.new(0, 10),

        Parent = self.interact,
    })

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 0,

        TextTransparency = 1, -- In = 0

        Parent = self.interact,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    self:_buildWell(self.interact)
    self.well.LayoutOrder = 1

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()

        self:_performCopy()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- iconLabel (the dev icon inside the well) is already handled by _revealCommon/_hideCommon
function CopyButton:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.well, { BackgroundTransparency = w.theme.FieldTransparency }, animate)
        w:_reveal(self.wellStroke, { Transparency = 0.85 }, animate)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.well, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.wellStroke, { Transparency = 1 }, animate)
    end
end

-- Re-apply the well's theme-driven fill transparency on a runtime ChangeTheme.
function CopyButton:_refreshTheme()
    variables.tweenService
        :Create(
            self.well,
            TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { BackgroundTransparency = self.window.theme.FieldTransparency }
        )
        :Play()
end

-- Update the string this button copies without rebuilding it.
function CopyButton:Set(text)
    self.text = tostring(text)
end

-- Room the compact copy button needs: side padding + title text + gap to the well + the well.
function CopyButton:_minWidth()
    local w = 30 + 10 + wellSize -- 15+15 padding, 10 gap to well, well itself
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

moveable(CopyButton)
lockable(CopyButton)

return CopyButton
]=====]

sources["components/descriptor"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Descriptor = {}
Descriptor.__index = Descriptor
Descriptor.__type = "Descriptor"

local locale = require(script.Parent.Parent.utility.locale)

function Descriptor.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        description = properties.description or properties.Description or "",
    }, Descriptor)

    self.main = self.window:Create("Frame", {
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        Size = UDim2.new(1, -30, 0, 0),

        Parent = self.tab.tabPage,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = self.main,
    })

    self.titleLabel = self.window:Create("TextLabel", {
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        RichText = true,
        Size = UDim2.new(1, -90, 0, 0),
        Text = locale.t(self.description),
        TextSize = 12,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,

        -- Animation
        TextTransparency = 1, -- In = 0.7

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- Bottom spacing
    self.window:Create("Frame", {
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 1,
        Size = UDim2.fromOffset(0, 15),
        Parent = self.main,
    })

    return self
end

return Descriptor
]=====]

sources["components/divider"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 10 "Divider": a subtle horizontal rule that splits a page into groups without the
-- weight of a full Section header. Three shapes:
--   1. Plain line spanning the row.
--   2. Line with a centred caption, the line broken into two independently-flexed halves either
--      side of it (see the row's UIListLayout below) so it stays balanced regardless of how long
--      or short the caption is - a short word like "Tight" leaves long stretches of line either
--      side, not a fixed even split.
--   3. "Spacing only": no visible line at all, just a fixed-height gap - line = false.
-- Vertical padding around the line comes from a named spacing preset (tight/normal/loose)
-- rather than a raw pixel prop, so it reads the same way across every divider in a page.

local Divider = {}
Divider.__index = Divider
Divider.__type = "Divider"

local utility = script.Parent.Parent.utility
local moveable = require(utility.moveable)
local locale = require(utility.locale)

-- Live-caught too roomy at "normal" (14/14) - read as a much bigger gap than the reference
-- around a captioned line. Tightened across the board; loose still stays clearly the most open
-- of the three, just from a smaller base.
local spacingPresets = {
    tight = { top = 4, bottom = 4 },
    normal = { top = 8, bottom = 8 },
    loose = { top = 18, bottom = 18 },
}

local defaultSpacerHeight = 24

function Divider.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local text = properties.text or properties.Text or ""
    local showLine = if properties.line ~= nil
        then properties.line
        elseif properties.Line ~= nil then properties.Line
        else true
    local spacingKey = string.lower(properties.spacing or properties.Spacing or "normal")
    local preset = spacingPresets[spacingKey] or spacingPresets.normal
    local spacerHeight = properties.height or properties.Height or defaultSpacerHeight

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        line = showLine,
    }, Divider)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Name = "Divider",

        Parent = self.tab.tabPage,
    })

    if not showLine then
        -- Spacing-only: just a fixed-height invisible gap, no row/line/title to build or reveal.
        self.window:Create("Frame", {
            Size = UDim2.fromOffset(0, spacerHeight),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,

            Parent = self.main,
        })

        return self
    end

    self.window:Create("UIPadding", {
        PaddingTop = UDim.new(0, preset.top),
        PaddingBottom = UDim.new(0, preset.bottom),

        Parent = self.main,
    })

    self.row = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.main,
    })

    -- No HorizontalFlex here (left at its default None) - live-caught that setting it to Fill
    -- distributes the row's width across *every* child, title included, whether or not that
    -- child has its own UIFlexItem: the title (AutomaticSize.X, no UIFlexItem) still got forced
    -- out to a wide flex-assigned box instead of its actual ~27px text width, centred inside
    -- that oversized box - which read as a huge gap between the line and the word, not the 8px
    -- Padding actually sitting between them. Left at None, only leftLine/rightLine's own
    -- UIFlexItem below makes them flex at all - the title's width is untouched.
    self.rowLayout = self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, if text ~= "" then 8 else 0),
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.row,
    })

    local function buildLineHalf(layoutOrder)
        local half = self.window:Create("Frame", {
            Size = UDim2.fromOffset(0, 1),
            BorderSizePixel = 0,
            LayoutOrder = layoutOrder,

            -- Animation
            BackgroundTransparency = 1, -- In = 0.88

            Parent = self.row,
        }, { BackgroundColor3 = "SurfaceStroke" })

        -- Opts this half into the row's Fill flex - the other non-flexed child (the title, when
        -- there is one) keeps its own natural width, so the two halves split whatever's left
        -- over evenly instead of the row forcing three equal thirds.
        self.window:Create("UIFlexItem", {
            FlexMode = Enum.UIFlexMode.Fill,
            Parent = half,
        })

        return half
    end

    self.leftLine = buildLineHalf(0)
    self.rightLine = buildLineHalf(2)

    if text ~= "" then
        self:_buildTitle(text)
    end

    return self
end

-- Built lazily - either at construction (if the divider started with a caption) or the first
-- time Set() gives a blank divider one. LayoutOrder 1 sits it between the two line halves.
function Divider:_buildTitle(text)
    self.title = self.window:Create("TextLabel", {
        Text = locale.t(text),

        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 12,
        TextXAlignment = Enum.TextXAlignment.Center,
        LayoutOrder = 1,

        -- Animation
        TextTransparency = 1, -- In = 0.5

        Parent = self.row,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })
end

-- Swap (or add/remove) the centred caption without breaking the line's alignment - the row's
-- Padding just collapses to 0 when there's no caption, so the two halves meet in the middle as
-- one continuous line instead of leaving a gap where the title used to be.
function Divider:Set(text)
    text = text or ""
    if not self.row then
        return -- spacing-only divider has no line/title to update
    end

    if text == "" then
        if self.title then
            self.title.Visible = false
        end
        self.rowLayout.Padding = UDim.new(0, 0)
        return
    end

    if not self.title then
        self:_buildTitle(text)
        if not self.window.hidden then
            self.window:_reveal(self.title, { TextTransparency = 0.5 }, false)
        end
    else
        self.title.Visible = true
        -- Direct assignment, not locale.t() - that returns a wrapper table meant for Window:
        -- Create's own property loop (which unwraps it via _bindLocale) and would fail if
        -- assigned straight onto Text like this. Every other element's dynamic Set() has the
        -- same rule (see Tag:SetText) - only the construction-time value round-trips through
        -- translation.
        self.title.Text = text
    end
    self.rowLayout.Padding = UDim.new(0, 10)
end

function Divider:_setShown(shown, animate)
    local w = self.window
    if self.leftLine then
        w:_reveal(self.leftLine, { BackgroundTransparency = if shown then 0.88 else 1 }, animate)
        w:_reveal(self.rightLine, { BackgroundTransparency = if shown then 0.88 else 1 }, animate)
    end
    if self.title then
        w:_reveal(self.title, { TextTransparency = if shown then 0.5 else 1 }, animate)
    end
end

moveable(Divider)

return Divider
]=====]

sources["components/drag"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Drag = {}
Drag.__index = Drag
Drag.__type = "Drag"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local constants = require(utility.constants)

function Drag.new(window, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
    }, Drag)

    -- Drag Point
    self.drag = self.window:Create("Frame", {
        BackgroundTransparency = 1,
        Size = UDim2.fromOffset(150, 20),
        AnchorPoint = Vector2.new(0.5, 0.5),
        -- hangs under the window's bottom edge; derived from the real size so it's right on the
        -- first open too (Show/minimise recompute the same way against self.size)
        Position = UDim2.new(0.5, 0, 0.5, self.window.size.Y.Offset / 2 + 15),
        ZIndex = constants.zIndex.drag,

        -- Animation
        Visible = false, -- In = true

        Parent = self.window.screenGui,
    })

    self.dragCosmetic = self.window:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.3),
        ZIndex = constants.zIndex.drag,

        -- Animation
        BackgroundTransparency = 1, -- In = 0.7
        Size = UDim2.fromOffset(0, 4), -- In = 100, 4

        Parent = self.drag,
    })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(0, 20),

        Parent = self.dragCosmetic,
    })

    -- White glow behind the drag bar
    self.window:CreateGlow(self.dragCosmetic, Color3.fromRGB(255, 255, 255), 10, 0.5)

    self.dragInteract = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        TextTransparency = 1,
        ZIndex = constants.zIndex.drag,

        Parent = self.drag,
    })

    local dragging = false
    local relative = nil

    -- main.Position offsets live in a space shifted from AbsolutePosition by the gui inset,
    -- even though the ScreenGui ignores inset. so the drag target has to add the inset back
    -- or the window lands ~inset px too high (measured in play: without it, jumps up ~58px).
    local offset = Vector2.zero
    local screenGui = self.window.screenGui

    if screenGui and screenGui.IgnoreGuiInset then
        offset = variables.guiService:GetGuiInset()
    end

    local function getPosition()
        local mouseLocation = variables.userInputService and variables.userInputService:GetMouseLocation()
            or Vector2.new(0, 0)
        local validRelative = relative or Vector2.new(0, 0)
        local validOffset = offset or Vector2.new(0, 0)

        return mouseLocation + validRelative + validOffset
    end

    -- main sits at the cursor target, the drag bar hangs under its bottom edge
    local function getTargets()
        local position = getPosition()
        local x, y = position.X, position.Y

        -- keepOnScreen: clamp the centre so it cant be pulled off screen
        if self.window.settings and self.window.settings.keepOnScreen then
            local size = self.window.main.AbsoluteSize
            local screen = self.window.screenGui.AbsoluteSize
            local margin = 8
            local halfX, halfY = size.X / 2, size.Y / 2
            -- math.max in case the window is bigger than the screen
            x = math.clamp(x, halfX + margin, math.max(halfX + margin, screen.X - halfX - margin))
            y = math.clamp(y, halfY + margin, math.max(halfY + margin, screen.Y - halfY - margin))
        end

        local mainTarget = UDim2.fromOffset(x, y)
        local dragTarget = UDim2.fromOffset(x, y + (self.window.main.Size.Y.Offset / 2 + 15))
        return mainTarget, dragTarget
    end

    self.window:Connect(self.drag.MouseEnter, function()
        if not dragging and not self.window.hidden then
            variables.tweenService
                :Create(
                    self.dragCosmetic,
                    TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                    { BackgroundTransparency = 0.5, Size = UDim2.new(0, 120, 0, 4) }
                )
                :Play()
        end
    end)

    self.window:Connect(self.drag.MouseLeave, function()
        if not dragging and not self.window.hidden then
            variables.tweenService
                :Create(
                    self.dragCosmetic,
                    TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                    { BackgroundTransparency = 0.7, Size = UDim2.new(0, 100, 0, 4) }
                )
                :Play()
        end
    end)

    -- Letting go, however it happens: the button coming up, the client losing focus, or the
    -- window going away out from under the grab. Only settle the bar back into line when
    -- theres something to look at, otherwise theres a tween to fight.
    local function releaseDrag()
        if not dragging then
            return
        end
        dragging = false

        if not self.window:_interactive() then
            return
        end

        variables.tweenService
            :Create(
                self.dragCosmetic,
                TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                { Size = UDim2.new(0, 100, 0, 4), BackgroundTransparency = 0.7 }
            )
            :Play()

        -- main lags while dragging, so settle both into line on release
        local settle = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
        local mainTarget, dragTarget = getTargets()
        variables.tweenService:Create(self.window.main, settle, { Position = mainTarget }):Play()
        variables.tweenService:Create(self.drag, settle, { Position = dragTarget }):Play()
    end

    self.window:Connect(self.dragInteract.InputBegan, function(input, processed)
        if processed then
            return
        end

        local inputType = input.UserInputType.Name
        if inputType == "MouseButton1" or inputType == "Touch" then
            -- a grab started mid-reveal would fight the tween thats still moving the window
            if not self.window:_interactive() then
                return
            end

            dragging = true

            -- refetch in case the inset changed (e.g. topbar toggled) since construction
            if screenGui and screenGui.IgnoreGuiInset then
                offset = variables.guiService:GetGuiInset()
            end

            relative = self.window.main.AbsolutePosition
                + self.window.main.AbsoluteSize * self.window.main.AnchorPoint
                - variables.userInputService:GetMouseLocation()
            if not self.window.hidden then
                variables.tweenService
                    :Create(
                        self.dragCosmetic,
                        TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
                        { Size = UDim2.new(0, 110, 0, 4), BackgroundTransparency = 0 }
                    )
                    :Play()
            end
        end
    end)

    self.window:Connect(variables.userInputService.InputEnded, function(input)
        local inputType = input.UserInputType.Name
        if inputType == "MouseButton1" or inputType == "Touch" then
            releaseDrag()
        end
    end)

    -- alt-tabbing with the button still down never delivers InputEnded, so without this the
    -- grab stays armed and the window snaps to the cursor the moment youre back
    self.window:Connect(variables.userInputService.WindowFocusReleased, releaseDrag)

    -- exponential smoothing per frame instead of a new tween each frame. constant is the
    -- fraction of the gap left after 1s, so smaller = snappier. main lags, the bar tracks tight
    local mainRemaining = 1e-7
    local barRemaining = 1e-60

    self.window:Connect(variables.runService.RenderStepped, function(dt)
        if not dragging then
            return
        end

        -- hidden or mid-animation means the grab went stale under us, so drop it here rather
        -- than let it wake up later and yank the window to wherever the cursor drifted
        if not self.window:_interactive() then
            releaseDrag()
            return
        end

        local mainTarget, dragTarget = getTargets()

        self.window.main.Position = self.window.main.Position:Lerp(mainTarget, 1 - mainRemaining ^ dt)
        self.drag.Position = self.drag.Position:Lerp(dragTarget, 1 - barRemaining ^ dt)
    end)

    return self
end

return Drag
]=====]

sources["components/dropdown"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Dropdown = {}
Dropdown.__index = Dropdown
Dropdown.__type = "Dropdown"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local image = require(utility.image)
local constants = require(utility.constants)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local moveable = require(utility.moveable)

local chevronIcon = constants.icons.chevron
local checkIcon = constants.icons.check
local dotIcon = constants.icons.dot
local searchIconAsset = constants.icons.search

-- Per-corner radii: an option's edge is rounded when nothing sits next to it, sharp otherwise
local roundRadius = UDim.new(0, 12)
local flatRadius = UDim.new(0, 7)

local searchCollapsedHeight = 30
local searchExpandedHeight = 38

-- Devlog 8: the panel opens tall enough to show this many full option rows before it caps out
-- and the list scrolls internally instead - was capped at a flat 180px, tall enough for barely
-- 2 rows once the header/search/padding overhead was subtracted.
local maxVisibleOptionRows = 4
local optionRowHeight = 38
local rowGap = 5
-- height of `maxVisibleOptionRows` option rows plus the gaps between them, no header/search/
-- padding included - that part (the "base") varies per dropdown (multiSelect adds a row), so
-- _openHeight adds this on top of its own base rather than this baking in a fixed total.
local capRowsHeight = maxVisibleOptionRows * optionRowHeight + math.max(0, maxVisibleOptionRows - 1) * rowGap + 2

local quickActionsRowHeight = 20
local quickActionsRowGap = 5
local searchTween = TweenInfo.new(0.35, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)

local function dedupStrings(arr)
    local seen = {}
    local out = {}
    for _, v in arr do
        if typeof(v) == "string" and not seen[v] then
            seen[v] = true
            table.insert(out, v)
        end
    end
    return out
end

local function normalizeValue(value, multi)
    if value == nil then
        return {}
    end
    if typeof(value) == "string" then
        return { value }
    end
    if typeof(value) == "table" then
        local out = dedupStrings(value)
        if not multi and #out > 1 then
            return { out[1] }
        end
        return out
    end
    return {}
end

-- The visible selection is always the intent narrowed to options that currently exist.
local function intersectWithOptions(value, options)
    local out = {}
    for _, v in value do
        if table.find(options, v) then
            table.insert(out, v)
        end
    end
    return out
end

local function sameSelection(a, b)
    if #a ~= #b then
        return false
    end
    for _, v in a do
        if not table.find(b, v) then
            return false
        end
    end
    return true
end

function Dropdown.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local options = properties.options or properties.Options or {}
    local multiSelect = properties.multiSelect or properties.MultiSelect or properties.MultipleOptions or false

    -- Optional section headers: { {name="MELEE", options={"Sword","Axe"}}, {name="RANGED", ...} }.
    -- When given, they take over from a flat `options` list - self.options is derived by
    -- flattening them in order, and every option is mapped back to its section name so
    -- rendering can insert a header before the first option of each run and re-group on filter.
    local sections = properties.sections or properties.Sections
    local sectionStarts = {} -- optionName -> section name, only the FIRST option of each section
    local sectionOf = {} -- optionName -> section name, every option
    if sections then
        local flat = {}
        for _, section in sections do
            local sectionName = section.name or section.Name or ""
            local sectionOptions = section.options or section.Options or {}
            local startedSection = false
            for _, optName in sectionOptions do
                table.insert(flat, optName)
                sectionOf[optName] = sectionName
                if not startedSection then
                    sectionStarts[optName] = sectionName
                    startedSection = true
                end
            end
        end
        options = flat
    end

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Dropdown",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState, -- dont save config for this element if true.
        locked = properties.locked or properties.Locked or false,

        flag = properties.flag
            or properties.Flag
            or (
                not (properties.forgetState or properties.ForgetState or tab.forgetState)
                    and functions.deriveFlagFromName(properties.name or properties.Name or "Dropdown")
                or nil
            ),

        callback = properties.callback or properties.Callback or function() end,

        options = dedupStrings(options),
        multiSelect = multiSelect,
        placeholderText = locale.resolve(properties.placeholder or properties.Placeholder or "None"),
        value = normalizeValue(
            properties.value or properties.Value or properties.currentOption or properties.CurrentOption,
            multiSelect
        ),

        _isOpen = false,
        _optionFrames = {},
        _headerFrames = {},
        _sectionStarts = sectionStarts,
        _sectionOf = sectionOf,
    }, Dropdown)

    -- Remember the full intent so a selection survives options that only load later (via
    -- Refresh), while self.value stays narrowed to options that currently exist.
    self._desiredValue = self.value
    self.value = intersectWithOptions(self.value, self.options)

    -- Register as a saveable control if flagged
    self.window:_registerControl(self)

    -- Outer wrapper: transparent, just holds the two cards and animates its height
    -- open <-> closed. Clips so the options card is hidden while collapsed.
    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 41),
        BorderSizePixel = 0,
        Name = self.name,
        ClipsDescendants = true,
        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    })

    -- Header card: the always-visible pill (icon + title + selected value + chevron)
    self.top = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 41),
        Position = UDim2.fromScale(0, 0),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 1,
        ZIndex = 1,

        Parent = self.main,
    }, { BackgroundTransparency = "ElementTransparency" })

    -- flat themed stroke, same as every other element's card (StyleElementPanel's gradient
    -- sheen read as an inconsistent/"improper" outline next to them - see StyleElementPanel's
    -- own doc comment; Popup still uses it deliberately for its changelog cards)
    self.stroke = self.window:StyleElementBody(self.top)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.top)
    self.flashTarget = self.top -- main is a transparent wrapper, so the error-flash tints the pill
    self.tooltipTarget = self.top -- same reason: hover on the actual pill, not the wrapper

    self.container = self.window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.top,
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        ZIndex = 5,
    })

    self.containerLayout = self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            -- Animation
            ImageTransparency = 1, -- In = 0

            ZIndex = 5,
            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        -- Configurables
        Text = locale.t(self.name),

        Size = UDim2.fromOffset(150, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        -- Animation
        TextTransparency = 1, -- In = 0

        ZIndex = 5,
        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.selectedLabel = self.window:Create("TextLabel", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -41, 0.5, 0),
        Size = UDim2.fromOffset(168, 15),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Right,
        TextWrapped = true,

        -- Animation
        TextTransparency = 1, -- In = 0.5

        ZIndex = 5,
        Parent = self.top,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.chevron = self.window:Create("ImageLabel", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -18, 0.5, 0),
        Size = UDim2.fromOffset(16, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        Image = "rbxassetid://" .. tostring(chevronIcon),
        Rotation = 180,

        -- Animation
        ImageTransparency = 1, -- In = 0.5

        ZIndex = 5,
        Parent = self.top,
    }, { ImageColor3 = "ContentColor" })

    -- Covers only the header, so option clicks in the open panel below don't hit it.
    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 41),
        Position = UDim2.fromScale(0, 0),
        BorderSizePixel = 0,
        Text = "",
        TextTransparency = 1,
        ZIndex = 10,
        AutoButtonColor = false,

        Parent = self.main,
    })

    -- Options card: a second (full-width) pill below the header, revealed as the wrapper
    -- grows. Anchored to the wrapper's bottom (top edge sits 6px under the header) so the
    -- clip hides it while collapsed.
    self.panel = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(1, 1),
        Position = UDim2.new(1, 0, 1, 0),
        Size = UDim2.new(1, 0, 1, -47),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        ZIndex = 1,

        BackgroundTransparency = 1, -- Open = ElementTransparency

        Parent = self.main,
    })

    self.panelStroke = self.window:StyleElementBody(self.panel)

    -- The card stacks the search bar over the list. The search bar is always present in
    -- the layout (it just grows/shrinks), so the gap under it is stable; the list is a
    -- flex-fill item, so it takes whatever height is left and slides down as search grows.
    self.window:Create("UIListLayout", {
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Vertical,
        VerticalAlignment = Enum.VerticalAlignment.Top,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.panel,
    })

    self.window:Create("UIPadding", {
        PaddingTop = UDim.new(0, 7),
        PaddingBottom = UDim.new(0, 6),

        Parent = self.panel,
    })

    self:_buildSearch()
    self:_buildQuickActions()

    self.list = self.window:Create("ScrollingFrame", {
        Active = true,
        Size = UDim2.new(1, 0, 0, 0), -- height comes from the UIFlexItem below
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        ClipsDescendants = true,
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        CanvasSize = UDim2.new(),
        ScrollBarImageColor3 = Color3.fromRGB(240, 240, 240),
        ScrollBarThickness = 3,
        ScrollBarImageTransparency = 1, -- scrollbar kept fully transparent
        ScrollingDirection = Enum.ScrollingDirection.Y,
        LayoutOrder = 3,
        ZIndex = 1,

        Parent = self.panel,
    })

    self.window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Fill,

        Parent = self.list,
    })

    self.listLayout = self.window:Create("UIListLayout", {
        Padding = UDim.new(0, 5),
        SortOrder = Enum.SortOrder.LayoutOrder,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,

        Parent = self.list,
    })

    self.window:Create("UIPadding", {
        PaddingBottom = UDim.new(0, 2),

        Parent = self.list,
    })

    -- Devlog 8: shown instead of the (now empty) option list when a search query matches
    -- nothing. A normal row in the same list/layout, sized the same as an option row so
    -- _openHeight's row math (which counts it in when visible) stays accurate.
    self.emptyLabel = self.window:Create("TextLabel", {
        Text = locale.t("No results found"),
        Size = UDim2.new(1, -12, 0, optionRowHeight),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 14,
        TextTransparency = 0.5,
        Visible = false,

        Parent = self.list,
    }, { TextColor3 = "PlaceholderColor", FontFace = "Font" })

    local function isOptionSelected(name)
        return table.find(self.value, name) ~= nil
    end

    local function renderOptionState(data, animate)
        local selected = isOptionSelected(data.name)
        local bgT = if self._isOpen then (selected and 0.9 or 0.95) else 1
        local titleT = if self._isOpen then (selected and 0 or 0.3) else 1
        -- Selected shows a bright check; unselected shows a faint dot
        local iconT = if self._isOpen then (selected and 0 or 0.7) else 1
        local strokeT = if self._isOpen then (selected and 0.85 or 0.93) else 1

        image.assign(data.checkIcon, "Image", if selected then checkIcon else dotIcon)

        if animate then
            local info = TweenInfo.new(0.3, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
            variables.tweenService:Create(data.frame, info, { BackgroundTransparency = bgT }):Play()
            variables.tweenService:Create(data.title, info, { TextTransparency = titleT }):Play()
            variables.tweenService:Create(data.checkIcon, info, { ImageTransparency = iconT }):Play()
            variables.tweenService:Create(data.stroke, info, { Transparency = strokeT }):Play()
        else
            data.frame.BackgroundTransparency = bgT
            data.title.TextTransparency = titleT
            data.checkIcon.ImageTransparency = iconT
            data.stroke.Transparency = strokeT
        end
    end

    local function updateSelectedLabel()
        if self.multiSelect then
            local n = #self.value
            if n == 0 then
                self.selectedLabel.Text = self.placeholderText
            elseif n == 1 then
                self.selectedLabel.Text = self.value[1]
            else
                self.selectedLabel.Text = locale.resolve("Various")
            end
        else
            self.selectedLabel.Text = self.value[1] or self.placeholderText
        end
    end

    self._renderOptionState = renderOptionState
    self._updateSelectedLabel = updateSelectedLabel

    local function buildOption(optionName)
        local frame = self.window:Create("Frame", {
            Size = UDim2.new(1, -12, 0, 38),
            BorderSizePixel = 0,

            BackgroundTransparency = 1,

            Parent = self.list,
        }, { BackgroundColor3 = "DropdownHighlight" })

        -- Radius is driven by adjacency in _updateCorners (7 flat / 12 rounded)
        local corner = self.window:Create("UICorner", {
            CornerRadius = flatRadius,
            Parent = frame,
        })

        -- Subtle stroke, only shown on the selected option
        local optionStroke = self.window:Create("UIStroke", {
            Color = Color3.fromRGB(255, 255, 255),
            Transparency = 1, -- selected = 0.85
            Parent = frame,
        })

        local interact = self.window:Create("TextButton", {
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            Text = "",
            TextTransparency = 1,
            ZIndex = 50,
            Parent = frame,
        })

        local container = self.window:Create("Frame", {
            AnchorPoint = Vector2.new(0, 0.5),
            Position = UDim2.new(0, 14, 0.5, 0),
            Size = UDim2.fromOffset(170, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ZIndex = 5,
            Parent = frame,
        })

        self.window:Create("UIListLayout", {
            Padding = UDim.new(0, 5),
            FillDirection = Enum.FillDirection.Horizontal,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder,
            Parent = container,
        })

        local checkIcon = self.window:Create("ImageLabel", {
            Image = "rbxassetid://" .. tostring(checkIcon),
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ImageTransparency = 1,
            ZIndex = 5,
            Parent = container,
        }, { ImageColor3 = "ContentColor" })

        local title = self.window:Create("TextLabel", {
            Text = optionName,
            Size = UDim2.fromOffset(170, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            TextSize = 16,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
            LayoutOrder = 1,
            TextTransparency = 1,
            ZIndex = 5,
            Parent = container,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })

        local data = {
            name = optionName,
            frame = frame,
            interact = interact,
            title = title,
            checkIcon = checkIcon,
            container = container,
            stroke = optionStroke,
            corner = corner,
            -- tracked per option so a rebuild tears them down with the frame
            connections = {},
        }

        table.insert(
            data.connections,
            self.window:ConnectFor(self, frame.MouseEnter, function()
                if not self._isOpen or not self.window:_interactive() then
                    return
                end
                if isOptionSelected(optionName) then
                    return
                end
                variables.tweenService
                    :Create(
                        frame,
                        TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                        { BackgroundTransparency = 0.9 }
                    )
                    :Play()
                variables.tweenService
                    :Create(
                        title,
                        TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                        { TextTransparency = 0.15 }
                    )
                    :Play()
            end)
        )

        table.insert(
            data.connections,
            self.window:ConnectFor(self, frame.MouseLeave, function()
                if not self._isOpen then
                    return
                end
                if isOptionSelected(optionName) then
                    return
                end
                variables.tweenService
                    :Create(
                        frame,
                        TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                        { BackgroundTransparency = 0.95 }
                    )
                    :Play()
                variables.tweenService
                    :Create(
                        title,
                        TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                        { TextTransparency = 0.3 }
                    )
                    :Play()
            end)
        )

        table.insert(
            data.connections,
            self.window:ConnectFor(self, interact.MouseButton1Click, function()
                -- options stay visible through the close tween; a click mid-fade must not land.
                -- locked forces the panel closed itself (see _applyLocked), but guard here too
                -- in case a click is already in flight the same frame it locks.
                if not self._isOpen or self.locked then
                    return
                end
                hapticEngine.click()
                soundEngine.click()
                local sel = isOptionSelected(optionName)

                if not self.multiSelect then
                    if sel then
                        self:_close()
                        return
                    end
                    self:Set({ optionName })
                    task.wait(0.1)
                    self:_close()
                    return
                end

                local newValue = table.clone(self.value)
                if sel then
                    local idx = table.find(newValue, optionName)
                    if idx then
                        table.remove(newValue, idx)
                    end
                else
                    table.insert(newValue, optionName)
                end

                self:Set(newValue)
            end)
        )

        return data
    end

    self._buildOption = buildOption

    -- Non-interactive section header row - only built for an option that's the first of its
    -- section (see self._sectionStarts above). Static transparency rather than tracking open/
    -- close like an option's own title does: self.main clips everything below 41px while
    -- closed regardless, so there's nothing to actually leak while collapsed.
    local function buildHeader(sectionName)
        local frame = self.window:Create("Frame", {
            Size = UDim2.new(1, -12, 0, 24),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,

            Parent = self.list,
        })
        local label = self.window:Create("TextLabel", {
            Text = locale.t(sectionName),
            Size = UDim2.new(1, -14, 1, 0),
            Position = UDim2.fromOffset(14, 0),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 12,
            Font = Enum.Font.GothamBold,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTransparency = 0.55,

            Parent = frame,
        }, { TextColor3 = "PlaceholderColor" })
        return { name = sectionName, frame = frame, label = label }
    end

    -- Builds every option (and, when sectioned, the header ahead of each section's first
    -- option) from self.options/self._sectionStarts, in order. Doesn't paint open/closed state
    -- or resize anything - callers (the initial build below, and Refresh) do that themselves
    -- afterward since they need it at different points in their own sequence.
    local function buildAllOptions()
        for _, opt in self.options do
            local sectionName = self._sectionStarts[opt]
            if sectionName then
                table.insert(self._headerFrames, buildHeader(sectionName))
            end
            local data = buildOption(opt)
            table.insert(self._optionFrames, data)
        end
    end
    self._buildAllOptions = buildAllOptions

    buildAllOptions()

    updateSelectedLabel()
    self:_updateCorners()

    -- Function
    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        if self.locked then
            return
        end
        hapticEngine.click()
        soundEngine.click()
        if self._isOpen then
            self:_close()
        else
            self:_open()
        end
    end)

    -- Hover feedback via the overlay + title only (stroke stays put - unlike _wireElementHover's
    -- elements, the header's stroke transparency also has to track open/close, so leaving hover
    -- out of it keeps those two animations from fighting over the same property).
    self.window:ConnectFor(self, self.main.MouseEnter, function()
        if self._isOpen or not self.window:_interactive() then
            return
        end
        variables.tweenService
            :Create(
                self.title,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { TextColor3 = self.window.theme.ElementTextHoverColor }
            )
            :Play()
        variables.tweenService
            :Create(
                self.hoverOverlay,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { BackgroundTransparency = 0.97 }
            )
            :Play()
    end)

    self.window:ConnectFor(self, self.main.MouseLeave, function()
        variables.tweenService
            :Create(
                self.title,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { TextColor3 = self.window.theme.ContentColor }
            )
            :Play()
        variables.tweenService
            :Create(
                self.hoverOverlay,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { BackgroundTransparency = 1 }
            )
            :Play()
    end)

    self.window:_wireTooltip(self)

    -- pinned to the header's right edge, same spot the chevron sits - _applyLocked hides the
    -- chevron/selected-value text in favour of this + the padlock, there isn't room for both
    self.lockIcon = self.window:_buildLockIcon(self.top, UDim2.new(1, -18, 0.5, 0), Vector2.new(1, 0.5))
    self.prohibitedIcon = self.window:_buildProhibitedIcon(self.container)
    self:_applyLocked(false)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- Search bar: collapsed it's just the icon (centred, no bar); tapping expands it into a
-- full field. It's always in the card's layout - only its height/fills animate - so the
-- list below just flexes down as it grows.
-- what the dev's callback receives. multiSelect hands out a copy: the live table is our
-- selection state, and a dev who keeps or mutates it would corrupt the dropdown.
function Dropdown:_callbackValue()
    if self.multiSelect then
        return table.clone(self.value)
    end
    return self.value[1]
end

function Dropdown:_buildSearch()
    self._searchOpen = false

    self.searchbar = self.window:Create("Frame", {
        Name = "Search",
        Size = UDim2.new(1, -12, 0, searchCollapsedHeight),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 1, -- expanded = 0.92
        LayoutOrder = 1,
        ClipsDescendants = false,
        ZIndex = 1,

        Parent = self.panel,
    })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(0, 12),
        Parent = self.searchbar,
    })

    self.searchStroke = self.window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),
        Transparency = 1, -- expanded = 0.86
        Parent = self.searchbar,
    })

    self.searchShadow = self.window:CreateGlow(self.searchbar, Color3.fromRGB(255, 255, 255), 20, 1) -- expanded = 0.92

    -- Full-bar tap target: expands the bar while it's collapsed. Kept above the option
    -- hit-targets (ZIndex 50) so taps here never bleed through to an option under them.
    self.searchToggle = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        Text = "",
        TextTransparency = 1,
        ZIndex = 51,
        Parent = self.searchbar,
    })

    self.searchInput = self.window:Create("TextBox", {
        Text = "",
        PlaceholderText = locale.t("Search..."),
        Size = UDim2.new(1, -58, 0, 16),
        Position = UDim2.new(0, 44, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        ClearTextOnFocus = false,
        TextEditable = false, -- enabled on expand
        Interactable = false, -- collapsed: let taps fall through to the toggle
        ZIndex = 52,

        TextTransparency = 1, -- expanded = 0.3

        Parent = self.searchbar,
    }, { TextColor3 = "ContentColor", FontFace = "Font", PlaceholderColor3 = "PlaceholderColor" })

    self.searchIcon = self.window:Create("ImageButton", {
        Image = "rbxassetid://" .. tostring(searchIconAsset),
        Size = UDim2.fromOffset(20, 20),
        Position = UDim2.new(0, 24, 0.5, 0), -- left-aligned (centre at x=24, edge at 14)
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundTransparency = 1,
        ScaleType = Enum.ScaleType.Fit,
        AutoButtonColor = false,
        ZIndex = 53,

        ImageTransparency = 1, -- In = 0.5

        Parent = self.searchbar,
    }, { ImageColor3 = "ContentColor" })

    self.window:ConnectFor(self, self.searchToggle.MouseButton1Click, function()
        if not self._searchOpen then
            self:_expandSearch()
        end
    end)
    self.window:ConnectFor(self, self.searchIcon.MouseButton1Click, function()
        if self._searchOpen then
            self:_collapseSearch()
        else
            self:_expandSearch()
        end
    end)
    self.window:ConnectFor(self, self.searchInput:GetPropertyChangedSignal("Text"), function()
        self:_applyFilter(self.searchInput.Text)
    end)
    self.window:ConnectFor(self, self.searchInput.FocusLost, function()
        if self.searchInput.Text == "" then
            self:_collapseSearch()
        end
    end)
end

function Dropdown:_expandSearch()
    if self._searchOpen then
        return
    end
    self._searchOpen = true
    self.searchInput.TextEditable = true
    self.searchInput.Interactable = true

    variables.tweenService
        :Create(
            self.searchbar,
            searchTween,
            { Size = UDim2.new(1, -12, 0, searchExpandedHeight), BackgroundTransparency = 0.92 }
        )
        :Play()
    variables.tweenService:Create(self.searchStroke, searchTween, { Transparency = 0.86 }):Play()
    variables.tweenService:Create(self.searchShadow, searchTween, { Transparency = 0.92 }):Play()
    variables.tweenService:Create(self.searchInput, searchTween, { TextTransparency = 0.3 }):Play()

    self.searchInput:CaptureFocus()
end

function Dropdown:_collapseSearch()
    if not self._searchOpen then
        return
    end
    self._searchOpen = false
    self.searchInput.TextEditable = false
    self.searchInput.Interactable = false
    self.searchInput:ReleaseFocus()
    self.searchInput.Text = "" -- fires the filter, showing everything again

    variables.tweenService
        :Create(
            self.searchbar,
            searchTween,
            { Size = UDim2.new(1, -12, 0, searchCollapsedHeight), BackgroundTransparency = 1 }
        )
        :Play()
    variables.tweenService:Create(self.searchStroke, searchTween, { Transparency = 1 }):Play()
    variables.tweenService:Create(self.searchShadow, searchTween, { Transparency = 1 }):Play()
    variables.tweenService:Create(self.searchInput, searchTween, { TextTransparency = 1 }):Play()
end

-- Quick text-button row between the search bar and the option list. "Clear" shows on every
-- dropdown (a one-tap way to empty the selection without hunting for whichever option is
-- currently checked); "Select all" only makes sense once there can be more than one selected
-- option, so it's multiSelect-only. Both act on whatever's currently VISIBLE, so an active search
-- filter scopes them to just the filtered options rather than the dropdown's full option set.
function Dropdown:_buildQuickActions()
    self.quickActionsRow = self.window:Create("Frame", {
        Name = "QuickActions",
        Size = UDim2.new(1, -12, 0, quickActionsRowHeight),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 2,

        Parent = self.panel,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 14),
        VerticalAlignment = Enum.VerticalAlignment.Center,

        Parent = self.quickActionsRow,
    })

    local function buildQuickAction(text, order)
        local button = self.window:Create("TextButton", {
            Text = locale.t(text),
            Size = UDim2.fromOffset(0, 16),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            TextSize = 13,
            Font = Enum.Font.GothamBold,
            AutoButtonColor = false,
            LayoutOrder = order,

            TextTransparency = 1, -- In = 0.35 (see _open/_close)

            Parent = self.quickActionsRow,
        }, { TextColor3 = "PlaceholderColor" })

        self.window:ConnectFor(self, button.MouseEnter, function()
            if not self._isOpen or not self.window:_interactive() then
                return
            end
            variables.tweenService
                :Create(
                    button,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                    { TextColor3 = self.window.theme.ElementTextHoverColor }
                )
                :Play()
        end)
        self.window:ConnectFor(self, button.MouseLeave, function()
            variables.tweenService
                :Create(
                    button,
                    TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                    { TextColor3 = self.window.theme.PlaceholderColor }
                )
                :Play()
        end)

        return button
    end

    if self.multiSelect then
        self.selectAllButton = buildQuickAction("Select all", 1)
        self.window:ConnectFor(self, self.selectAllButton.MouseButton1Click, function()
            if not self._isOpen or self.locked then
                return
            end
            hapticEngine.click()
            soundEngine.click()
            self:_selectAllVisible()
        end)
    end

    self.clearButton = buildQuickAction("Clear", 2)
    self.window:ConnectFor(self, self.clearButton.MouseButton1Click, function()
        if not self._isOpen or self.locked then
            return
        end
        hapticEngine.click()
        soundEngine.click()
        self:_clearVisible()
    end)
end

-- Shared tail for _selectAllVisible/_clearVisible: repaint, tell the dev, and save - the same
-- three steps a single option click already does after touching self.value.
function Dropdown:_afterValueChanged()
    self._desiredValue = table.clone(self.value)
    for _, data in self._optionFrames do
        self._renderOptionState(data, true)
    end
    self._updateSelectedLabel()
    self.window:_runGuarded(self, self.callback, self:_callbackValue())
    self.window:_persist(self)
end

function Dropdown:_selectAllVisible()
    local changed = false
    for _, data in self._optionFrames do
        if data.frame.Visible and not table.find(self.value, data.name) then
            table.insert(self.value, data.name)
            changed = true
        end
    end
    if changed then
        self:_afterValueChanged()
    end
end

function Dropdown:_clearVisible()
    local changed = false
    for _, data in self._optionFrames do
        if data.frame.Visible then
            local idx = table.find(self.value, data.name)
            if idx then
                table.remove(self.value, idx)
                changed = true
            end
        end
    end
    if changed then
        self:_afterValueChanged()
    end
end

function Dropdown:_applyFilter(query)
    query = string.lower(query or "")
    local anyOptionVisible = false
    for _, data in self._optionFrames do
        local visible = query == "" or string.find(string.lower(data.name), query, 1, true) ~= nil
        data.frame.Visible = visible
        anyOptionVisible = anyOptionVisible or visible
    end
    -- a header shows only while at least one option in its own section still matches
    for _, header in self._headerFrames do
        local anyVisible = false
        for _, data in self._optionFrames do
            if self._sectionOf[data.name] == header.name and data.frame.Visible then
                anyVisible = true
                break
            end
        end
        header.frame.Visible = anyVisible
    end
    self.emptyLabel.Visible = query ~= "" and not anyOptionVisible
    self:_updateCorners()
    self:_resizeToOptions()
end

-- match the panel to whats visible. only while open: closed height is the header alone.
function Dropdown:_resizeToOptions()
    if not self._isOpen then
        return
    end
    variables.tweenService:Create(self.main, searchTween, { Size = UDim2.new(1, -20, 0, self:_openHeight()) }):Play()
end

-- Per-corner rounding: an option's top corners round off only when nothing sits above it,
-- and its bottom corners only when nothing sits below - so a run of options reads as one
-- grouped block with rounded outer edges and sharp seams (a lone option is fully rounded).
-- Runs over the currently VISIBLE options, so it re-groups correctly while searching. A
-- section header breaks the run too (self._sectionStarts), so each section rounds off on its
-- own instead of reading as one continuous block across a header.
function Dropdown:_updateCorners()
    local visible = {}
    for _, data in self._optionFrames do
        if data.frame.Visible then
            table.insert(visible, data)
        end
    end

    for i, data in visible do
        local startsRun = i == 1 or self._sectionStarts[data.name] ~= nil
        local nextStartsRun = visible[i + 1] and self._sectionStarts[visible[i + 1].name] ~= nil
        local endsRun = i == #visible or nextStartsRun
        local topR = if startsRun then roundRadius else flatRadius
        local botR = if endsRun then roundRadius else flatRadius
        data.corner.TopLeftRadius = topR
        data.corner.TopRightRadius = topR
        data.corner.BottomLeftRadius = botR
        data.corner.BottomRightRadius = botR
    end
end

-- Open height sized to the options (header + search + paddings + rows + any section headers),
-- capped so long lists scroll instead of running off the window - the cap itself is sized to
-- maxVisibleOptionRows full rows (see above), not a flat number, so it still guarantees that many
-- rows show even when the multi-select controls row adds its own height on top. Short lists open
-- just tall enough, no dead space. Sized from what's actually on screen, so a search filter (or
-- an Add/Remove while open) grows and shrinks the panel to fit rather than leaving dead space.
function Dropdown:_openHeight()
    local n = 0
    for _, data in self._optionFrames do
        if data.frame.Visible then
            n += 1
        end
    end
    local h = 0
    for _, header in self._headerFrames do
        if header.frame.Visible then
            h += 1
        end
    end
    if self.emptyLabel and self.emptyLabel.Visible then
        n += 1 -- the "no results" row takes the same space a normal option row would
    end
    local rows = n * optionRowHeight + h * 24 + math.max(0, n + h - 1) * rowGap + 2
    local base = 95 + quickActionsRowHeight + quickActionsRowGap -- the Clear row is always built now
    return math.min(base + capRowsHeight, base + rows)
end

function Dropdown:_open()
    if self._isOpen or self.locked then
        return
    end
    self._isOpen = true

    if self._outsideClickConn then
        self.window:Disconnect(self._outsideClickConn)
    end
    self._outsideClickConn = self.window:Connect(variables.userInputService.InputBegan, function(input)
        if
            input.UserInputType ~= Enum.UserInputType.MouseButton1
            and input.UserInputType ~= Enum.UserInputType.Touch
        then
            return
        end

        local pos = input.Position
        local mainPos = self.main.AbsolutePosition
        local mainSize = self.main.AbsoluteSize
        if
            pos.X < mainPos.X
            or pos.X > mainPos.X + mainSize.X
            or pos.Y < mainPos.Y
            or pos.Y > mainPos.Y + mainSize.Y
        then
            self:_close()
        end
    end)

    local targetHeight = self:_openHeight()

    variables.tweenService
        :Create(
            self.main,
            TweenInfo.new(0.5, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            { Size = UDim2.new(1, -20, 0, targetHeight) }
        )
        :Play()
    variables.tweenService
        :Create(
            self.chevron,
            TweenInfo.new(0.7, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            { Rotation = 0 }
        )
        :Play()
    variables.tweenService
        :Create(
            self.panel,
            TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { BackgroundTransparency = self.window.theme.ElementTransparency or 0 }
        )
        :Play()
    variables.tweenService
        :Create(
            self.panelStroke,
            TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { Transparency = self.window.theme.ElementStrokeTransparency }
        )
        :Play()
    variables.tweenService
        :Create(
            self.searchIcon,
            TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { ImageTransparency = 0.5 }
        )
        :Play()

    if self.selectAllButton then
        variables.tweenService
            :Create(
                self.selectAllButton,
                TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { TextTransparency = 0.35 }
            )
            :Play()
    end
    if self.clearButton then
        variables.tweenService
            :Create(
                self.clearButton,
                TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { TextTransparency = 0.35 }
            )
            :Play()
    end

    for _, data in self._optionFrames do
        self._renderOptionState(data, true)
    end

    self:_scrollIntoView(targetHeight)
end

-- Devlog 8: if opening would push the panel's bottom edge below what's actually on screen (the
-- dropdown sits near the end of a tab/page), nudge the parent ScrollingFrame's CanvasPosition
-- down just enough to bring it fully into view instead of opening cut off past the viewport.
-- Walks up to the nearest ScrollingFrame ancestor rather than assuming self.tab.tabPage directly
-- - a dropdown nested in a Group/Collapsible sits inside a plain Frame, not the tab's own page.
function Dropdown:_scrollIntoView(targetHeight)
    local page = self.main:FindFirstAncestorWhichIsA("ScrollingFrame")
    if not page then
        return
    end

    local viewTop = page.AbsolutePosition.Y
    local viewBottom = viewTop + page.AbsoluteWindowSize.Y
    local dropdownTop = self.main.AbsolutePosition.Y
    local dropdownBottom = dropdownTop + targetHeight

    local overflow = dropdownBottom - viewBottom
    if overflow <= 0 then
        return
    end

    -- No manual max-scroll clamp: page.CanvasSize can still read stale/zero right after a tab
    -- switch (AutomaticCanvasSize hasn't caught up to the just-shown content yet - live-caught
    -- this capping every scroll to 0). Roblox already clamps CanvasPosition itself when it's set
    -- past what the canvas actually has, so handing it a generous target is safe either way.
    local margin = 10
    local targetY = page.CanvasPosition.Y + overflow + margin

    variables.tweenService
        :Create(
            page,
            TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { CanvasPosition = Vector2.new(page.CanvasPosition.X, targetY) }
        )
        :Play()
end

function Dropdown:_close()
    if not self._isOpen then
        return
    end
    self._isOpen = false

    if self._outsideClickConn then
        self.window:Disconnect(self._outsideClickConn)
        self._outsideClickConn = nil
    end

    self:_collapseSearch()

    variables.tweenService
        :Create(
            self.chevron,
            TweenInfo.new(0.7, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            { Rotation = 180 }
        )
        :Play()
    variables.tweenService
        :Create(
            self.panel,
            TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { BackgroundTransparency = 1 }
        )
        :Play()
    variables.tweenService
        :Create(
            self.panelStroke,
            TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { Transparency = 1 }
        )
        :Play()
    variables.tweenService
        :Create(
            self.searchIcon,
            TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { ImageTransparency = 1 }
        )
        :Play()

    if self.selectAllButton then
        variables.tweenService
            :Create(
                self.selectAllButton,
                TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { TextTransparency = 1 }
            )
            :Play()
    end
    if self.clearButton then
        variables.tweenService
            :Create(
                self.clearButton,
                TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { TextTransparency = 1 }
            )
            :Play()
    end

    for _, data in self._optionFrames do
        self._renderOptionState(data, true)
    end

    variables.tweenService
        :Create(
            self.main,
            TweenInfo.new(0.5, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            { Size = UDim2.new(1, -20, 0, 41) }
        )
        :Play()
end

-- tear an option down through the window registries, so rebuild churn doesnt leak tracked
-- instances (which would slow ChangeTheme forever) or dead connections
function Dropdown:_destroyOption(data)
    if data.connections then
        for _, connection in data.connections do
            local idx = table.find(self.connections, connection)
            if idx then
                table.remove(self.connections, idx)
            end
            self.window:Disconnect(connection)
        end
        data.connections = nil
    end
    self.window:DestroySubtree(data.frame)
end

-- Replaces the option pool with a plain flat list. Any section grouping the dropdown was built
-- with is dropped here, since a bare name list gives no way to know which section a name
-- belongs to - a sectioned dropdown that needs to reload its options would need a dedicated
-- API this doesn't attempt to be.
function Dropdown:Refresh(newOptions)
    self.options = dedupStrings(newOptions or {})
    self._sectionStarts = {}
    self._sectionOf = {}

    for _, data in self._optionFrames do
        self:_destroyOption(data)
    end
    table.clear(self._optionFrames)
    for _, header in self._headerFrames do
        self.window:DestroySubtree(header.frame)
    end
    table.clear(self._headerFrames)

    -- re-derive the visible selection from the full intent: an option that loads now (or
    -- comes back) re-selects, one that's genuinely gone drops out. self.value only ever holds
    -- real options, so the saved config never carries a stale selection across sessions.
    local previous = self.value
    self.value = intersectWithOptions(self._desiredValue or self.value, self.options)
    local selectionChanged = not sameSelection(self.value, previous)

    self:_buildAllOptions()
    -- fresh frames default to the closed look, so paint the open state if the panel is
    -- already open (otherwise they'd sit blank until hovered)
    if self._isOpen then
        for _, data in self._optionFrames do
            self._renderOptionState(data, false)
        end
    end

    self._updateSelectedLabel()
    -- reconcile with any active search (also refreshes corners); empty query shows all
    self:_applyFilter(if self._searchOpen then self.searchInput.Text else "")

    -- the visible selection changed (options arrived or dropped): tell the dev and save it
    if selectionChanged then
        self.window:_runGuarded(self, self.callback, self:_callbackValue())
        self.window:_persist(self)
    end
end

function Dropdown:Add(option)
    if typeof(option) ~= "string" or option == "" then
        return
    end
    if table.find(self.options, option) then
        return
    end

    table.insert(self.options, option)
    local data = self._buildOption(option)
    table.insert(self._optionFrames, data)

    if self._isOpen then
        self._renderOptionState(data, true)
    end

    -- reconcile with any active search rather than showing an option the query excludes,
    -- and resize for the new row (also refreshes corners)
    self:_applyFilter(if self._searchOpen then self.searchInput.Text else "")
end

function Dropdown:Remove(option)
    local idx = table.find(self.options, option)
    if not idx then
        return
    end

    table.remove(self.options, idx)

    for i, data in self._optionFrames do
        if data.name == option then
            self:_destroyOption(data)
            table.remove(self._optionFrames, i)
            break
        end
    end

    local valueIdx = table.find(self.value, option)
    if valueIdx then
        table.remove(self.value, valueIdx)
        self._desiredValue = table.clone(self.value)
        self._updateSelectedLabel()
        -- removing a selected option changes the selection; surface and save that
        self.window:_runGuarded(self, self.callback, self:_callbackValue())
        self.window:_persist(self)
    end

    -- one row shorter; resize and re-corner around whats left
    self:_applyFilter(if self._searchOpen then self.searchInput.Text else "")
end

function Dropdown:Set(value, skipCallback)
    local newValue = normalizeValue(value, self.multiSelect)
    -- keep the full request so options that arrive later can restore it (see Refresh)
    self._desiredValue = newValue
    self.value = intersectWithOptions(newValue, self.options)

    for _, data in self._optionFrames do
        self._renderOptionState(data, true)
    end
    self._updateSelectedLabel()

    if not skipCallback then
        self.window:_runGuarded(self, self.callback, self:_callbackValue())
        self.window:_persist(self) -- skipCallback means apply quietly, so dont autosave either
    end
end

-- Clears the active selection back to the placeholder - a plain Set(nil) under the hood, since
-- an empty self.value is exactly what already makes updateSelectedLabel fall back to it.
function Dropdown:Reset(skipCallback)
    self:Set(nil, skipCallback)
end

-- Dim the header, show the padlock (see window.luau's shared _buildLockIcon/_applyLockedVisual)
-- and the "no entry" glyph, hide the chevron/selected-value text in favour of the padlock (no
-- room for both), and force-close if it's open when locked.
function Dropdown:_applyLocked(animate)
    self.window:_applyLockedVisual(self, animate)
    local info = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local set = function(instance, props)
        if animate then
            variables.tweenService:Create(instance, info, props):Play()
        else
            for prop, value in props do
                instance[prop] = value
            end
        end
    end
    set(self.chevron, { ImageTransparency = if self.locked then 1 else 0.5 })
    set(self.selectedLabel, { TextTransparency = if self.locked then 1 else 0.5 })
    if self.locked and self._isOpen then
        self:_close()
    end
end

function Dropdown:SetLocked(locked)
    locked = locked and true or false
    if locked == self.locked then
        return
    end
    self.locked = locked
    self:_applyLocked(true)
end

-- Lock/Unlock/IsLocked: the shared naming lockable.luau gives every other locking-capable
-- element - aliased into this component's own pre-existing SetLocked/padlock-icon dimming
-- rather than the mixin's scrim (see lockable.luau's own header comment). `reason` isn't
-- supported here.
function Dropdown:Lock()
    self:SetLocked(true)
end
function Dropdown:Unlock()
    self:SetLocked(false)
end
function Dropdown:IsLocked(): boolean
    return self.locked == true
end

function Dropdown:_setShown(shown, animate)
    -- Custom reveal: main is a transparent wrapper, so reveal the header card (self.top)
    -- rather than main. The options card fades in on open, not here.
    -- Locked-aware title/chevron/selected-value targets, computed as this call's own target
    -- rather than a second tween chasing it in afterward - two simultaneous tweens on the same
    -- property fight each other frame to frame instead of one cleanly winning (the same class
    -- of bug as the tab indicator's own tween race).
    local w = self.window
    local titleTransparency = if self.locked then 0.6 else 0
    local sideTransparency = if self.locked then 1 else 0.5 -- chevron + selected-value text
    w:_reveal(self.stroke, { Transparency = if shown then w.theme.ElementStrokeTransparency else 1 }, animate)
    w:_reveal(self.title, { TextTransparency = if shown then titleTransparency else 1 }, animate)
    w:_reveal(self.top, { BackgroundTransparency = if shown then (w.theme.ElementTransparency or 0) else 1 }, animate)
    if self.iconLabel then
        w:_reveal(self.iconLabel, { ImageTransparency = if shown then titleTransparency else 1 }, animate)
    end
    if self.descriptor then
        w:_reveal(self.descriptor.titleLabel, { TextTransparency = if shown then 0.7 else 1 }, animate)
    end
    w:_reveal(self.selectedLabel, { TextTransparency = if shown then sideTransparency else 1 }, animate)
    w:_reveal(self.chevron, { ImageTransparency = if shown then sideTransparency else 1 }, animate)

    -- lockIcon/prohibitedIcon.Visible aren't touched by any of the above, so they don't need
    -- re-asserting here - only _applyLocked/SetLocked ever change them

    -- if the window hides while we're open, collapse so we dont reopen mid-air
    if not shown and self._isOpen then
        self:_close()
    end
end

-- Devlog 7: was five hand-rolled Move* methods identical to every other component's own
-- copy-paste - consolidated onto the shared mixin (also picks up :SetVisible for free).
moveable(Dropdown)

return Dropdown
]=====]

sources["components/flipbutton"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A Button that carries two labels. Hovering flips the title between them (a clipped container
-- squishes shut, swaps text, springs back open - Roblox UI has no real 3D, so this is the fake
-- card-flip every UI kit leans on). Clicking still runs the callback like a normal Button.

local FlipButton = {}
FlipButton.__index = FlipButton
FlipButton.__type = "FlipButton"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local titleHeight = 16

function FlipButton.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Button",
        secondaryName = properties.secondaryName
            or properties.SecondaryName
            or properties.backText
            or properties.BackText,
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        compact = tab.compact or false,

        callback = properties.callback or properties.Callback or function() end,

        _showingBack = false,
    }, FlipButton)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self.window:_wireTooltip(self)

    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- callback + red error-flash, shared by both layouts
function FlipButton:_runCallback()
    self.window:_runGuarded(self, self.callback)
end

-- the clipped title wrapper both layouts flip. fixed to the wider of the two faces so the
-- squish/reopen never reflows anything next to it.
function FlipButton:_buildFlipContainer(parent, layoutOrder)
    local window = self.window
    local font = window.theme.Font

    self._frontWidth = functions.textWidth(font, 16, self.name)
    self._backWidth = functions.textWidth(font, 16, self.secondaryName or "")
    self._faceWidth = math.max(self._frontWidth, self._backWidth, 1)

    self.flipContainer = window:Create("Frame", {
        Size = UDim2.fromOffset(self._faceWidth, titleHeight),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ClipsDescendants = true,
        LayoutOrder = layoutOrder,

        Parent = parent,
    })

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.new(1, 0, 1, 0),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,

        TextTransparency = 1, -- In = 0

        Parent = self.flipContainer,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    return self.flipContainer
end

-- squish shut, swap the label at the bottom (hidden by the clip), spring back open
local closeInfo = TweenInfo.new(0.14, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
local openInfo = TweenInfo.new(0.28, Enum.EasingStyle.Back, Enum.EasingDirection.Out)

function FlipButton:_flip(showBack)
    if not self.secondaryName or self.secondaryName == "" then
        return -- nothing to flip to
    end
    if self._showingBack == showBack then
        return
    end
    self._showingBack = showBack

    self._flipToken = (self._flipToken or 0) + 1
    local token = self._flipToken

    local ts = variables.tweenService
    ts:Create(self.flipContainer, closeInfo, { Size = UDim2.fromOffset(0, titleHeight) }):Play()

    -- task.delay rather than Tween.Completed: a same-property tween created before this one
    -- finishes (a quick re-hover) cancels it, and a cancelled tween's Completed is unreliable
    -- across executors. A plain delay always fires, and the token guard still drops it if a
    -- newer flip has since taken over the container.
    task.delay(closeInfo.Time, function()
        if self._flipToken ~= token then
            return -- superseded by a newer flip; that one owns the container now
        end
        self.title.Text = locale.resolve(showBack and self.secondaryName or self.name)
        ts:Create(self.flipContainer, openInfo, { Size = UDim2.fromOffset(self._faceWidth, titleHeight) }):Play()
    end)
end

-- Hover flips the title for a mouse; MouseEnter/MouseLeave never fire for touch at all, so
-- without this a phone never sees the back face. A tap toggles it instead - same _flip, just a
-- different trigger. Shared by both layouts so the two builds can't drift out of sync on this.
function FlipButton:_wireFlipTrigger()
    self.window:ConnectFor(self, self.interact.MouseEnter, function()
        if not self.window:_interactive() then
            return
        end
        self:_flip(true)
    end)
    self.window:ConnectFor(self, self.interact.MouseLeave, function()
        self:_flip(false)
    end)
    self.window:ConnectFor(self, self.interact.InputBegan, function(input)
        if input.UserInputType ~= Enum.UserInputType.Touch or not self.window:_interactive() then
            return
        end
        self:_flip(not self._showingBack)
    end)
end

-- full-width: icon left, flipping title beside it, width-bounce on press (matches button.luau)
function FlipButton:_buildFull()
    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 43),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = 0

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)

    self.container = self.window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.main,
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.containerLayout = self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self:_buildFlipContainer(self.container, 1)

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        TextTransparency = 1,

        Parent = self.main,
    })

    self.window:_wireElementHover(self)
    self:_wireFlipTrigger()

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()
        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -26, 0, 43) }
            )
            :Play()

        self:_runCallback()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -20, 0, 43) }
            )
            :Play()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- compact (row): content-sized, centred icon + flipping title, no width-bounce
function FlipButton:_buildCompact()
    local window = self.window

    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name)
    self.hoverOverlay = self.interact

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 16),
        PaddingRight = UDim.new(0, 16),

        Parent = self.interact,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        Padding = UDim.new(0, 6),

        Parent = self.interact,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.interact,
        }, { ImageColor3 = "ContentColor" })
    end

    self:_buildFlipContainer(self.interact, 1)

    self.window:_wireElementHover(self)
    self:_wireFlipTrigger()

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()

        self:_runCallback()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

function FlipButton:_setShown(shown, animate)
    if shown then
        self.window:_revealCommon(self, animate)
    else
        self.window:_hideCommon(self, animate)
    end
end

-- Update either face without rebuilding. Pass nil to leave a face as-is. Resizes the flip
-- container (tweened, like the input/keybind pill) when the wider face changes.
function FlipButton:Set(front, back)
    if front ~= nil then
        self.name = tostring(front)
    end
    if back ~= nil then
        self.secondaryName = tostring(back)
    end

    local font = self.window.theme.Font
    self._frontWidth = functions.textWidth(font, 16, self.name)
    self._backWidth = functions.textWidth(font, 16, self.secondaryName or "")
    local faceWidth = math.max(self._frontWidth, self._backWidth, 1)

    if faceWidth ~= self._faceWidth then
        self._faceWidth = faceWidth
        variables.tweenService
            :Create(self.flipContainer, constants.pillResizeInfo, { Size = UDim2.fromOffset(faceWidth, titleHeight) })
            :Play()
    end

    self.title.Text = locale.resolve(self._showingBack and self.secondaryName or self.name)
end

-- Room the compact flip button needs before its label would clip: side padding + icon
-- (and its gap) if shown + the wider of the two faces.
function FlipButton:_minWidth()
    local w = 32 -- interact padding, 16 each side
    if self.icon then
        w += 22 -- 16 icon + 6 gap to title
    end
    w += self._faceWidth or functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

moveable(FlipButton)
lockable(FlipButton)

return FlipButton
]=====]

sources["components/gradientpicker"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 5: a collapsed header pill (name + a live gradient swatch + optional glow) that opens
-- into a stops rail (drag to reposition, add/remove) and the shared hsvEditor (hsvEditor.luau,
-- also used by ColorPicker) bound to whichever stop is selected. Value is a real ColorSequence,
-- built fresh from the stop list on every change.

local GradientPicker = {}
GradientPicker.__index = GradientPicker
GradientPicker.__type = "GradientPicker"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local hsvEditor = require(utility.hsvEditor)

local headerHeight = 44
local squareSize = 140
local narrowWidth = 380
local glowOnTransparency = 0.55
local minStops = 2
local maxStops = 8
local swatchSize = UDim2.fromOffset(44, 22)

local fadeInfo = TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
-- closing fades faster than it opens, and faster than the card shrinks, so the content is
-- gone before (or right as) the height tween finishes instead of visibly cutting off mid-fade
local closeFadeInfo = TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local openInfo = TweenInfo.new(0.5, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
-- closing height: Quart out, quick and clean, no overshoot (a shrink bouncing past its target
-- and back would read as jittery, not springy)
local heightInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
-- opening height: Back out - grows slightly past the final height then eases back, a little
-- bounce of "life" instead of a mechanical stop
local heightOpenInfo = TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local chevronInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
local dragInfo = TweenInfo.new(0.12, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local heldInfo = TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
-- header swatch "pop" on click - a quick squash out, a springier settle back
local popOutInfo = TweenInfo.new(0.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local popBackInfo = TweenInfo.new(0.28, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
-- glow pulse on open: flashes brighter than the steady-state glow, then relaxes back down to it
local glowPulseInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local glowRelaxInfo = TweenInfo.new(0.4, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
-- preview bar wipe-reveal cover
local wipeInfo = TweenInfo.new(0.35, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
-- stop handles popping in with a spring, staggered per handle
local handleSpringInfo = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
-- delay between each staggered reveal group/handle when opening
local staggerStep = 0.05

local function clamp01(n)
    return math.clamp(n, 0, 1)
end

-- Sort by time, clamp the outer keypoints to exactly 0/1 (Roblox requires it), and nudge any
-- collapsed duplicates apart so ColorSequence.new never sees two keypoints at the same Time.
local function buildSequence(stops)
    local sorted = table.clone(stops)
    table.sort(sorted, function(a, b)
        return a.time < b.time
    end)

    local keypoints = {}
    for i, stop in sorted do
        local t = stop.time
        if i == 1 then
            t = 0
        elseif i == #sorted then
            t = 1
        end
        table.insert(keypoints, { time = t, color = stop.color })
    end
    for i = 2, #keypoints do
        if keypoints[i].time <= keypoints[i - 1].time then
            keypoints[i].time = math.min(1, keypoints[i - 1].time + 0.001)
        end
    end

    local built = {}
    for _, kp in keypoints do
        table.insert(built, ColorSequenceKeypoint.new(kp.time, kp.color))
    end
    return ColorSequence.new(built)
end

-- Roblox doesn't expose a Luau-side "sample this ColorSequence at t" helper (that's baked into
-- UIGradient's own renderer), so a new stop's starting colour is interpolated by hand between
-- its two nearest sorted neighbours.
local function colorAt(stops, t)
    local sorted = table.clone(stops)
    table.sort(sorted, function(a, b)
        return a.time < b.time
    end)
    if #sorted == 0 then
        return Color3.fromRGB(255, 255, 255)
    end
    if t <= sorted[1].time then
        return sorted[1].color
    end
    if t >= sorted[#sorted].time then
        return sorted[#sorted].color
    end
    for i = 1, #sorted - 1 do
        local a, b = sorted[i], sorted[i + 1]
        if t >= a.time and t <= b.time then
            local span = b.time - a.time
            local alpha = if span > 0 then (t - a.time) / span else 0
            return a.color:Lerp(b.color, alpha)
        end
    end
    return sorted[#sorted].color
end

-- Accepts a ColorSequence, or a plain list of {time, color} / {Color3, Color3, ...} (evenly
-- spread), or nil for a sensible default two-stop gradient.
local function normalizeStops(value)
    if typeof(value) == "ColorSequence" then
        local stops = {}
        for _, kp in value.Keypoints do
            table.insert(stops, { time = kp.Time, color = kp.Value })
        end
        return stops
    end
    if typeof(value) == "table" and #value > 0 then
        local stops = {}
        local isColorList = typeof(value[1]) == "Color3"
        for i, entry in value do
            if isColorList then
                table.insert(stops, { time = (i - 1) / math.max(1, #value - 1), color = entry })
            else
                table.insert(stops, {
                    time = clamp01(entry.time or entry.Time or 0),
                    color = entry.color or entry.Color or Color3.fromRGB(255, 255, 255),
                })
            end
        end
        -- ColorSequence.new needs at least 2 keypoints; a single-colour list still has to make
        -- a valid (if flat) gradient rather than error the whole element out.
        if #stops == 1 then
            table.insert(stops, { time = 1, color = stops[1].color })
        end
        return stops
    end
    return {
        { time = 0, color = Color3.fromRGB(52, 199, 89) },
        { time = 1, color = Color3.fromRGB(10, 132, 255) },
    }
end

function GradientPicker.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Gradient Picker",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,

        callback = properties.callback or properties.Callback or function() end,

        _isOpen = false,
        showGlow = if properties.glow ~= nil
            then properties.glow
            elseif properties.Glow ~= nil then properties.Glow
            else true,
    }, GradientPicker)

    self.stops = normalizeStops(
        properties.gradient or properties.Gradient or properties.value or properties.Value or properties.colors
    )
    self.selected = self.stops[1]
    self.value = buildSequence(self.stops)

    self.flag = properties.flag
        or properties.Flag
        or (not self.forgetState and functions.deriveFlagFromName(self.name) or nil)
    self.window:_registerControl(self)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, headerHeight),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)

    -- UIShadow only takes one flat Color3 - a single glow can't actually shimmer with the whole
    -- gradient. Layering three, sampled at 0/0.5/1 across the current stops and each softly
    -- blurred+transparent, blends into a real multi-hue halo instead of one flat tint.
    self.previewGlows = {}
    for _ = 1, 3 do
        table.insert(self.previewGlows, self.window:CreateGlow(self.main, self.stops[1].color, 26, 1))
    end

    self:_buildHeader()
    self:_buildBody()

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        self:_popSwatch()
        if self._isOpen then
            self:_close()
        else
            self:_open()
        end
    end)

    self.window:ConnectFor(self, self.main.MouseEnter, function()
        if self._isOpen or not self.window:_interactive() then
            return
        end
        local theme = self.window.theme
        variables.tweenService
            :Create(self.stroke, fadeInfo, { Transparency = theme.ElementStrokeHoverTransparency, Color = theme.ElementStrokeHover })
            :Play()
        variables.tweenService:Create(self.title, fadeInfo, { TextColor3 = theme.ElementTextHoverColor }):Play()
        variables.tweenService:Create(self.hoverOverlay, fadeInfo, { BackgroundTransparency = 0.97 }):Play()
    end)

    self.window:ConnectFor(self, self.main.MouseLeave, function()
        local theme = self.window.theme
        variables.tweenService
            :Create(self.stroke, fadeInfo, { Transparency = theme.ElementStrokeTransparency, Color = theme.ElementStroke })
            :Play()
        variables.tweenService:Create(self.title, fadeInfo, { TextColor3 = theme.ContentColor }):Play()
        variables.tweenService:Create(self.hoverOverlay, fadeInfo, { BackgroundTransparency = 1 }):Play()
    end)

    self.window:_wireTooltip(self)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    self:_applyBodyVisibility(false, false)
    self:_setControlsVisible(false)

    self.window:ConnectFor(self, self.main:GetPropertyChangedSignal("AbsoluteSize"), function()
        if self.window.animating or (self.window.hidden and self.window.hasShownOnce) then
            return
        end
        self:_applyLayout()
    end)
    self:_applyLayout()

    self:_render("instant")

    return self
end

function GradientPicker:_buildHeader()
    local container = self.window:Create("Frame", {
        Size = UDim2.new(1, -90, 0, 16),
        Position = UDim2.new(0, 20, 0, headerHeight / 2),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ZIndex = 5,

            ImageTransparency = 1, -- In = 0

            Parent = container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 1,
        ZIndex = 5,

        TextTransparency = 1, -- In = 0

        Parent = container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- header swatch: a small pill painted with the live gradient itself (a real UIGradient), so
    -- the collapsed row already reads as "this is a gradient", not just a flat colour
    self.swatch = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -16, 0, headerHeight / 2),
        Size = swatchSize,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 3,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = self.swatch })
    self.swatchGradient = self.window:Create("UIGradient", { Color = self.value, Parent = self.swatch })

    -- chevron: 180deg = closed (matches dropdown.luau's own convention), tweens to 0 on open
    self.chevron = self.window:Create("ImageLabel", {
        Image = constants.icons.chevron,
        Size = UDim2.fromOffset(12, 12),
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -68, 0, headerHeight / 2),
        Rotation = 180,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        ZIndex = 3,

        ImageTransparency = 1, -- In = 0.4

        Parent = self.main,
    }, { ImageColor3 = "ContentColor" })

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, headerHeight),
        BorderSizePixel = 0,
        Text = "",
        AutoButtonColor = false,
        ZIndex = 10,

        Parent = self.main,
    })
end

function GradientPicker:_buildBody()
    -- live preview bar: the same gradient, big, full width, above the rail
    self.preview = self.window:Create("Frame", {
        Size = UDim2.new(1, -40, 0, 44),
        Position = UDim2.new(0, 20, 0, headerHeight),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 2,

        BackgroundTransparency = 1, -- Open = 0

        Parent = self.main,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 10), Parent = self.preview })
    self.previewStroke = self.window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),

        Transparency = 1, -- Open = 0.9

        Parent = self.preview,
    })
    self.previewGradient = self.window:Create("UIGradient", { Color = self.value, Parent = self.preview })

    -- wipe-reveal cover: a plain surface sitting over the preview, right-anchored so shrinking
    -- its width uncovers the gradient left-to-right instead of just fading in place. Reset to
    -- fully-covering (no animation) whenever the card closes, ready for the next open.
    self.previewCover = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(1, 0),
        Position = UDim2.fromScale(1, 0),
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        ZIndex = 3,

        Parent = self.preview,
    }, { BackgroundColor3 = "StatBackground" })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 10), Parent = self.previewCover })

    -- stops rail: a thin track with a draggable circular handle per stop
    self.rail = self.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 4),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 2,

        BackgroundTransparency = 1, -- Open = 0.85

        Parent = self.main,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = self.rail })

    self.railInteract = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 1, 20),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Text = "",
        AutoButtonColor = false,
        ZIndex = 2,

        Parent = self.rail,
    })

    self.stopHandles = {} -- stop -> { frame, ring }

    -- add / remove stop buttons, stacked under the rail
    -- plain text, no glyph: an emoji/icon-font symbol isn't guaranteed to rasterize on every
    -- client's font (unverified this session), and "+"/"-" alone read fine without one
    self.addButton = self:_buildStopButton("+  Add stop", 0)
    self.removeButton = self:_buildStopButton("-  Remove stop", 1)

    self.window:ConnectFor(self, self.addButton.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        self:_addStop()
    end)
    self.window:ConnectFor(self, self.removeButton.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        self:_removeSelectedStop()
    end)

    for _, stop in self.stops do
        self:_createStopHandle(stop)
    end

    -- shared HSV editor, bound to whichever stop is selected
    local initHue, initSat, initVal = self.selected.color:ToHSV()
    self.hsv = hsvEditor.build(self.window, self, self.main, {
        squareSize = squareSize,
        hueHeight = 14,
        gap = 14,
        hue = initHue,
        sat = initSat,
        val = initVal,
        onChange = function(h, s, v)
            if not self.selected then
                return
            end
            self.selected.color = Color3.fromHSV(h, s, v)
            self:_render("drag")
            self:_fireCallback()
        end,
        onCommit = function()
            self.window:_persist(self)
        end,
    })

    self.window:ConnectFor(self, self.railInteract.InputBegan, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            -- a bare click on the track (not a handle) adds a stop right there
            local width = self.rail.AbsoluteSize.X
            if width <= 0 then
                return
            end
            local mouse = self:_mouseLocation()
            local t = clamp01((mouse.X - self.rail.AbsolutePosition.X) / width)
            self:_addStop(t)
        end
    end)
end

function GradientPicker:_buildStopButton(text, order)
    local button = self.window:Create("TextButton", {
        Size = UDim2.fromOffset(0, 32),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        Text = text,
        TextSize = 14,
        AutoButtonColor = false,
        LayoutOrder = order,
        ZIndex = 2,

        BackgroundTransparency = 1, -- Open = 0.9
        TextTransparency = 1, -- Open = 0.15

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })
    self.window:Create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = button })
    return button
end

function GradientPicker:_mouseLocation()
    local mouse = variables.userInputService:GetMouseLocation()
    local screenGui = self.window.screenGui
    if screenGui and screenGui.IgnoreGuiInset then
        return mouse - variables.guiService:GetGuiInset()
    end
    return mouse
end

function GradientPicker:_createStopHandle(stop)
    local handle = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(stop.time, 0, 0.5, 0),
        Size = UDim2.fromOffset(20, 20),
        BackgroundColor3 = stop.color,
        BorderSizePixel = 0,
        ZIndex = 3,

        -- a stop created while already open (Set()/_addStop from an open picker) has to start
        -- visible - nothing else is going to reveal it, since _applyBodyVisibility only fires
        -- on _open()/_close()
        BackgroundTransparency = if self._isOpen then 0 else 1,

        Parent = self.rail,
    })
    self.window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = handle })
    local ring = self.window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),
        Thickness = 2,

        Transparency = 1, -- managed by _render (selection ring)

        Parent = handle,
    })
    local grabber = self.window:Create("TextButton", {
        Size = UDim2.fromOffset(30, 30),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundTransparency = 1,
        Text = "",
        AutoButtonColor = false,
        ZIndex = 4,

        Parent = handle,
    })

    self.stopHandles[stop] = { frame = handle, ring = ring }

    self.window:ConnectFor(self, grabber.InputBegan, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            self:_selectStop(stop)
            self:_beginDrag(stop, input.UserInputType == Enum.UserInputType.MouseButton1)
        end
    end)

    return handle
end

function GradientPicker:_beginDrag(stop, isMouse)
    self._drag = stop
    self._dragIsMouse = isMouse
    local handle = self.stopHandles[stop]
    if handle then
        variables.tweenService:Create(handle.frame, heldInfo, { Size = UDim2.fromOffset(26, 26) }):Play()
    end

    if self._dragConnection then
        self._dragConnection:Disconnect()
        self._dragConnection = nil
    end

    self._dragConnection = variables.runService.RenderStepped:Connect(function()
        local mouseReleased = self._dragIsMouse
            and not variables.userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
        if self.window.unloaded or not self._drag or mouseReleased then
            if mouseReleased then
                self:_endDrag()
                return
            end
            if self._dragConnection then
                self._dragConnection:Disconnect()
                self._dragConnection = nil
            end
            return
        end
        self:_pumpDrag()
    end)
end

function GradientPicker:_pumpDrag()
    local width = self.rail.AbsoluteSize.X
    if width <= 0 or not self._drag then
        return
    end
    local mouse = self:_mouseLocation()
    local t = clamp01((mouse.X - self.rail.AbsolutePosition.X) / width)
    if t == self._drag.time then
        return
    end
    self._drag.time = t
    self.value = buildSequence(self.stops)
    self:_render("drag")
    self:_fireCallback()
end

function GradientPicker:_endDrag()
    local stop = self._drag
    self._drag = nil
    if stop then
        local handle = self.stopHandles[stop]
        if handle then
            variables.tweenService:Create(handle.frame, heldInfo, { Size = UDim2.fromOffset(20, 20) }):Play()
        end
    end
    if self._dragConnection then
        self._dragConnection:Disconnect()
        self._dragConnection = nil
    end
    self.window:_persist(self)
end

function GradientPicker:_selectStop(stop)
    self.selected = stop
    local h, s, v = stop.color:ToHSV()
    self.hsv:SetColor(h, s, v, true)
    self:_render("animate")
end

-- Insert a new stop at `atTime` (defaults to the midpoint of the widest gap between existing
-- stops), coloured by interpolating the sequence at that point, then selects it.
function GradientPicker:_addStop(atTime)
    if #self.stops >= maxStops then
        return
    end

    if not atTime then
        local sorted = table.clone(self.stops)
        table.sort(sorted, function(a, b)
            return a.time < b.time
        end)
        local bestGap, bestMid = 0, 0.5
        for i = 1, #sorted - 1 do
            local gap = sorted[i + 1].time - sorted[i].time
            if gap > bestGap then
                bestGap = gap
                bestMid = (sorted[i].time + sorted[i + 1].time) / 2
            end
        end
        atTime = bestMid
    end

    local color = colorAt(self.stops, atTime)
    local stop = { time = clamp01(atTime), color = color }
    table.insert(self.stops, stop)
    self:_createStopHandle(stop)
    hapticEngine.click()
    soundEngine.click()
    self:_selectStop(stop)

    self.value = buildSequence(self.stops)
    self:_render("animate")
    self:_fireCallback()
    self.window:_persist(self)
end

function GradientPicker:_removeSelectedStop()
    if not self.selected or #self.stops <= minStops then
        return
    end

    local idx = table.find(self.stops, self.selected)
    if not idx then
        return
    end

    local handle = self.stopHandles[self.selected]
    if handle then
        handle.frame:Destroy()
    end
    self.stopHandles[self.selected] = nil
    table.remove(self.stops, idx)

    self.selected = self.stops[math.max(1, idx - 1)]
    if self.selected then
        local h, s, v = self.selected.color:ToHSV()
        self.hsv:SetColor(h, s, v, true)
    end

    self.value = buildSequence(self.stops)
    self:_render("animate")
    self:_fireCallback()
    self.window:_persist(self)
end

function GradientPicker:_render(mode)
    self.swatchGradient.Color = self.value
    self.previewGradient.Color = self.value

    -- sample the live gradient at 0/0.5/1 so the three stacked glows actually track whatever
    -- colours are currently at each end and the middle, not just whichever stop was leftmost
    self.previewGlows[1].Color = colorAt(self.stops, 0)
    self.previewGlows[2].Color = colorAt(self.stops, 0.5)
    self.previewGlows[3].Color = colorAt(self.stops, 1)

    for stop, handle in self.stopHandles do
        local pos = UDim2.new(stop.time, 0, 0.5, 0)
        if mode == "drag" or mode == "animate" then
            variables.tweenService
                :Create(handle.frame, if mode == "drag" then dragInfo else openInfo, { Position = pos, BackgroundColor3 = stop.color })
                :Play()
        else
            handle.frame.Position = pos
            handle.frame.BackgroundColor3 = stop.color
        end
        handle.ring.Transparency = if stop == self.selected and self._isOpen then 0 else 1
    end

    -- _removeSelectedStop already refuses to drop below minStops; this is just the visual cue
    variables.tweenService
        :Create(self.removeButton, fadeInfo, { TextTransparency = if #self.stops > minStops then 0.15 else 0.6 })
        :Play()
end

function GradientPicker:_fireCallback()
    self.window:_runGuarded(self, self.callback, self.value)
end

-- Quick tactile feedback on the header swatch the instant it's clicked, independent of (and
-- faster than) the open/close animation that follows - squashes narrower, then springs back
-- past its resting width before settling (Back easing) for a little bounce.
function GradientPicker:_popSwatch()
    local squashed = UDim2.fromOffset(swatchSize.X.Offset * 0.85, swatchSize.Y.Offset * 0.85)
    local outTween = variables.tweenService:Create(self.swatch, popOutInfo, { Size = squashed })
    outTween:Play()
    local connection
    connection = outTween.Completed:Connect(function()
        connection:Disconnect()
        variables.tweenService:Create(self.swatch, popBackInfo, { Size = swatchSize }):Play()
    end)
end

-- Stop handles pop in from a tiny point with a spring (Back easing), staggered left-to-right
-- by each stop's time so they read as a little cascade rather than popping in all at once.
-- animate = false/nil snaps instantly (used for the initial hidden state and on close).
function GradientPicker:_revealStopHandles(open, animate)
    if not animate then
        for _, handle in self.stopHandles do
            handle.frame.BackgroundTransparency = if open then 0 else 1
            handle.frame.Size = UDim2.fromOffset(20, 20)
            if not open then
                handle.ring.Transparency = 1
            end
        end
        return
    end

    if not open then
        for _, handle in self.stopHandles do
            variables.tweenService:Create(handle.frame, animate, { BackgroundTransparency = 1 }):Play()
            handle.ring.Transparency = 1
        end
        return
    end

    local sorted = table.clone(self.stops)
    table.sort(sorted, function(a, b)
        return a.time < b.time
    end)
    for i, stop in sorted do
        local handle = self.stopHandles[stop]
        if handle then
            handle.frame.Size = UDim2.fromOffset(2, 2)
            handle.frame.BackgroundTransparency = 0
            task.delay((i - 1) * 0.04, function()
                if self._isOpen then
                    variables.tweenService:Create(handle.frame, handleSpringInfo, { Size = UDim2.fromOffset(20, 20) }):Play()
                end
            end)
        end
    end
end

function GradientPicker:_open()
    if self._isOpen then
        return
    end
    self._isOpen = true
    self._openSeq = (self._openSeq or 0) + 1
    local seq = self._openSeq
    self:_setControlsVisible(true)

    if self._outsideClickConn then
        self.window:Disconnect(self._outsideClickConn)
    end
    self._outsideClickConn = self.window:Connect(variables.userInputService.InputBegan, function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end
        local pos = input.Position
        local mainPos = self.main.AbsolutePosition
        local mainSize = self.main.AbsoluteSize
        if pos.X < mainPos.X or pos.X > mainPos.X + mainSize.X or pos.Y < mainPos.Y or pos.Y > mainPos.Y + mainSize.Y then
            self:_close()
        end
    end)

    -- 1) card grows with a slight bounce past its final height instead of a flat stop
    variables.tweenService:Create(self.main, heightOpenInfo, { Size = UDim2.new(1, -20, 0, self._openHeight) }):Play()
    if self.chevron then
        variables.tweenService:Create(self.chevron, chevronInfo, { Rotation = 0 }):Play()
    end

    -- 4) glow pulse: flashes past its steady-state glow, then relaxes back down to it
    if self.showGlow then
        for _, glow in self.previewGlows do
            variables.tweenService:Create(glow, glowPulseInfo, { Transparency = math.max(0, glowOnTransparency - 0.3) }):Play()
        end
        task.delay(glowPulseInfo.Time, function()
            if self._isOpen and self._openSeq == seq then
                for _, glow in self.previewGlows do
                    variables.tweenService:Create(glow, glowRelaxInfo, { Transparency = glowOnTransparency }):Play()
                end
            end
        end)
    end

    -- 2) + 5) staggered reveal: preview bar (wiping its cover away) first, then the rail +
    -- buttons + stop handles (spring-popping in, see _revealStopHandles), then the HSV editor
    variables.tweenService:Create(self.preview, fadeInfo, { BackgroundTransparency = 0 }):Play()
    variables.tweenService:Create(self.previewStroke, fadeInfo, { Transparency = 0.9 }):Play()
    variables.tweenService:Create(self.previewCover, wipeInfo, { Size = UDim2.fromScale(0, 1) }):Play()

    task.delay(staggerStep, function()
        if not self._isOpen or self._openSeq ~= seq then
            return
        end
        variables.tweenService:Create(self.rail, fadeInfo, { BackgroundTransparency = 0.85 }):Play()
        variables.tweenService:Create(self.addButton, fadeInfo, { BackgroundTransparency = 0.9, TextTransparency = 0.15 }):Play()
        variables.tweenService:Create(self.removeButton, fadeInfo, { BackgroundTransparency = 0.9, TextTransparency = 0.15 }):Play()
        self:_revealStopHandles(true, fadeInfo)
    end)

    task.delay(staggerStep * 2, function()
        if not self._isOpen or self._openSeq ~= seq then
            return
        end
        self.hsv:SetVisible(true, true)
    end)

    self:_render("animate")
end

function GradientPicker:_close()
    if not self._isOpen then
        return
    end
    self._isOpen = false
    self._openSeq = (self._openSeq or 0) + 1 -- invalidates any staggered/delayed open steps still pending

    if self._outsideClickConn then
        self.window:Disconnect(self._outsideClickConn)
        self._outsideClickConn = nil
    end
    if self._drag then
        self:_endDrag()
    end

    -- everything fades out together (no stagger) on the quicker closeFadeInfo, so the content
    -- is gone before (or right as) the height tween below finishes instead of cutting off mid-fade
    variables.tweenService:Create(self.preview, closeFadeInfo, { BackgroundTransparency = 1 }):Play()
    variables.tweenService:Create(self.previewStroke, closeFadeInfo, { Transparency = 1 }):Play()
    variables.tweenService:Create(self.rail, closeFadeInfo, { BackgroundTransparency = 1 }):Play()
    variables.tweenService:Create(self.addButton, closeFadeInfo, { BackgroundTransparency = 1, TextTransparency = 1 }):Play()
    variables.tweenService:Create(self.removeButton, closeFadeInfo, { BackgroundTransparency = 1, TextTransparency = 1 }):Play()
    self:_revealStopHandles(false, closeFadeInfo)
    self.previewCover.Size = UDim2.fromScale(1, 1) -- reset instantly, ready to wipe again next open
    self.hsv:SetVisible(false, true)
    self:_render("animate") -- also drops the selection ring now that _isOpen is false
    variables.tweenService:Create(self.main, heightInfo, { Size = UDim2.new(1, -20, 0, headerHeight) }):Play()
    if self.chevron then
        variables.tweenService:Create(self.chevron, chevronInfo, { Rotation = 180 }):Play()
    end

    task.delay(closeFadeInfo.Time, function()
        if not self._isOpen then
            self:_setControlsVisible(false)
        end
    end)
end

-- Only the instant (open = init/close) snap path now - the animated open sequence lives inline
-- in _open() so it can stagger; _close() plays its own (simultaneous, not staggered) tweens.
function GradientPicker:_applyBodyVisibility(open, animate)
    local set = {
        [self.preview] = { BackgroundTransparency = if open then 0 else 1 },
        [self.previewStroke] = { Transparency = if open then 0.9 else 1 },
        [self.rail] = { BackgroundTransparency = if open then 0.85 else 1 },
        [self.addButton] = { BackgroundTransparency = if open then 0.9 else 1, TextTransparency = if open then 0.15 else 1 },
        [self.removeButton] = { BackgroundTransparency = if open then 0.9 else 1, TextTransparency = if open then 0.15 else 1 },
    }

    for instance, props in set do
        if animate then
            variables.tweenService:Create(instance, animate, props):Play()
        else
            for prop, value in props do
                instance[prop] = value
            end
        end
    end
    self:_revealStopHandles(open, animate)
    if not open then
        self.previewCover.Size = UDim2.fromScale(1, 1)
    end
end

function GradientPicker:_setControlsVisible(visible)
    for _, frame in { self.preview, self.rail, self.addButton, self.removeButton } do
        frame.Visible = visible
    end
end

-- Wide: rail + buttons left, square+hue right, side by side under the preview bar.
-- Narrow: stacked, editor centred underneath.
function GradientPicker:_applyLayout()
    local width = self.main.AbsoluteSize.X
    local mode = if width > 0 and width < narrowWidth then "narrow" else "wide"
    if mode == self._layoutMode then
        return
    end
    self._layoutMode = mode

    local leftWidth = if mode == "wide" then UDim.new(1, -(20 + squareSize + 16 + 20)) else UDim.new(1, -40)
    local y = headerHeight + 44 + 16 -- under the preview bar

    self.rail.Position = UDim2.new(0, 20 + 10, 0, y + 13)
    self.rail.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset - 20, 0, 4)

    y += 34
    self.addButton.Position = UDim2.new(0, 20, 0, y)
    self.addButton.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 32)
    y += 32 + 8
    self.removeButton.Position = UDim2.new(0, 20, 0, y)
    self.removeButton.Size = UDim2.new(leftWidth.Scale, leftWidth.Offset, 0, 32)
    local leftBottom = y + 32

    if mode == "wide" then
        self.hsv.root.Position = UDim2.new(1, -20 - squareSize, 0, headerHeight + 44 + 16)
        self._openHeight = math.max(leftBottom, headerHeight + 44 + 16 + squareSize + 14 + 14) + 20
    else
        local hsvY = leftBottom + 16
        self.hsv.root.Position = UDim2.new(0.5, -squareSize / 2, 0, hsvY)
        self._openHeight = hsvY + squareSize + 14 + 14 + 20
    end

    if self._isOpen then
        variables.tweenService:Create(self.main, heightInfo, { Size = UDim2.new(1, -20, 0, self._openHeight) }):Play()
    end
end

-- value: ColorSequence, or a plain list (Color3s evenly spread, or {time, color} tables)
function GradientPicker:Set(value, skipCallback)
    self.stops = normalizeStops(value)
    for _, handle in self.stopHandles do
        handle.frame:Destroy()
    end
    self.stopHandles = {}
    for _, stop in self.stops do
        self:_createStopHandle(stop)
    end
    self.selected = self.stops[1]
    local h, s, v = self.selected.color:ToHSV()
    self.hsv:SetColor(h, s, v, false)

    self.value = buildSequence(self.stops)
    self:_render(if skipCallback then "instant" else "animate")

    if not skipCallback then
        self:_fireCallback()
        self.window:_persist(self)
    end
end

function GradientPicker:SetGlow(shown)
    self.showGlow = shown and true or false
    for _, glow in self.previewGlows do
        variables.tweenService:Create(glow, fadeInfo, { Transparency = if self.showGlow then glowOnTransparency else 1 }):Play()
    end
end

-- Persistence: "time:hex,time:hex,..." - a plain flat string like every other flag value.
function GradientPicker:_serialize()
    local parts = {}
    for _, stop in self.stops do
        table.insert(parts, string.format("%.4f:%s", stop.time, stop.color:ToHex()))
    end
    return table.concat(parts, ",")
end

function GradientPicker:_deserialize(raw)
    local stops = {}
    for part in tostring(raw):gmatch("[^,]+") do
        local t, hex = part:match("^([%d%.]+):(%x+)$")
        if t and hex then
            local ok, color = pcall(Color3.fromHex, hex)
            if ok then
                table.insert(stops, { time = clamp01(tonumber(t)), color = color })
            end
        end
    end
    if #stops >= minStops then
        self:Set(stops)
    end
end

function GradientPicker:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.swatch, { BackgroundTransparency = 0 }, animate)
        w:_reveal(self.chevron, { ImageTransparency = 0.4 }, animate)
        for _, glow in self.previewGlows do
            w:_reveal(glow, { Transparency = if self.showGlow then glowOnTransparency else 1 }, animate)
        end
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.swatch, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.chevron, { ImageTransparency = 1 }, animate)
        for _, glow in self.previewGlows do
            w:_reveal(glow, { Transparency = 1 }, animate)
        end
        if self._isOpen then
            self:_close()
        end
    end
end

moveable(GradientPicker)
lockable(GradientPicker)

return GradientPicker
]=====]

sources["components/group"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Group = {}
Group.__index = Group
Group.__type = "Group"

-- A layout container. Lays its children along one axis and nests, so a row of columns
-- gives you a grid. A row wraps when it runs out of width instead of shrinking forever.
-- Mimics the Tab fields components read (window, tabPage, elements, compact, direction,
-- _moveElement) so the exact same element code builds inside it, and flags still register
-- on window.controls through the nesting.
--
-- row    -> children build compact and share the width, wrapping to new rows as needed
-- column -> children build full width, stacked top to bottom
-- The public API calls these "row"/"column"; "horizontal"/"vertical" work too.

local moveable = require(script.Parent.Parent.utility.moveable)
local log = require(script.Parent.Parent.utility.log)
local assignOrder = require(script.Parent.Parent.utility.ordering)

local elementPadding = 8

-- these render fine side by side in a row: the compact builds (button/toggle/stat), the
-- newer compact builds (checkbox/copybutton/flipbutton/ripplebutton/holdbutton), and the slider
-- (it reflows to its narrow layout). Everything else added below (dropdown/section/colorpicker/
-- gradientpicker/input/keybind/progressbar/scrollhint/segmentedpicker/shimmerlabel/changelog/
-- spacer/collapsible) has no compact build of its own and stays full-only, same as
-- Section/Label already did.
local compactCapable = {
    button = true,
    toggle = true,
    stat = true,
    slider = true,
    checkbox = true,
    copybutton = true,
    flipbutton = true,
    ripplebutton = true,
    holdbutton = true,
    -- fixed-width by design (see statuscard.luau's own header comment), so it sits fine next to
    -- a row's other compact elements without needing the wrap-to-content-width treatment those
    -- get from Group:_wrapChild - it still goes through that path (its own _minWidth just
    -- returns the width it already has), so it participates in row wrapping like anything else.
    statuscard = true,
}

function Group.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local dir = string.lower(properties.direction or properties.Direction or "row")
    local vertical = dir == "column" or dir == "vertical"
    local horizontal = not vertical
    local direction = if horizontal then Enum.FillDirection.Horizontal else Enum.FillDirection.Vertical

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"), -- host: a Tab or a parent Group
        window = tab.window,
        direction = direction,
        compact = horizontal, -- row children pack side by side
        forgetState = tab.forgetState, -- inherit the host's config-persistence stance
        elements = {},
        -- assume shown until _setShown says otherwise (a group built before the window's first
        -- reveal has nothing to conflict with yet)
        _windowWantsShown = true,
    }, Group)

    -- Dependency group: dependsOn is anything with a .value and a .callback (a toggle, a
    -- dropdown, a checkbox, ...) - every element type already stores its user callback under
    -- that name and invokes it uniformly, so wrapping it is a generic hook that works across all
    -- of them without each element needing its own "value changed" signal. condition defaults to
    -- a plain truthy check (built for a toggle); pass one explicitly for a dropdown/slider-driven
    -- group (e.g. function(v) return v == "Advanced" end).
    local dependsOn = properties.dependsOn or properties.DependsOn
    if dependsOn then
        self._dependsOn = dependsOn
        self._condition = properties.condition or properties.Condition or function(value)
            return value == true
        end

        local originalCallback = dependsOn.callback
        dependsOn.callback = function(...)
            if originalCallback then
                originalCallback(...)
            end
            self:_applyDependency(true)
        end
    end

    -- if our host is a row we're a column, so we hand our width to its flex
    local nestedInRow = tab.direction == Enum.FillDirection.Horizontal

    self.main = self.window:Create("Frame", {
        Name = "Group",
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        AutomaticSize = Enum.AutomaticSize.Y,
        -- row matches a normal element's inset (1,-20). column is full width so its
        -- full-build children (1,-20) line up with the rest of the tab.
        Size = if horizontal then UDim2.new(1, -20, 0, 0) else UDim2.new(1, 0, 0, 0),

        Parent = self.tab.tabPage,
    })

    if nestedInRow then
        -- let the parent row divide its width between columns
        self.main.Size = UDim2.new(0, 0, 0, 0)
        self.window:Create("UIFlexItem", {
            FlexMode = Enum.UIFlexMode.Fill,
            Parent = self.main,
        })
    end

    -- children parent here
    self.tabPage = self.main

    self.layout = self.window:Create("UIListLayout", {
        FillDirection = direction,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, elementPadding),
        -- Top, not Center, for a row: every original compact type (Button/Toggle/Stat/Slider/...)
        -- shares roughly the same height, so this looked identical either way until StatusCard
        -- (a taller, resizable card) could sit in a row too - Center meant a StatusCard
        -- expanding/collapsing changed the *row's* own height, which re-centred every other,
        -- fixed-height sibling in it - live-reported as "a toggle desce sozinha", when the
        -- toggle itself never actually moved or resized, everything around it did. Top pins
        -- every child to the row's own top edge regardless of what a taller sibling is doing.
        VerticalAlignment = Enum.VerticalAlignment.Top,
        HorizontalAlignment = if horizontal then Enum.HorizontalAlignment.Left else Enum.HorizontalAlignment.Center,

        Parent = self.main,
    })

    return self
end

function Group:_add(componentName, properties)
    if self.compact and not compactCapable[componentName] then
        log.warn(
            `Rayfield: a row only holds compact elements `
                .. `(button/toggle/stat/slider/checkbox/copybutton/flipbutton/ripplebutton), `
                .. `ignoring '{componentName}'. Use a column for it.`
        )
        return nil
    end

    local element = require(script.Parent[componentName]).new(self, properties)
    table.insert(self.elements, element)
    assignOrder(element, #self.elements * 10)
    self.window:_restoreLate(element)

    if self.compact then
        self:_wrapChild(element)
    end
    self:_reflowRow() -- a leaf landing in a row of columns has to widen the gap back out

    -- same as Tab:_register: elements added after Window:Show must be revealed here
    -- or they stay fully transparent
    if not self.window.hidden then
        element:_setShown(self:_actualShown(true), true)
    end

    return element
end

-- true if `shown` should actually render given self._dependsOn's current value - shared by
-- _add's own late-reveal above and _setShown/_applyDependency below, so all three agree on the
-- same logic rather than each re-deriving it slightly differently.
function Group:_actualShown(shown)
    if not self._dependsOn then
        return shown
    end
    return shown and self._condition(self._dependsOn.value)
end

-- Re-applies the dependency condition against whatever self._dependsOn.value currently is,
-- against self._windowWantsShown (whatever _setShown last set) rather than assuming the window
-- is up - the wrapped callback below can fire from a control changed while the window itself is
-- hidden or mid-reveal, and this must not fight that.
function Group:_applyDependency(animate)
    local shown = self:_actualShown(self._windowWantsShown)
    for _, el in self.elements do
        el:_setShown(shown, animate)
    end
end

-- Padding is one property for the whole row, so it has to suit whatever the row ends up
-- holding. Columns carry their own 10px side margin (the 1,-20), so where two meet the gutter
-- is 10+10=20, twice the 10px outer margin - pull them together by one margin's worth to match.
-- Leaves carry no margin, so the same pull would just overlap them: a row holding any leaf
-- keeps the leaf gap and lets the columns sit a touch wider apart.
function Group:_reflowRow()
    if self.direction ~= Enum.FillDirection.Horizontal then
        return
    end

    local onlyGroups = #self.elements > 0
    for _, element in self.elements do
        if element.__type ~= "Group" then
            onlyGroups = false
            break
        end
    end

    self.layout.Padding = if onlyGroups then UDim.new(0, -10) else UDim.new(0, elementPadding)
end

-- A row wraps instead of shrinking forever. Each child is frozen to the width it actually
-- needs (element:_minWidth counts its icon, text, control + padding), so the row breaks on
-- real bounds, and HorizontalFlex grows each row's items to fill it.
function Group:_wrapChild(element)
    self.layout.Wraps = true
    self.layout.HorizontalFlex = Enum.UIFlexAlignment.Fill

    -- tells a width-owning element (the slider) that we drive its width now, so its own
    -- reflow stops fighting us. plain compact elements ignore the flag.
    element._widthManaged = true

    local minWidth = if element._minWidth then element:_minWidth() else 0
    if minWidth > 0 then
        element.main.AutomaticSize = Enum.AutomaticSize.None
        element.main.Size = UDim2.new(0, minWidth, element.main.Size.Y.Scale, element.main.Size.Y.Offset)
    end
end

function Group:CreateButton(properties)
    return self:_add("button", properties)
end
function Group:CreateFlipButton(properties)
    return self:_add("flipbutton", properties)
end
function Group:CreateCopyButton(properties)
    return self:_add("copybutton", properties)
end
function Group:CreateRippleButton(properties)
    return self:_add("ripplebutton", properties)
end
function Group:CreateToggle(properties)
    return self:_add("toggle", properties)
end
function Group:CreateSwitch(properties)
    return self:_add("toggle", properties)
end
function Group:CreateCheckbox(properties)
    return self:_add("checkbox", properties)
end
function Group:CreateStat(properties)
    return self:_add("stat", properties)
end
function Group:CreateStatusCard(properties)
    return self:_add("statuscard", properties)
end
function Group:CreateSlider(properties)
    return self:_add("slider", properties)
end
function Group:CreateDropdown(properties)
    return self:_add("dropdown", properties)
end
function Group:CreateSection(properties)
    return self:_add("section", properties)
end
function Group:CreateLabel(properties)
    return self:_add("label", properties)
end
function Group:CreateParagraph(properties)
    return self:_add("paragraph", properties)
end
function Group:CreateDivider(properties)
    return self:_add("divider", properties)
end
function Group:CreateProgressBar(properties)
    return self:_add("progressbar", properties)
end
function Group:CreateConsole(properties)
    return self:_add("console", properties)
end
function Group:CreateScrollHint(properties)
    return self:_add("scrollhint", properties)
end
function Group:CreateSegmentedPicker(properties)
    return self:_add("segmentedpicker", properties)
end
function Group:CreateShimmerLabel(properties)
    return self:_add("shimmerlabel", properties)
end
function Group:CreateInput(properties)
    return self:_add("input", properties)
end
function Group:CreateKeybind(properties)
    return self:_add("keybind", properties)
end
function Group:CreateColorPicker(properties)
    return self:_add("colorpicker", properties)
end
function Group:CreateGradientPicker(properties)
    return self:_add("gradientpicker", properties)
end
function Group:CreateHoldButton(properties)
    return self:_add("holdbutton", properties)
end
function Group:CreateChangelog(properties)
    return self:_add("changelog", properties)
end
function Group:CreateSpacer(properties)
    return self:_add("spacer", properties)
end
function Group:CreateTabbox(properties)
    return self:_add("tabbox", properties)
end

-- Collapsible reads window/tabPage/forgetState off whatever host it's given (see its own header
-- comment - same minimal contract Tabbox's fake-host trick relies on), so a Group already
-- satisfies it with no changes needed there. Not compact-capable (a collapsible's header/chevron
-- and its own expanding content don't fit a row's inline layout), so this only actually works
-- inside a column - exactly like CreateSection/CreateLabel above. That's what makes two
-- independently-expanding "Basic"/"Advanced" panels side by side possible: a row of two columns,
-- one CreateCollapsible each.
function Group:CreateCollapsible(properties)
    return self:_add("collapsible", properties)
end

-- a nested group: a column (for a grid) or another row inside this one
function Group:_addGroup(properties)
    properties = if typeof(properties) == "table" then table.clone(properties) else {}

    -- adapt a row that's about to hold columns instead of compact leaves:
    if self.direction == Enum.FillDirection.Horizontal then
        -- top-align, not centre: a column growing (e.g. a dropdown opening) must push down,
        -- not re-centre and shove the other column around.
        self.layout.VerticalAlignment = Enum.VerticalAlignment.Top
        -- full width (unless we're ourselves a nested column sharing a parent's flex) so
        -- column content lines up with the tab's normal elements instead of sitting 10px in.
        if self.tab.direction ~= Enum.FillDirection.Horizontal then
            self.main.Size = UDim2.new(1, 0, 0, 0)
        end
    end

    local group = Group.new(self, properties)
    table.insert(self.elements, group)
    group.main.LayoutOrder = #self.elements * 10
    self:_reflowRow()
    return group
end

function Group:CreateGroup(properties)
    return self:_addGroup(properties)
end

-- reorder a child within this group
function Group:_moveElement(element, targetIndex)
    local idx = table.find(self.elements, element)
    if not idx then
        return
    end
    table.remove(self.elements, idx)
    targetIndex = math.clamp(targetIndex, 1, #self.elements + 1)
    table.insert(self.elements, targetIndex, element)
    for i, el in self.elements do
        assignOrder(el, i * 10)
    end
end

-- children live in group.elements, not tab.elements, so forward the reveal down.
-- nested groups forward it again, so a whole grid reveals in one call. Remembers `shown` as
-- self._windowWantsShown regardless of _dependsOn, so a later dependency change (the wrapped
-- callback calling _applyDependency) knows whether the window even wants this group up at all,
-- not just the condition's own state.
function Group:_setShown(shown, animate)
    self._windowWantsShown = shown
    local actual = self:_actualShown(shown)
    for _, el in self.elements do
        el:_setShown(actual, animate)
    end
end

-- same reason: forward a runtime theme refresh down to the children (nested groups recurse).
function Group:_refreshTheme()
    for _, el in self.elements do
        if el._refreshTheme then
            el:_refreshTheme()
        end
    end
end

-- reorder the group within its host
moveable(Group)

return Group
]=====]

sources["components/holdbutton"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 6: a press-and-hold confirm button. A fill bar slides left -> right while held, clipped
-- to the card's own rounded corners; the callback only fires once the fill actually reaches
-- 100%. Releasing early snaps the fill back empty instead of firing anything - the point is to
-- make an accidental tap harmless for a destructive action ("Hold to wipe save" etc).

local HoldButton = {}
HoldButton.__index = HoldButton
HoldButton.__type = "HoldButton"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local cancelInfo = TweenInfo.new(0.2, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

function HoldButton.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Hold Button",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        compact = tab.compact or false,

        -- seconds the bar takes to fill; danger = tint the fill red instead of the accent colour
        holdDuration = properties.holdDuration or properties.HoldDuration or 1,
        danger = properties.danger or properties.Danger or false,
        locked = properties.locked or properties.Locked or false,

        callback = properties.callback or properties.Callback or function() end,

        _holding = false,
    }, HoldButton)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self:_applyLocked(false)
    self.window:_wireTooltip(self)

    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

function HoldButton:_runCallback()
    self.window:_runGuarded(self, self.callback)
end

-- Clipped overlay matching the card's own rounded corners, holding the actual fill bar.
-- Parented after the hover overlay and before the title/icon (all default ZIndex 1, so
-- creation order alone keeps it above the hover tint but under the text).
function HoldButton:_buildFillLayer(parent)
    self.fillClip = self.window:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ClipsDescendants = true,

        Parent = parent,
    })
    self.window:Create("UICorner", {
        Parent = self.fillClip,
    }, { CornerRadius = "ElementCornerRadius" })

    self.fill = self.window:Create("Frame", {
        Size = UDim2.new(0, 0, 1, 0),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 0.75,
        BorderSizePixel = 0,

        Parent = self.fillClip,
    }, { BackgroundColor3 = if self.danger then "ErrorColor" else "AccentColor" })

    -- ClipsDescendants clips to fillClip's plain rectangular bounds regardless of its own
    -- UICorner - a UICorner only shapes how a frame draws ITSELF, not the clip region it casts
    -- on children - so without a matching UICorner here too, the fill's own square corners still
    -- render past the card's rounded edge whenever it isn't fully empty or full.
    self.window:Create("UICorner", {
        Parent = self.fill,
    }, { CornerRadius = "ElementCornerRadius" })

    return self.fillClip
end

-- Every fill-size change funnels through here so a new tween always cancels whatever's still
-- running first - two simultaneous TweenService tweens on the same property fight each other
-- frame to frame instead of one cleanly superseding the other, which was leaving the bar stuck
-- mid-animation when a completion and a release landed close together.
function HoldButton:_setFill(size, tweenInfo)
    if self._fillTween then
        self._fillTween:Cancel()
        self._fillTween = nil
    end
    if tweenInfo then
        local tween = variables.tweenService:Create(self.fill, tweenInfo, { Size = size })
        self._fillTween = tween
        tween:Play()
    else
        self.fill.Size = size
    end
end

function HoldButton:_beginHold()
    if self.locked or self._holding then
        return
    end
    self._holding = true
    self:_setFill(UDim2.fromScale(1, 1), TweenInfo.new(self.holdDuration, Enum.EasingStyle.Linear))

    local holdToken = (self._holdToken or 0) + 1
    self._holdToken = holdToken
    task.delay(self.holdDuration, function()
        -- still the same hold, and it wasn't released early - completes it
        if self._holding and self._holdToken == holdToken then
            self._holding = false
            hapticEngine.click()
            soundEngine.click()
            self:_runCallback()
            self:_setFill(UDim2.new(0, 0, 1, 0), cancelInfo) -- smooth reset, not an instant snap
        end
    end)
end

function HoldButton:_cancelHold()
    if not self._holding then
        return
    end
    self._holding = false
    self._holdToken = (self._holdToken or 0) + 1 -- invalidate the pending completion above
    self:_setFill(UDim2.new(0, 0, 1, 0), cancelInfo)
end

function HoldButton:_wireHold()
    self.window:ConnectFor(self, self.interact.InputBegan, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            self:_beginHold()
        end
    end)

    -- global, like the pickers' own drag release: a mouse-up anywhere ends the hold, not just
    -- one that lands back on the button
    self.window:ConnectFor(self, variables.userInputService.InputEnded, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            self:_cancelHold()
        end
    end)
end

-- full-width: title/icon left (matches button.luau's layout, minus the click flash)
function HoldButton:_buildFull()
    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 43),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = 0

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)
    self:_buildFillLayer(self.main)

    self.container = self.window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.main,
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.containerLayout = self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),

        Size = UDim2.fromOffset(250, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.lockIcon = self.window:_buildLockIcon(self.main)
    self.prohibitedIcon = self.window:_buildProhibitedIcon(self.container or self.interact)

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        TextTransparency = 1,

        Parent = self.main,
    })

    self.window:_wireElementHover(self)
    self:_wireHold()
end

-- compact (row): content-sized, centred icon + title
function HoldButton:_buildCompact()
    local window = self.window

    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name)
    self.hoverOverlay = self.interact
    self:_buildFillLayer(self.interact)

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 16),
        PaddingRight = UDim.new(0, 16),

        Parent = self.interact,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        Padding = UDim.new(0, 6),

        Parent = self.interact,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.interact,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.interact,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    self.lockIcon = self.window:_buildLockIcon(self.main)
    self.prohibitedIcon = self.window:_buildProhibitedIcon(self.container or self.interact)

    self.window:_wireElementHover(self)
    self:_wireHold()
end

-- Dim the content, show the padlock (see window.luau's shared _buildLockIcon/_applyLockedVisual),
-- and stop new holds from starting - any hold already in progress is cancelled outright rather
-- than left to finish.
function HoldButton:_applyLocked(animate)
    self.window:_applyLockedVisual(self, animate)
    if self.locked and self._holding then
        self:_cancelHold()
    end
end

function HoldButton:SetLocked(locked)
    locked = locked and true or false
    if locked == self.locked then
        return
    end
    self.locked = locked
    self:_applyLocked(true)
end

-- Lock/Unlock/IsLocked: the shared naming lockable.luau gives every other locking-capable
-- element - aliased into this component's own pre-existing SetLocked/padlock-icon dimming
-- rather than the mixin's scrim (see lockable.luau's own header comment). `reason` isn't
-- supported here.
function HoldButton:Lock()
    self:SetLocked(true)
end
function HoldButton:Unlock()
    self:SetLocked(false)
end
function HoldButton:IsLocked(): boolean
    return self.locked == true
end

function HoldButton:_setShown(shown, animate)
    if shown then
        -- _revealCommon is locked-aware (see window.luau) - it already dims title/icon
        -- correctly by itself, no second tween needed to fix it up afterward
        self.window:_revealCommon(self, animate)
    else
        self.window:_hideCommon(self, animate)
        self:_cancelHold()
    end
end

-- Room the compact hold button needs before its label would clip.
function HoldButton:_minWidth()
    local w = 32
    if self.icon then
        w += 22
    end
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

moveable(HoldButton)

return HoldButton
]=====]

sources["components/hud"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A small draggable status chip, independent of the main window - stays on screen (and keeps
-- updating) even while the window itself is hidden or minimised, for something a player wants
-- visible at a glance the whole session (FPS/ping, a running automation's headline status).
-- Parented straight to window.screenGui rather than window.main, since Window:Hide/Show only
-- ever animate main - a HUD parented there rides along for free without needing its own
-- show/hide wiring.
--
-- Deliberately its own tiny component rather than a Label/Stat repurposed: those both live
-- inside a Tab's page and follow the tab's own reveal/hide lifecycle, which is exactly the
-- coupling this is meant to escape.
--
-- Sized and weighted like the "watermark" HUDs most executor UIs ship (bold text, a coloured
-- accent tick, generous padding) rather than a slim inline label - the first two passes read as
-- too small/flat next to one of those on screen at the same time, live-caught (user: "ta feio,
-- pequeno").

local Hud = {}
Hud.__index = Hud
Hud.__type = "Hud"

local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local functions = require(utility.functions)
local image = require(utility.image)

local revealInfo = TweenInfo.new(0.5, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local dragStrokeInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

function Hud.new(window, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
        text = properties.text or properties.Text or "",
    }, Hud)

    local hasIcon = (properties.icon or properties.Icon) ~= nil
    -- A user id: shows that user's headshot as a small circular avatar ahead of everything else -
    -- same rbxthumb:// URI trick toast.luau's own avatar variant and utility/image.luau's
    -- image.avatar both already use, no HTTP round trip needed.
    local avatarUserId = properties.avatar or properties.Avatar

    local startPosition = properties.position or properties.Position or UDim2.new(0, 20, 0, 20)

    self.main = self.window:Create("Frame", {
        Name = "Hud",
        AutomaticSize = Enum.AutomaticSize.XY,
        Size = UDim2.fromOffset(0, 0),
        Position = startPosition,
        AnchorPoint = Vector2.new(0, 0),
        BorderSizePixel = 0,
        Active = true,

        -- reveal: grows in from a slightly smaller/transparent state instead of just popping in
        BackgroundTransparency = 1, -- In = 0 (the gradient below carries the real look)

        Parent = self.window.screenGui,
    })

    self.window:Create("UIGradient", {
        Rotation = 270,
        Offset = Vector2.new(0, -0.1),

        Parent = self.main,
    }, { Color = { "WindowColor", functions.toColorSequence } })

    -- fixed rather than the theme's own CornerRoundness: this chip is meant to read the same
    -- (comfortably rounded, not the window's own pill-ish 20px default) regardless of whatever
    -- corner style a particular window happens to be using.
    self.window:Create("UICorner", {
        CornerRadius = UDim.new(0, 8),
        Parent = self.main,
    })

    self.stroke = self.window:Create("UIStroke", {
        Thickness = 1,
        Transparency = 1, -- In = 0.8

        Parent = self.main,
    }, { Color = "SurfaceStroke" })

    self.shadow = self.window:CreateGlow(self.main, "ShadowColor", 14, 1) -- In = 0.6

    self.window:Create("UIPadding", {
        PaddingTop = UDim.new(0, 7),
        PaddingBottom = UDim.new(0, 7),
        PaddingLeft = UDim.new(0, 9),
        PaddingRight = UDim.new(0, 11),
        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 8),
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.main,
    })

    -- The accent tick (a small coloured bar between the icon/avatar and the text) that used to
    -- live here is gone - live-reported as "essa porra de barra colorida... só atrapalhando", not
    -- needed now that the chip carries real content (avatar, name, colour-coded readouts) instead
    -- of needing its own identity mark.
    if hasIcon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = image.resolve(properties.icon or properties.Icon),
            Size = UDim2.fromOffset(14, 14),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.main,
        }, { ImageColor3 = "ContentColor" })
    end

    if avatarUserId then
        self.avatarImage = self.window:Create("ImageLabel", {
            Image = ("rbxthumb://type=AvatarHeadShot&id=%d&w=48&h=48"):format(avatarUserId),
            Size = UDim2.fromOffset(18, 18),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            LayoutOrder = 1,

            ImageTransparency = 1, -- In = 0

            Parent = self.main,
        })
        self.window:Create("UICorner", {
            CornerRadius = UDim.new(1, 0),
            Parent = self.avatarImage,
        })
    end

    self.label = self.window:Create("TextLabel", {
        Text = self.text,
        -- A dev building a multi-segment readout (player name, hub name, colour-coded ping/fps -
        -- see the hub template's own use of this) needs real inline colour, which only renders
        -- through RichText - plain text with a literal "<font...>" in it would otherwise show
        -- those tags as text instead of parsing them.
        RichText = true,
        AutomaticSize = Enum.AutomaticSize.XY,
        Size = UDim2.fromOffset(0, 0),
        BackgroundTransparency = 1,
        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 3,

        -- Animation
        TextTransparency = 1, -- In = 0

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    -- Fired once per drag (on release, not per-frame - see the release() local in _wireDrag)
    -- with the chip's landed Position, so a consumer script can persist a player's dragged
    -- position across sessions (see Window:RegisterFlag in windowExtra.luau) without polling.
    self._positionChangedCallbacks = {}

    self:_reveal(hasIcon)
    self:_wireDrag()

    return self
end

-- Grow-and-fade-in, same beat as a notification card's own entrance.
function Hud:_reveal(hasIcon)
    local ts = variables.tweenService
    ts:Create(self.main, revealInfo, { BackgroundTransparency = 0 }):Play()
    ts:Create(self.stroke, revealInfo, { Transparency = 0.8 }):Play()
    ts:Create(self.shadow, revealInfo, { Transparency = 0.6 }):Play()
    if hasIcon and self.iconLabel then
        ts:Create(self.iconLabel, revealInfo, { ImageTransparency = 0 }):Play()
    end
    if self.avatarImage then
        ts:Create(self.avatarImage, revealInfo, { ImageTransparency = 0 }):Play()
    end
    ts:Create(self.label, revealInfo, { TextTransparency = 0 }):Play()
end

function Hud:SetText(text)
    self.text = text
    self.label.Text = text
end

-- Toggle the whole chip on/off - a dev wiring this to a player Settings toggle (e.g. "show FPS/
-- ping") doesn't need to Destroy()/recreate it just to let a player hide it and bring it back.
function Hud:SetVisible(visible: boolean)
    self.main.Visible = visible and true or false
end

-- Move the chip directly (e.g. restoring a player's last dragged position from a saved flag -
-- see Window:RegisterFlag). Doesn't itself fire OnPositionChanged: that hook is specifically "the
-- player just dragged this", not "something moved it", so a restore here can't loop back into
-- whatever's listening for the drag.
function Hud:SetPosition(position: UDim2)
    self.main.Position = position
end

-- Fires once per drag, right when the player lets go (not continuously while dragging - see
-- notifyPositionSettled in _wireDrag), with the chip's landed Position. For persisting a dragged
-- position across sessions.
function Hud:OnPositionChanged(callback: (position: UDim2) -> ())
    table.insert(self._positionChangedCallbacks, callback)
end

-- Plain mouse/touch drag, clamped to stay fully on screen. Same grab-relative-offset +
-- GetMouseLocation() + GuiInset approach window.luau's own _bindTopbarDrag uses (see its
-- comments for why: main.Position lives in inset-shifted space even though the ScreenGui
-- ignores the inset itself), just simpler since there's no lagging bar to also drag along.
function Hud:_wireDrag()
    local uis = variables.userInputService
    local dragging = false
    local relative = Vector2.zero
    local offset = Vector2.zero
    if self.window.screenGui and self.window.screenGui.IgnoreGuiInset then
        offset = variables.guiService:GetGuiInset()
    end

    local function target()
        local position = uis:GetMouseLocation() + relative + offset
        local size = self.main.AbsoluteSize
        local screen = self.window.screenGui.AbsoluteSize
        local margin = 4
        local x = math.clamp(position.X, margin, math.max(margin, screen.X - size.X - margin))
        local y = math.clamp(position.Y, margin, math.max(margin, screen.Y - size.Y - margin))
        return UDim2.fromOffset(x, y)
    end

    -- brightens the stroke while held, same tactile cue drag.luau's own bar uses, so the chip
    -- doesn't just silently teleport around with nothing acknowledging the grab
    local function setGrabbed(grabbed)
        variables.tweenService
            :Create(self.stroke, dragStrokeInfo, { Transparency = grabbed and 0.35 or 0.8 })
            :Play()
    end

    self.window:ConnectFor(self, self.main.InputBegan, function(input, processed)
        if processed then
            return
        end
        local t = input.UserInputType
        if t ~= Enum.UserInputType.MouseButton1 and t ~= Enum.UserInputType.Touch then
            return
        end
        dragging = true
        setGrabbed(true)
        if self.window.screenGui and self.window.screenGui.IgnoreGuiInset then
            offset = variables.guiService:GetGuiInset()
        end
        relative = self.main.AbsolutePosition - uis:GetMouseLocation()
    end)

    local function notifyPositionSettled()
        for _, callback in self._positionChangedCallbacks do
            task.spawn(callback, self.main.Position)
        end
    end

    local function release(input)
        local t = input.UserInputType
        if t == Enum.UserInputType.MouseButton1 or t == Enum.UserInputType.Touch then
            if dragging then
                setGrabbed(false)
                notifyPositionSettled()
            end
            dragging = false
        end
    end
    self.window:ConnectFor(self, uis.InputEnded, release)
    self.window:ConnectFor(self, uis.WindowFocusReleased, function()
        if dragging then
            setGrabbed(false)
            notifyPositionSettled()
        end
        dragging = false
    end)

    self.window:ConnectFor(self, variables.runService.RenderStepped, function()
        if dragging then
            self.main.Position = target()
        end
    end)
end

function Hud:Destroy()
    if self._pulseTween then
        self._pulseTween:Cancel()
        self._pulseTween = nil
    end
    if self.connections then
        for _, connection in self.connections do
            self.window:Disconnect(connection)
        end
        table.clear(self.connections)
    end
    self.window:DestroySubtree(self.main)
end

return Hud
]=====]

sources["components/input"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Input = {}
Input.__index = Input
Input.__type = "Input"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local resizeInfo = constants.pillResizeInfo
-- text is muted at rest, opaque while typing
local focusInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

-- Parse a simple exponent expression like "5^3" → 125. Falls back to tonumber for
-- plain numbers and scientific notation ("9e9" → 9000000000).
local function parseExp(text)
    local a, b = text:match("^([%d%.%-]+)%^([%d%.%-]+)$")
    if a and b then
        local na, nb = tonumber(a), tonumber(b)
        if na and nb then
            return na ^ nb
        end
    end
    return tonumber(text)
end

function Input.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Input",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,
        placeholder = properties.placeholder or properties.Placeholder or "",
        numeric = properties.numeric or properties.Numeric or false, -- strip anything not a number
        clearOnFocus = properties.clearOnFocus or properties.ClearOnFocus or false,

        callback = properties.callback or properties.Callback or function() end,
    }, Input)

    self.value =
        tostring(properties.value or properties.Value or properties.currentValue or properties.CurrentValue or "")

    self.flag = properties.flag
        or properties.Flag
        or (not self.forgetState and functions.deriveFlagFromName(self.name) or nil)
    self.window:_registerControl(self)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 41),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)

    -- Left: title (+ icon)
    self.container = self.window:Create("Frame", {
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ZIndex = 5,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(150, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 1,
        ZIndex = 5,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- Right: the field. A faint white pill pinned to the right that hugs its text.
    self.box = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -7, 0, 20),
        Size = UDim2.fromOffset(85, 30),
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- In = FieldTransparency

        Parent = self.main,
    }, { BackgroundColor3 = "FieldBackground" })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),
        Parent = self.box,
    })

    self.boxStroke = self.window:Create("UIStroke", {
        Transparency = 1, -- In = 0.85

        Parent = self.box,
    }, { Color = "SurfaceStroke" })

    -- glow behind the box, invisible until a set flashes it green/red
    self.glow = self.window:CreateGlow(self.box, "FieldGlow", 20, 1)
    self._glowIdle = 1 -- glow hidden at rest (used by the set-result flash)

    self.input = self.window:Create("TextBox", {
        Text = self.value,
        PlaceholderText = locale.t(self.placeholder),
        Size = UDim2.new(1, -15, 0, 15),
        Position = UDim2.new(0.5, 0, 0.5, 0),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Center,
        TextTruncate = Enum.TextTruncate.AtEnd,
        ClearTextOnFocus = self.clearOnFocus,

        TextTransparency = 1, -- In = 0.6

        Parent = self.box,
    }, { TextColor3 = "ContentColor", FontFace = "Font", PlaceholderColor3 = "PlaceholderColor" })

    -- resize to hug the text; numeric mode also strips non-number chars as they're typed
    self.window:ConnectFor(self, self.input:GetPropertyChangedSignal("Text"), function()
        if self.numeric then
            local cleaned = (self.input.Text:gsub("[^%d%.%-eE%^]", ""))
            if cleaned ~= self.input.Text then
                self.input.Text = cleaned
                return -- the reassignment re-fires this, we size on that pass
            end
        end
        self:_sizeBox(true)
    end)

    -- opaque while the field is focused, back to muted when you click away
    self.window:ConnectFor(self, self.input.Focused, function()
        variables.tweenService:Create(self.input, focusInfo, { TextTransparency = 0 }):Play()
    end)

    -- commit on focus loss (enter or click away)
    self.window:ConnectFor(self, self.input.FocusLost, function()
        variables.tweenService:Create(self.input, focusInfo, { TextTransparency = 0.6 }):Play()
        -- clearOnFocus blanks the box on focus, so a click in and straight back out would
        -- commit "" over a good value. nothing typed means nothing to commit.
        if self.clearOnFocus and self.input.Text == "" and self.value ~= "" then
            self.input.Text = self.value
            return
        end
        if self.input.Text == self.value then
            return -- unchanged: dont re-fire the devs callback for a stray click
        end
        self:_commit(self.input.Text)
    end)

    self.window:_wireElementHover(self)
    self.window:_wireTooltip(self)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    self:_sizeBox(false) -- initial hug, no animation

    return self
end

-- width the pill needs to hug its text (placeholder when empty), floored so it stays a
-- readable pill and capped so a long value can't run over the title
function Input:_sizeBox(animate)
    local shown = self.input.Text ~= "" and self.input.Text or self.placeholder
    local width = math.clamp(functions.textWidth(self.window.theme.Font, 15, shown) + 30, 70, 220)
    if animate then
        variables.tweenService:Create(self.box, resizeInfo, { Size = UDim2.fromOffset(width, 30) }):Play()
    else
        self.box.Size = UDim2.fromOffset(width, 30)
    end
end

-- store + fire the callback + autosave, shared by typing and :Set. silent skips the
-- callback/persist/flash so config loads restore quietly.
function Input:_commit(text, silent)
    text = tostring(text)
    if self.numeric then
        local n = parseExp(text)
        if not n or n == math.huge or n == -math.huge then
            -- invalid or non-finite number: revert the textbox to the previous value
            if self.input.Text ~= self.value then
                self.input.Text = self.value
            end
            return
        end
        text = tostring(n)
    end

    local changed = text ~= self.value
    self.value = text
    if self.input.Text ~= text then
        self.input.Text = text
    end

    if not silent then
        self.window:_runGuarded(self, self.callback, text)
        self.window:_persist(self)
        -- green flash to confirm the value landed (only when it actually changed, and not while a
        -- config restore is applying every field at once)
        if changed and not self.window._loading then
            hapticEngine.click()
            soundEngine.click()
            self.window:_flashResult(self, true)
        end
    end
end

function Input:Set(value, skipCallback)
    self:_commit(value, skipCallback)
end

function Input:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.box, { BackgroundTransparency = w.theme.FieldTransparency }, animate)
        w:_reveal(self.boxStroke, { Transparency = 0.85 }, animate)
        w:_reveal(self.input, { TextTransparency = 0.6 }, animate)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.box, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.boxStroke, { Transparency = 1 }, animate)
        w:_reveal(self.input, { TextTransparency = 1 }, animate)
    end
end

-- Re-apply the field's theme-driven fill transparency on a runtime ChangeTheme (its colour
-- rides a themeProperty). Called on the visible tab only, so the field is shown.
function Input:_refreshTheme()
    variables.tweenService
        :Create(
            self.box,
            TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { BackgroundTransparency = self.window.theme.FieldTransparency }
        )
        :Play()
end

moveable(Input)
lockable(Input)

return Input
]=====]

sources["components/keybind"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Keybind = {}
Keybind.__index = Keybind
Keybind.__type = "Keybind"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local constants = require(utility.constants)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local enums = require(utility.enums)
local log = require(utility.log)

local resizeInfo = constants.pillResizeInfo
local recordInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

-- shorter labels for the mouse buttons (KeyCodes already read fine)
local mouseNames = {
    [Enum.UserInputType.MouseButton1] = "MB1",
    [Enum.UserInputType.MouseButton2] = "MB2",
    [Enum.UserInputType.MouseButton3] = "MB3",
}

local function keyName(value)
    if typeof(value) ~= "EnumItem" or value == Enum.KeyCode.Unknown then
        return "None"
    end
    return mouseNames[value] or value.Name
end

-- accept an EnumItem, a KeyCode name, or a mouse button name, fall back to unbound.
-- mouse buttons bind like any other key, so a string has to reach them too.
local function coerceKey(value)
    if typeof(value) == "EnumItem" then
        return value
    end
    if type(value) == "string" then
        local ok, key = pcall(function()
            return Enum.KeyCode[value]
        end)
        if ok and key then
            return key
        end
        local mouseOk, button = pcall(function()
            return Enum.UserInputType[value]
        end)
        if mouseOk and button and mouseNames[button] then
            return button
        end
    end
    return Enum.KeyCode.Unknown
end

function Keybind.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Keybind",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,

        -- the settings' menu-toggle keybind. it drives settings.toggleKeybind, so its clash
        -- check runs the other way: reject keys an element keybind already owns.
        isMenuToggle = properties.isMenuToggle or properties.IsMenuToggle or false,

        -- fires when the bound key is pressed (or, in hold mode, with true/false)
        callback = properties.callback or properties.Callback or function() end,
        -- fires when the binding changes (rebind or :Set), gets the new key
        onChanged = properties.onChanged or properties.OnChanged or function() end,

        -- hold mode: callback(true) once the key survives holdThreshold, callback(false) on release.
        -- the threshold means a quick accidental tap fires nothing.
        hold = properties.hold or properties.Hold or false,
        holdThreshold = properties.holdThreshold or properties.HoldThreshold or 0.2,

        recording = false,
    }, Keybind)

    self.value = coerceKey(properties.value or properties.Value or properties.default or properties.Default)

    self.flag = properties.flag
        or properties.Flag
        or (not self.forgetState and functions.deriveFlagFromName(self.name) or nil)
    self.window:_registerControl(self)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 41),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)

    -- Left: title (+ icon)
    self.container = self.window:Create("Frame", {
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ZIndex = 5,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(150, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 1,
        ZIndex = 5,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- Right: the key box. A faint white pill pinned right that hugs the key name.
    self.box = self.window:Create("TextButton", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -7, 0, 20),
        Size = UDim2.fromOffset(40, 30),
        AutoButtonColor = false,
        Text = "",
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- In = FieldTransparency

        Parent = self.main,
    }, { BackgroundColor3 = "FieldBackground" })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),
        Parent = self.box,
    })

    self.boxStroke = self.window:Create("UIStroke", {
        Transparency = 1, -- In = 0.85

        Parent = self.box,
    }, { Color = "SurfaceStroke" })

    -- soft white glow behind the box: 0.9 idle, 0.7 while recording
    self.glow = self.window:CreateGlow(self.box, "FieldGlow", 20, 1)
    self._glowIdle = 0.9 -- glow Transparency at rest (used by the set-result flash)

    self.keyLabel = self.window:Create("TextLabel", {
        Text = keyName(self.value),
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Center,
        ZIndex = 2,

        TextTransparency = 1, -- In = 0.6

        Parent = self.box,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.window:ConnectFor(self, self.box.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        -- A keybind is fundamentally a physical-key concept - _capture below only ever
        -- recognizes Enum.UserInputType.Keyboard (plus MB2/MB3, which a touch device also has
        -- no equivalent for). Entering "Recording" on a touch-primary device would just sit
        -- there forever with no input it could ever actually catch, discoverable only as "tapping
        -- this does nothing" - telling the player why up front instead of pretending to listen.
        if self.window:IsMobile() then
            self.window:Notify({
                title = locale.resolve("Keybind unavailable"),
                content = locale.resolve("Keybinds need a physical keyboard or mouse."),
            })
            return
        end
        if self.recording then
            self:_stopRecording()
        else
            self:_startRecording()
        end
    end)

    -- one persistent listener: captures the next key while recording, otherwise fires the
    -- callback when the bound key is pressed. `processed` is Roblox's gameProcessedEvent, true
    -- when the input was already consumed (typing in a box, core UI), so we skip it either way
    -- and keybinds never go off mid-type.
    self.window:ConnectFor(self, variables.userInputService.InputBegan, function(input, processed)
        if processed then
            return
        end
        if self.recording then
            self:_capture(input)
            return
        end
        -- another keybind is mid-rebind: the key being pressed is meant for it, dont let it
        -- also trigger us
        if self.window._recordingKeybind then
            return
        end
        if self:_matches(input) then
            if self.hold then
                self:_beginHold(input)
            else
                self.window:_runGuarded(self, self.callback, self.value)
            end
        end
    end)

    self.window:_wireElementHover(self)
    self.window:_wireTooltip(self)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    self:_sizeBox(false) -- initial hug, no animation

    return self
end

-- width the box needs to hug the current label, floored so a single key still reads as a pill
function Keybind:_sizeBox(animate)
    local width = math.clamp(functions.textWidth(self.window.theme.Font, 15, self.keyLabel.Text) + 28, 40, 200)
    if animate then
        variables.tweenService:Create(self.box, resizeInfo, { Size = UDim2.fromOffset(width, 30) }):Play()
    else
        self.box.Size = UDim2.fromOffset(width, 30)
    end
end

-- deepen the glow, light the label fully and prompt for a key
function Keybind:_startRecording()
    -- only one keybind records at a time; cancel whoever was listening before us
    local current = self.window._recordingKeybind
    if current and current ~= self then
        current:_stopRecording()
    end
    self.recording = true
    self.window._recordingKeybind = self -- window skips its toggle key while we listen
    self.keyLabel.Text = locale.resolve("Recording")
    self:_sizeBox(true)
    variables.tweenService:Create(self.glow, recordInfo, { Transparency = 0.7 }):Play()
    variables.tweenService:Create(self.keyLabel, recordInfo, { TextTransparency = 0 }):Play()
    -- a plain settled step to 0.7 is easy to miss in a glance across a settings list, and reads
    -- as just "a bit brighter" rather than "actively waiting for input". A slow breathing pulse
    -- is a state nothing else on this element produces, so it's unambiguous which box (if any)
    -- is currently listening.
    self:_startRecordPulse()
end

-- breathing glow while self.recording holds, same loop shape shimmerlabel.luau's own
-- task.spawn + Completed:Wait() shimmer sweep uses. Checks self.recording before every leg so
-- it winds down within one half-pulse (<=0.6s) of _stopRecording flipping the flag, rather than
-- fighting that tween's own settle back to the idle 0.9.
function Keybind:_startRecordPulse()
    local pulseInfo = TweenInfo.new(0.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
    task.spawn(function()
        while self.recording and self.glow.Parent do
            local brighten = variables.tweenService:Create(self.glow, pulseInfo, { Transparency = 0.35 })
            brighten:Play()
            brighten.Completed:Wait()
            if not self.recording or not self.glow.Parent then
                break
            end
            local dim = variables.tweenService:Create(self.glow, pulseInfo, { Transparency = 0.7 })
            dim:Play()
            dim.Completed:Wait()
        end
    end)
end

-- revert the glow + label and relabel to whatever value we ended up with
function Keybind:_stopRecording()
    self.recording = false
    -- clear next frame, not now: the key that stops us (a toggle-key clash) is still being
    -- dispatched, and the window's toggle listener may run after us. keep the flag up so it
    -- still bails instead of hiding the window on the same press.
    if self.window._recordingKeybind == self then
        local window = self.window
        task.defer(function()
            if window._recordingKeybind == self then
                window._recordingKeybind = nil
            end
        end)
    end
    self.keyLabel.Text = keyName(self.value)
    self:_sizeBox(true)
    variables.tweenService:Create(self.glow, recordInfo, { Transparency = 0.9 }):Play()
    variables.tweenService:Create(self.keyLabel, recordInfo, { TextTransparency = 0.6 }):Play()
end

-- capture the next input while recording. Esc cancels, Backspace clears, MB1 is the click
-- that opened us so it's ignored
function Keybind:_capture(input)
    local key
    if input.UserInputType == Enum.UserInputType.Keyboard then
        if input.KeyCode == Enum.KeyCode.Escape then
            self:_stopRecording()
            return
        end
        if input.KeyCode == Enum.KeyCode.Backspace then
            self:_bind(Enum.KeyCode.Unknown)
            return
        end
        key = input.KeyCode
    elseif
        input.UserInputType == Enum.UserInputType.MouseButton2
        or input.UserInputType == Enum.UserInputType.MouseButton3
    then
        key = input.UserInputType
    end
    if not key then
        return
    end

    if self.isMenuToggle then
        -- the menu toggle cant land on a key an element keybind already owns, else that press
        -- would both fire the element and open/close the window. bail and keep the old binding.
        local clash = self.window:_keybindUsing(key, self)
        if clash then
            self.window:Notify({
                title = locale.resolve("Keybind unavailable"),
                content = string.format(
                    locale.resolve("%s is bound to %s. Kept %s."),
                    keyName(key),
                    clash.name,
                    keyName(self.value)
                ),
            })
            self:_stopRecording()
            self.window:_flashResult(self, false) -- red: rejected
            return
        end
    elseif key == self.window.settings.toggleKeybind then
        -- an element keybind cant clash with the menu toggle key, same double-fire problem the
        -- other way round. bail, tell them, and keep the old binding.
        self.window:Notify({
            title = locale.resolve("Keybind unavailable"),
            content = string.format(
                locale.resolve("%s is the menu toggle key. Kept %s."),
                keyName(key),
                keyName(self.value)
            ),
        })
        self:_stopRecording()
        self.window:_flashResult(self, false) -- red: rejected
        return
    end

    self:_bind(key)
end

-- commit a new binding from the user: store, relabel, notify + autosave
function Keybind:_bind(key)
    self.value = key
    self:_stopRecording()
    self.window:_runGuarded(self, self.onChanged, key)
    self.window:_persist(self)

    self.window:_flashResult(self, true) -- green: bound
end

-- does this input match the bound key (either a KeyCode or a mouse button)
function Keybind:_matches(input)
    local v = self.value
    if typeof(v) ~= "EnumItem" or v == Enum.KeyCode.Unknown then
        return false
    end
    if v.EnumType == Enum.KeyCode then
        return input.KeyCode == v
    elseif v.EnumType == Enum.UserInputType then
        return input.UserInputType == v
    end
    return false
end

-- hold mode: arm after holdThreshold (a quick tap never counts), fire callback(true) then
-- callback(false) once, edge-triggered off this exact press ending.
function Keybind:_beginHold(input)
    if self._holding or self._holdPress then
        return -- already tracking a hold
    end
    local press = {}
    self._holdPress = press

    -- match the release against the exact key that started this hold, not self.value, so a
    -- rebind mid-hold still lets the original key release and fire callback(false).
    local heldKeyCode = input.KeyCode
    local heldInputType = input.UserInputType

    task.delay(self.holdThreshold, function()
        if self._holdPress ~= press then
            return -- released (or rebound) before it armed
        end
        self._holding = true
        self.window:_runGuarded(self, self.callback, true)
    end)

    -- release edge off the global InputEnded (robust to synthetic input, where the original
    -- InputObject's state doesnt always transition). filed on the element so Tab:Remove drops it
    -- and a release cant fire the callback against a torn-down keybind.
    local conn
    conn = self.window:ConnectFor(self, variables.userInputService.InputEnded, function(ended)
        local released = if heldKeyCode ~= Enum.KeyCode.Unknown
            then ended.KeyCode == heldKeyCode
            else ended.UserInputType == heldInputType
        if not released then
            return
        end
        -- ConnectFor files it on our list too, so drop it there or repeated holds pile up
        if self.connections then
            local index = table.find(self.connections, conn)
            if index then
                table.remove(self.connections, index)
            end
        end
        self.window:Disconnect(conn)
        if self._holdPress == press then
            self._holdPress = nil
        end
        if self._holding then
            self._holding = false
            self.window:_runGuarded(self, self.callback, false)
        end
    end)
end

function Keybind:Set(value, skipChanged)
    local key = coerceKey(value)

    -- same clash rules as interactive capture: a shared bind double-fires, so refuse it and
    -- keep the current one. covers programmatic sets and config restores alike.
    if key ~= Enum.KeyCode.Unknown then
        if self.isMenuToggle then
            local clash = self.window:_keybindUsing(key, self)
            if clash then
                log.warn(
                    "Rayfield: "
                        .. keyName(key)
                        .. " is bound to '"
                        .. tostring(clash.name)
                        .. "'; kept "
                        .. keyName(self.value)
                )
                return
            end
        elseif key == self.window.settings.toggleKeybind then
            log.warn("Rayfield: " .. keyName(key) .. " is the menu toggle key; kept " .. keyName(self.value))
            return
        end
    end

    self.value = key
    if self.recording then
        self:_stopRecording() -- also relabels + resizes for us
    else
        self.keyLabel.Text = keyName(self.value)
        self:_sizeBox(true)
    end

    if not skipChanged then
        self.window:_runGuarded(self, self.onChanged, self.value)
        self.window:_persist(self)
    end
end

-- Persistence: store the enum type + value so any bound KeyCode or mouse button round-trips.
function Keybind:_serialize()
    return { tostring(self.value.EnumType), self.value.Value }
end

function Keybind:_deserialize(raw)
    -- the saved type is tostring(EnumType), e.g. "Enum.KeyCode", so strip the prefix before lookup
    local enumName = tostring(raw[1]):gsub("^Enum%.", "")
    local enumOk, enumType = pcall(function()
        return Enum[enumName]
    end)
    if not enumOk or not enumType then
        return
    end

    local item = enums.itemFromValue(enumType, raw[2])
    if item then
        self:Set(item)
    end
end

function Keybind:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.box, { BackgroundTransparency = w.theme.FieldTransparency }, animate)
        w:_reveal(self.boxStroke, { Transparency = 0.85 }, animate)
        w:_reveal(self.keyLabel, { TextTransparency = 0.6 }, animate)
        w:_reveal(self.glow, { Transparency = 0.9 }, animate)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.box, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.boxStroke, { Transparency = 1 }, animate)
        w:_reveal(self.keyLabel, { TextTransparency = 1 }, animate)
        w:_reveal(self.glow, { Transparency = 1 }, animate)
    end
end

-- Re-apply the box's theme-driven fill transparency on a runtime ChangeTheme (its colour rides
-- a themeProperty). Called on the visible tab only, so the box is shown.
function Keybind:_refreshTheme()
    variables.tweenService
        :Create(
            self.box,
            TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { BackgroundTransparency = self.window.theme.FieldTransparency }
        )
        :Play()
end

moveable(Keybind)
lockable(Keybind)

return Keybind
]=====]

sources["components/label"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 9 "Label": a bare line of text on the page, no card behind it - for copy that doesn't
-- belong hanging off a button/toggle as a description (that's Descriptor, only ever built
-- internally by another element's own `description` property) but also isn't substantial enough
-- to earn its own Paragraph card (see paragraph.luau). Wraps onto further lines on its own as the
-- window narrows, same as every other element's text - explicit width math (the row's own width
-- minus the icon's, if there is one) rather than UIListLayout + UIFlexItem, which only reliably
-- grows/shrinks a sibling's width, not wraps text inside it.

local Label = {}
Label.__index = Label
Label.__type = "Label"

local moveable = require(script.Parent.Parent.utility.moveable)
local locale = require(script.Parent.Parent.utility.locale)

local iconSize = 16
local iconGap = 8

function Label.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local text = properties.text or properties.Text or ""

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        icon = properties.icon or properties.Icon,
    }, Label)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.tab.tabPage,
    })

    local titleInset = if self.icon then iconSize + iconGap else 0

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(iconSize, iconSize),
            Position = UDim2.fromOffset(0, 1), -- nudged down a hair to sit on the first line's baseline
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            -- Animation
            ImageTransparency = 1, -- In = 0

            Parent = self.main,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(text),

        Position = UDim2.fromOffset(titleInset, 0),
        Size = UDim2.new(1, -titleInset, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        TextWrapped = true,

        -- Animation
        TextTransparency = 1, -- In = 0

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    return self
end

-- Swap the copy - main's AutomaticSize.Y reflows the row to the new height on its own, no
-- manual height math needed.
function Label:Set(text)
    self.title.Text = text or ""
end

function Label:_setShown(shown, animate)
    local w = self.window
    w:_reveal(self.title, { TextTransparency = if shown then 0 else 1 }, animate)
    if self.iconLabel then
        w:_reveal(self.iconLabel, { ImageTransparency = if shown then 0 else 1 }, animate)
    end
end

moveable(Label)

return Label
]=====]

sources["components/notification"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Notification = {}
Notification.__index = Notification
Notification.__type = "Notification"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local constants = require(utility.constants)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

-- Timings/easings copied from Rayfield Gen1 (all Exponential, Out).
local growInfo = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local fadeLong = TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- bg + stroke
local fadeShort = TweenInfo.new(0.3, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- title/icon/desc/shadow
-- entry: card slides in from the right as the slot opens
local swipeInInfo = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
-- exit "scale": shrink width + collapse height while it fades
local shrinkInfo = TweenInfo.new(0.9, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)

local offscreenRight = UDim2.new(0.5, 360, 0.5, 0)
local centred = UDim2.new(0.5, 0, 0.5, 0)

-- Roughly what fits in the 800px stack. Past this the oldest is retired early rather than
-- left to march off the top of the screen still running its own dwell loop.
local maxLive = 6

-- Gap between stacked notifications. Applied INSIDE each notification (as top
-- padding on the outer frame) rather than on the container's UIListLayout, so
-- removing one collapses its gap with it instead of dropping an external gap
-- and making the notifications above jump up.
local stackPadding = 8

-- Auto duration from content length, clamped to a sensible window (Gen1-style)
local function autoDuration(content)
    return math.clamp(#content * 0.06 + 3, 3, 9)
end

-- Height of the optional progress bar (see SetProgress) - lazily built, so most notifications
-- never pay for it.
local progressHeight = 4

function Notification.new(window, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
        title = properties.title or properties.Title or "Notification",
        -- Description is Fluent's own name for this same field - accepted here too so the
        -- typed NotifySuccess/Warning/Info/Error wrappers (see window.luau) can just forward
        -- whatever shape a script already calls them with, Fluent-style or not.
        content = properties.content or properties.Content or properties.description or properties.Description or "",
        icon = properties.icon or properties.Icon,
        -- optional per-instance override for the icon's own colour - the typed wrappers pass
        -- their preset accent through here; plain Window:Notify calls leave it nil and get the
        -- ordinary themed ContentColor, same as before this existed.
        accentColor = properties.accentColor or properties.AccentColor,
        _hovered = false,
        _dismissed = false,
        Destroyed = false, -- public mirror of _dismissed, for a caller polling a held reference
    }, Notification)

    -- Persist: skip the auto-dismiss dwell entirely - the caller owns this notification's
    -- lifetime and must call :Destroy() themselves. For a long-running job's progress card
    -- (see SetProgress below) rather than an ordinary toast that should just go away on its own.
    self.persist = properties.persist or properties.Persist or false

    -- Time is Fluent's own name for this field, same reasoning as content/Description above.
    self.duration = if self.persist
        then math.huge
        else properties.duration or properties.Duration or properties.time or properties.Time or autoDuration(
            self.content
        )

    local hasIcon = self.icon ~= nil and self.icon ~= 0 and self.icon ~= ""

    -- Outer frame: the stack layout item. Invisible itself; only its height is
    -- animated (grow in / collapse the gap on exit).
    self.main = self.window:Create("Frame", {
        Name = "Notification",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 0),
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.notification,

        Parent = self.window.notifications,
    })

    -- Inter-notification gap lives here (not on the stack layout) so it collapses
    -- with the card and its neighbours don't jump when it's removed.
    self.window:Create("UIPadding", {
        PaddingTop = UDim.new(0, stackPadding),

        Parent = self.main,
    })

    -- Inner body: the visible card. Centred so the exit width-shrink pulls in
    -- symmetrically from both sides.
    self.body = self.window:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        Size = UDim2.new(1, 0, 1, 0),
        Position = offscreenRight, -- starts off to the right; _show slides it in
        AnchorPoint = Vector2.new(0.5, 0.5),
        Active = true, -- receives input for click-to-dismiss
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.notification,

        -- Animation
        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    })

    self.window:Create("UIGradient", {
        Rotation = 270,
        Offset = Vector2.new(0, -0.1),

        Parent = self.body,
    }, { Color = { "WindowColor", functions.toColorSequence } })

    self.window:Create("UICorner", {
        Parent = self.body,
    }, { CornerRadius = "CornerRoundness" })

    self.stroke = self.window:Create("UIStroke", {
        Transparency = 1, -- In = 0.95

        Parent = self.body,
    }, { Color = "SurfaceStroke" })

    self.shadow = self.window:CreateGlow(self.body, "ShadowColor", 20, 1) -- In = 0.6

    -- Horizontal insets; vertical padding comes from centering the row in the grown height
    self.window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 20),
        PaddingRight = UDim.new(0, 20),

        Parent = self.body,
    })

    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 14),

        Parent = self.body,
    })

    if hasIcon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(24, 24),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            LayoutOrder = 1,
            ZIndex = constants.zIndex.notification,

            -- Animation
            ImageTransparency = 1, -- In = 0

            Parent = self.body,
        }, { ImageColor3 = "ContentColor" })

        -- Plain instance property, set once, after the theme binding above rather than through
        -- it - only ImageTransparency ever gets tweened on this label (see _show/_dismiss), so
        -- there's nothing later that would fight or overwrite a colour set here.
        if self.accentColor then
            self.iconLabel.ImageColor3 = self.accentColor
        end
    end

    -- Text column fills the row minus icon + padding (container is 300 wide)
    self.container = self.window:Create("Frame", {
        Size = UDim2.fromOffset(hasIcon and 222 or 260, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 2,
        ZIndex = constants.zIndex.notification,

        Parent = self.body,
    })

    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 4),

        Parent = self.container,
    })

    self.titleLabel = self.window:Create("TextLabel", {
        Text = self.title,
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 1,
        ZIndex = constants.zIndex.notification,

        -- Animation
        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    if self.content ~= "" then
        self.descriptionLabel = self.window:Create("TextLabel", {
            Text = self.content,
            Size = UDim2.new(1, 0, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundTransparency = 1,
            TextSize = 15,
            TextWrapped = true,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextYAlignment = Enum.TextYAlignment.Top,
            LayoutOrder = 2,
            ZIndex = constants.zIndex.notification,

            -- Animation
            TextTransparency = 1, -- In = 0.35

            Parent = self.container,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })
    end

    -- Newest sits at the bottom of the (bottom-anchored) stack
    self.window._notificationCount = (self.window._notificationCount or 0) + 1
    self.main.LayoutOrder = self.window._notificationCount

    -- a callback that notifies in a loop would stack cards forever, so retire the oldest once
    -- theres more than the stack can show
    local live = self.window._liveNotifications
    if not live then
        live = {}
        self.window._liveNotifications = live
    end
    table.insert(live, self)
    while #live > maxLive do
        local oldest = table.remove(live, 1)
        if oldest and oldest ~= self then
            task.spawn(oldest._dismiss, oldest)
        end
    end

    -- tracked so _dismiss can drop them; notifications come and go so we cant let their
    -- connections/instances sit in the window lists until Unload
    self._connections = {
        self.window:Connect(self.body.MouseEnter, function()
            self._hovered = true
        end),
        self.window:Connect(self.body.MouseLeave, function()
            self._hovered = false
        end),
        self.window:Connect(self.body.InputBegan, function(input)
            if
                input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch
            then
                self:_dismiss()
            end
        end),
    }

    task.spawn(function()
        self:_show()
    end)

    return self
end

-- Height the card needs, measured without rendering (so nothing flickers into
-- the stack before it's ready to animate).
function Notification:_measure()
    local colWidth = self.iconLabel and 222 or 260

    local contentH = functions.textHeight(self.window.theme.TitleFont, 16, self.title, colWidth)
    if self.descriptionLabel then
        contentH = contentH + 4 + functions.textHeight(self.window.theme.Font, 15, self.content, colWidth)
    end
    if self.progressTrack then
        contentH = contentH + 4 + progressHeight
    end

    return math.max(contentH, self.iconLabel and 24 or 0) + 28
end

-- Re-measures and tweens the outer slot to the new height - anything that changes the card's
-- text/progress after it's already on screen (ChangeTitle/ChangeDescription/SetProgress) needs
-- this, since (unlike the inner labels) the outer frame's height is a one-shot tween from _show,
-- not AutomaticSize - see _show's own comment on why (no flicker before the grow-in starts).
function Notification:_resize()
    if self._dismissed or not self.main.Parent then
        return
    end
    local target = self:_measure() + stackPadding
    variables.tweenService:Create(self.main, fadeLong, { Size = UDim2.new(1, 0, 0, target) }):Play()
end

-- Update the title/description after the card is already showing - a progress card started with
-- Notify({ persist = true }) calls these each step instead of firing a new toast per tick.
function Notification:ChangeTitle(text)
    if self._dismissed then
        return
    end
    self.title = text
    self.titleLabel.Text = text
    self:_resize()
end

function Notification:ChangeDescription(text)
    if self._dismissed then
        return
    end
    self.content = text
    self:_ensureDescriptionLabel()
    self.descriptionLabel.Text = text
    self:_resize()
end

-- Lazily builds the description label for a card that started with no content (title-only) -
-- ChangeDescription can still be the first thing that gives it one.
function Notification:_ensureDescriptionLabel()
    if self.descriptionLabel then
        return
    end
    self.descriptionLabel = self.window:Create("TextLabel", {
        Text = "",
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        TextSize = 15,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        LayoutOrder = 2,
        ZIndex = constants.zIndex.notification,

        TextTransparency = 0.35,

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })
end

-- Thin accent-coloured bar under the text, lazily built on first use - most notifications never
-- call this, so it costs nothing for the ordinary toast path.
function Notification:_ensureProgressBar()
    if self.progressTrack then
        return
    end
    self.progressTrack = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, progressHeight),
        BackgroundTransparency = 0.85,
        BorderSizePixel = 0,
        LayoutOrder = 3,
        ClipsDescendants = true,
        ZIndex = constants.zIndex.notification,

        Parent = self.container,
    }, { BackgroundColor3 = "SurfaceStroke" })
    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),
        Parent = self.progressTrack,
    })
    self.progressFill = self.window:Create("Frame", {
        Size = UDim2.new(0, 0, 1, 0),
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.notification,

        Parent = self.progressTrack,
    }, { BackgroundColor3 = "AccentColor" })
    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),
        Parent = self.progressFill,
    })
end

-- 0-1. A long-running batch action (redeeming N codes, importing M entries) calls this each
-- step instead of firing a fresh toast per item - one card, updated in place.
function Notification:SetProgress(fraction)
    if self._dismissed then
        return
    end
    fraction = math.clamp(fraction or 0, 0, 1)
    local firstUse = not self.progressTrack
    self:_ensureProgressBar()
    if firstUse then
        self:_resize()
    end
    variables.tweenService:Create(self.progressFill, fadeShort, { Size = UDim2.new(fraction, 0, 1, 0) }):Play()
end

-- Public alias for _dismiss - a persist notification has no dwell timer to end it, so the
-- caller ends it explicitly (a batch job finishing, an error aborting it) via this name.
function Notification:Destroy()
    self:_dismiss()
end

-- Enter: grow the height, then stagger the fades (Gen1 timing).
function Notification:_show()
    -- All sizing done before anything is visible: outer is height 0 and the body
    -- is fully transparent until the grow tween starts, so there's no flicker.
    -- +stackPadding because the outer's top padding holds the inter-card gap.
    local target = self:_measure() + stackPadding
    if not self.main.Parent then
        return
    end

    hapticEngine.notify()
    soundEngine.notify()

    -- Open the slot and slide the card in from the right (body starts off-right), fading as it comes
    variables.tweenService:Create(self.main, growInfo, { Size = UDim2.new(1, 0, 0, target) }):Play()
    variables.tweenService:Create(self.body, swipeInInfo, { Position = centred }):Play()
    variables.tweenService:Create(self.body, fadeLong, { BackgroundTransparency = 0 }):Play()
    variables.tweenService:Create(self.titleLabel, fadeShort, { TextTransparency = 0 }):Play()
    variables.tweenService:Create(self.stroke, fadeLong, { Transparency = 0.95 }):Play()
    variables.tweenService:Create(self.shadow, fadeShort, { Transparency = 0.6 }):Play()

    task.wait(0.05)
    if self._dismissed or not self.main.Parent then
        return -- dismissed mid-stagger; dont fight the exit fade
    end
    if self.iconLabel then
        variables.tweenService:Create(self.iconLabel, fadeShort, { ImageTransparency = 0 }):Play()
    end

    task.wait(0.05)
    if self._dismissed or not self.main.Parent then
        return
    end
    if self.descriptionLabel then
        variables.tweenService:Create(self.descriptionLabel, fadeShort, { TextTransparency = 0.35 }):Play()
    end

    -- Dwell, pausing while hovered
    local elapsed = 0
    while elapsed < self.duration and not self._dismissed and self.main.Parent do
        local dt = task.wait()
        if not self._hovered then
            elapsed += dt
        end
    end

    self:_dismiss()
end

-- Exit: fade out while the card shrinks (width + height) - Gen1's exit.
function Notification:_dismiss()
    if self._dismissed then
        return
    end
    self._dismissed = true
    self.Destroyed = true

    local live = self.window._liveNotifications
    local index = live and table.find(live, self)
    if live and index then
        table.remove(live, index)
    end

    if not self.main.Parent then
        return
    end

    -- Fade everything out (runs during the shrink -> "goes transparent as it scales")
    variables.tweenService:Create(self.body, fadeLong, { BackgroundTransparency = 1 }):Play()
    variables.tweenService:Create(self.stroke, fadeLong, { Transparency = 1 }):Play()
    variables.tweenService:Create(self.shadow, fadeShort, { Transparency = 1 }):Play()
    variables.tweenService:Create(self.titleLabel, fadeShort, { TextTransparency = 1 }):Play()
    if self.descriptionLabel then
        variables.tweenService:Create(self.descriptionLabel, fadeShort, { TextTransparency = 1 }):Play()
    end
    if self.iconLabel then
        variables.tweenService:Create(self.iconLabel, fadeShort, { ImageTransparency = 1 }):Play()
    end
    -- Live-caught: these two were never included here, so a progress card's bar just sat fully
    -- opaque while everything else around it faded in ~0.3-0.4s, only actually disappearing once
    -- the 0.9s shrink below finally clipped it out of view - reads as "the bar takes way longer
    -- to go than the rest of the card", not a synchronized exit.
    if self.progressTrack then
        variables.tweenService:Create(self.progressTrack, fadeShort, { BackgroundTransparency = 1 }):Play()
    end
    if self.progressFill then
        variables.tweenService:Create(self.progressFill, fadeShort, { BackgroundTransparency = 1 }):Play()
    end

    -- Shrink: narrow the card (width -90) and collapse the slot (height 0) together
    variables.tweenService:Create(self.body, shrinkInfo, { Size = UDim2.new(1, -90, 1, 0) }):Play()
    local collapse = variables.tweenService:Create(self.main, shrinkInfo, { Size = UDim2.new(1, 0, 0, 0) })
    collapse:Play()
    collapse.Completed:Wait()

    if not self.main.Parent then
        return
    end

    for _, connection in self._connections do
        self.window:Disconnect(connection)
    end
    self.window:DestroySubtree(self.main)
end

return Notification
]=====]

sources["components/paragraph"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 9 "Paragraph": a styled card for copy too long to hang off an element as a description
-- (that's Descriptor, only ever built internally by another element's own `description`
-- property) - longform notices, docs, changelog-adjacent writeups. Title and body are
-- independently optional; whichever one's empty just isn't shown in the card's own UIListLayout
-- (Visible = false skips it entirely), and AutomaticSize.Y reflows the card's height around
-- whatever's left - so passing just a body (or just a title) never leaves a blank line where the
-- other would've been.

local Paragraph = {}
Paragraph.__index = Paragraph
Paragraph.__type = "Paragraph"

local utility = script.Parent.Parent.utility
local moveable = require(utility.moveable)
local locale = require(utility.locale)

function Paragraph.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local titleText = properties.title or properties.Title or ""
    local contentText = properties.content or properties.Content or ""

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        icon = properties.icon or properties.Icon,
    }, Paragraph)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BorderSizePixel = 0,
        Name = "Paragraph",
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        -- Devlog 7 fix: stays clickable/hoverable even at ElementTransparency 1 (a fully "glass"
        -- window) - every card-shaped element needs this directly, see StyleElementBody's own
        -- comment for why it isn't handled there instead.
        Active = true,

        -- Animation
        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)

    self.window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 18),
        PaddingRight = UDim.new(0, 18),
        PaddingTop = UDim.new(0, 16),
        PaddingBottom = UDim.new(0, 16),

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 6),

        Parent = self.main,
    })

    -- Header: icon (optional) + title, same layout section.luau uses. A Frame of its own
    -- (rather than parenting icon/title straight to main) so hiding an empty title also hides
    -- the icon beside it for free, and the card's own UIListLayout skips the whole row in one go.
    self.headerRow = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 18),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 0,
        Visible = titleText ~= "",

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 8),
        SortOrder = Enum.SortOrder.LayoutOrder,
        VerticalAlignment = Enum.VerticalAlignment.Center,

        Parent = self.headerRow,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            -- Animation
            ImageTransparency = 1, -- In = 0

            Parent = self.headerRow,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(titleText),

        Size = UDim2.fromOffset(0, 18),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        -- Animation
        TextTransparency = 1, -- In = 0

        Parent = self.headerRow,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    self.body = self.window:Create("TextLabel", {
        Text = locale.t(contentText),

        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Top,
        TextWrapped = true,
        LayoutOrder = 1,
        Visible = contentText ~= "",

        -- Animation
        TextTransparency = 1, -- In = 0.3

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    return self
end

function Paragraph:SetTitle(text)
    text = text or ""
    self.headerRow.Visible = text ~= ""
    self.title.Text = text
end

function Paragraph:SetContent(text)
    text = text or ""
    self.body.Visible = text ~= ""
    self.body.Text = text
end

-- Accepts either key casing, same as every other CreateX properties table. Updates whichever
-- half is present - Set({ Content = "..." }) alone leaves the title untouched.
function Paragraph:Set(properties)
    properties = if typeof(properties) == "table" then properties else {}
    local title = properties.title or properties.Title
    local content = properties.content or properties.Content
    if title ~= nil then
        self:SetTitle(title)
    end
    if content ~= nil then
        self:SetContent(content)
    end
end

function Paragraph:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.body, { TextTransparency = 0.3 }, animate)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.body, { TextTransparency = 1 }, animate)
    end
end

moveable(Paragraph)

return Paragraph
]=====]

sources["components/popup"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Popup: a modal that dims the screen and floats a card in the centre. Modular by design -
-- give it a title and buttons for a choice dialog, or a list of boxes for a changelog. Built
-- from the window's own gradient/corner/stroke/shadow so it reads as part of the same UI.

local Popup = {}
Popup.__index = Popup
Popup.__type = "Popup"

-- Utility
local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local functions = require(utility.functions)
local constants = require(utility.constants)
local locale = require(utility.locale)
local log = require(utility.log)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

-- Timings (Exponential Out, matching the notification/toast feel).
local enterInfo = TweenInfo.new(0.5, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- card rise-in
local fadeLong = TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- fill + stroke
local fadeShort = TweenInfo.new(0.3, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- content + shadow
local backdropInfo = TweenInfo.new(0.35, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
-- Devlog 7 "smooth dialog motion": a light scale pop alongside the existing fade/drift, tuned
-- with Back rather than the literal Elastic easing style - Elastic overshoots and settles in
-- several visible bounces, which reads as springy/toylike on something as small as this card;
-- Back gives the same "landed with a little life in it" feel in one clean overshoot.
local scaleEnterInfo = TweenInfo.new(0.45, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local scaleExitInfo = TweenInfo.new(0.22, Enum.EasingStyle.Quint, Enum.EasingDirection.In)
local scaleFrom = 0.9 -- starting scale on enter
local scaleTo = 0.96 -- scale settled to on exit (a subtle shrink-away, not a full collapse)

-- Card metrics.
local cardWidth = 400
local sidePadding = 22
local topPadding = 24
local bottomPadding = 22
local regionGap = 16 -- between header, content and footer
local innerWidth = cardWidth - sidePadding * 2

local titleSize = 18
local subtitleSize = 14
local contentSize = 15
local headerIconSize = 16
local headerIconGap = 12 -- icon to title-column
local maxContentHeight = 300 -- content region scrolls past this
-- the content scrolls, so it clips its children; this inset keeps box strokes off the edge
local contentInset = 4
local contentWidth = innerWidth - contentInset * 2

-- Box (changelog card) metrics.
local boxSidePad = 16
local boxVerticalPad = 13
local boxIconSize = 20
local boxIconGap = 10
local boxTitleSize = 15
local boxDescSize = 14
local boxGap = 8
local boxWidthInset = 10 -- boxes sit a touch narrower so they clear the scrollbar

-- Footer buttons.
local buttonHeight = 40
local buttonGap = 8
local buttonCorner = UDim.new(1, 0) -- pill
local buttonTextSize = 16

local backdropShown = 0.5 -- how dark the dim gets

-- Open popups, oldest first. Escape only ever closes the last one so two stacked popups dont
-- both vanish on a single press. A popup torn down some other way (its window went with it)
-- never runs Close, so entries are pruned by liveness rather than trusted to remove themselves.
local stack = {}

local function topmost(popup)
    for index = #stack, 1, -1 do
        local open = stack[index]
        if open._closed or not open.screenGui.Parent then
            table.remove(stack, index)
        end
    end
    return stack[#stack] == popup
end

function Popup.new(window, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
        title = properties.title or properties.Title or "Popup",
        subtitle = properties.subtitle or properties.Subtitle,
        content = properties.content or properties.Content,
        icon = properties.icon or properties.Icon,
        boxes = properties.boxes or properties.Boxes,
        options = properties.options or properties.Options,
        -- Optional single-line field between the content and the buttons - what turns a plain
        -- confirm dialog into a "type something and submit" prompt (a key/password gate, an
        -- import string, a rename). Accepts a plain string (placeholder text) or a table for
        -- more control. inputValue is readable/writable by any button's own callback since it
        -- runs before Close tears the popup down.
        inputConfig = (function()
            local raw = properties.input or properties.Input
            if raw == nil then
                return nil
            end
            if type(raw) == "string" then
                return { placeholder = raw }
            end
            return raw
        end)(),
        inputValue = "",
        -- click the dim or press Escape to close (no callback fires). On by default.
        dismissable = if properties.dismissable ~= nil
            then properties.dismissable
            elseif properties.Dismissable ~= nil then properties.Dismissable
            else true,
        _reveal = {}, -- { instance, prop, to } fadeables, tweened in on show and out on close
        _connections = {},
        _closed = false,
    }, Popup)

    -- default to a single dismiss button so a bare popup still closes
    if not self.options or #self.options == 0 then
        self.options = { { text = "Okay" } }
    end

    if self.inputConfig then
        self.inputValue = tostring(self.inputConfig.value or self.inputConfig.Value or "")
    end

    self:_build()
    table.insert(stack, self) -- built, so it has a screenGui for the liveness prune

    task.spawn(function()
        self:_show()
    end)

    return self
end

-- Register a transparency-driven instance so _show can fade it in (to `to`) and _dismiss can
-- fade it back out (to 1). Every fadeable funnels here so the two directions stay in sync.
function Popup:_fade(instance, prop, to)
    table.insert(self._reveal, { instance = instance, prop = prop, to = to })
    return instance
end

function Popup:_build()
    local window = self.window
    local hasIcon = self.icon ~= nil and self.icon ~= 0 and self.icon ~= ""

    -- Own ScreenGui so the modal sits above the window, toasts and notifications alike.
    self.screenGui = window:Create("ScreenGui", {
        Name = variables.httpService:GenerateGUID(false),
        IgnoreGuiInset = true,
        ResetOnSpawn = false,
        Enabled = true,
        DisplayOrder = constants.displayOrder.popup,
        ZIndexBehavior = Enum.ZIndexBehavior.Global,

        Parent = variables.guiContainer,
    })

    -- Dim backdrop, also the click-to-dismiss surface and the input sink for everything below.
    -- A plain Active frame, not a button - it only needs to swallow input, so a frame is the
    -- right primitive.
    self.backdrop = window:Create("Frame", {
        Name = "Backdrop",
        BackgroundColor3 = Color3.fromRGB(0, 0, 0),
        BorderSizePixel = 0,
        Size = UDim2.fromScale(1, 1),
        Active = true,

        BackgroundTransparency = 1, -- shown = backdropShown

        Parent = self.screenGui,
    })
    self:_fade(self.backdrop, "BackgroundTransparency", backdropShown)

    -- Card: the window's own look (white base + gradient + rounded corner + stroke + glow).
    self.card = window:Create("Frame", {
        Name = "Card",
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, 0, 0.5, 14), -- drifts up to centre on show
        Size = UDim2.fromOffset(cardWidth, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        Active = true, -- clicks on the card never reach the backdrop
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- shown = 0

        Parent = self.screenGui,
    })
    self:_fade(self.card, "BackgroundTransparency", 0)

    -- Devlog 7: the light elastic-ish scale pop on open/close (see _show/Close) - a UIScale
    -- rather than resizing Size directly, so it scales everything inside uniformly (text
    -- included) around the card's own centre without disturbing the fixed height computed below.
    self.cardScale = window:Create("UIScale", {
        Scale = scaleFrom,

        Parent = self.card,
    })

    window:Create("UIGradient", {
        Rotation = 270,
        Offset = Vector2.new(0, -0.1),

        Parent = self.card,
    }, { Color = { "WindowColor", functions.toColorSequence } })

    window:Create("UICorner", {
        Parent = self.card,
    }, { CornerRadius = "CornerRoundness" })

    self.cardStroke = window:Create("UIStroke", {
        Transparency = 1, -- shown = 0.95

        Parent = self.card,
    }, { Color = "SurfaceStroke" })
    self:_fade(self.cardStroke, "Transparency", 0.95)

    self.cardShadow = window:CreateGlow(self.card, "ShadowColor", 26, 1) -- shown = 0.55
    self:_fade(self.cardShadow, "Transparency", 0.55)

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, sidePadding),
        PaddingRight = UDim.new(0, sidePadding),
        PaddingTop = UDim.new(0, topPadding),
        PaddingBottom = UDim.new(0, bottomPadding),

        Parent = self.card,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, regionGap),

        Parent = self.card,
    })

    -- Pre-measure like the notifications do, then lock the card to a fixed height. Otherwise the
    -- card grows a few pixels a moment after it shows, as the brand font's glyphs finish loading
    -- and AutomaticSize re-measures the text - reads as the font "settling" after the reveal.
    local headerHeight = self:_measureHeader(hasIcon)
    self:_buildHeader(hasIcon, headerHeight)
    local contentHeight = self:_buildContent()
    local inputHeight = if self.inputConfig then self:_buildInput() else 0
    self:_buildFooter()

    -- header, footer, and content/input if present
    local regions = 2 + (contentHeight > 0 and 1 or 0) + (inputHeight > 0 and 1 or 0)
    local cardHeight = topPadding
        + headerHeight
        + contentHeight
        + inputHeight
        + buttonHeight
        + bottomPadding
        + regionGap * (regions - 1)
    self.card.Size = UDim2.fromOffset(cardWidth, cardHeight)
    self.card.AutomaticSize = Enum.AutomaticSize.None

    -- dismiss surfaces
    if self.dismissable then
        table.insert(
            self._connections,
            window:Connect(self.backdrop.InputBegan, function(input)
                if
                    input.UserInputType == Enum.UserInputType.MouseButton1
                    or input.UserInputType == Enum.UserInputType.Touch
                then
                    self:Close()
                end
            end)
        )
        table.insert(
            self._connections,
            window:Connect(variables.userInputService.InputBegan, function(input, processed)
                if not processed and input.KeyCode == Enum.KeyCode.Escape and topmost(self) then
                    self:Close()
                end
            end)
        )
    end
end

function Popup:_buildHeader(hasIcon, headerHeight)
    local window = self.window

    local header = window:Create("Frame", {
        Name = "Header",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, headerHeight),
        LayoutOrder = 1,

        Parent = self.card,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, headerIconGap),

        Parent = header,
    })

    if hasIcon then
        self:_fade(
            window:Create("ImageLabel", {
                Image = self.icon,
                Size = UDim2.fromOffset(headerIconSize, headerIconSize),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                LayoutOrder = 1,

                ImageTransparency = 1, -- shown = 0

                Parent = header,
            }, { ImageColor3 = "TitlingColor" }),
            "ImageTransparency",
            0
        )
    end

    local textColumn = window:Create("Frame", {
        Name = "Text",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, hasIcon and -(headerIconSize + headerIconGap) or 0, 0, self._columnH),
        LayoutOrder = 2,

        Parent = header,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 3),

        Parent = textColumn,
    })

    self:_fade(
        window:Create("TextLabel", {
            Text = locale.t(self.title),
            Size = UDim2.new(1, 0, 0, self._titleH),
            BackgroundTransparency = 1,
            TextSize = titleSize,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
            LayoutOrder = 1,

            TextTransparency = 1, -- shown = 0

            Parent = textColumn,
        }, { TextColor3 = "TitlingColor", FontFace = "Font" }),
        "TextTransparency",
        0
    )

    if self.subtitle and self.subtitle ~= "" then
        self:_fade(
            window:Create("TextLabel", {
                Text = locale.t(self.subtitle),
                Size = UDim2.new(1, 0, 0, self._subH),
                BackgroundTransparency = 1,
                TextSize = subtitleSize,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextWrapped = true,
                LayoutOrder = 2,

                TextTransparency = 1, -- shown = 0.55

                Parent = textColumn,
            }, { TextColor3 = "TitlingColor", FontFace = "Font" }),
            "TextTransparency",
            0.55
        )
    end
end

-- The middle region: a paragraph, a list of boxes, or nothing. Whichever it is, it lives in a
-- scrolling frame capped at maxContentHeight so a long changelog scrolls instead of running off.
function Popup:_buildContent()
    if (not self.content or self.content == "") and (not self.boxes or #self.boxes == 0) then
        return 0 -- title + buttons only (a plain confirm dialog)
    end

    local window = self.window
    local measured = if self.boxes and #self.boxes > 0 then self:_measureBoxes() else self:_measureText()
    local viewHeight = math.min(measured, maxContentHeight) + contentInset * 2

    local content = window:Create("ScrollingFrame", {
        Name = "Content",
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, viewHeight),
        CanvasSize = UDim2.new(0, 0, 0, 0),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        ScrollBarThickness = 4,
        ScrollBarImageColor3 = Color3.fromRGB(255, 255, 255),
        ScrollingDirection = Enum.ScrollingDirection.Y,
        LayoutOrder = 2,

        ScrollBarImageTransparency = 1, -- shown = 0.8, fades in with the rest

        Parent = self.card,
    })
    self:_fade(content, "ScrollBarImageTransparency", 0.8)

    -- the scroll clips, so pad the region to keep box strokes off the edge
    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, contentInset),
        PaddingRight = UDim.new(0, contentInset),
        PaddingTop = UDim.new(0, contentInset),
        PaddingBottom = UDim.new(0, contentInset),

        Parent = content,
    })

    if self.boxes and #self.boxes > 0 then
        window:Create("UIListLayout", {
            FillDirection = Enum.FillDirection.Vertical,
            HorizontalAlignment = Enum.HorizontalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder,
            Padding = UDim.new(0, boxGap),

            Parent = content,
        })
        for index, box in self.boxes do
            self:_buildBox(content, box, index)
        end
    else
        self:_fade(
            window:Create("TextLabel", {
                Text = locale.t(self.content),
                Size = UDim2.new(1, 0, 0, measured),
                BackgroundTransparency = 1,
                TextSize = contentSize,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Top,
                TextWrapped = true,

                TextTransparency = 1, -- shown = 0.5

                Parent = content,
            }, { TextColor3 = "ContentColor", FontFace = "Font" }),
            "TextTransparency",
            0.5
        )
    end

    return viewHeight
end

-- Full-width key/text field, its own fixed-height region between content and footer (see
-- inputConfig's own comment on self). Same field styling input.luau's own compact row uses
-- (FieldBackground/SurfaceStroke/PlaceholderColor), just stretched to the card's width instead of
-- hugging its text - a modal's field reads as a form, not a settings row.
local inputHeight = 44

function Popup:_buildInput()
    local window = self.window
    local config = self.inputConfig

    local field = window:Create("Frame", {
        Name = "InputField",
        BorderSizePixel = 0,
        Size = UDim2.new(1, 0, 0, inputHeight),
        LayoutOrder = 3,

        BackgroundTransparency = 1, -- shown = FieldTransparency

        Parent = self.card,
    }, { BackgroundColor3 = "FieldBackground" })
    self:_fade(field, "BackgroundTransparency", window.theme.FieldTransparency)

    window:Create("UICorner", {
        Parent = field,
    }, { CornerRadius = "CornerRoundness" })

    local fieldStroke = window:Create("UIStroke", {
        Transparency = 1, -- shown = 0.85

        Parent = field,
    }, { Color = "SurfaceStroke" })
    self:_fade(fieldStroke, "Transparency", 0.85)

    self.inputGlow = window:CreateGlow(field, "FieldGlow", 20, 1)
    self._inputGlowIdle = 1 -- hidden at rest; flashed red on a rejected submit (see Close/_flashInputError)

    self.inputBox = self:_fade(
        window:Create("TextBox", {
            Text = self.inputValue,
            PlaceholderText = locale.t(config.placeholder or config.Placeholder or ""),
            Size = UDim2.new(1, -28, 1, 0),
            Position = UDim2.fromScale(0.5, 0.5),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = contentSize,
            TextXAlignment = Enum.TextXAlignment.Left,
            ClearTextOnFocus = false,

            TextTransparency = 1, -- shown = 0

            Parent = field,
        }, { TextColor3 = "ContentColor", FontFace = "Font", PlaceholderColor3 = "PlaceholderColor" }),
        "TextTransparency",
        0
    )

    table.insert(
        self._connections,
        window:Connect(self.inputBox:GetPropertyChangedSignal("Text"), function()
            self.inputValue = self.inputBox.Text
        end)
    )

    -- Enter submits the same as clicking the first primary-styled button, so a key/prompt field
    -- behaves like an actual form instead of needing a mouse click every time.
    table.insert(
        self._connections,
        window:Connect(self.inputBox.FocusLost, function(enterPressed)
            if not enterPressed or self._closed then
                return
            end
            for _, option in self.options do
                local style = (typeof(option) == "table" and (option.style or option.Style)) or nil
                if style == "primary" then
                    self:_activateOption(option)
                    return
                end
            end
        end)
    )

    return inputHeight
end

-- Briefly flashes the input field's own glow/stroke red - the same "rejected" cue a Set()
-- mismatch gets elsewhere in the library, so a bad key reads as *this field* being wrong rather
-- than a generic error toast the player has to go connect back to the field themselves.
function Popup:FlashInputError()
    if not self.inputGlow or self._closed then
        return
    end
    local flashInfo = TweenInfo.new(0.15, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local ts = variables.tweenService
    ts:Create(self.inputGlow, flashInfo, { Color = self.window.theme.ErrorColor, Transparency = 0.5 }):Play()
    task.delay(0.5, function()
        if self._closed then
            return
        end
        ts:Create(self.inputGlow, flashInfo, { Transparency = 1 }):Play()
    end)
end

-- One changelog box: a card in the element-panel style (gradient stroke sheen), icon optional,
-- a semibold title and a softer description.
function Popup:_buildBox(parent, box, order)
    local window = self.window
    box = if typeof(box) == "table" then box else { title = tostring(box) }
    local hasIcon = box.icon ~= nil and box.icon ~= 0 and box.icon ~= ""
    local frameH, titleH, descH, columnH = self:_measureBox(box)

    local frame = window:Create("Frame", {
        Name = "Box",
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        Size = UDim2.new(1, -boxWidthInset, 0, frameH),
        LayoutOrder = order,

        BackgroundTransparency = 1, -- shown = 0

        Parent = parent,
    })
    self:_fade(frame, "BackgroundTransparency", 0)

    local stroke = window:StyleElementPanel(frame)
    self:_fade(stroke, "Transparency", window.theme.ElementStrokeTransparency)

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, boxSidePad),
        PaddingRight = UDim.new(0, boxSidePad),
        PaddingTop = UDim.new(0, boxVerticalPad),
        PaddingBottom = UDim.new(0, boxVerticalPad),

        Parent = frame,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, boxIconGap),

        Parent = frame,
    })

    if hasIcon then
        self:_fade(
            window:Create("ImageLabel", {
                Image = box.icon,
                Size = UDim2.fromOffset(boxIconSize, boxIconSize),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                LayoutOrder = 1,

                ImageTransparency = 1, -- shown = 0

                Parent = frame,
            }, { ImageColor3 = "ContentColor" }),
            "ImageTransparency",
            0
        )
    end

    local textColumn = window:Create("Frame", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, hasIcon and -(boxIconSize + boxIconGap) or 0, 0, columnH),
        LayoutOrder = 2,

        Parent = frame,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 3),

        Parent = textColumn,
    })

    self:_fade(
        window:Create("TextLabel", {
            Text = locale.t(box.title or box.Title or ""),
            Size = UDim2.new(1, 0, 0, titleH),
            BackgroundTransparency = 1,
            TextSize = boxTitleSize,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
            LayoutOrder = 1,

            TextTransparency = 1, -- shown = 0

            Parent = textColumn,
        }, { TextColor3 = "ContentColor", FontFace = "TitleFont" }),
        "TextTransparency",
        0
    )

    local description = box.description or box.Description
    if description and description ~= "" then
        self:_fade(
            window:Create("TextLabel", {
                Text = locale.t(description),
                Size = UDim2.new(1, 0, 0, descH),
                BackgroundTransparency = 1,
                TextSize = boxDescSize,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Top,
                TextWrapped = true,
                LayoutOrder = 2,

                TextTransparency = 1, -- shown = 0.65

                Parent = textColumn,
            }, { TextColor3 = "ContentColor", FontFace = "Font" }),
            "TextTransparency",
            0.65
        )
    end
end

function Popup:_buildFooter()
    local window = self.window

    local footer = window:Create("Frame", {
        Name = "Footer",
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, buttonHeight),
        LayoutOrder = 4,

        Parent = self.card,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.Fill, -- buttons share the row evenly
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, buttonGap),

        Parent = footer,
    })

    for index, option in self.options do
        self:_buildButton(footer, option, index)
    end
end

-- One footer button. Neutral matches the element body; "primary" and "danger" tint it green/red
-- the way the library flags a good or destructive action.
function Popup:_buildButton(parent, option, order)
    local window = self.window
    option = if typeof(option) == "table" then option else { text = tostring(option) }
    local style = option.style or option.Style or "neutral"
    local label = option.text or option.Text or option.name or option.Name or "Okay"
    local callback = option.callback or option.Callback

    -- flat fills so hover just tweens the colour (no overlay). neutral takes a faint white edge
    -- so it recedes; the accents carry their own colour and a bolder edge.
    local restColor, hoverColor, edgeColor, strokeShown
    if style == "primary" then
        restColor, hoverColor, edgeColor, strokeShown =
            window.theme.AccentColor, window.theme.AccentStroke, window.theme.AccentStroke, 0.1
    elseif style == "danger" then
        restColor, hoverColor, edgeColor, strokeShown =
            window.theme.ErrorColor, window.theme.ErrorStrokeColor, window.theme.ErrorStrokeColor, 0
    else
        restColor, hoverColor, edgeColor, strokeShown =
            window.theme.NeutralButton, window.theme.NeutralButtonHover, window.theme.NeutralButtonStroke, 0.85
    end

    local button = window:Create("Frame", {
        Name = "Button",
        BackgroundColor3 = restColor,
        BorderSizePixel = 0,
        Size = UDim2.new(0, 0, 0, buttonHeight),
        LayoutOrder = order,

        BackgroundTransparency = 1, -- shown = 0

        Parent = parent,
    })
    self:_fade(button, "BackgroundTransparency", 0)

    window:Create("UIFlexItem", { FlexMode = Enum.UIFlexMode.Fill, Parent = button })
    window:Create("UICorner", { CornerRadius = buttonCorner, Parent = button })

    local stroke = window:Create("UIStroke", {
        Color = edgeColor,
        Transparency = 1, -- shown = strokeShown

        Parent = button,
    })
    self:_fade(stroke, "Transparency", strokeShown)

    self:_fade(
        window:Create("TextLabel", {
            Text = locale.t(label),
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            TextSize = buttonTextSize,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextTruncate = Enum.TextTruncate.AtEnd,

            -- adaptive: black or white by the fill's luminance, so every style stays readable
            TextColor3 = functions.contrastText(restColor),
            TextTransparency = 1, -- shown = 0

            Parent = button,
        }, { FontFace = "Font" }),
        "TextTransparency",
        0
    )

    local interact = window:Create("TextButton", {
        Text = "",
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        ZIndex = 2,

        Parent = button,
    })

    local hoverInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    table.insert(
        self._connections,
        window:Connect(interact.MouseEnter, function()
            if self._closed then
                return
            end
            variables.tweenService:Create(button, hoverInfo, { BackgroundColor3 = hoverColor }):Play()
        end)
    )
    table.insert(
        self._connections,
        window:Connect(interact.MouseLeave, function()
            variables.tweenService:Create(button, hoverInfo, { BackgroundColor3 = restColor }):Play()
        end)
    )

    option._stroke = stroke
    option._label = label
    option._callback = callback

    table.insert(
        self._connections,
        window:Connect(interact.MouseButton1Click, function()
            self:_activateOption(option)
        end)
    )
end

-- Runs one option's callback (mouse click, or Enter in an input field targeting the first
-- primary button) and closes - unless the popup has an input field and the callback explicitly
-- returns false, which means "rejected, stay open" (a key/prompt validator saying no). Passes
-- the current input value as the callback's argument; a plain confirm dialog with no input just
-- gets "", which every existing callback (none of which take an argument) already ignores.
function Popup:_activateOption(option)
    if self._closed then
        return
    end
    hapticEngine.click()
    soundEngine.click()
    if option._stroke then
        variables.tweenService
            :Create(option._stroke, TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
                Transparency = 1,
            })
            :Play()
    end
    if option._callback then
        local ok, result = pcall(option._callback, self.inputValue)
        if not ok then
            log.warn("Rayfield: popup button '" .. tostring(option._label) .. "' callback errored:")
            log.print(result)
        elseif self.inputConfig and result == false then
            self:FlashInputError()
            return -- rejected: leave the popup open for another attempt
        end
    end
    self:Close()
end

-- Measure the header parts once and stash them, so both the card height and the header's own
-- fixed layout use the same numbers. Everything is sized off these, so nothing re-measures on
-- screen once the font's glyphs land. Returns the header row height.
function Popup:_measureHeader(hasIcon)
    local textWidth = innerWidth - (if hasIcon then headerIconSize + headerIconGap else 0)
    self._titleH = functions.textHeight(self.window.theme.Font, titleSize, locale.resolve(self.title), textWidth)
    self._subH = if self.subtitle and self.subtitle ~= ""
        then functions.textHeight(self.window.theme.Font, subtitleSize, locale.resolve(self.subtitle), textWidth)
        else 0
    self._columnH = self._titleH + (if self._subH > 0 then 3 + self._subH else 0)
    return math.max(self._columnH, if hasIcon then headerIconSize else 0)
end

-- Height a paragraph needs at the content region's width.
function Popup:_measureText()
    -- measure what actually renders: the label shows the translated string
    return functions.textHeight(self.window.theme.Font, contentSize, locale.resolve(self.content), contentWidth)
end

-- Every measurement one box needs: its frame height (content + padding), its title and
-- description text heights, and the text column height. Both the card sizing and the box build
-- read from here, so a box is built at a fixed size rather than auto-sizing (which re-measures).
function Popup:_measureBox(box)
    box = if typeof(box) == "table" then box else { title = tostring(box) }
    local hasIcon = box.icon ~= nil and box.icon ~= 0 and box.icon ~= ""
    local textWidth = contentWidth - boxWidthInset - boxSidePad * 2 - (if hasIcon then boxIconSize + boxIconGap else 0)

    local titleH = functions.textHeight(
        self.window.theme.TitleFont,
        boxTitleSize,
        locale.resolve(box.title or box.Title or ""),
        textWidth
    )
    local descH = 0
    local description = box.description or box.Description
    if description and description ~= "" then
        descH = functions.textHeight(self.window.theme.Font, boxDescSize, locale.resolve(description), textWidth)
    end

    local columnH = titleH + (if descH > 0 then 3 + descH else 0)
    local frameH = math.max(columnH, if hasIcon then boxIconSize else 0) + boxVerticalPad * 2
    return frameH, titleH, descH, columnH
end

-- Total height every box stacks to, so the content region knows when to start scrolling.
function Popup:_measureBoxes()
    local total = 0
    for index, box in self.boxes do
        total += (self:_measureBox(box))
        if index < #self.boxes then
            total += boxGap
        end
    end
    return total
end

-- Enter: darken the backdrop, drift the card up into place and fade everything in. No UIScale -
-- scaling the card scales its text, which reads as the font size settling after the reveal.
function Popup:_show()
    if not self.screenGui.Parent then
        return
    end

    hapticEngine.notify()
    soundEngine.notify()

    variables.tweenService:Create(self.card, enterInfo, { Position = UDim2.new(0.5, 0, 0.5, 0) }):Play()
    variables.tweenService:Create(self.cardScale, scaleEnterInfo, { Scale = 1 }):Play()

    for _, entry in self._reveal do
        local info = if entry.instance == self.backdrop then backdropInfo else fadeLong
        variables.tweenService:Create(entry.instance, info, { [entry.prop] = entry.to }):Play()
    end
end

-- Exit: fade everything back out while the card drifts down a touch, then tear it all down.
function Popup:Close()
    if self._closed then
        return
    end
    self._closed = true

    local index = table.find(stack, self)
    if index then
        table.remove(stack, index)
    end

    for _, connection in self._connections do
        self.window:Disconnect(connection)
    end
    self._connections = {}

    if not self.screenGui.Parent then
        return
    end

    variables.tweenService:Create(self.card, fadeShort, { Position = UDim2.new(0.5, 0, 0.5, 10) }):Play()
    variables.tweenService:Create(self.cardScale, scaleExitInfo, { Scale = scaleTo }):Play()

    for _, entry in self._reveal do
        variables.tweenService:Create(entry.instance, fadeShort, { [entry.prop] = 1 }):Play()
    end

    task.delay(fadeShort.Time, function()
        self.window:DestroySubtree(self.screenGui)
    end)
end

return Popup
]=====]

sources["components/progressbar"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A read-only gradient bar with a percent (or "340 xp out of 500", with a custom max + suffix)
-- readout. Dev-driven only - no interact surface, no flag/config, no callback - Set() is the
-- only way its value moves, and it animates smoothly when it does.

local ProgressBar = {}
ProgressBar.__index = ProgressBar
ProgressBar.__type = "ProgressBar"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local odometer = require(utility.odometer)
local moveable = require(utility.moveable)
local locale = require(utility.locale)

local tweenInfo = TweenInfo.new(0.45, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)

function ProgressBar.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Progress",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,

        max = properties.max or properties.Max or 100,
        suffix = properties.suffix or properties.Suffix or "",
    }, ProgressBar)

    if self.max <= 0 then
        self.max = 100
    end

    local initialValue = if (properties.value or properties.Value) ~= nil
        then (properties.value or properties.Value)
        else 0
    self.value = math.clamp(initialValue, 0, self.max)
    self._lastValue = self.value

    self:_buildFull()
    self.window:_wireTooltip(self)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

-- percent by default; "340 xp out of 500" once a suffix says this bar counts something instead
function ProgressBar:_format(value)
    if self.suffix ~= "" then
        return math.floor(value + 0.5) .. " " .. self.suffix .. " out of " .. math.floor(self.max + 0.5)
    end
    local pct = if self.max ~= 0 then (value / self.max) * 100 else 0
    return math.floor(pct + 0.5) .. "%"
end

function ProgressBar:_buildFull()
    local window = self.window

    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 60),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)

    -- Top row: title (+ icon) left, readout right. Same split Checkbox/CopyButton use in a
    -- compact row - HorizontalFlex on the layout pins the two groups to either end, rather
    -- than a UIFlexItem on either side (which only governs shrink/grow, not placement).
    self.container = window:Create("Frame", {
        Position = UDim2.new(0, 20, 0, 14),
        Size = UDim2.new(1, -40, 0, 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.main,
    })

    self.containerLayout = window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.container,
    })

    -- left: icon + title, sharing whatever width the value readout doesn't need
    self.titleGroup = window:Create("Frame", {
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 0,

        Parent = self.container,
    })

    window:Create("UIListLayout", {
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.titleGroup,
    })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.titleGroup,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.titleGroup,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.titleGroup,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    self.valueHost = window:Create("Frame", {
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 1,

        Parent = self.container,
    })

    self.valueOdo = odometer.new(self.window, self.valueHost, {
        textSize = 15,
        alignment = Enum.HorizontalAlignment.Right,
        transparency = 1, -- revealed to 0.5 on show, matching the slider readout
        duration = 0.28,
    })
    self.valueOdo:snap(self:_format(self.value))

    -- Bottom: the track
    self.track = window:Create("Frame", {
        Position = UDim2.new(0, 20, 1, -18),
        Size = UDim2.new(1, -40, 0, 10),
        BorderSizePixel = 0,
        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    }, { BackgroundColor3 = "SliderBackground" })

    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 10),
        Parent = self.track,
    })

    self.progress = window:Create("Frame", {
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.fromScale(0, 0.5),
        Size = UDim2.fromScale(0, 1),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        BackgroundTransparency = 1, -- In = 0

        Parent = self.track,
    })

    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 10),
        Parent = self.progress,
    })

    window:Create("UIGradient", {
        Offset = Vector2.new(0, 0.5),
        Rotation = 2,
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.85),
            NumberSequenceKeypoint.new(1, 0),
        }),

        Parent = self.progress,
    }, { Color = { "SliderProgress", functions.toColorSequence } })

    self.progressGlow = window:CreateGlow(self.progress, "AccentColor", 16, 1)

    self:_renderProgress()
end

function ProgressBar:_renderProgress(info)
    local ratio = if self.max ~= 0 then math.clamp(self.value / self.max, 0, 1) else 0
    local size = UDim2.fromScale(ratio, 1)
    if info then
        variables.tweenService:Create(self.progress, info, { Size = size }):Play()
    else
        self.progress.Size = size
    end
end

-- Animates the bar and rolls the readout to the new value. skipAnimation snaps instead, for a
-- caller restoring a known state (e.g. rebuilding a list of bars) rather than reporting progress.
function ProgressBar:Set(value, skipAnimation)
    value = math.clamp(value, 0, self.max)
    local goingUp = value >= self._lastValue -- compare against the pre-call value first
    self.value = value

    if skipAnimation then
        self:_renderProgress()
        if self.valueOdo then
            self.valueOdo:snap(self:_format(value))
        end
    else
        self:_renderProgress(tweenInfo)
        if self.valueOdo then
            self.valueOdo:to(self:_format(value), goingUp)
        end
    end

    self._lastValue = value
end

local glowReveal = TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out, 0, false, 0.35)

function ProgressBar:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.track, { BackgroundTransparency = 0 }, animate)
        w:_reveal(self.progress, { BackgroundTransparency = 0 }, animate)
        if self.valueOdo then
            self.valueOdo:reveal(0.5, animate)
        end
        w:_reveal(self.progressGlow, { Transparency = math.max(0.55, w.theme.AccentGlow) }, animate, glowReveal)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.track, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.progress, { BackgroundTransparency = 1 }, animate)
        if self.valueOdo then
            self.valueOdo:reveal(1, animate)
        end
        w:_reveal(self.progressGlow, { Transparency = 1 }, animate, glowReveal)
    end
end

function ProgressBar:_refreshTheme()
    variables.tweenService
        :Create(
            self.progressGlow,
            TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { Transparency = math.max(0.55, self.window.theme.AccentGlow) }
        )
        :Play()
end

moveable(ProgressBar)

return ProgressBar
]=====]

sources["components/resize"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 8 "corner grip": a small drag handle in the window's bottom-right corner that resizes
-- self.main freely (clamped, see windowSizing.clampUserSize). self.main's AnchorPoint is
-- (0.5, 0.5), so a naive Size change would grow/shrink the window from its centre - every resize
-- here also nudges Position by half the size delta in the same direction, so the top-left corner
-- stays put and only the bottom-right edge (where the grip lives) actually moves, matching how an
-- OS window resize handle behaves.
--
-- Committed on release, not live every frame: self.size/self.customSize only take the new size
-- once the drag ends, so every other system that reads them mid-drag (the reveal target,
-- _applyWindowSize's own viewport refit, the drag bar's position calc) isn't fighting a value
-- that's changing 60 times a second. Persisted to disk on release too, so it survives a restart.
-- Double-click snaps back to the window's original screen-fit size (self.window.defaultSize, the
-- dev-supplied/built-in size from construction - never overwritten by a later resize) rather than
-- whatever the most recent drag happened to land on.
--
-- Devlog 12: sits straddling the window's own corner point now (half on the card, half over
-- whatever's behind it) instead of tucked a few px inside it - checked WindUI's own resize
-- handle for reference (same idea as this window's own drag bar sitting fully outside main: a
-- window control doesn't have to live entirely inside the frame it controls). Still parented to
-- self.main rather than a free-floating sibling like the drag bar, though - main has no
-- ClipsDescendants, so a child is free to render past its edge with no extra position-sync
-- connection needed, and main's own AnchorPoint/Position math keeps it glued to the corner for
-- free as the window moves or resizes.

local Resize = {}
Resize.__index = Resize
Resize.__type = "Resize"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local windowSizing = require(utility.windowSizing)
local constants = require(utility.constants)

-- Touch-friendly hit target, centred on the corner it straddles.
local gripSize = 40

-- WindUI's own resize glyph, checked directly in their source (ResizeHandle's ImageLabel) - a
-- curved diagonal swoosh mark. Downloaded and measured the actual asset: the visible stroke only
-- fills a 130x130 box inside the image's full 420x420 canvas (WindUI itself renders it at 96px
-- inside a 32px hit box, i.e. already 3x oversized on purpose) - rendering it anywhere near our
-- old 26-34px range left the *visible mark* at an unreadable ~8-10px, which is what kept reading
-- as tiny no matter how much the outer box grew. Sized up to match roughly the same overshoot
-- WindUI itself uses, and the visible stroke also isn't centred in its own canvas (its own
-- bounding box centres about 9.3% of the render size toward the bottom-right) - arcIconOffset
-- below corrects for that so the *stroke*, not the image's empty canvas, centres on the corner.
local arcImageSize = 80
local arcImageHoverSize = 92
local arcImageDragSize = 86
local arcIconOffset = -8 -- pulls the visibly-offset stroke back onto the corner point, both axes
local arcImage = "rbxassetid://120997033468887"
-- WindUI's own three-state opacity: quite faint at rest, brighter on hover, fully opaque while
-- actually dragging. Fainter than this grip needed at rest when it lived inside the card - it's
-- not sitting on a solid background anymore, it's half over whatever's behind the window.
local arcRestTransparency = 0.8
local arcHoverTransparency = 0.35
local arcDragTransparency = 0

local snapBackInfo = TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
-- Same feel as the drag bar's own hover/grab animation (dragCosmetic in drag.luau) - a small
-- Back/Out pop rather than a plain linear-ish ease, so growing on hover reads as a springy nudge.
local hoverInfo = TweenInfo.new(0.25, Enum.EasingStyle.Back, Enum.EasingDirection.Out)

-- Two clicks this close together are a double-click; anything slower is two separate
-- single clicks (the second one just starts a fresh drag).
local doubleClickWindow = 0.4

local function currentViewport(): Vector2?
    local camera = variables.workspace.CurrentCamera
    return camera and camera.ViewportSize
end

function Resize.new(window)
    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
        resizing = false,
        _lastClickAt = nil :: number?,
    }, Resize)

    -- Dead-centre on main's own bottom-right corner point (AnchorPoint 0.5,0.5 at Position
    -- 1,0,1,0) rather than inset from it - straddles the edge instead of sitting inside it.
    -- Scaled up on a touch-primary device (window.mobileHitScale, default 1.4x) - 40px is
    -- comfortable for a mouse pointer's precision but tight for a fingertip.
    local touchGripSize = if window:IsMobile() then gripSize * window.mobileHitScale else gripSize
    self.grip = self.window:Create("Frame", {
        Name = "ResizeGrip",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(1, 0, 1, 0),
        Size = UDim2.fromOffset(touchGripSize, touchGripSize),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        -- above bottomFade (100) - live-caught the fade's own gradient painting straight over
        -- the grip's arc at a lower ZIndex, tinting it with a grey diagonal wash
        ZIndex = constants.zIndex.resizeGrip,
        Visible = self.window.settings.resizeGripEnabled,

        Parent = self.window.main,
    })

    -- AnchorPoint (0.5, 0.5) means growing/shrinking Size on hover/drag never moves this point,
    -- so the small constant arcIconOffset correction stays valid across all three size states
    -- without needing its own tween. Starts fully hidden (transparent, zero size) rather than at
    -- its usual rest state - see Resize:_reveal() below, called from the same point in
    -- Window:_firstShow() the drag bar's own grow-in plays from, per an explicit ask to match it.
    self.icon = self.window:Create("ImageLabel", {
        Name = "Glyph",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, arcIconOffset, 0.5, arcIconOffset),
        Size = UDim2.fromOffset(0, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Image = arcImage,
        ImageTransparency = 1,

        Parent = self.grip,
    }, { ImageColor3 = "ContentColor" })

    self.interact = self.window:Create("TextButton", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Text = "",
        TextTransparency = 1,

        Parent = self.grip,
    })

    -- Three states, matching WindUI's own opacity scheme, plus the drag bar's own "grows a
    -- little on hover/grab" pop (dragCosmetic's MouseEnter/InputBegan tweens in drag.luau) - so
    -- the grip reads as interactive without shouting for attention sitting over the game behind
    -- it, and covers touch (which never fires MouseEnter/MouseLeave) the same way the bar does.
    local function setIconState(transparency, size)
        variables.tweenService:Create(self.icon, hoverInfo, {
            ImageTransparency = transparency,
            Size = UDim2.fromOffset(size, size),
        }):Play()
    end

    self.window:Connect(self.interact.MouseEnter, function()
        if not self.resizing then
            setIconState(arcHoverTransparency, arcImageHoverSize)
        end
    end)
    self.window:Connect(self.interact.MouseLeave, function()
        if not self.resizing then
            setIconState(arcRestTransparency, arcImageSize)
        end
    end)
    -- MouseEnter/MouseLeave don't fire for touch - a tap both starts the drag AND should pop the
    -- icon the same way a hover would, so touch gets the same cue via the drag start itself
    -- below rather than a dedicated touch event.

    local screenGui = self.window.screenGui
    local dragStartMouse = Vector2.zero
    local dragStartSize = Vector2.zero
    local dragStartCentreAbs = Vector2.zero

    -- The exact same exponential-smoothing constants drag.luau's own mainRemaining/barRemaining
    -- use - main (the window body) lags noticeably behind its own target; the bar tracks its own
    -- target almost instantly, which is what actually reads as "elastic": the bar stays close to
    -- the cursor while the body visibly drags behind it. resizeRemaining plays main's role here;
    -- gripRemaining plays the bar's.
    local resizeRemaining = 1e-7
    local gripRemaining = 1e-60

    -- The exact target this frame resolved to, before the lerp above eases main toward it -
    -- commitResize banks and settles onto this on release rather than whatever main's own
    -- Size/Position happen to be lerped to that frame, so a resize let go mid-ease still saves
    -- (and lands on) the size you actually dragged to, not a slightly-behind snapshot of it.
    local lastTargetSize = Vector2.zero
    local lastTargetPosition = UDim2.new()

    -- What was actually being asked for, clarified after a few rounds of talking past each
    -- other: not the window's own Size/Position lag (that part already worked, verified live) -
    -- the icon itself sitting rigidly pinned to the corner the whole drag, never reaching toward
    -- the cursor the way the drag bar visibly "chases" the mouse during a window move. This is a
    -- pixel offset layered on top of the grip's normal corner anchor (Position stays
    -- UDim2.new(1,0,1,0) at rest) - Lerped toward how far the live mouse currently sits from the
    -- true corner, same elastic constant as the window's own resize follow, then eased back to
    -- zero (onto the corner) on release.
    local gripDragOffset = Vector2.zero

    local function insetOffset(): Vector2
        if screenGui and screenGui.IgnoreGuiInset then
            return variables.guiService:GetGuiInset()
        end
        return Vector2.zero
    end

    -- Window:_clampedPosition() itself clamps against self.window.size - the COMMITTED size,
    -- only updated on release (see this file's own header comment on why). Live-caught: calling
    -- it as-is mid-drag keeps the half-width/half-height bound pinned to whatever size the window
    -- was *before* this drag started, so as it actually grows/shrinks the clamp thinks it's still
    -- the old size and reins the position back in to fit that - reading as the window barely
    -- moving off its starting spot no matter how far you drag, while the size itself still
    -- visibly (if erratically, fighting that same wrong clamp) changes. Mirrors the exact same
    -- math by hand against the size actually being dragged to instead.
    local function clampedPositionForSize(position: UDim2, sizeVec: Vector2): UDim2
        local window = self.window
        if not window.settings or not window.settings.keepOnScreen then
            return position
        end
        if position.X.Scale ~= 0 or position.Y.Scale ~= 0 then
            return position
        end
        local screen = window.screenGui.AbsoluteSize
        local halfX, halfY = sizeVec.X / 2, sizeVec.Y / 2
        local margin = 8
        local x = math.clamp(position.X.Offset, halfX + margin, math.max(halfX + margin, screen.X - halfX - margin))
        local y = math.clamp(position.Y.Offset, halfY + margin, math.max(halfY + margin, screen.Y - halfY - margin))
        if x == position.X.Offset and y == position.Y.Offset then
            return position
        end
        return UDim2.fromOffset(x, y)
    end

    local function applyResize(mouseLocation: Vector2, dt: number)
        local delta = mouseLocation - dragStartMouse
        local clamped = windowSizing.clampUserSize(currentViewport(), dragStartSize + delta)
        local consumed = clamped - dragStartSize -- how much of the drag survived clamping

        local newCentrePositionSpace = dragStartCentreAbs + consumed / 2 + insetOffset()
        local target = clampedPositionForSize(
            UDim2.fromOffset(newCentrePositionSpace.X, newCentrePositionSpace.Y),
            clamped
        )

        lastTargetSize = clamped
        lastTargetPosition = target

        local targetSize = UDim2.fromOffset(clamped.X, clamped.Y)
        local settle = 1 - resizeRemaining ^ dt
        self.window.main.Size = self.window.main.Size:Lerp(targetSize, settle)
        self.window.main.Position = self.window.main.Position:Lerp(target, settle)

        -- Live-follow the drag bar too, not just once the resize commits. It used to only move
        -- via commitResize's own _syncDragBar call on release, so it visibly stayed put for the
        -- whole drag and only snapped into place the instant you let go - live-caught reading as
        -- "doesn't move while resizing" and, on a big enough shrink, as the bar ending up stuck
        -- *inside* the now-smaller window (its stale position was still where the old, bigger
        -- bottom edge used to be) until grabbing it forced a fresh, correct getTargets() read.
        -- _syncDragBar itself reads self.window.size, which is deliberately NOT live mid-drag
        -- (see this file's own header comment on why) - so this mirrors its exact math by hand
        -- against main's own eased Size/Position instead of calling it or the raw target, so the
        -- bar never gets ahead of the window it's actually hanging under.
        if self.window.drag and self.window.drag.drag then
            local mainPos = self.window.main.Position
            local mainSize = self.window.main.Size
            self.window.drag.drag.Position = UDim2.new(
                mainPos.X.Scale,
                mainPos.X.Offset,
                mainPos.Y.Scale,
                mainPos.Y.Offset + mainSize.Y.Offset / 2 + 15
            )
        end

        -- First attempt at this chased the raw mouse relative to main's own *already-lagging*
        -- corner, which double-counts main's own lag on top of the icon's - the two stack, and
        -- the icon ends up much further from the corner than intended ("vai muito longe",
        -- live-caught). drag.luau doesn't do that either: the bar doesn't chase the window body,
        -- it chases the *same fresh target* the body chases, just with its own, much snappier
        -- constant - so it stays close while the body visibly trails behind it. Mirrors that
        -- exactly: trueCornerAbs is where the corner *should* be this instant (from
        -- dragStartCentreAbs/consumed/clamped, before easing main toward it - not main's actual
        -- current position), and the grip eases toward that - independently of how far main
        -- itself has caught up yet.
        --
        -- Second attempt landed consistently below the real cursor - built trueCornerAbs off
        -- `target` instead, which (like drag.luau's own main.Position) carries +insetOffset() to
        -- correct for main.Position's offset-space being shifted from AbsolutePosition by the gui
        -- inset (see insetOffset()'s own comment) - cornerAbs, read straight off
        -- main.AbsolutePosition, has no such shift, so the difference between the two carried a
        -- constant ~inset-sized bias downward the whole drag. dragStartCentreAbs is already in
        -- AbsolutePosition-space (captured straight from it, no inset math), so building
        -- trueCornerAbs from that instead keeps both sides of the subtraction in the same space.
        local trueCornerAbs = dragStartCentreAbs + consumed / 2 + clamped / 2
        local cornerAbs = self.window.main.AbsolutePosition + self.window.main.AbsoluteSize
        local targetNudge = trueCornerAbs - cornerAbs
        gripDragOffset = gripDragOffset:Lerp(targetNudge, 1 - gripRemaining ^ dt)
        self.grip.Position = UDim2.new(1, gripDragOffset.X, 1, gripDragOffset.Y)
    end

    -- Bank the drag into self.size/self.customSize (everything downstream - the reveal target,
    -- _applyWindowSize's viewport refit, the drag bar's own math - reads those, not main.Size
    -- directly) and persist it.
    local function commitResize()
        local size = UDim2.fromOffset(lastTargetSize.X, lastTargetSize.Y)
        self.window.size = size
        self.window.customSize = lastTargetSize
        self.window.settings.customWindowSize = { X = lastTargetSize.X, Y = lastTargetSize.Y }

        -- the rail collapses to icons on a narrow enough window (see Window:_applySidebarWidth),
        -- so a resize has to re-derive it
        if self.window.tabsMode == "Sidebar" then
            self.window:_applySidebarWidth()
        end

        -- Settle the live ease onto the exact final target with a visible glide, same easing as
        -- drag.luau's own releaseDrag settle tween - persistence above already banked the target
        -- directly rather than reading main's own (still mid-ease) Size/Position, so there's
        -- nothing for this tween to race. This was the actually-missing piece live-caught as "the
        -- resize doesn't move like the drag handle" - the in-drag ease alone (matching
        -- mainRemaining's own snappy 1e-7) reads as basically instant on its own; the release
        -- glide is what the drag handle itself is actually recognisable by. Skips _clampToScreen/
        -- _syncDragBar deliberately (same as releaseDrag) - both would read main's still-old
        -- Position synchronously and instantly overwrite it, fighting the tween just started.
        local settle = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
        variables.tweenService:Create(self.window.main, settle, { Size = size, Position = lastTargetPosition }):Play()
        if self.window.drag and self.window.drag.drag then
            local barTarget = UDim2.new(
                lastTargetPosition.X.Scale,
                lastTargetPosition.X.Offset,
                lastTargetPosition.Y.Scale,
                lastTargetPosition.Y.Offset + lastTargetSize.Y / 2 + 15
            )
            variables.tweenService:Create(self.window.drag.drag, settle, { Position = barTarget }):Play()
        end

        -- Ease the icon's own cursor-chase back onto the corner (Position UDim2.new(1,0,1,0), no
        -- offset) rather than snapping - same glide the window/bar just got.
        gripDragOffset = Vector2.zero
        variables.tweenService:Create(self.grip, settle, { Position = UDim2.new(1, 0, 1, 0) }):Play()

        self.window:SaveSettings()
    end

    local function releaseResize()
        if not self.resizing then
            return
        end
        self.resizing = false
        commitResize()
        setIconState(arcRestTransparency, arcImageSize)
    end

    -- Double-click: snap back to the window's original screen-fit size instead of starting a
    -- drag. Tweens main and the drag bar together (same shape as the "Reset Window Position"
    -- settings button) so the bar doesn't lag a frame behind and read as detached mid-tween.
    function self:_snapToDefault()
        local target = windowSizing.fit(currentViewport(), self.window.defaultSize)

        local centreAbs = self.window.main.AbsolutePosition + self.window.main.AbsoluteSize * self.window.main.AnchorPoint
        local centrePositionSpace = centreAbs + insetOffset()
        -- Same stale-size clamp trap as applyResize above - clamp against the size we're
        -- snapping *to* (target), not self.window.size (still whatever it was before the snap).
        local targetPosition = clampedPositionForSize(
            UDim2.fromOffset(centrePositionSpace.X, centrePositionSpace.Y),
            Vector2.new(target.X.Offset, target.Y.Offset)
        )

        variables.tweenService:Create(self.window.main, snapBackInfo, { Size = target, Position = targetPosition })
            :Play()
        if self.window.drag and self.window.drag.drag then
            local barTarget = UDim2.new(
                targetPosition.X.Scale,
                targetPosition.X.Offset,
                targetPosition.Y.Scale,
                targetPosition.Y.Offset + target.Y.Offset / 2 + 15
            )
            variables.tweenService:Create(self.window.drag.drag, snapBackInfo, { Position = barTarget }):Play()
        end

        self.window.size = target
        self.window.customSize = self.window.defaultSize
        self.window.settings.customWindowSize = nil
        self.window:SaveSettings()
    end

    self.window:Connect(self.interact.InputBegan, function(input, processed)
        if processed then
            return
        end
        local inputType = input.UserInputType.Name
        if inputType ~= "MouseButton1" and inputType ~= "Touch" then
            return
        end
        -- _interactive() alone doesn't cover a *steady* minimised window (it only tracks
        -- animating/hidden) - a collapsed bar isn't something you'd resize, and Window:
        -- ToggleMinimise already hides the grip once collapsed, but the mouse can still be
        -- sitting where the grip used to be the instant the collapse starts.
        if not self.window:_interactive() or self.window.minimised then
            return
        end

        local now = os.clock()
        if self._lastClickAt and now - self._lastClickAt < doubleClickWindow then
            self._lastClickAt = nil
            self:_snapToDefault()
            return
        end
        self._lastClickAt = now

        self.resizing = true
        setIconState(arcDragTransparency, arcImageDragSize)
        dragStartMouse = variables.userInputService:GetMouseLocation()
        dragStartSize = Vector2.new(self.window.main.Size.X.Offset, self.window.main.Size.Y.Offset)
        dragStartCentreAbs = self.window.main.AbsolutePosition
            + self.window.main.AbsoluteSize * self.window.main.AnchorPoint
        -- Cancels any still-running release-settle tween on the icon (grabbing again fast enough
        -- to catch it mid-glide) and starts the chase fresh from the true corner, not wherever
        -- that tween had eased to yet.
        gripDragOffset = Vector2.zero
        self.grip.Position = UDim2.new(1, 0, 1, 0)
    end)

    self.window:Connect(variables.runService.RenderStepped, function(dt)
        if not self.resizing then
            return
        end
        if not self.window:_interactive() then
            releaseResize()
            return
        end
        applyResize(variables.userInputService:GetMouseLocation(), dt)
    end)

    self.window:Connect(variables.userInputService.InputEnded, function(input)
        local inputType = input.UserInputType.Name
        if inputType == "MouseButton1" or inputType == "Touch" then
            releaseResize()
        end
    end)
    -- alt-tabbing mid-drag never delivers InputEnded, same story as the window-drag handle
    self.window:Connect(variables.userInputService.WindowFocusReleased, releaseResize)

    return self
end

function Resize:SetEnabled(enabled: boolean)
    self.grip.Visible = enabled and true or false
    if not self.grip.Visible and self.resizing then
        self.resizing = false
    end
end

-- Public wrapper for the Settings "Reset Window Size" button - the exact same snap the grip's
-- own double-click already does.
function Resize:ResetSize()
    self:_snapToDefault()
end

-- Grow-and-fade the icon in from nothing, called from the same point in Window:_firstShow() the
-- drag bar's own dragCosmetic reveal plays from - same shape, same two TweenInfos, so the two
-- read as one matched pair of "the window's controls waking up" rather than the bar arriving on
-- its own and the resize corner just being there the whole time.
function Resize:_reveal()
    variables.tweenService
        :Create(self.icon, TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
            ImageTransparency = arcRestTransparency,
        })
        :Play()
    variables.tweenService
        :Create(self.icon, TweenInfo.new(1, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
            Size = UDim2.fromOffset(arcImageSize, arcImageSize),
        })
        :Play()
end

return Resize
]=====]

sources["components/ripplebutton"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A Button variant whose press feedback is a ripple spreading from the exact point you press
-- (mouse or touch), clipped to the card's rounded corners, instead of Button's usual stroke-ghost
-- + width-bounce flash.

local RippleButton = {}
RippleButton.__index = RippleButton
RippleButton.__type = "RippleButton"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

function RippleButton.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Button",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        compact = tab.compact or false,

        callback = properties.callback or properties.Callback or function() end,
    }, RippleButton)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self.window:_wireTooltip(self)

    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    return self
end

function RippleButton:_runCallback()
    self.window:_runGuarded(self, self.callback)
end

-- A clipped overlay matching the card's own rounded corners. Parented right after the hover
-- overlay and before the title/icon (both default ZIndex 1, so sibling order alone puts this
-- above the faint hover tint but under the text - a ripple that reads without blurring it).
function RippleButton:_buildRippleLayer(parent)
    self.rippleClip = self.window:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ClipsDescendants = true,

        Parent = parent,
    })

    self.window:Create("UICorner", {
        Parent = self.rippleClip,
    }, { CornerRadius = "ElementCornerRadius" })

    return self.rippleClip
end

-- Expand a circle from the press point to well past the card's far corner, fading out as it
-- grows. AbsoluteSize's diagonal is the longest any interior point can be from any corner, so
-- it's always enough regardless of where the press landed.
local rippleInfo = TweenInfo.new(0.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

function RippleButton:_spawnRipple(screenPosition)
    local size = self.main.AbsoluteSize
    if size.X <= 0 or size.Y <= 0 then
        return -- not laid out yet (e.g. a stray input mid-reveal)
    end

    -- screenPosition and AbsolutePosition are already in the same coordinate space (see
    -- Window:_mouseAbsolutePosition) - no GuiInset adjustment needed on top of it.
    local localPos = screenPosition - self.main.AbsolutePosition
    local diameter = size.Magnitude

    local circle = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromOffset(localPos.X, localPos.Y),
        Size = UDim2.fromOffset(0, 0),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 0.65,
        BorderSizePixel = 0,

        Parent = self.rippleClip,
    })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),
        Parent = circle,
    })

    variables.tweenService
        :Create(circle, rippleInfo, {
            Size = UDim2.fromOffset(diameter, diameter),
            BackgroundTransparency = 1,
        })
        :Play()

    -- Destroy is idempotent, so this is safe even if the element (and this circle along with
    -- it) was already torn down by a Tab:Remove mid-ripple.
    task.delay(rippleInfo.Time, function()
        circle:Destroy()
    end)
end

function RippleButton:_wireRipple()
    self.window:ConnectFor(self, self.interact.InputBegan, function(input)
        if
            input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        then
            self:_spawnRipple(Vector2.new(input.Position.X, input.Position.Y))
        end
    end)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        hapticEngine.click()
        soundEngine.click()
        self:_runCallback()
    end)
end

-- full-width: title/icon left (matches button.luau, minus the width-bounce press flash)
function RippleButton:_buildFull()
    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 43),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = 0

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self.hoverOverlay = self.window:CreateHoverOverlay(self.main)
    self:_buildRippleLayer(self.main)

    self.container = self.window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.main,
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.containerLayout = self.window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),

        Size = UDim2.fromOffset(250, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        TextTransparency = 1,

        Parent = self.main,
    })

    self.window:_wireElementHover(self)
    self:_wireRipple()
end

-- compact (row): content-sized, centred icon + title (matches button.luau)
function RippleButton:_buildCompact()
    local window = self.window

    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name)
    self.hoverOverlay = self.interact
    self:_buildRippleLayer(self.interact)

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 16),
        PaddingRight = UDim.new(0, 16),

        Parent = self.interact,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        Padding = UDim.new(0, 6),

        Parent = self.interact,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.interact,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.interact,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    self.window:_wireElementHover(self)
    self:_wireRipple()
end

function RippleButton:_setShown(shown, animate)
    if shown then
        self.window:_revealCommon(self, animate)
    else
        self.window:_hideCommon(self, animate)
    end
end

-- Room the compact ripple button needs before its label would clip: side padding + icon
-- (and its gap) if shown + the title text.
function RippleButton:_minWidth()
    local w = 32 -- interact padding, 16 each side
    if self.icon then
        w += 22 -- 16 icon + 6 gap to title
    end
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

moveable(RippleButton)
lockable(RippleButton)

return RippleButton
]=====]

sources["components/scrollhint"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A centred line of text with a bouncing arrow underneath it, for pointing a user further down
-- a page. Purely decorative - no card, no flag, no callback. Set(text) swaps the line at runtime.

local ScrollHint = {}
ScrollHint.__index = ScrollHint
ScrollHint.__type = "ScrollHint"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local moveable = require(utility.moveable)
local locale = require(utility.locale)
local constants = require(utility.constants)

local chevronIcon = constants.icons.chevron

function ScrollHint.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        text = properties.text or properties.Text or properties.name or properties.Name or "Scroll for more",
    }, ScrollHint)

    self:_build()
    self:_startBounce()

    return self
end

function ScrollHint:_build()
    local window = self.window

    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 40),
        BorderSizePixel = 0,
        Name = "ScrollHint",
        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    })

    -- the row hugs its own content and sits centred in the full-width main, rather than
    -- the usual left-anchored layout every other element uses
    self.container = window:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.main,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6),
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,

        Parent = self.container,
    })

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.text),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,
        LayoutOrder = 0,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- layout-managed wrapper (fixed slot, sized to the icon) holding the actual icon - the
    -- bounce tweens the icon's own Position inside it, so it never fights the row's
    -- UIListLayout the way tweening a direct layout child's Position would.
    self.arrowSlot = window:Create("Frame", {
        Size = UDim2.fromOffset(14, 14),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 1,

        Parent = self.container,
    })

    self.arrow = window:Create("ImageLabel", {
        Image = chevronIcon,
        Size = UDim2.fromScale(1, 1),
        Rotation = 180, -- chevron points down (matches the dropdown's collapsed orientation)
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        ImageTransparency = 1, -- In = 0

        Parent = self.arrowSlot,
    }, { ImageColor3 = "ContentColor" })
end

-- Gentle up/down bob, forever, purely as a "look here" cue. Exits on its own once the arrow's
-- gone (Tab:Remove tore the instances down) - matches Window's LiveAnimation loop shape, just
-- scoped to one element instead of the whole window.
local bounceInfo = TweenInfo.new(0.6, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)

function ScrollHint:_startBounce()
    task.spawn(function()
        local down = true
        while self.arrow.Parent do
            local tween = variables.tweenService
                :Create(self.arrow, bounceInfo, { Position = UDim2.fromOffset(0, down and 5 or 0) })
            tween:Play()
            tween.Completed:Wait()
            down = not down
        end
    end)
end

-- Update the line at runtime.
function ScrollHint:Set(text)
    self.text = tostring(text)
    self.title.Text = locale.resolve(self.text)
end

function ScrollHint:_setShown(shown, animate)
    local w = self.window
    w:_reveal(self.title, { TextTransparency = if shown then 0 else 1 }, animate)
    w:_reveal(self.arrow, { ImageTransparency = if shown then 0 else 1 }, animate)
end

moveable(ScrollHint)

return ScrollHint
]=====]

sources["components/search"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Search: a pill that takes over the tab strip and searches every page at once. The Search
-- action toggles it; while open the tab selector hides and every content tab's elements are
-- gathered into one results page, filtered live by name. Closing puts everything back exactly
-- where it was. Values ported from the RF2 design (Window.Search).

local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local constants = require(utility.constants)
local locale = require(utility.locale)
local action = require(script.Parent.action)

local search = {}

-- crossfade between the tab strip and the search pill, and the search parts fading in/out
local swapInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

-- resting/lit brightness for the Search action icon, matching the other topbar actions
local iconRest = 0.6
local iconLit = 0.2

-- Gap between the sidebar rail and the search pill beside it (and the same again on the pill's
-- own right edge), so the field doesn't sit flush against either.
local searchRailGap = 12

-- The searchable text for one unit: a leaf's own name, or every descendant leaf name joined
-- so a group matches when any child inside it does. Recurses into anything that can host its
-- own nested elements the same way window.luau's own forEachElement does (Group, and a
-- Collapsible/Tabbox via the Group(s) underneath them) - without this, a toggle tucked inside a
-- Collapsible or Tabbox page was searchable by nothing at all, not even its own name, since only
-- the Group case was ever handled here.
local function unitText(unit)
    if unit.__type == "Group" or unit.__type == "Collapsible" or unit.__type == "Tabbox" then
        local parts = {}
        local function walk(container)
            local elements = if container.__type == "Collapsible" then container._group.elements else container.elements
            for _, child in elements do
                if child.__type == "Group" or child.__type == "Collapsible" then
                    walk(child)
                elseif child.__type == "Tabbox" then
                    for _, page in child.pages do
                        walk(page)
                    end
                elseif child.name then
                    table.insert(parts, child.name)
                end
            end
        end
        if unit.__type == "Tabbox" then
            for _, page in unit.pages do
                walk(page)
            end
        else
            walk(unit)
        end
        return table.concat(parts, "\n")
    end
    return unit.name or ""
end

-- Every top-level element across the real content pages (the settings page and other
-- neglected tabs aren't pages you search). Sections are headers, so skip them.
local function collectUnits(window)
    local units = {}
    for _, tab in window.tabs do
        if tab.neglectSelector then
            continue
        end
        for _, element in tab.elements do
            if element.__type ~= "Section" then
                table.insert(units, element)
            end
        end
    end
    return units
end

-- Fade the pill's fill, stroke, shadow, icon and field in or out together.
local function setPillShown(window, shown, info)
    variables.tweenService
        :Create(window.searchPill, info, {
            BackgroundTransparency = if shown then 0.9 else 1,
        })
        :Play()
    variables.tweenService:Create(window.searchStroke, info, { Transparency = if shown then 0.85 else 1 }):Play()
    variables.tweenService:Create(window.searchShadow, info, { Transparency = if shown then 0.92 else 1 }):Play()
    variables.tweenService:Create(window.searchIcon, info, { ImageTransparency = if shown then 0.65 else 1 }):Play()
    variables.tweenService:Create(window.searchInput, info, { TextTransparency = if shown then 0.2 else 1 }):Play()
end

-- Show/hide the content tab pills as the strip swaps with the search field.
local function setTabsShown(window, shown, info)
    for _, tab in window.tabs do
        if not tab.neglectSelector and tab.topbarItem then
            tab:_applyVisual(
                if shown then (if window.selectedTab == tab then "selected" else "unselected") else "hidden",
                info
            )
        end
    end
end

-- Toggle each unit's visibility against the query. Empty query shows everything, so the
-- open field doubles as a browse-all-pages view.
local function applyFilter(window, query)
    query = string.lower(query or "")
    local anyVisible = false
    for _, entry in window._searchUnits do
        local match = query == "" or string.find(entry.text, query, 1, true) ~= nil
        entry.unit.main.Visible = match
        if entry.unit.descriptor then
            entry.unit.descriptor.main.Visible = match
        end
        anyVisible = anyVisible or match
    end
    window.searchEmpty.Visible = not anyVisible and query ~= ""
end

-- Pull every unit into the results page, remembering where each came from, and lay them out
-- grouped by page in creation order.
local function gatherUnits(window)
    window._searchUnits = {}
    local order = 0
    for _, unit in collectUnits(window) do
        order += 1
        local main = unit.main
        table.insert(window._searchUnits, {
            unit = unit,
            text = string.lower(unitText(unit)),
            homeParent = main.Parent,
            homeOrder = main.LayoutOrder,
            descOrder = unit.descriptor and unit.descriptor.main.LayoutOrder,
        })

        main.LayoutOrder = order * 10
        main.Parent = window.searchPage
        main.Visible = true
        if unit.descriptor then
            unit.descriptor.main.LayoutOrder = order * 10 + 1
            unit.descriptor.main.Parent = window.searchPage
            unit.descriptor.main.Visible = true
        end
    end
end

-- Put every unit back in the tab it came from, at its original order. Guards a unit whose
-- element was removed mid-search (its frame is gone).
local function restoreUnits(window)
    for _, entry in window._searchUnits do
        local unit = entry.unit
        if unit.main and unit.main.Parent then
            unit.main.LayoutOrder = entry.homeOrder
            unit.main.Parent = entry.homeParent
            unit.main.Visible = true
        end
        if unit.descriptor and unit.descriptor.main and unit.descriptor.main.Parent then
            unit.descriptor.main.LayoutOrder = entry.descOrder
            unit.descriptor.main.Parent = entry.homeParent
            unit.descriptor.main.Visible = true
        end
    end
    window._searchUnits = {}
end

function search.open(window)
    -- minimised: the results page would render outside the collapsed bar and steal focus
    if window._searching or window.minimised or not window:_interactive() then
        return
    end
    window._searching = true

    gatherUnits(window)
    applyFilter(window, "")
    window:_jumpTo(window.searchPage)

    -- Top mode: the strip swaps out for the field, they share the same row. Sidebar mode: the
    -- rail is down the left and the field sits beside it, so there's nothing to swap - the tabs
    -- stay exactly where they are and stay clickable while searching.
    if window.tabsMode ~= "Sidebar" then
        setTabsShown(window, false, swapInfo)
        task.delay(swapInfo.Time, function()
            if window._searching then
                window.tabList.Visible = false
            end
        end)
    end

    window.searchPill.Visible = true
    setPillShown(window, true, swapInfo)
    window.searchInput:CaptureFocus()

    variables.tweenService:Create(window.searchAction.iconLabel, swapInfo, { ImageTransparency = iconLit }):Play()
end

-- config.showTabs: fade the tab strip back in (false when the caller hides the window).
-- config.jumpTo: the page to slide back to, or false to leave navigation to the caller.
function search.close(window, config)
    if not window._searching then
        return
    end
    config = config or {}
    window._searching = false

    window.searchInput.Text = ""
    window.searchInput:ReleaseFocus()
    window.searchEmpty.Visible = false

    restoreUnits(window)
    local target = if config.jumpTo == nil then window.selectedTab and window.selectedTab.tabPage else config.jumpTo
    if target then
        window:_jumpTo(target)
    end

    setPillShown(window, false, swapInfo)
    task.delay(swapInfo.Time, function()
        if not window._searching then
            window.searchPill.Visible = false
        end
    end)

    -- Sidebar mode never hid them in the first place (see search.open), so there's nothing to
    -- bring back - re-running the fade there would only re-animate rows that never left.
    if config.showTabs and window.tabsMode ~= "Sidebar" then
        window.tabList.Visible = true
        setTabsShown(window, true, swapInfo)
    end

    variables.tweenService:Create(window.searchAction.iconLabel, swapInfo, { ImageTransparency = iconRest }):Play()
end

-- Keep the pill lined up beside the rail when its width changes (the rail collapses to icons on
-- a narrow window - see Window:_applySidebarWidth). No-op in Top mode, where the pill takes the
-- full strip regardless.
function search.railWidth(window, width: number)
    if window.tabsMode ~= "Sidebar" or not window.searchPill then
        return
    end
    window.searchPill.Position = UDim2.new(0, width + searchRailGap, 0, 66)
    window.searchPill.Size = UDim2.new(1, -(width + searchRailGap * 2), 0, 35)
end

function search.toggle(window)
    if window._searching then
        search.close(window, { showTabs = true })
    else
        search.open(window)
    end
end

function search.build(window)
    window._searching = false

    -- Results page: a page like a tab's, holding whatever the search gathers.
    window.searchPage = window:Create("ScrollingFrame", {
        Name = "Search",
        Size = UDim2.new(1, -20, 1, 0),
        Position = UDim2.new(0.5, 0, 0, 68),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        ScrollBarThickness = 0,
        ScrollingDirection = Enum.ScrollingDirection.Y,
        LayoutOrder = 2000, -- sits after every tab page

        Parent = window.elements,
    })

    window:Create("UIListLayout", {
        Padding = UDim.new(0, 7),
        FillDirection = Enum.FillDirection.Vertical,
        VerticalAlignment = Enum.VerticalAlignment.Top,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = window.searchPage,
    })

    window:Create("UIPadding", {
        PaddingTop = UDim.new(0, 10),
        PaddingBottom = UDim.new(0, 33),

        Parent = window.searchPage,
    })

    -- Empty state, floated over the content area rather than in the results list so it centres
    -- cleanly. Only shown when a query matches nothing.
    window.searchEmpty = window:Create("TextLabel", {
        Name = "NoResults",
        Text = locale.t("No results"),
        FontFace = variables.brandFont(Enum.FontWeight.Medium),
        TextSize = 15,
        TextTransparency = 0.6,
        BackgroundTransparency = 1,
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, 0, 0.55, 0),
        Size = UDim2.fromOffset(200, 20),
        Visible = false,
        ZIndex = 3,

        Parent = window.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- Search pill: takes the tab strip's row in Top mode. In Sidebar mode the rail is down the
    -- left instead, so the pill only takes the space beside it (see search.railWidth) and the
    -- rail itself stays put rather than swapping out - live-reported as wanting the tabs to stay
    -- visible while searching.
    local sidebar = window.tabsMode == "Sidebar"
    window.searchPill = window:Create("Frame", {
        Name = "SearchBar",
        AnchorPoint = if sidebar then Vector2.new(0, 0) else Vector2.new(0.5, 0),
        Position = if sidebar
            then UDim2.new(0, (window.sidebarWidth or 219) + searchRailGap, 0, 66)
            else UDim2.new(0.5, 0, 0, 66),
        Size = if sidebar
            then UDim2.new(1, -((window.sidebarWidth or 219) + searchRailGap + searchRailGap), 0, 35)
            else UDim2.new(1, -35, 0, 35),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 10,

        BackgroundTransparency = 1, -- shown = 0.9
        Visible = false,

        Parent = window.main,
    })

    window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),
        Parent = window.searchPill,
    })

    window.searchStroke = window:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),
        Thickness = 1,

        Transparency = 1, -- shown = 0.85

        Parent = window.searchPill,
    })

    window.searchShadow = window:Create("UIShadow", {
        BlurRadius = UDim.new(0, 20),
        Color = Color3.fromRGB(255, 255, 255),
        ZIndex = -1,

        Transparency = 1, -- shown = 0.92

        Parent = window.searchPill,
    })

    window.searchIcon = window:Create("ImageLabel", {
        Image = "rbxassetid://" .. tostring(constants.icons.search),
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.new(0, 15, 0.5, 1),
        Size = UDim2.fromOffset(16, 16),
        BackgroundTransparency = 1,
        ZIndex = 10,

        ImageTransparency = 1, -- shown = 0.65

        Parent = window.searchPill,
    }, { ImageColor3 = "ContentColor" })

    window.searchInput = window:Create("TextBox", {
        Text = "",
        PlaceholderText = locale.t("Search all pages"),
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.new(0, 40, 0.5, 0),
        Size = UDim2.new(1, -110, 0, 18),
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        ClearTextOnFocus = false,
        ClipsDescendants = true,
        ZIndex = 10,

        TextTransparency = 1, -- shown = 0.2

        Parent = window.searchPill,
    }, { TextColor3 = "ContentColor", FontFace = "Font", PlaceholderColor3 = "PlaceholderColor" })

    window:Connect(window.searchInput:GetPropertyChangedSignal("Text"), function()
        if window._searching then
            applyFilter(window, window.searchInput.Text)
        end
    end)

    -- Search action: last in the row (leftmost), toggles the field.
    window.searchAction = action.new(window, {
        name = "Search",
        icon = constants.icons.search,
        order = 4,

        callback = function()
            search.toggle(window)
        end,
    })
    -- keep the icon lit while the field is open, the way the settings cog stays lit on its page
    window.searchAction.isLit = function()
        return window._searching
    end
end

return search
]=====]

sources["components/section"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Section = {}
Section.__index = Section
Section.__type = "Section"

local moveable = require(script.Parent.Parent.utility.moveable)
local locale = require(script.Parent.Parent.utility.locale)

function Section.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Section",
        icon = properties.icon or properties.Icon,
    }, Section)

    -- first element in a tab shouldn't get extra space above it, only sections that
    -- follow something. this section isn't registered yet so an empty list means first.
    local topSpace = if #self.tab.elements == 0 then 0 else 13

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -40, 0, 20 + topSpace),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundTransparency = 1,
        Parent = self.tab.tabPage,
    })

    if topSpace > 0 then
        self.window:Create("UIPadding", {
            PaddingTop = UDim.new(0, topSpace),
            Parent = self.main,
        })
    end

    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6),
        SortOrder = Enum.SortOrder.LayoutOrder,
        VerticalAlignment = Enum.VerticalAlignment.Top,
        Parent = self.main,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            -- Animation
            ImageTransparency = 1, -- In = 0.65

            Parent = self.main,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        -- Configurables
        Text = locale.t(self.name),

        Size = UDim2.fromOffset(0, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 15,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        -- Animation
        TextTransparency = 1, -- In = 0.6

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    return self
end

function Section:_setShown(shown, animate)
    local w = self.window
    w:_reveal(self.title, { TextTransparency = if shown then 0.6 else 1 }, animate)
    if self.iconLabel then
        w:_reveal(self.iconLabel, { ImageTransparency = if shown then 0.65 else 1 }, animate)
    end
end

moveable(Section)

return Section
]=====]

sources["components/segmentedpicker"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A pill bar split into equal segments, with a white indicator that slides to whichever one is
-- active. A segment can itself hold a couple of nested options (e.g. "Premium" holding "Monthly"
-- / "Annual") - picking it expands those inline, sharing the same slot the collapsed label sat
-- in, rather than growing the bar. Every segment's own width comes from HorizontalFlex.Fill, so
-- the indicator's target Position/Size is plain fraction math (index/count) - no AbsolutePosition
-- reads, no waiting on a layout to settle, nothing for it to race with.

local SegmentedPicker = {}
SegmentedPicker.__index = SegmentedPicker
SegmentedPicker.__type = "SegmentedPicker"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

local fadeInfo = TweenInfo.new(0.18, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local barHeight = 40
-- text sitting directly on the white indicator (a selected top-level segment, or an inactive
-- child once expanded - the outer white shows through behind it) needs dark ink to read; text
-- on the dark bar itself, or on the childIndicator's own dark inset, needs the theme's light one
local darkTextColor = Color3.fromRGB(20, 20, 20)
local childIndicatorColor = Color3.fromRGB(20, 20, 20)
local childIndicatorInset = 6 -- px of white margin left showing around the childIndicator

-- Squish & stretch, in two tweens rather than one: a quick stretch into a shape spanning both
-- the old and new bounds (so the pill briefly smears in the direction of travel, like it's
-- being dragged rather than teleported), then a springy settle - Back overshoots slightly past
-- the exact target size before easing back, reading as a soft bounce rather than a hard stop.
local stretchInfo = TweenInfo.new(0.12, Enum.EasingStyle.Sine, Enum.EasingDirection.Out)
local settleInfo = TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out)

local function slideIndicator(pill, targetPos, targetSize, skipAnimation)
    if skipAnimation then
        pill.Position, pill.Size = targetPos, targetSize
        return
    end

    local fromPos, fromSize = pill.Position, pill.Size
    local fromLeft = fromPos.X.Scale
    local fromRight = fromLeft + fromSize.X.Scale
    local toLeft = targetPos.X.Scale
    local toRight = toLeft + targetSize.X.Scale

    local stretchLeft = math.min(fromLeft, toLeft)
    local stretchRight = math.max(fromRight, toRight)

    -- offset components (the childIndicator's inset margin) carry over unchanged - only the
    -- scale portion actually needs to stretch across the gap between old and new position
    local stretchPos = UDim2.new(stretchLeft, targetPos.X.Offset, targetPos.Y.Scale, targetPos.Y.Offset)
    local stretchSize =
        UDim2.new(stretchRight - stretchLeft, targetSize.X.Offset, targetSize.Y.Scale, targetSize.Y.Offset)

    local stretchTween =
        variables.tweenService:Create(pill, stretchInfo, { Position = stretchPos, Size = stretchSize })
    stretchTween:Play()

    -- :Once() isn't guaranteed on every client this session has run into - :Connect() + manual
    -- disconnect is the one form of "run this once" every client here has actually supported
    local connection
    connection = stretchTween.Completed:Connect(function()
        connection:Disconnect()
        variables.tweenService:Create(pill, settleInfo, { Position = targetPos, Size = targetSize }):Play()
    end)
end

-- Accepts a bare string ("Low") or a table ({ text = "Premium", options = {...} }); always
-- returns the table shape internally so every other function only has one case to handle.
local function normalizeOption(option)
    if typeof(option) == "table" then
        return {
            text = option.text or option.Text or "",
            options = option.options or option.Options,
        }
    end
    return { text = tostring(option) }
end

function SegmentedPicker.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local rawOptions = properties.options or properties.Options or {}
    local options = {}
    for _, option in rawOptions do
        table.insert(options, normalizeOption(option))
    end

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        options = options,
        description = properties.description or properties.Description,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,
        callback = properties.callback or properties.Callback or function() end,

        flag = properties.flag
            or properties.Flag
            or (
                not (properties.forgetState or properties.ForgetState or tab.forgetState)
                    and functions.deriveFlagFromName(properties.name or properties.Name or "SegmentedPicker")
                or nil
            ),
    }, SegmentedPicker)

    self.window:_registerControl(self)

    self:_build()

    -- resolve the initial value: a leaf's own text (nested or not), defaulting to the first
    -- top-level option's first available leaf
    local initial = properties.value or properties.Value
    local index, childIndex = self:_find(initial)
    if not index then
        index, childIndex = 1, (options[1] and options[1].options) and 1 or nil
    end
    if childIndex then
        self.segments[index].activeChild = childIndex
        self.segments[index].collapsedLabel.Text = locale.resolve(self:_childText(index, childIndex))
    end
    self:_select(index, childIndex, true)

    if self.description then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    self.window:_restoreLate(self)

    return self
end

function SegmentedPicker:_childText(index, childIndex)
    local child = self.options[index].options[childIndex]
    return if typeof(child) == "table" then child.text or child.Text else tostring(child)
end

-- Locate a leaf by its text; returns (topLevelIndex, childIndex?) or nil if it isn't in
-- self.options at all (e.g. a stale saved value from before the options list changed).
function SegmentedPicker:_find(text)
    if text == nil then
        return nil
    end
    for i, option in self.options do
        if option.text == text then
            return i, nil
        end
        if option.options then
            for j, child in option.options do
                local childText = if typeof(child) == "table" then child.text or child.Text else tostring(child)
                if childText == text then
                    return i, j
                end
            end
        end
    end
    return nil
end

function SegmentedPicker:_build()
    local window = self.window

    -- self.main is the outer, tabPage-parented frame - assignOrder (shared by every Tab/Group)
    -- sets element.main.LayoutOrder directly, so this has to be the actual tabPage child or the
    -- picker's position among the tab's other elements would silently stop tracking creation
    -- order. A darker frame here, the same idea as the icon well behind PinnedList's icons - a
    -- dedicated background specifically surrounding this element rather than just the ordinary
    -- card treatment every other element gets, for a more "premium" look. self.bar (below) is
    -- the actual pill everything else in this file already assumes "main" means.
    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, barHeight + 34),
        BorderSizePixel = 0,
        Name = "SegmentedPicker",
        BackgroundColor3 = Color3.fromRGB(24, 24, 24),

        BackgroundTransparency = 1, -- In = 0.5

        Parent = self.tab.tabPage,
    })

    -- rounder than the standard ElementCornerRadius on purpose - this card is taller than a
    -- normal element body, so the usual radius reads as barely-rounded next to the fully
    -- pill-shaped bar sitting inside it.
    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 18),
        Parent = self.main,
    })

    self.bar = window:Create("Frame", {
        Size = UDim2.new(1, -16, 0, barHeight),
        Position = UDim2.fromScale(0.5, 0.5),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        Name = "Bar",
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        -- lets _indicatorGoal below overize the sliding pill by a couple px on every edge without
        -- it ever actually poking out past the bar's own rounded silhouette - see that comment
        ClipsDescendants = true,

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.main,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.bar)

    window:Create("UICorner", {
        Parent = self.bar,
    }, { CornerRadius = "PillCornerRadius" })

    self.row = window:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.bar,
    })

    -- the sliding indicator - a free Frame with no layout of its own, so tweening its Position/
    -- Size directly never has anything to fight (see toggle.luau's knob, same idea). No explicit
    -- ZIndex on this or the two siblings below - confirmed live that staggering explicit ZIndex
    -- (1/2/3/4) here broke real click completion on the buttons entirely (hover still fired,
    -- MouseButton1Click never did), while button.luau's interact - which relies purely on being
    -- the last-created sibling, no explicit ZIndex anywhere - has always clicked fine. Creation
    -- order alone (indicator, then childIndicator, then segmentsRow-with-the-actual-buttons last)
    -- reproduces that same reliable layering without whatever the explicit-ZIndex path breaks.
    self.indicator = window:Create("Frame", {
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.row,
    }, { BackgroundColor3 = "FieldGlow" })

    window:Create("UICorner", {
        Parent = self.indicator,
    }, { CornerRadius = "PillCornerRadius" })

    -- the dark inset pill marking the active child while a nested segment is expanded - sits on
    -- top of self.indicator's white (which, expanded, just stays at the whole segment's size and
    -- reads as that pair's shared background) with a few px of inset on every side so the white
    -- shows through as a thin ring around it, same as the reference. Shared across every nested
    -- segment since only one can ever be expanded at a time.
    self.childIndicator = window:Create("Frame", {
        BorderSizePixel = 0,
        BackgroundColor3 = childIndicatorColor,
        Visible = false,

        BackgroundTransparency = 1,

        Parent = self.row,
    })

    window:Create("UICorner", {
        Parent = self.childIndicator,
    }, { CornerRadius = "PillCornerRadius" })

    self.segmentsRow = window:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.row,
    })

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 4),
        PaddingRight = UDim.new(0, 4),
        PaddingTop = UDim.new(0, 4),
        PaddingBottom = UDim.new(0, 4),

        Parent = self.segmentsRow,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        HorizontalFlex = Enum.UIFlexAlignment.Fill,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.segmentsRow,
    })

    self.segments = {}
    for i, option in self.options do
        self.segments[i] = self:_buildSegment(option, i)
    end
end

-- One top-level slot: a plain button if it has no children, or a collapsed label + an expanded
-- row of child buttons (crossfaded, both occupying the same slot) if it does.
function SegmentedPicker:_buildSegment(option, index)
    local window = self.window

    -- Confirmed live with GetGuiObjectsAtPosition: this slot's AbsoluteSize was 213x0 - zero
    -- height, an unclickable sliver, while its child TextButton still rendered its text at
    -- full size regardless (Roblox doesn't clip text to a 0-height parent) - looked completely
    -- normal, wasn't clickable at all. HorizontalFlex.Fill only stretches the main (horizontal)
    -- axis; it never touches height, so a child with no Size of its own collapses to 0 on the
    -- cross axis. Explicit full-height Size fixes it - width is still overridden by Fill flex.
    local slot = window:Create("Frame", {
        Size = UDim2.new(0, 0, 1, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = index,

        Parent = self.segmentsRow,
    })

    local segment = { option = option, slot = slot, children = {} }

    if not option.options then
        segment.button = window:Create("TextButton", {
            Size = UDim2.fromScale(1, 1),
            Text = locale.t(option.text),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 15,

            Parent = slot,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })

        window:ConnectFor(self, segment.button.MouseButton1Click, function()
            self:_pick(index, nil)
        end)

        return segment
    end

    -- which child this segment represents when collapsed - starts on the first one, remembered
    -- across collapsing/re-expanding and across switching to another top-level segment and back
    segment.activeChild = 1

    -- collapsed shows the active child's own name ("Monthly"), not option.text ("Premium") -
    -- there's no separate parent label at rest, just whichever child is currently picked
    segment.collapsedLabel = window:Create("TextButton", {
        Size = UDim2.fromScale(1, 1),
        Text = locale.t(self:_childText(index, 1)),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,

        Parent = slot,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- selecting this segment (from the collapsed label, only ever shown/clickable while it
    -- isn't the active one) is what reveals its siblings - _render expands it automatically
    -- for as long as it stays the selected top-level segment
    window:ConnectFor(self, segment.collapsedLabel.MouseButton1Click, function()
        self:_pick(index, segment.activeChild)
    end)

    segment.expandedRow = window:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = false,

        Parent = slot,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        HorizontalFlex = Enum.UIFlexAlignment.Fill,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = segment.expandedRow,
    })

    for j, child in option.options do
        local childText = if typeof(child) == "table" then child.text or child.Text else tostring(child)
        local childButton = window:Create("TextButton", {
            -- same fix as slot above: HorizontalFlex.Fill only stretches width, an explicit
            -- Size is still needed for height or this collapses to an unclickable 0
            Size = UDim2.new(0, 0, 1, 0),
            Text = locale.t(childText),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 15,
            LayoutOrder = j,

            Parent = segment.expandedRow,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })

        window:ConnectFor(self, childButton.MouseButton1Click, function()
            self:_pick(index, j)
        end)

        segment.children[j] = childButton
    end

    return segment
end

-- Where the outer (white) indicator belongs for a top-level segment: plain fraction-of-the-bar
-- math, since HorizontalFlex.Fill already guarantees every slot is exactly 1/count of the row -
-- nothing here needs to read anything back off an actual Instance to be correct. Always the full
-- segment width, expanded or not.
function SegmentedPicker:_indicatorGoal(index)
    local segmentScale = 1 / #self.options
    -- overized by a couple px on every edge on purpose: Scale-based Position/Size rounds to the
    -- nearest pixel independently for the indicator and for self.bar underneath it, so even
    -- identical fraction math can land them a pixel apart - right at a rounded end (only the
    -- first/last segment has one), that shows as a hairline of the bar's own background peeking
    -- through the corner. self.bar's own ClipsDescendants (see its Create() call) trims this
    -- margin back to the bar's exact pill silhouette, so the overize only ever closes the gap,
    -- never actually pokes out past the true edge.
    local edgeBleed = 2
    return UDim2.new((index - 1) * segmentScale, -edgeBleed, 0, -edgeBleed),
        UDim2.new(segmentScale, edgeBleed * 2, 1, edgeBleed * 2)
end

-- Where the inset childIndicator belongs: the same sub-fraction math as the old single-indicator
-- version used, but pulled in by childIndicatorInset on every side so the outer white shows
-- through as a thin ring around it.
function SegmentedPicker:_childIndicatorGoal(index, childIndex)
    local segmentScale = 1 / #self.options
    local childCount = #self.segments[index].option.options
    local childScale = segmentScale / childCount
    local x = (index - 1) * segmentScale + (childIndex - 1) * childScale

    local inset = childIndicatorInset
    return UDim2.new(x, inset, 0, inset), UDim2.new(childScale, -inset * 2, 1, -inset * 2)
end

-- No separate "expanded" toggle state anymore - a nested segment is expanded exactly when it's
-- the selected one, full stop. Selecting it (from anywhere else) is what reveals its siblings;
-- picking a specific child inside it changes which one's marked without collapsing anything;
-- only picking a genuinely different top-level segment collapses it back to its remembered
-- child's name. Matches the actual ask: click "Monthly", "Annual" appears and stays right there
-- until you pick "Free" again.
function SegmentedPicker:_select(index, childIndex, skipAnimation)
    self.selectedIndex, self.selectedChildIndex = index, childIndex
    self:_render(skipAnimation)
end

function SegmentedPicker:_render(skipAnimation)
    local index, childIndex = self.selectedIndex, self.selectedChildIndex

    for i, segment in self.segments do
        local active = i == index
        if segment.button then
            self.window:_reveal(segment.button, {
                TextColor3 = active and darkTextColor or self.window.theme.ContentColor,
            }, not skipAnimation, fadeInfo)
        else
            local expanded = active
            if expanded then
                segment.expandedRow.Visible = true
            end
            self.window:_reveal(segment.collapsedLabel, {
                TextTransparency = expanded and 1 or 0,
            }, not skipAnimation, fadeInfo)
            for j, childButton in segment.children do
                local childActive = expanded and childIndex == j
                -- expanded, the outer white indicator becomes this pair's shared background - an
                -- inactive child sits right on that white, so it needs dark text now; the active
                -- one sits on the dark childIndicator inset instead, so it flips to light
                self.window:_reveal(childButton, {
                    TextTransparency = expanded and 0 or 1,
                    TextColor3 = childActive and self.window.theme.ContentColor or darkTextColor,
                }, not skipAnimation, fadeInfo)
            end
            if not expanded then
                -- a generation token guards against collapsing then re-expanding the same
                -- segment within fadeInfo.Time, where this delayed hide would otherwise fire
                -- after the re-expand already turned Visible back on and yank it away again
                segment._collapseGen = (segment._collapseGen or 0) + 1
                local gen = segment._collapseGen
                task.delay(if skipAnimation then 0 else fadeInfo.Time, function()
                    if segment.expandedRow and segment._collapseGen == gen then
                        segment.expandedRow.Visible = false
                    end
                end)
            end
        end
    end

    -- the outer white indicator always sits at the whole top-level segment's size, expanded or
    -- not - expanded, that's exactly the shared white background the reference shows behind both
    -- children; the childIndicator (below) is what actually marks which one is picked
    local goalPosition, goalSize = self:_indicatorGoal(index)
    slideIndicator(self.indicator, goalPosition, goalSize, skipAnimation)

    local expandedSegment = index and self.segments[index]
    if expandedSegment and expandedSegment.option.options then
        local childPosition, childSize = self:_childIndicatorGoal(index, childIndex)
        -- going from hidden to shown, snap straight to the target instead of stretching - it was
        -- last positioned wherever it happened to be left (or its layout default, 0,0/0,0) and
        -- has no meaningful "old spot" to smear from yet
        local wasHidden = not self.childIndicator.Visible
        self.childIndicator.Visible = true
        if skipAnimation or wasHidden then
            self.childIndicator.Position, self.childIndicator.Size = childPosition, childSize
        else
            slideIndicator(self.childIndicator, childPosition, childSize, false)
        end
        self.window:_reveal(self.childIndicator, { BackgroundTransparency = 0 }, not skipAnimation, fadeInfo)
    elseif self.childIndicator.BackgroundTransparency == 0 then
        local tween = variables.tweenService:Create(self.childIndicator, fadeInfo, { BackgroundTransparency = 1 })
        tween:Play()
        -- :Once() isn't guaranteed on every client this session has run into (UIListLayout.Enabled
        -- not existing at all on one was the earlier surprise) - :Connect() + manual disconnect is
        -- the one form of "run this once" every client here has actually supported
        local connection
        connection = tween.Completed:Connect(function()
            connection:Disconnect()
            local stillCollapsed = not (self.segments[self.selectedIndex] or {}).option
                or not self.segments[self.selectedIndex].option.options
            if stillCollapsed then
                self.childIndicator.Visible = false
            end
        end)
    end
end

function SegmentedPicker:_pick(index, childIndex)
    local segment = self.segments[index]
    if segment.option.options and childIndex then
        segment.activeChild = childIndex
        segment.collapsedLabel.Text = locale.resolve(self:_childText(index, childIndex))
    end

    if self.selectedIndex == index and self.selectedChildIndex == childIndex then
        return
    end
    hapticEngine.click()
    soundEngine.click()
    self:_select(index, childIndex)

    local value = segment.option.text
    if childIndex and segment.option.options then
        value = self:_childText(index, childIndex)
    end
    self.value = value

    self.window:_runGuarded(self, self.callback, self.value)
    self.window:_persist(self)
end

-- Programmatic select, by a leaf's text (same value a callback receives).
function SegmentedPicker:Set(value, skipCallback)
    local index, childIndex = self:_find(value)
    if not index then
        return
    end
    self.value = value
    local segment = self.segments[index]
    if childIndex and segment.option.options then
        segment.activeChild = childIndex
        segment.collapsedLabel.Text = locale.resolve(self:_childText(index, childIndex))
    end
    self:_select(index, childIndex)

    if not skipCallback then
        self.window:_runGuarded(self, self.callback, self.value)
        self.window:_persist(self)
    end
end

function SegmentedPicker:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_reveal(self.main, { BackgroundTransparency = 0.5 }, animate)
        w:_reveal(self.stroke, { Transparency = w.theme.ElementStrokeTransparency }, animate)
        w:_reveal(self.bar, { BackgroundTransparency = w.theme.ElementTransparency or 0 }, animate)
        w:_reveal(self.indicator, { BackgroundTransparency = 0 }, animate)
        if self.descriptor then
            w:_reveal(self.descriptor.titleLabel, { TextTransparency = 0.7 }, animate)
        end
    else
        w:_reveal(self.main, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.stroke, { Transparency = 1 }, animate)
        w:_reveal(self.bar, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.indicator, { BackgroundTransparency = 1 }, animate)
        if self.descriptor then
            w:_reveal(self.descriptor.titleLabel, { TextTransparency = 1 }, animate)
        end
    end
end

moveable(SegmentedPicker)
lockable(SegmentedPicker)

return SegmentedPicker
]=====]

sources["components/shimmerlabel"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A big heading with a soft band of light sweeping across the text, on a loop with a small rest
-- between passes. TextLabels take a UIGradient the same way Frames do (it recolours the glyphs,
-- not a background), so this is just a gradient with a bright band riding a NumberSequence-free
-- Color rebuild, and its Offset tweened back and forth past both edges.

local ShimmerLabel = {}
ShimmerLabel.__index = ShimmerLabel
ShimmerLabel.__type = "ShimmerLabel"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local moveable = require(utility.moveable)
local locale = require(utility.locale)

-- a still moment at each end before the next pass, so it doesn't read as a nervous, continuous
-- back-and-forth loop
local restTime = 0.5

local function clamp01(n)
    return math.clamp(n, 0.02, 0.9)
end

function ShimmerLabel.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        text = properties.text or properties.Text or properties.name or properties.Name or "",
        speed = properties.speed or properties.Speed or 1.4,
        spread = clamp01(properties.spread or properties.Spread or 0.2),
        angle = properties.angle or properties.Angle or 20,
        textSize = properties.textSize or properties.TextSize or 32,
    }, ShimmerLabel)

    self:_build()
    self:_startLoop()

    return self
end

function ShimmerLabel:_build()
    local window = self.window

    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, self.textSize + 24),
        BorderSizePixel = 0,
        Name = "ShimmerLabel",
        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    })

    self.label = window:Create("TextLabel", {
        Text = locale.t(self.text),
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = self.textSize,
        TextXAlignment = Enum.TextXAlignment.Center,
        TextTruncate = Enum.TextTruncate.AtEnd,

        TextTransparency = 1, -- In = 0

        Parent = self.main,
    }, { TextColor3 = "PlaceholderColor", FontFace = "TitleFont" })

    self.gradient = window:Create("UIGradient", {
        Rotation = self.angle,
        Offset = Vector2.new(-1 - self.spread, 0),

        Parent = self.label,
    })

    self:_rebuildColors()
end

-- Base (muted) everywhere except a bright band self.spread wide, centred on the gradient's own
-- middle - the Offset sweep is what carries that band across the text, not this sequence itself.
function ShimmerLabel:_rebuildColors()
    local base = self.window.theme.PlaceholderColor
    local bright = self.window.theme.ContentColor
    local half = self.spread / 2

    self.gradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, base),
        ColorSequenceKeypoint.new(0.5 - half, base),
        ColorSequenceKeypoint.new(0.5, bright),
        ColorSequenceKeypoint.new(0.5 + half, base),
        ColorSequenceKeypoint.new(1, base),
    })
end

function ShimmerLabel:_startLoop()
    task.spawn(function()
        while self.gradient.Parent do
            local reach = 1 + self.spread
            self.gradient.Offset = Vector2.new(-reach, 0)
            local tween = variables.tweenService:Create(
                self.gradient,
                TweenInfo.new(self.speed, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                { Offset = Vector2.new(reach, 0) }
            )
            tween:Play()
            tween.Completed:Wait()
            task.wait(restTime)
        end
    end)
end

-- Runtime setters - size, speed, angle and text are all adjustable per the devlog; spread too,
-- since it's shown as its own slider in the reference.
function ShimmerLabel:Set(text)
    self.text = tostring(text)
    self.label.Text = locale.resolve(self.text)
end

function ShimmerLabel:SetSpeed(seconds)
    self.speed = math.max(0.2, seconds)
end

function ShimmerLabel:SetSpread(fraction)
    self.spread = clamp01(fraction)
    self:_rebuildColors()
end

function ShimmerLabel:SetAngle(degrees)
    self.angle = degrees
    self.gradient.Rotation = degrees
end

function ShimmerLabel:SetTextSize(size)
    self.textSize = size
    self.label.TextSize = size
    self.main.Size = UDim2.new(1, -20, 0, size + 24)
end

function ShimmerLabel:_setShown(shown, animate)
    self.window:_reveal(self.label, { TextTransparency = if shown then 0 else 1 }, animate)
end

moveable(ShimmerLabel)

return ShimmerLabel
]=====]

sources["components/slider"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Slider = {}
Slider.__index = Slider
Slider.__type = "Slider"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local odometer = require(utility.odometer)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

-- Decimal places implied by an increment (0.1 -> 1, 0.25 -> 2, 1 -> 0). Used so
-- the readout formats mid-roll floats to the same precision as landed values.
local function decimalsOf(step)
    local decimals = 0
    while step % 1 ~= 0 and decimals < 6 do
        step = step * 10
        decimals += 1
    end
    return decimals
end

-- snap onto the increment grid anchored at range[1], so both endpoints stay reachable
-- (a zero-anchored grid cant express range = {0.5, 2.5} with increment 1)
local function snapTo(range, increment, value)
    local snapped = range[1] + math.round((value - range[1]) / increment) * increment
    return math.clamp(snapped, range[1], range[2])
end

local tweenInfo = TweenInfo.new(0.45, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local heldInfo = TweenInfo.new(0.3, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
local followInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

-- half the handle's own 18px size - see _renderProgress for how this keeps the handle's centre
-- inset from either edge of the track, so it can never poke out past the track's own bounds
local handleRadius = 9

-- Below this element width we reflow to the stacked layout (title/value on top, full-width
-- track under it) so the slider stays usable in a narrow column or small window instead of
-- overlapping. Sits well below a full-width slider (~435) - including the slightly narrower
-- width it has before the window's intro grow finishes - and well above a grid column (~180),
-- so those two cases land cleanly on either side and open/close transients never straddle it.
local narrowWidth = 300

function Slider.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Slider",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState,

        range = properties.range or properties.Range or { 0, 100 },
        increment = properties.increment or properties.Increment or 1,
        suffix = properties.suffix or properties.Suffix or "",

        callback = properties.callback or properties.Callback or function() end,

        dragging = false,
        minimal = properties.minimal or properties.Minimal or false, -- track only, no name/value
    }, Slider)

    -- keep range ascending and increment positive so the clamp/snap math stays sane
    if self.range[1] > self.range[2] then
        self.range = { self.range[2], self.range[1] }
    end
    if self.increment <= 0 then
        self.increment = 1
    end

    self.value = if (properties.value or properties.Value) ~= nil
        then (properties.value or properties.Value)
        elseif (properties.currentValue or properties.CurrentValue) ~= nil then (
            properties.currentValue or properties.CurrentValue
        )
        else self.range[1]

    -- snap + clamp the starting value the same way Set does, so the stored value
    -- and the bar never disagree (and a bad initial value can't be saved)
    self.value = snapTo(self.range, self.increment, self.value)

    self._decimals = decimalsOf(self.increment)

    self.flag = properties.flag
        or properties.Flag
        or (not self.forgetState and functions.deriveFlagFromName(self.name) or nil)
    self.window:_registerControl(self)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 65),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = self.window:StyleElementBody(self.main)
    self._lastValue = self.value

    -- minimal is just the track (built below); skip the whole title/value block
    if not self.minimal then
        self:_buildLabel()
    end

    -- Right: the track. Devlog 7: thinner, more minimal (was 14px) - a slim rail with the
    -- pill handle riding above it, rather than a chunky bar the handle sits flush inside.
    self.track = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(1, 0.5),
        Position = UDim2.new(1, -15, 0.5, 0),
        Size = UDim2.fromOffset(222, 6),
        BorderSizePixel = 0,
        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    }, { BackgroundColor3 = "SliderBackground" })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),

        Parent = self.track,
    })

    self.progress = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.fromScale(0, 0.5),
        Size = UDim2.fromScale(0, 1),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 2,
        BackgroundTransparency = 1, -- In = 0

        Parent = self.track,
    })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),

        Parent = self.progress,
    })

    self.window:Create("UIGradient", {
        Offset = Vector2.new(0, 0.5),
        Rotation = 2,
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.85),
            NumberSequenceKeypoint.new(1, 0),
        }),

        Parent = self.progress,
    }, { Color = { "SliderProgress", functions.toColorSequence } })

    -- Green glow behind the filled progress (revealed on show)
    self.progressGlow = self.window:CreateGlow(self.progress, "AccentColor", 20, 1)

    -- Handle: a small solid-white circular pill riding on the thin track, sized independent
    -- of the track's own (now much slimmer) height rather than filling it. Ghosts + grows a
    -- stroke while held, same feel as before, just smaller so it still reads as minimal.
    --
    -- Parented to the track directly, not the fill - its own position is computed explicitly
    -- in _renderProgress (bounded, see handleRadius) rather than anchored past the fill's own
    -- edge with a fixed offset like the old version did. That fixed "+20px past the fill" was
    -- size-independent by construction (AnchorPoint(1,0.5) addresses the handle's own right
    -- edge, not something that moves with its width) - live-caught it poking a good 5px past
    -- the whole element's own right edge at the slider's max value, regardless of handle size,
    -- which is why shrinking the handle for the Devlog 7 redesign never actually changed it:
    -- reported as "the handle goes outside the slider, can't grab it" once this became the one
    -- slider (Settings > Window transparency) actually getting dragged to its own maximum.
    self.handle = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0, 0.5),
        Size = UDim2.fromOffset(18, 18),
        BorderSizePixel = 0,
        ZIndex = 50,
        BackgroundTransparency = 1, -- In = 0

        Parent = self.track,
    }, { BackgroundColor3 = "SliderHandle" })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),

        Parent = self.handle,
    })

    -- White glow behind the drag handle (revealed on show)
    self.handleGlow = self.window:CreateGlow(self.handle, Color3.fromRGB(255, 255, 255), 10, 1)

    self.handleStroke = self.window:Create("UIStroke", {
        Transparency = 1, -- 0.6 while held

        Parent = self.handle,
    }, { Color = "SliderStroke" })

    self.interact = self.window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        Text = "",
        TextTransparency = 1,
        ZIndex = 10,

        Parent = self.track,
    })

    -- Subtle hover on the slider track itself, not the whole element row
    self.window:ConnectFor(self, self.main.MouseEnter, function()
        if not self.window:_interactive() then
            return -- window still revealing/hiding: dont light up mid-animation
        end
        variables.tweenService
            :Create(self.track, tweenInfo, { BackgroundColor3 = self.window.theme.SliderBackgroundHover })
            :Play()
    end)

    self.window:ConnectFor(self, self.main.MouseLeave, function()
        variables.tweenService
            :Create(self.track, tweenInfo, { BackgroundColor3 = self.window.theme.SliderBackground })
            :Play()
    end)

    self.window:ConnectFor(self, self.interact.InputBegan, function(input)
        if
            input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch
        then
            hapticEngine.click() -- one tick on grab, not per drag frame
            soundEngine.click()
            self.dragging = true
            self:_setHeld(true)
            self:_updateFromMouse()

            -- drop any stale follow first, in case InputBegan fires again before InputEnded
            if self._dragConnection then
                self._dragConnection:Disconnect()
                self._dragConnection = nil
            end

            -- Only run the per-frame follow while actually dragging. Self-terminates if the
            -- window unloads mid-drag, since InputEnded won't fire to clean us up then.
            self._dragConnection = variables.runService.RenderStepped:Connect(function()
                if self.window.unloaded or not self.dragging then
                    if self._dragConnection then
                        self._dragConnection:Disconnect()
                        self._dragConnection = nil
                    end
                    return
                end
                self:_updateFromMouse()
            end)
        end
    end)

    self.window:ConnectFor(self, variables.userInputService.InputEnded, function(input)
        if
            (input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch)
            and self.dragging
        then
            self.dragging = false
            self:_setHeld(false)

            if self._dragConnection then
                self._dragConnection:Disconnect()
                self._dragConnection = nil
            end

            self.window:_persist(self)
        end
    end)

    self.window:_wireTooltip(self)

    if self.description and not self.minimal then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    -- pick wide vs stacked from the real width, and keep it in sync if that width changes
    -- (column resolves its size a frame after we build, and windows can be small)
    self.window:ConnectFor(self, self.main:GetPropertyChangedSignal("AbsoluteSize"), function()
        -- Ignore the transient widths the window sweeps through as it collapses/grows on
        -- hide/show/minimise, so the slider just keeps the mode it settled on while visible.
        -- The one time we DO want a hidden-window reflow is the initial layout pass before the
        -- first open (the element sizes to its real/column width while the window's still
        -- hidden) - so only block hidden reflows once the window has been shown at least once.
        if self.window.animating or (self.window.hidden and self.window.hasShownOnce) then
            return
        end
        self:_applyLayout()
    end)
    self:_applyLayout()

    if self.minimal then
        -- bare: no title/value, keep the compact 41px height so it lines up with
        -- buttons/toggles/stats, and let the track fill the bar
        self.main.Size = UDim2.new(1, -20, 0, 41)
        self.track.AnchorPoint = Vector2.new(0.5, 0.5)
        self.track.Position = UDim2.new(0.5, 0, 0.5, 0)
        self.track.Size = UDim2.new(1, -30, 0, 6)
    end

    self:_renderProgress()

    return self
end

-- The title + value block: the left column in the wide layout, the top row in the narrow
-- one. A minimal slider skips this entirely and shows only the track.
function Slider:_buildLabel()
    -- Left: title (+ icon) stacked over the value
    self.container = self.window:Create("Frame", {
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.new(0, 20, 0.5, 0),
        Size = UDim2.fromOffset(170, 33),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,

        Parent = self.main,
    })

    self.containerLayout = self.window:Create("UIListLayout", {
        Padding = UDim.new(0, 2),
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.container,
    })

    self.titleContainer = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,

        Parent = self.container,
    })

    self.window:Create("UIListLayout", {
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.titleContainer,
    })

    -- narrow layout puts title + value on one row; this fills the title so the value
    -- gets pushed to the right. wide layout sets it back to None (title over value).
    self.titleFlex = self.window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.None,
        Parent = self.titleContainer,
    })

    if self.icon then
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ZIndex = 5,

            -- Animation
            ImageTransparency = 1, -- In = 0

            Parent = self.titleContainer,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = self.window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.new(1, 0, 0, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd, -- ellipsize instead of wrapping when the column's tight
        RichText = true,
        LayoutOrder = 1,
        ZIndex = 5,

        -- Animation
        TextTransparency = 1, -- In = 0

        Parent = self.titleContainer,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- shrink to share the title row with the icon when space is tight
    self.window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    -- Odometer readout: host frame in place of the old label; the odometer lays
    -- its per-digit reels out inside it, left-aligned under the title.
    self.valueHost = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 6,
        LayoutOrder = 1, -- sits under the title (wide) / right of it (narrow)

        Parent = self.container,
    })

    self.valueOdo = odometer.new(self.window, self.valueHost, {
        textSize = 15,
        alignment = Enum.HorizontalAlignment.Left,
        transparency = 1, -- revealed to 0.3 on show
        duration = 0.28, -- snappy roll on :Set; drag snaps instead (stays glued to the handle)
    })
    self.valueOdo:snap(self:_format(self.value))
end

-- Set the element height, keeping the width alone when a horizontal group owns it
-- (_widthManaged): there the stack freezes us to _minWidth and wraps, so we must not
-- stomp the X it set. Standalone we take the usual full width.
function Slider:_setMainHeight(height)
    if self._widthManaged then
        self.main.Size = UDim2.new(self.main.Size.X.Scale, self.main.Size.X.Offset, 0, height)
    else
        self.main.Size = UDim2.new(1, -20, 0, height)
    end
end

-- wide: title over value on the left, fixed track on the right.
-- narrow: title + value share the top row (value pushed right), full-width track below.
-- Chosen from the slider's real width, so a slider in a narrow column (a grid) stacks while a
-- full-width one stays wide. The AbsoluteSize handler that calls this ignores the transient
-- widths the window sweeps through as it opens/closes, so this only ever runs on a settled
-- width (see the guard where it's connected).
function Slider:_applyLayout()
    if self.minimal then
        return -- bare mode has a fixed slim layout, nothing to reflow
    end
    local width = self.main.AbsoluteSize.X
    local mode = if width > 0 and width < narrowWidth then "narrow" else "wide"
    if self._layoutMode == mode then
        return
    end
    self._layoutMode = mode

    if mode == "narrow" then
        self:_setMainHeight(70)

        self.container.AnchorPoint = Vector2.new(0, 0)
        self.container.Position = UDim2.new(0, 20, 0, 14)
        self.container.Size = UDim2.new(1, -40, 0, 16)
        self.containerLayout.FillDirection = Enum.FillDirection.Horizontal
        self.titleFlex.FlexMode = Enum.UIFlexMode.Fill -- title grows, value hugs the right
        self.valueHost.AutomaticSize = Enum.AutomaticSize.X
        self.valueHost.Size = UDim2.new(0, 0, 0, 16)

        self.track.AnchorPoint = Vector2.new(0.5, 1)
        self.track.Position = UDim2.new(0.5, 0, 1, -14)
        self.track.Size = UDim2.new(1, -30, 0, 6)
    else
        self:_setMainHeight(65)

        self.container.AnchorPoint = Vector2.new(0, 0.5)
        self.container.Position = UDim2.new(0, 20, 0.5, 0)
        self.container.Size = UDim2.new(0, 170, 0, 33)
        self.containerLayout.FillDirection = Enum.FillDirection.Vertical
        self.titleFlex.FlexMode = Enum.UIFlexMode.None
        self.valueHost.AutomaticSize = Enum.AutomaticSize.None
        self.valueHost.Size = UDim2.new(1, 0, 0, 16)

        self.track.AnchorPoint = Vector2.new(1, 0.5)
        self.track.Position = UDim2.new(1, -15, 0.5, 0)
        self.track.Size = UDim2.new(0, 222, 0, 6)
    end
end

function Slider:_format(value)
    local text = string.format("%." .. self._decimals .. "f", value)
    if self.suffix ~= "" then
        return text .. " " .. self.suffix
    end
    return text
end

function Slider:_renderProgress(info)
    local span = self.range[2] - self.range[1]
    local ratio = if span ~= 0 then math.clamp((self.value - self.range[1]) / span, 0, 1) else 0
    -- the handle's centre goes from handleRadius (its left edge flush with the track's own
    -- left edge) to 1-scale minus handleRadius (its right edge flush with the track's own
    -- right edge) - expressed as one Scale+Offset pair so it works at any track width without
    -- reading AbsoluteSize, and never depends on the handle's own size the way anchoring it
    -- past the fill's edge with a fixed offset used to (see the handle's own comment).
    local insetX = handleRadius - 2 * handleRadius * ratio
    -- Fill width tracked the raw ratio (0 -> flush left, 1 -> flush right), so it always ran
    -- past where the handle's own centre actually sat - invisible at ratio 0 (zero width either
    -- way) but visibly overshot the handle everywhere else, worst at the low/high end of a grid
    -- column's narrower track where the mismatch reads as a bigger fraction of it. Same
    -- Scale+Offset expression as handlePos below, so the fill's edge and the handle's centre
    -- are mathematically the same point at any track width, not just visually close at the one
    -- width this got eyeballed at.
    local size = UDim2.new(ratio, insetX, 1, 0)
    local handlePos = UDim2.new(ratio, insetX, 0.5, 0)
    if info then
        variables.tweenService:Create(self.progress, info, { Size = size }):Play()
        variables.tweenService:Create(self.handle, info, { Position = handlePos }):Play()
    else
        self.progress.Size = size
        self.handle.Position = handlePos
    end
end

function Slider:_updateFromMouse()
    local width = self.track.AbsoluteSize.X
    if width <= 0 then
        return
    end

    local ratio =
        math.clamp((variables.userInputService:GetMouseLocation().X - self.track.AbsolutePosition.X) / width, 0, 1)
    local value = snapTo(self.range, self.increment, self.range[1] + ratio * (self.range[2] - self.range[1]))

    if value ~= self.value then
        self.value = value
        if self.valueOdo then
            self.valueOdo:snap(self:_format(value)) -- glued to the handle: no roll mid-drag
        end
        self._lastValue = value
        self:_renderProgress(followInfo)
        self:_fireCallback(value)
    end
end

function Slider:_setHeld(held)
    if held then
        variables.tweenService
            :Create(self.handle, heldInfo, { Size = UDim2.fromOffset(24, 24), BackgroundTransparency = 0.7 })
            :Play()
        variables.tweenService:Create(self.handleStroke, heldInfo, { Transparency = 0.6 }):Play()
    else
        variables.tweenService
            :Create(self.handle, heldInfo, { Size = UDim2.fromOffset(18, 18), BackgroundTransparency = 0 })
            :Play()
        variables.tweenService:Create(self.handleStroke, heldInfo, { Transparency = 1 }):Play()
    end
end

-- pcall + debounced error-flash via Window:_runGuarded (fires every drag frame)
function Slider:_fireCallback(value)
    self.window:_runGuarded(self, self.callback, value)
end

function Slider:Set(value, skipCallback)
    value = snapTo(self.range, self.increment, value)
    self.value = value
    if self.valueOdo then
        self.valueOdo:to(self:_format(value), value >= (self._lastValue or value))
    end
    self._lastValue = value
    self:_renderProgress(tweenInfo)

    if not skipCallback then
        self:_fireCallback(value)
        self.window:_persist(self)
    end
end

-- glows delayed so they don't float in before the bar during the window-open fade
local sliderGlowReveal = TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out, 0, false, 0.35)

function Slider:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.track, { BackgroundTransparency = 0 }, animate)
        w:_reveal(self.progress, { BackgroundTransparency = 0 }, animate)
        w:_reveal(self.handle, { BackgroundTransparency = 0 }, animate)
        if self.valueOdo then
            self.valueOdo:reveal(0.3, animate)
        end
        -- soften the accent bloom on light themes (AccentGlow) but never below the default 0.55
        w:_reveal(self.progressGlow, { Transparency = math.max(0.55, w.theme.AccentGlow) }, animate, sliderGlowReveal)
        w:_reveal(self.handleGlow, { Transparency = 0.8 }, animate, sliderGlowReveal)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.track, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.progress, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.handle, { BackgroundTransparency = 1 }, animate)
        if self.valueOdo then
            self.valueOdo:reveal(1, animate)
        end
        w:_reveal(self.progressGlow, { Transparency = 1 }, animate, sliderGlowReveal)
        w:_reveal(self.handleGlow, { Transparency = 1 }, animate, sliderGlowReveal)
    end
end

-- Re-apply the accent glow strength on a runtime ChangeTheme (fill/handle/track ride
-- themeProperties). Called on the visible tab only.
function Slider:_refreshTheme()
    variables.tweenService
        :Create(
            self.progressGlow,
            TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
            { Transparency = math.max(0.55, self.window.theme.AccentGlow) }
        )
        :Play()
end

-- Room the slider needs in a row: its narrow layout puts title + value on the top row,
-- so that has to fit, and we floor it so the track underneath stays draggable.
function Slider:_minWidth()
    if self.minimal then
        return 100 -- a slim bar: side padding + a usable minimum track
    end
    local w = 40 -- container inset, 20 each side
    if self.icon then
        w += 22 -- 16 icon + 6 gap
    end
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    w += 12 -- gap before the value
    w += functions.textWidth(self.window.theme.Font, 15, self:_format(self.value))
    return math.max(w, 160)
end

moveable(Slider)
lockable(Slider)

return Slider
]=====]

sources["components/spacer"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 7: an invisible gap with a configurable height, for custom breathing room between
-- elements/sections beyond whatever the tab page's own UIListLayout gap already gives.

local Spacer = {}
Spacer.__index = Spacer
Spacer.__type = "Spacer"

local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local moveable = require(utility.moveable)

local heightInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)

function Spacer.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = "Spacer",
        height = properties.height or properties.Height or 12,
    }, Spacer)

    self.main = self.window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, self.height),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Name = self.name,

        Parent = self.tab.tabPage,
    })

    return self
end

-- Nothing to fade in/out - a spacer has no visual content of its own. Still needs the method:
-- Tab:_register's reveal pass, and a runtime SetVisible, both call it unconditionally.
function Spacer:_setShown(shown, animate) end

-- Changes the gap's height, tweened by default (pass animate = false to snap instantly).
function Spacer:SetHeight(height, animate)
    self.height = height
    local target = UDim2.new(1, -20, 0, height)
    if animate == false then
        self.main.Size = target
    else
        variables.tweenService:Create(self.main, heightInfo, { Size = target }):Play()
    end
end

moveable(Spacer)

return Spacer
]=====]

sources["components/stat"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Statistic = {}
Statistic.__index = Statistic
Statistic.__type = "Statistic"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local odometer = require(utility.odometer)
local moveable = require(utility.moveable)
local constants = require(utility.constants)
local locale = require(utility.locale)
local log = require(utility.log)

-- Accent gradients per direction (fill drives the card + glow, stroke is the brighter edge)
local accents = constants.statAccents

local accentTransparency = NumberSequence.new({
    NumberSequenceKeypoint.new(0, 0.85),
    NumberSequenceKeypoint.new(1, 0),
})

local compactHeight = 41

local accentTweenInfo = TweenInfo.new(0.6, Enum.EasingStyle.Exponential)

-- UIShadow glows take one colour, so the halo uses the brightest stop of the direction's fill.
local function glowColor(accent)
    return accent.fill.Keypoints[1].Value
end

-- "Neutral" (no established trend yet - see _hasValue) used to be the same hardcoded green as
-- "positive" regardless of theme, which read as "why is this a KPI colour" on any hub whose theme
-- wasn't that particular green (live-reported: "os bgl que ta verde ia seguir a cor do theme").
-- Positive/negative stay their own fixed semantic green/red on purpose - those convey a real
-- direction, and diluting that into "whatever colour the theme happens to be" would make a stat
-- that's visibly gone up or down harder to read at a glance, not easier. Derived fresh from the
-- theme's own AccentColor rather than looked up once and cached, so a live Settings > Color theme
-- swap reaches it the next time this stat updates (every Set() call re-derives it).
local function themeNeutralAccent(theme)
    local accent = theme.AccentColor
    return {
        fill = ColorSequence.new(accent, accent:Lerp(Color3.new(0, 0, 0), 0.25)),
        stroke = ColorSequence.new(accent:Lerp(Color3.new(1, 1, 1), 0.2), accent),
    }
end

local function formatPct(pct)
    if pct > 0 then
        return string.format("+%.1f%%", pct)
    elseif pct < 0 then
        return string.format("%.1f%%", pct)
    else
        return "0%"
    end
end

local function formatValue(value)
    if typeof(value) ~= "number" then
        return tostring(value)
    end
    local s = tostring(math.floor(math.abs(value)))
    local result = s:reverse():gsub("%d%d%d", "%0,"):reverse()
    if result:sub(1, 1) == "," then
        result = result:sub(2)
    end
    return if value < 0 then "-" .. result else result
end

local function formatChange(delta)
    if delta > 0 then
        return "+" .. formatValue(math.round(delta))
    elseif delta < 0 then
        return formatValue(math.round(delta))
    else
        return "0"
    end
end

function Statistic.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Statistic",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,

        value = if (properties.value or properties.Value) ~= nil then (properties.value or properties.Value) else 0,
        -- did we start with a real value, or is the displayed number just a placeholder?
        -- the first Set on a placeholder establishes the baseline instead of showing a change
        _hasValue = (properties.value or properties.Value) ~= nil,

        numberEasing = if (properties.numberEasing ~= nil)
            then properties.numberEasing
            elseif properties.NumberEasing ~= nil then properties.NumberEasing
            else true,

        changeMode = properties.changeMode or properties.ChangeMode or "percentage", -- "percentage" | "absolute"
        changeBaseline = properties.changeBaseline or properties.ChangeBaseline or "previous",

        prefix = properties.prefix or properties.Prefix or "",
        suffix = properties.suffix or properties.Suffix or "",

        -- 41px single-readout card. config opt-in, forced on in a row. only room for
        -- one number, so `display` picks value or % change.
        compact = properties.compact or properties.Compact or tab.compact or false,
        display = (properties.display or properties.Display or "value"), -- "value" | "change"

        _initialValue = if (properties.value or properties.Value) ~= nil
            then (properties.value or properties.Value)
            else nil,
        _lastChange = 0,
    }, Statistic)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    self.window:_wireTooltip(self)

    if self.description then
        if self.compact then
            log.warn(`Rayfield: a compact stat has no room for a description, ignoring it on '{self.name}'.`)
        else
            self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
        end
    end

    return self
end

-- full 90px card: title, value bottom-left, % change bottom-right
function Statistic:_buildFull()
    local window = self.window

    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 90),
        BorderSizePixel = 0,
        Name = self.name,
        ZIndex = 5,
        -- Devlog 7 fix: stays clickable even at ElementTransparency 1 (a fully "glass" window) -
        -- see Window:StyleElementBody's own comment on the same fix for why. stat.luau styles
        -- its own card instead of going through that helper, so it needs this directly.
        Active = true,

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundColor3 = "StatBackground", BackgroundTransparency = "ElementTransparency" })

    window:Create("UICorner", {
        Parent = self.main,
    }, { CornerRadius = "ElementCornerRadius" })

    self.stroke = window:Create("UIStroke", {
        Transparency = 1, -- Animation In = 0
        Color = Color3.fromRGB(255, 255, 255),

        Parent = self.main,
    }, { Transparency = "ElementStrokeTransparency" })

    local neutralAccent = themeNeutralAccent(window.theme)

    self.strokeGradient = window:Create("UIGradient", {
        Rotation = 2,
        Offset = Vector2.new(0, 0.5),
        Color = neutralAccent.stroke,
        Transparency = accentTransparency,

        Parent = self.stroke,
    })

    self.titleContainer = window:Create("Frame", {
        Size = UDim2.new(1, -40, 0, 32),
        Position = UDim2.fromOffset(20, 15),
        BorderSizePixel = 0,
        LayoutOrder = -1,
        BackgroundTransparency = 1,
        ZIndex = 5,

        Parent = self.main,
    })

    self.gradientContainer = window:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        Position = UDim2.fromOffset(0, 0),
        BorderSizePixel = 0,
        BackgroundTransparency = 1, -- In 0
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        ZIndex = 5,

        Parent = self.main,
    })

    -- Soft accent halo behind the card. UIShadow (no image) is our glow standard; its colour
    -- follows the stat direction and it reveals from hidden to 0.7 like the rest of the card.
    self.glow = window:CreateGlow(self.main, glowColor(neutralAccent), 13, 1)

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),

        Size = UDim2.fromOffset(300, 19),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 19,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,
        ZIndex = 10,

        TextTransparency = 1, -- In = 0

        Parent = self.titleContainer,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    self.mainGradient = window:Create("UIGradient", {
        Rotation = 2,
        Offset = Vector2.new(0, 0.5),
        Color = neutralAccent.fill,
        Transparency = accentTransparency,

        Parent = self.gradientContainer,
    })

    window:Create("UICorner", {
        Parent = self.gradientContainer,
    }, { CornerRadius = "ElementCornerRadius" })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(32, 32),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ZIndex = 10,

            ImageTransparency = 1, -- In = 0

            Parent = self.titleContainer,
        }, { ImageColor3 = "ContentColor" })
    end

    self.containerLayout = window:Create("UIListLayout", {
        Padding = UDim.new(0, 8),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.titleContainer,
    })

    -- Value (bottom-left) + change (bottom-right) odometer readouts.
    self.valueHost = window:Create("Frame", {
        AnchorPoint = Vector2.new(0, 1),
        Position = UDim2.new(0, 20, 1, -15),
        Size = UDim2.fromOffset(200, 20),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 10,

        Parent = self.main,
    })

    self.changeHost = window:Create("Frame", {
        AnchorPoint = Vector2.new(1, 1),
        Position = UDim2.new(1, -20, 1, -15),
        Size = UDim2.fromOffset(200, 15),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 10,

        Parent = self.main,
    })

    self.valueOdo = odometer.new(window, self.valueHost, {
        textSize = 20,
        alignment = Enum.HorizontalAlignment.Left,
        transparency = 1, -- revealed to 0 on show
    })
    self.valueOdo:snap(self:_formatValue(self.value))

    self.changeOdo = odometer.new(window, self.changeHost, {
        textSize = 15,
        alignment = Enum.HorizontalAlignment.Right,
        transparency = 1,
    })
    self.changeOdo:snap(self:_formatChange(0))

    self._accentGradients = { self.strokeGradient, self.mainGradient }
end

-- compact 41px card: icon+title left, one readout right. accent gradient sits on
-- the card (the flexed child), not a separate overlay
function Statistic:_buildCompact()
    local window = self.window

    -- in a row it's content-sized and flexes; standalone it's full-width, no flex item
    local inRow = self.tab.compact or false

    self.main = window:Create("Frame", {
        Name = self.name,
        Size = if inRow then UDim2.fromOffset(0, compactHeight) else UDim2.new(1, -20, 0, compactHeight),
        AutomaticSize = if inRow then Enum.AutomaticSize.X else Enum.AutomaticSize.None,
        ClipsDescendants = true,
        BorderSizePixel = 0,
        ZIndex = 5,
        Active = true, -- Devlog 7 fix - see the other _build's own main creation for why

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundColor3 = "StatBackground", BackgroundTransparency = "ElementTransparency" })

    window:Create("UICorner", {
        Parent = self.main,
    }, { CornerRadius = "ElementCornerRadius" })

    self.stroke = window:Create("UIStroke", {
        Transparency = 1, -- In = ElementStrokeTransparency
        Color = Color3.fromRGB(255, 255, 255),

        Parent = self.main,
    }, { Transparency = "ElementStrokeTransparency" })

    local neutralAccent = themeNeutralAccent(window.theme)

    self.strokeGradient = window:Create("UIGradient", {
        Rotation = 2,
        Offset = Vector2.new(0, 0.5),
        Color = neutralAccent.stroke,
        Transparency = accentTransparency,

        Parent = self.stroke,
    })

    if inRow then
        window:Create("UIFlexItem", {
            FlexMode = Enum.UIFlexMode.Fill,
            Parent = self.main,
        })
    end

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.Fill,

        Parent = self.main,
    })

    -- accent surface + content: white base + accent gradient, title left, readout right
    self.card = window:Create("Frame", {
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, compactHeight),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = 5,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    })

    window:Create("UICorner", {
        Parent = self.card,
    }, { CornerRadius = "ElementCornerRadius" })

    self.mainGradient = window:Create("UIGradient", {
        Rotation = 2,
        Offset = Vector2.new(0, 0.5),
        Color = neutralAccent.fill,
        Transparency = accentTransparency,

        Parent = self.card,
    })

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 15),
        PaddingRight = UDim.new(0, 15),

        Parent = self.card,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,
        Padding = UDim.new(0, 10),

        Parent = self.card,
    })

    -- icon + title (left)
    self.titleContainer = window:Create("Frame", {
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 0,
        ZIndex = 6,

        Parent = self.card,
    })

    -- title gives up room to the readout when tight
    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.titleContainer,
    })

    window:Create("UIListLayout", {
        Padding = UDim.new(0, 6),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.titleContainer,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(20, 20), -- smaller than the full 32
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,
            ZIndex = 6,

            ImageTransparency = 1, -- In = 0

            Parent = self.titleContainer,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,
        ZIndex = 6,

        TextTransparency = 1, -- In = 0

        Parent = self.titleContainer,
    }, { TextColor3 = "ContentColor", FontFace = "Font" }) -- Medium, like the other row elements

    -- grows to its text, shrinks + ellipsizes when tight
    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    -- single readout (right)
    self.readoutHost = window:Create("Frame", {
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, 18),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 1,
        ZIndex = 6,

        Parent = self.card,
    })

    self.readoutOdo = odometer.new(window, self.readoutHost, {
        textSize = 17,
        alignment = Enum.HorizontalAlignment.Right,
        transparency = 1,
    })
    self.readoutOdo:snap(self.display == "change" and self:_formatChange(0) or self:_formatValue(self.value))

    self._accentGradients = { self.strokeGradient, self.mainGradient }
end

function Statistic:_setAccent(key, direction)
    -- "neutral" isn't in the static table any more - see themeNeutralAccent's own comment on why -
    -- re-derived here so a theme swapped since construction is picked up the next time a value
    -- actually changes, rather than only once at build time.
    local accent = if key == "neutral" then themeNeutralAccent(self.window.theme) else accents[key]
    self.strokeGradient.Color = accent.stroke
    self.mainGradient.Color = accent.fill
    if self.glow then
        self.glow.Color = glowColor(accent)
    end

    -- Subtle rotation + offset shift to give the gradient a bit of life
    local rotation = if direction == 1 then 14 elseif direction == -1 then -10 else 2
    local offset = if direction == 1
        then Vector2.new(0.04, 0.5)
        elseif direction == -1 then Vector2.new(-0.04, 0.5)
        else Vector2.new(0, 0.5)
    for _, gradient in self._accentGradients do
        variables.tweenService:Create(gradient, accentTweenInfo, { Rotation = rotation, Offset = offset }):Play()
    end
end

function Statistic:_formatValue(value)
    return self.prefix .. formatValue(value) .. self.suffix
end

function Statistic:_formatChange(delta)
    if self.changeMode == "absolute" then
        return formatChange(delta)
    else
        return formatPct(delta)
    end
end

-- Put a value on a readout: rolls when number easing is on and there's a previous number to
-- roll from, snaps otherwise. Both card shapes and ResetBaseline go through here.
function Statistic:_showValue(odo, value, previousValue, hasNoHistory)
    if self.numberEasing and not hasNoHistory then
        odo:to(self:_formatValue(value), value >= previousValue)
    else
        odo:snap(self:_formatValue(value))
    end
end

-- full: roll value + change independently
function Statistic:_updateFullReadouts(value, previousValue, targetChange, noChange, infinityText, hasNoHistory)
    self:_showValue(self.valueOdo, value, previousValue, hasNoHistory)

    if infinityText then
        self.changeOdo:snap(infinityText)
        self._lastChange = 0
    elseif self.numberEasing and not noChange then
        self.changeOdo:to(self:_formatChange(targetChange), targetChange >= self._lastChange)
        self._lastChange = targetChange
    else
        self.changeOdo:snap(self:_formatChange(targetChange or 0))
        self._lastChange = targetChange or 0
    end
end

-- compact: roll the one readout
function Statistic:_updateCompactReadout(value, previousValue, targetChange, noChange, infinityText, hasNoHistory)
    if self.display == "change" then
        if infinityText then
            self.readoutOdo:snap(infinityText)
            self._lastChange = 0
        elseif self.numberEasing and not noChange then
            self.readoutOdo:to(self:_formatChange(targetChange), targetChange >= self._lastChange)
            self._lastChange = targetChange
        else
            self.readoutOdo:snap(self:_formatChange(targetChange or 0))
            self._lastChange = targetChange or 0
        end
    else -- "value"
        self:_showValue(self.readoutOdo, value, previousValue, hasNoHistory)
    end
end

function Statistic:Set(value)
    assert(typeof(value) == "number", "Statistic:Set() - value must be a number, got " .. typeof(value))

    local previousValue = self.value
    local hasNoHistory = not self._hasValue
    self.value = value
    self._hasValue = true

    if hasNoHistory then
        self._initialValue = value
    end

    local refValue = if self.changeBaseline == "initial" then self._initialValue else previousValue
    local noChange = hasNoHistory or refValue == value

    -- Determine target change, accent, and direction
    local targetChange, infinityText, accentKey, direction
    if noChange then
        targetChange = 0
        accentKey = "neutral"
        direction = 0
    elseif refValue == 0 then
        local sign = if value > 0 then "+" else "-"
        local suffix = if self.changeMode == "percentage" then "∞%" else "∞"
        infinityText = sign .. suffix
        accentKey = if value > 0 then "positive" else "negative"
        direction = if value > 0 then 1 else -1
    elseif self.changeMode == "percentage" then
        targetChange = ((value - refValue) / math.abs(refValue)) * 100
        direction = if targetChange > 0 then 1 elseif targetChange < 0 then -1 else 0
        accentKey = if direction == 1 then "positive" elseif direction == -1 then "negative" else "neutral"
    else
        targetChange = value - refValue
        direction = if targetChange > 0 then 1 elseif targetChange < 0 then -1 else 0
        accentKey = if direction == 1 then "positive" elseif direction == -1 then "negative" else "neutral"
    end

    self:_setAccent(accentKey, direction)

    if self.compact then
        self:_updateCompactReadout(value, previousValue, targetChange, noChange, infinityText, hasNoHistory)
    else
        self:_updateFullReadouts(value, previousValue, targetChange, noChange, infinityText, hasNoHistory)
    end
end

function Statistic:ResetBaseline(newBaseline)
    local previousValue = self.value
    local hasNoHistory = not self._hasValue
    local baseline = if typeof(newBaseline) == "number" then newBaseline else self.value
    self._initialValue = baseline
    self.value = baseline
    self._hasValue = true
    self._lastChange = 0

    -- change readout drops back to 0; the value readout follows the new baseline
    if self.compact then
        if self.display == "change" then
            self.readoutOdo:snap(self:_formatChange(0))
        else
            self:_showValue(self.readoutOdo, baseline, previousValue, hasNoHistory)
        end
    else
        self.changeOdo:snap(self:_formatChange(0))
        self:_showValue(self.valueOdo, baseline, previousValue, hasNoHistory)
    end

    self:_setAccent("neutral", 0)
end

function Statistic:_setShown(shown, animate)
    local w = self.window

    if self.compact then
        w:_reveal(
            self.main,
            { BackgroundTransparency = if shown then (self.window.theme.ElementTransparency or 0) else 1 },
            animate
        )
        w:_reveal(
            self.stroke,
            { Transparency = if shown then self.window.theme.ElementStrokeTransparency else 1 },
            animate
        )
        w:_reveal(self.card, { BackgroundTransparency = if shown then 0 else 1 }, animate)
        w:_reveal(self.title, { TextTransparency = if shown then 0 else 1 }, animate)
        if self.iconLabel then
            w:_reveal(self.iconLabel, { ImageTransparency = if shown then 0 else 1 }, animate)
        end
        self.readoutOdo:reveal(if shown then 0 else 1, animate)
        return
    end

    if shown then
        w:_revealCommon(self, animate)
        w:_reveal(self.gradientContainer, { BackgroundTransparency = 0 }, animate)
        w:_reveal(self.glow, { Transparency = 0.82 }, animate)
        self.valueOdo:reveal(0, animate)
        self.changeOdo:reveal(0, animate)
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.gradientContainer, { BackgroundTransparency = 1 }, animate)
        w:_reveal(self.glow, { Transparency = 1 }, animate)
        self.valueOdo:reveal(1, animate)
        self.changeOdo:reveal(1, animate)
    end
end

-- Room the compact card needs: padding + icon (and gap) if shown + title text + the gap
-- to the readout + the readout number itself. Lets a horizontal group wrap sensibly.
function Statistic:_minWidth()
    local w = 30 + 10 -- 15+15 card padding, 10 gap between title and readout
    if self.icon then
        w += 26 -- 20 icon + 6 gap
    end
    -- measure what actually renders: the title shows the translated string
    w += functions.textWidth(self.window.theme.Font, 16, locale.resolve(self.name))
    local readout = if self.display == "change" then self:_formatChange(0) else self:_formatValue(self.value)
    w += functions.textWidth(self.window.theme.Font, 17, readout)
    return w
end

moveable(Statistic)

return Statistic
]=====]

sources["components/statuscard"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A compact, collapsible multi-row status widget - live "Currently Doing / Dungeon / Phase /
-- Room / Enemies" style readouts, one line per row, packed close together (label, a dim dot,
-- then the value) rather than spread across the card the way Stat's own single title+value
-- layout is. Stat is built for one headline number with a trend; this is for several small,
-- frequently-updated facts about what a script is doing right now (an auto-farm's live state),
-- which a single Stat card or the floating HUD (one line, no room for more than a couple of
-- readouts before it gets unreadable) don't fit well.
--
-- Fixed-width by design (not full tab width like every other element) - it's meant to read as a
-- self-contained widget, and fits inside a row Group next to other compact elements for exactly
-- that reason (see group.luau's own compactCapable table).

local StatusCard = {}
StatusCard.__index = StatusCard
StatusCard.__type = "StatusCard"

local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local lockable = require(utility.lockable)
local constants = require(utility.constants)
local locale = require(utility.locale)
local log = require(utility.log)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

-- main's own UIPadding eats outerPad on every side - collapsed height is outerPad*2 +
-- headerRowHeight, NOT just one flat "header height" constant (that was the actual bug: an
-- arbitrary 30 that didn't leave room for the 14px padding above *and* below a 24px icon badge,
-- so the collapsed card came out shorter than its own header content and the icon visibly
-- poked out - live-caught, "quando fecha o icone fica pra fora").
local outerPad = 14
local headerRowHeight = 24 -- matches the icon badge's own height; title/chevron centre within it
local headerGap = 10 -- breathing room between the header and the first row, only present when expanded
local chevronInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
local heightInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)

local function keyOf(row)
    return row.key or row.Key or row.label or row.Label
end

function StatusCard.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Status",
        icon = properties.icon or properties.Icon,
        width = properties.width or properties.Width or 260,
        collapsible = if properties.collapsible ~= nil
            then properties.collapsible
            elseif properties.Collapsible ~= nil then properties.Collapsible
            else true,
        glow = if properties.glow ~= nil then properties.glow elseif properties.Glow ~= nil then properties.Glow else true,
        expanded = if properties.expanded ~= nil
            then properties.expanded
            elseif properties.Expanded ~= nil then properties.Expanded
            else true,

        _rows = {}, -- ordered list of { key, label, value, muted, frame, labelLabel, valueLabel }
    }, StatusCard)

    if not self.collapsible then
        self.expanded = true
    end

    local window = self.window

    self.main = window:Create("Frame", {
        Name = self.name,
        Size = UDim2.fromOffset(self.width, outerPad * 2 + headerRowHeight),
        BorderSizePixel = 0,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        Active = true, -- Devlog 7 fix - see Window:StyleElementBody's own comment on why

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = self.tab.tabPage,
    }, { BackgroundColor3 = "StatBackground", BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)

    if self.glow then
        self.shadow = window:CreateGlow(self.main, "AccentColor", 16, 1) -- In = 0.88
    end

    self.padding = window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, outerPad),
        PaddingRight = UDim.new(0, outerPad),
        PaddingTop = UDim.new(0, outerPad),
        PaddingBottom = UDim.new(0, outerPad),

        Parent = self.main,
    })

    -- Header: icon badge + title, chevron on the right if collapsible. Sized to headerRowHeight
    -- exactly (matches the icon badge's own 24px, the tallest thing in it) - main's own height
    -- accounts for this plus outerPad above *and* below explicitly (see _setHeight), so the
    -- collapsed card is never shorter than its own padding + header actually need.
    self.header = window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, headerRowHeight),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.main,
    })

    self.titleContainer = window:Create("Frame", {
        Size = UDim2.new(1, -20, 1, 0), -- leaves room for the chevron on the right
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.header,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 8),

        Parent = self.titleContainer,
    })

    if self.icon then
        -- A small tinted chip rather than a bare glyph - reads as a deliberate badge instead of
        -- a plain icon floating next to text, the same "accent chip" language a premium widget
        -- like this calls for.
        self.iconBadge = window:Create("Frame", {
            Size = UDim2.fromOffset(24, 24),
            BorderSizePixel = 0,
            LayoutOrder = 0,

            BackgroundTransparency = 1, -- In = 0.85

            Parent = self.titleContainer,
        }, { BackgroundColor3 = "AccentColor" })
        window:Create("UICorner", {
            CornerRadius = UDim.new(0, 7),
            Parent = self.iconBadge,
        })
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(14, 14),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.fromScale(0.5, 0.5),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.iconBadge,
        }, { ImageColor3 = "AccentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.titleContainer,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    if self.collapsible then
        self.chevron = window:Create("ImageLabel", {
            Image = constants.icons.chevron,
            Size = UDim2.fromOffset(12, 12),
            AnchorPoint = Vector2.new(1, 0.5),
            Position = UDim2.new(1, 0, 0.5, 0),
            Rotation = if self.expanded then 0 else 180,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,

            ImageTransparency = 1, -- In = 0.4

            Parent = self.header,
        }, { ImageColor3 = "ContentColor" })

        self.headerInteract = window:Create("TextButton", {
            BackgroundTransparency = 1,
            Size = UDim2.fromScale(1, 1),
            Text = "",

            Parent = self.header,
        })
        window:Connect(self.headerInteract.MouseButton1Click, function()
            hapticEngine.click()
            soundEngine.click()
            self:Toggle()
        end)
    end

    -- Content: clips so the collapse never shows a half-cut row, height tweens between 0 and
    -- rowsContainer's own real AbsoluteSize.Y - same shape collapsible.luau's own contentWrapper
    -- uses, for the same reason (see _setHeight below).
    self.contentWrapper = window:Create("Frame", {
        Position = UDim2.fromOffset(0, headerRowHeight),
        Size = UDim2.new(1, 0, 0, 0),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ClipsDescendants = true,

        Parent = self.main,
    })

    -- headerGap lives *inside* the clipped wrapper (not as a fixed offset outside it) so it
    -- collapses away to nothing along with the rows when hidden, instead of leaving a bare gap
    -- floating under the header with nothing below it.
    self.rowsContainer = window:Create("Frame", {
        Position = UDim2.fromOffset(0, headerGap),
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = self.contentWrapper,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Vertical,
        Padding = UDim.new(0, 6),

        Parent = self.rowsContainer,
    })

    local initialRows = properties.rows or properties.Rows or {}
    for _, row in initialRows do
        self:_buildRow(row)
    end

    if self.expanded then
        self:_setHeight(self:_contentHeight(), false)
    end

    window:ConnectFor(self, self.rowsContainer:GetPropertyChangedSignal("AbsoluteSize"), function()
        if self.expanded then
            self:_setHeight(self:_contentHeight(), true)
        end
    end)

    return self
end

-- contentWrapper's own target height when expanded: the gap down to the first row, plus every
-- row stacked (rowsContainer's real AbsoluteSize.Y already accounts for the rows' own padding).
function StatusCard:_contentHeight()
    return headerGap + self.rowsContainer.AbsoluteSize.Y
end

-- Drives contentWrapper's height AND main's own height together, exactly like Collapsible's own
-- _setHeight - confirmed live on this executor that AutomaticSize.Y on a parent doesn't reliably
-- follow a *tweened* child Size change, so main's height is driven explicitly here instead of
-- left on AutomaticSize. main's own height is outerPad on both sides of the header, PLUS
-- contentWrapper's current height - forgetting the padding here is exactly what made the
-- collapsed card shorter than its own header content (see outerPad's own comment above).
function StatusCard:_setHeight(targetContentHeight, animate)
    local contentSize = UDim2.new(1, 0, 0, targetContentHeight)
    local height = outerPad * 2 + headerRowHeight + targetContentHeight
    -- Inside a row Group, the row's own HorizontalFlex owns this card's width (Group:_wrapChild
    -- sets _widthManaged for exactly this) - rewriting it back to self.width on every expand/
    -- collapse is what left the card frozen at its own 260px next to a toggle that had stretched
    -- to fill the row, live-reported as "it stays a square and doesn't take the space it should".
    -- Keep whatever width it currently has in that case and only drive the height.
    local mainSize = if self._widthManaged
        then UDim2.new(self.main.Size.X.Scale, self.main.Size.X.Offset, 0, height)
        else UDim2.fromOffset(self.width, height)
    if animate then
        variables.tweenService:Create(self.contentWrapper, heightInfo, { Size = contentSize }):Play()
        variables.tweenService:Create(self.main, heightInfo, { Size = mainSize }):Play()
    else
        self.contentWrapper.Size = contentSize
        self.main.Size = mainSize
    end
end

function StatusCard:_buildRow(row)
    local window = self.window
    local key = keyOf(row)
    if not key then
        log.warn("Rayfield: a StatusCard row needs a `label` (or explicit `key`), skipping one on '" .. self.name .. "'.")
        return
    end

    local frame = window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        -- Roblox's real default SortOrder is Name (alphabetical), not LayoutOrder - rowsContainer's
        -- own UIListLayout sets SortOrder = LayoutOrder explicitly (see its own Create call
        -- below) specifically so this actually controls order instead of silently being ignored.
        LayoutOrder = #self._rows + 1,

        Parent = self.rowsContainer,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        Padding = UDim.new(0, 5),

        Parent = frame,
    })

    local labelLabel = window:Create("TextLabel", {
        Text = locale.t(row.label or row.Label or key),
        Size = UDim2.fromOffset(0, 14),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTransparency = 0.45, -- a fixed dim, not theme-tweened - a label is never the accent
        LayoutOrder = 0,

        Parent = frame,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    local dotLabel = window:Create("TextLabel", {
        Text = "\194\183", -- middle dot "·" (U+00B7)
        Size = UDim2.fromOffset(6, 14),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 13,
        TextTransparency = 0.6,
        LayoutOrder = 1,

        Parent = frame,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    local valueLabel = window:Create("TextLabel", {
        Text = tostring(row.value or row.Value or ""),
        Size = UDim2.fromOffset(0, 14),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 13,
        TextXAlignment = Enum.TextXAlignment.Left,
        FontFace = variables.brandFont(Enum.FontWeight.SemiBold),
        LayoutOrder = 2,

        Parent = frame,
    })
    self:_paintValue(valueLabel, row.muted or row.Muted or false)

    if not self.window.hidden then
        window:_reveal(labelLabel, { TextTransparency = 0.45 }, true)
        window:_reveal(dotLabel, { TextTransparency = 0.6 }, true)
        window:_reveal(valueLabel, { TextTransparency = 0 }, true)
    else
        labelLabel.TextTransparency = 0.45
        dotLabel.TextTransparency = 0.6
        valueLabel.TextTransparency = 0
    end

    table.insert(self._rows, {
        key = key,
        frame = frame,
        labelLabel = labelLabel,
        dotLabel = dotLabel,
        valueLabel = valueLabel,
        muted = row.muted or row.Muted or false,
    })
end

-- muted (e.g. "none"/"0"/an inactive readout) reads as a plain, unremarkable value; anything
-- else rides the live theme accent so a glance at the card tells you which lines actually matter
-- right now, the same "colour carries meaning" idea Stat's own accent follows.
function StatusCard:_paintValue(valueLabel, muted)
    if muted then
        valueLabel.TextColor3 = self.window.theme.PlaceholderColor
    else
        valueLabel.TextColor3 = self.window.theme.AccentColor
    end
end

function StatusCard:_findRow(key)
    for _, entry in self._rows do
        if entry.key == key then
            return entry
        end
    end
    return nil
end

-- Update one row's value (and optionally whether it reads as muted) by key. No-ops quietly on an
-- unknown key rather than throwing - a live readout calling this every tick shouldn't need to
-- guard against a key that hasn't been added yet.
function StatusCard:SetRow(key, value, muted)
    local entry = self:_findRow(key)
    if not entry then
        return
    end
    entry.valueLabel.Text = tostring(value)
    if muted ~= nil then
        entry.muted = muted
        self:_paintValue(entry.valueLabel, muted)
    end
end

-- Appends a new row (or inserts at `index`, matching MoveTo's own 1-based indexing) after
-- construction - a script whose readouts aren't all known up front (an auto-farm that only shows
-- "Chests ready" once it's actually found one, say) can grow the card instead of pre-declaring
-- every possible row hidden. Doesn't call _setHeight itself - adding/removing a row always
-- changes rowsContainer's own AbsoluteSize, and the constructor's own
-- GetPropertyChangedSignal("AbsoluteSize") listener already reacts to that; calling _setHeight
-- again here raced that same listener's own call (both landing a tween on the same instance
-- within the same frame, one interrupting the other) - live-caught as the card settling at the
-- wrong height after Add/Remove.
function StatusCard:AddRow(row, index)
    self:_buildRow(row)
    if index then
        local entry = self._rows[#self._rows]
        table.remove(self._rows, #self._rows)
        table.insert(self._rows, math.clamp(index, 1, #self._rows + 1), entry)
        -- re-sync every row's LayoutOrder to its new position - same reason _buildRow assigns
        -- one at all instead of leaving the Roblox default (see its own comment).
        for i, e in self._rows do
            e.frame.LayoutOrder = i
        end
    end
end

function StatusCard:RemoveRow(key)
    for i, entry in self._rows do
        if entry.key == key then
            self.window:DestroySubtree(entry.frame)
            table.remove(self._rows, i)
            return
        end
    end
end

-- Bulk replace: clears every existing row and rebuilds from `rows`, for a script that's easier
-- to write as "here's the whole current state" each update rather than a stream of SetRow calls.
-- Same "don't also call _setHeight here" reasoning as AddRow/RemoveRow above - the constructor's
-- own AbsoluteSize-changed listener reacts to the row-count change on its own. The one edge case
-- this leaves uncovered - a Set() whose new rows net the exact same total height as the old ones
-- (e.g. clearing to zero rows when there already were none) - never actually needs a resize
-- either, since nothing about the real height changed.
function StatusCard:Set(rows)
    for _, entry in self._rows do
        self.window:DestroySubtree(entry.frame)
    end
    table.clear(self._rows)
    for _, row in rows or {} do
        self:_buildRow(row)
    end
end

function StatusCard:SetExpanded(expanded)
    if not self.collapsible then
        return
    end
    expanded = expanded and true or false
    if expanded == self.expanded then
        return
    end
    self.expanded = expanded

    self:_setHeight(if expanded then self:_contentHeight() else 0, true)
    if self.chevron then
        variables.tweenService:Create(self.chevron, chevronInfo, { Rotation = if expanded then 0 else 180 }):Play()
    end
end

function StatusCard:Toggle()
    self:SetExpanded(not self.expanded)
end

-- What the card needs to still read properly, not the width it likes to be on its own. Returning
-- self.width (260) here made it demand more of a shared row than it actually needs - a toggle
-- beside it got squeezed or wrapped onto its own line. Row flex grows it back out from this
-- floor; standalone (not in a row) it still builds at self.width.
function StatusCard:_minWidth()
    return math.min(self.width, 180)
end

function StatusCard:_setShown(shown, animate)
    local w = self.window
    w:_reveal(self.main, { BackgroundTransparency = if shown then (w.theme.ElementTransparency or 0) else 1 }, animate)
    w:_reveal(self.stroke, { Transparency = if shown then w.theme.ElementStrokeTransparency else 1 }, animate)
    if self.shadow then
        w:_reveal(self.shadow, { Transparency = if shown then 0.88 else 1 }, animate)
    end
    if self.iconBadge then
        w:_reveal(self.iconBadge, { BackgroundTransparency = if shown then 0.85 else 1 }, animate)
    end
    if self.iconLabel then
        w:_reveal(self.iconLabel, { ImageTransparency = if shown then 0 else 1 }, animate)
    end
    w:_reveal(self.title, { TextTransparency = if shown then 0 else 1 }, animate)
    if self.chevron then
        w:_reveal(self.chevron, { ImageTransparency = if shown then 0.4 else 1 }, animate)
    end
    for _, entry in self._rows do
        w:_reveal(entry.labelLabel, { TextTransparency = if shown then 0.45 else 1 }, animate)
        w:_reveal(entry.dotLabel, { TextTransparency = if shown then 0.6 else 1 }, animate)
        w:_reveal(entry.valueLabel, { TextTransparency = if shown then 0 else 1 }, animate)
    end
end

-- Row values' TextColor3 is a plain assignment (AccentColor vs PlaceholderColor depends on each
-- row's own `muted` flag, which a single themeProperty binding can't express), so a live
-- Settings > Color theme swap needs telling explicitly here - everything else on the card
-- (ContentColor labels, the AccentColor icon badge/glow) already rides a themeProperty binding
-- and refreshes itself through the normal ChangeTheme loop.
function StatusCard:_refreshTheme()
    for _, entry in self._rows do
        self:_paintValue(entry.valueLabel, entry.muted)
    end
end

moveable(StatusCard)
lockable(StatusCard)

return StatusCard
]=====]

sources["components/tab"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Tab = {}
Tab.__index = Tab
Tab.__type = "Tab"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local locale = require(utility.locale)
local assignOrder = require(utility.ordering)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local search = require(script.Parent.search)
local tabSelector = require(script.Parent.tabSelector)

-- Walk a tab or group's children (groups nest) and tear each element down: drop its flag from
-- the window registry and disconnect every connection it owns, so nothing outlives the
-- instances we're about to destroy.
local function teardownElements(window, elements)
    for _, element in elements do
        if element.__type == "Group" then
            teardownElements(window, element.elements)
        else
            window:_unregisterControl(element)
        end

        -- persistent connections filed via window:ConnectFor
        if element.connections then
            for _, connection in element.connections do
                window:Disconnect(connection)
            end
            element.connections = nil
        end

        -- transient, self-managed connections that may still be live if removed mid-interaction
        if element._dragConnection then
            element._dragConnection:Disconnect()
            element._dragConnection = nil
        end
        if element._outsideClickConn then
            window:Disconnect(element._outsideClickConn)
            element._outsideClickConn = nil
        end
    end
end


local selectTweenInfo = TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local hoverTweenInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

function Tab.new(window, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
        name = properties.name or properties.Name,
        icon = properties.icon or properties.Icon,
        neglectSelector = properties.neglectSelector or properties.NeglectSelector or false,
        customOrder = properties.customOrder or properties.CustomOrder or 0,
        -- when true, controls on this tab default to not persisting to config (the settings tab)
        forgetState = properties.forgetState or properties.ForgetState or false,
        locked = properties.locked or properties.Locked or false,

        elements = {},
        connections = {}, -- tracked so Remove can drop them without waiting for Unload
    }, Tab)

    -- a tab needs at least one of a name or an icon to show in the selector
    assert(self.name or self.icon, "A tab needs a name or an icon.")

    if not self.neglectSelector then -- Allow for tabs to be hidden from the tab selector, for Rayfield Settings.
        -- Builds topbarItem/topbarItemInteract/topbarItemStroke/topbarItemShadow/
        -- topbarItemContainer/topbarItemIcon/topbarItemTitle - a row in Sidebar mode, a pill in
        -- Top mode. Ported from upstream Rayfield Gen2 1.2's own tabSelector.luau: each one owns
        -- and fades its own background/stroke/shadow on selection now (see _applyVisual below),
        -- not a single shared pill sliding between them.
        local sidebarTabs = self.window.tabsMode == "Sidebar"
        require(script.Parent.tabSelector).build(self, sidebarTabs)

        -- "New"/"updated" indicator - a small dot pinned to the icon's own top-right corner
        -- rather than a layout sibling, so it tracks the icon's own size for free instead of
        -- needing its own re-position pass every frame. Built hidden and always present when
        -- there's an icon to pin it to, so SetBadge can turn it on any time after the tab exists
        -- (e.g. a hub flagging "Priority System" as updated this patch) without a dev needing to
        -- predict that at CreateTab time.
        if self.topbarItemIcon then
            self.badgeDot = self.window:Create("Frame", {
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, 3, 0, -3),
                Size = UDim2.fromOffset(7, 7),
                BorderSizePixel = 0,
                ZIndex = 3, -- above the icon (2)
                Visible = properties.badge or properties.Badge or false,

                Parent = self.topbarItemIcon,
            }, { BackgroundColor3 = "AccentColor" })
            self.window:Create("UICorner", {
                CornerRadius = UDim.new(1, 0),
                Parent = self.badgeDot,
            })
        end

        -- flows after icon/title via topbarItemContainer's own UIListLayout - the position/
        -- anchor _buildLockIcon takes don't matter here, a list-managed child's Position is
        -- overridden by the layout regardless of what it's created with
        self.lockIcon = self.window:_buildLockIcon(self.topbarItemContainer)
        self:_applyLocked()
    end

    -- Tab Page
    self.tabPage = self.window:Create("ScrollingFrame", {
        Name = self.name,
        Size = UDim2.new(1, -20, 1, 0),
        Position = UDim2.new(0.5, 0, 0, 68),
        AnchorPoint = Vector2.new(0.5, 0.5),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        ScrollBarThickness = 0,
        ScrollingDirection = Enum.ScrollingDirection.Y,

        LayoutOrder = self.customOrder or 0,

        Parent = self.window.elements,
    })

    self.tabPageLayout = self.window:Create("UIListLayout", {
        Padding = UDim.new(0, 7),
        FillDirection = Enum.FillDirection.Vertical,
        VerticalAlignment = Enum.VerticalAlignment.Top,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.tabPage,
    })

    self.window:Create("UIPadding", {
        -- Devlog 7: the gap under the tab dock read as glued to it (13px measured live) -
        -- widened so the first section/element always gets real breathing room below the dock.
        PaddingTop = UDim.new(0, 22),
        PaddingBottom = UDim.new(0, 33),

        Parent = self.tabPage,
    })

    if not self.neglectSelector then
        table.insert(
            self.connections,
            self.window:Connect(self.topbarItemInteract.MouseButton1Click, function()
                if self.locked then
                    return
                end
                hapticEngine.click()
                soundEngine.click()
                self:Select()
            end)
        )

        table.insert(
            self.connections,
            self.window:Connect(self.topbarItemInteract.MouseEnter, function()
                if not self.window:_interactive() then
                    return -- window still revealing/hiding: dont light up mid-animation
                end
                if self.window.selectedTab ~= self then
                    self:_applyVisual("hover", hoverTweenInfo)
                end
            end)
        )

        table.insert(
            self.connections,
            self.window:Connect(self.topbarItemInteract.MouseLeave, function()
                if self.window.selectedTab ~= self then
                    self:_applyVisual("unselected", hoverTweenInfo)
                end
            end)
        )

    end

    -- Auto-select is handled by Window:CreateTab after insertion

    return self
end

-- Each row/pill owns and fades its own background/stroke/shadow now - ported from upstream
-- Rayfield Gen2 1.2's own tabSelector.applyVisual, ambient states table included. TabColor stays
-- the text/icon colour throughout (no contrast computation against a shared pill colour needed,
-- since there's no shared pill anymore).
function Tab:_applyVisual(stateName, tweenInfo)
    if self.neglectSelector or not self.topbarItem then
        return
    end

    local mode = if self.window.tabsMode == "Sidebar" then "sidebar" else "top"
    local states = tabSelector.states[mode]
    local state = states[stateName]
    if not state then
        return
    end

    -- locked reads as (at least) unselected-dim no matter which state was actually asked for -
    -- computed here rather than in a separate pass afterward, so there's only ever one tween per
    -- property instead of two racing each other.
    if self.locked and state.content < states.unselected.content then
        state = states.unselected
    end

    tabSelector.applyVisual(self, state, tweenInfo)
end

-- Show/hide the padlock and re-paint with whatever visual is already active, so the dim baked
-- into _applyVisual above takes effect immediately.
function Tab:_applyLocked()
    if self.lockIcon then
        self.lockIcon.Visible = self.locked
    end
    self:_applyVisual(if self.window.selectedTab == self then "selected" else "unselected")
end

function Tab:SetLocked(locked)
    locked = locked and true or false
    if locked == self.locked then
        return
    end
    self.locked = locked
    self:_applyLocked()
end

function Tab:Select(noAnimation)
    -- selecting a tab (e.g. via the settings action) leaves search: bring the strip back,
    -- but let the navigation below pick the page.
    if self.window._searching then
        search.close(self.window, { showTabs = true, jumpTo = false })
    end

    self.window.selectedTab = self
    self.window:_jumpTo(self.tabPage)

    -- Opening a tab is what "new"/"updated" is meant to track - clear the dot the moment the
    -- player actually looks, same as a notification badge on any other app. A dev wanting it to
    -- persist across visits can just call SetBadge(true) again afterward.
    self:SetBadge(false)

    -- noAnimation = initial selection, the pill is still hidden and the window reveal shows it.
    -- a dev calling Navigate/Select before the first Show() hits the same case even without
    -- passing it explicitly - a tween played now would resolve while main is invisible, so the
    -- icon it targets would just pop straight to its end state the moment the window appears
    local skipAnimation = noAnimation or not self.window:_interactive()

    if not self.neglectSelector and not skipAnimation then
        self:_applyVisual("selected", selectTweenInfo)
    end

    for _, tab in self.window.tabs do
        if tab ~= self.window.selectedTab then
            tab:Deselect(skipAnimation)
        end
    end

    if self ~= self.window.rfSettings and self.window.settingsAction and not skipAnimation then
        variables.tweenService
            :Create(
                self.window.settingsAction.iconLabel,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { ImageTransparency = 0.6 }
            )
            :Play()
    end
end

function Tab:Deselect(noAnimation)
    if not self.neglectSelector and not noAnimation then
        self:_applyVisual("unselected", selectTweenInfo)
    end
end

-- shared tail for every CreateX: track it, order it, and reveal it if the window is
-- already open. without this, elements added after Window:Show stay fully transparent.
function Tab:_register(element)
    table.insert(self.elements, element)
    assignOrder(element, #self.elements * 10)
    self.window:_restoreLate(element)

    if not self.window.hidden then
        element:_setShown(true, true)
    end

    return element
end

-- Button
function Tab:CreateButton(properties)
    return self:_register(require(script.Parent.button).new(self, properties))
end

-- Flip button: a two-faced Button whose title flips on hover
function Tab:CreateFlipButton(properties)
    return self:_register(require(script.Parent.flipbutton).new(self, properties))
end

-- Copy button: title left, a checkmark-swapping icon well right that copies to the clipboard
function Tab:CreateCopyButton(properties)
    return self:_register(require(script.Parent.copybutton).new(self, properties))
end

-- Ripple button: a Button whose press feedback is a ripple from the press point
function Tab:CreateRippleButton(properties)
    return self:_register(require(script.Parent.ripplebutton).new(self, properties))
end

-- Switch/Toggle
function Tab:CreateToggle(properties)
    return self:_register(require(script.Parent.toggle).new(self, properties))
end

function Tab:CreateSwitch(properties)
    return self:CreateToggle(properties)
end

-- Checkbox: a compact alternative to Toggle
function Tab:CreateCheckbox(properties)
    return self:_register(require(script.Parent.checkbox).new(self, properties))
end

-- Section
function Tab:CreateSection(properties)
    return self:_register(require(script.Parent.section).new(self, properties))
end

-- Label: a bare line of text, no card - for copy too slight for its own Paragraph
function Tab:CreateLabel(properties)
    return self:_register(require(script.Parent.label).new(self, properties))
end

-- Paragraph: a title + body card, for copy too long to hang off an element as a description
function Tab:CreateParagraph(properties)
    return self:_register(require(script.Parent.paragraph).new(self, properties))
end

-- Divider: a subtle rule (plain, captioned, or spacing-only) that splits a page into groups
-- without a full Section header
function Tab:CreateDivider(properties)
    return self:_register(require(script.Parent.divider).new(self, properties))
end

-- Stat
function Tab:CreateStat(properties)
    return self:_register(require(script.Parent.stat).new(self, properties))
end

-- Compact, collapsible multi-row status widget - see statuscard.luau's own header comment.
function Tab:CreateStatusCard(properties)
    return self:_register(require(script.Parent.statuscard).new(self, properties))
end

-- Slider
function Tab:CreateSlider(properties)
    return self:_register(require(script.Parent.slider).new(self, properties))
end

-- Dropdown
function Tab:CreateDropdown(properties)
    return self:_register(require(script.Parent.dropdown).new(self, properties))
end

-- Progress bar: read-only gradient fill + readout, animates on Set
function Tab:CreateProgressBar(properties)
    return self:_register(require(script.Parent.progressbar).new(self, properties))
end

-- A monospaced, self-scrolling block for code or log output. See console.luau's own header
-- comment. Ported from upstream Rayfield Gen2 1.2.
function Tab:CreateConsole(properties)
    return self:_register(require(script.Parent.console).new(self, properties))
end

-- Scroll hint: centred text + bouncing arrow, points further down a page
function Tab:CreateScrollHint(properties)
    return self:_register(require(script.Parent.scrollhint).new(self, properties))
end

-- Segmented picker: pill bar with a sliding indicator, segments can nest a couple of sub-options
function Tab:CreateSegmentedPicker(properties)
    return self:_register(require(script.Parent.segmentedpicker).new(self, properties))
end

-- Shimmer label: a big heading with a light band sweeping across the text on a loop
function Tab:CreateShimmerLabel(properties)
    return self:_register(require(script.Parent.shimmerlabel).new(self, properties))
end

-- Input
function Tab:CreateInput(properties)
    return self:_register(require(script.Parent.input).new(self, properties))
end

-- Keybind
function Tab:CreateKeybind(properties)
    return self:_register(require(script.Parent.keybind).new(self, properties))
end

-- Color picker
function Tab:CreateColorPicker(properties)
    return self:_register(require(script.Parent.colorpicker).new(self, properties))
end

-- Gradient picker: a collapsible stops-rail editor producing a real ColorSequence
function Tab:CreateGradientPicker(properties)
    return self:_register(require(script.Parent.gradientpicker).new(self, properties))
end

-- Group (layout container). A row that wraps by default; pass direction="column" for a
-- column. Nest a row of columns for a grid. Add elements via group:CreateX.
function Tab:CreateGroup(properties)
    return self:_register(require(script.Parent.group).new(self, properties))
end

-- Nested tab switcher - see tabbox.luau's own header comment. Routed through _register like any
-- other element (LayoutOrder among its siblings, late-add reveal if the window's already open) -
-- it has the same main/_setShown shape _register expects even though it carries no flag of its
-- own (each of its own pages' children register their own flags independently).
function Tab:CreateTabbox(properties)
    return self:_register(require(script.Parent.tabbox).new(self, properties))
end

-- Hold button: press-and-hold confirm, fill bar completes the callback only at 100%
function Tab:CreateHoldButton(properties)
    return self:_register(require(script.Parent.holdbutton).new(self, properties))
end

-- Collapsible section: a header that expands/collapses to reveal its own nested elements,
-- built via the same CreateX surface as a Tab or Group (collapsible:CreateToggle, etc).
function Tab:CreateCollapsible(properties)
    return self:_register(require(script.Parent.collapsible).new(self, properties))
end

-- Changelog / update log: a title + version/date header over a list of ADDED/FIXED/CHANGED/
-- REMOVED tagged entries. Static once built.
function Tab:CreateChangelog(properties)
    return self:_register(require(script.Parent.changelog).new(self, properties))
end

-- Spacer: an invisible gap with a configurable height, for custom breathing room between
-- elements/sections.
function Tab:CreateSpacer(properties)
    return self:_register(require(script.Parent.spacer).new(self, properties))
end

function Tab:_moveElement(element, targetIndex)
    local idx = table.find(self.elements, element)
    if not idx then
        return
    end
    table.remove(self.elements, idx)
    targetIndex = math.clamp(targetIndex, 1, #self.elements + 1)
    table.insert(self.elements, targetIndex, element)
    for i, el in self.elements do
        assignOrder(el, i * 10)
    end
end

-- Public wrapper - lets a consumer script (e.g. one adding its own control onto Rayfield's own
-- Window.rfSettings tab, alongside the built-in toggles) place it at a specific position instead
-- of always landing after everything the tab already had, which is all a plain CreateX call after
-- the fact can ever do.
function Tab:MoveElement(element, targetIndex: number)
    self:_moveElement(element, targetIndex)
end

-- Toggle the "new"/"updated" dot pinned to this tab's icon (see Tab.new). No-ops quietly on a
-- tab built without an icon - there's nowhere for the dot to attach - so a dev flagging several
-- tabs as updated after a patch doesn't need to special-case the icon-less ones.
function Tab:SetBadge(shown: boolean)
    if self.badgeDot then
        self.badgeDot.Visible = shown and true or false
    end
end

function Tab:Remove()
    local window = self.window

    -- search reparents elements into its results page; close it first so this tabs
    -- units go home before their page is destroyed under them
    if window._searching then
        search.close(window, { showTabs = true, jumpTo = window.selectedTab and window.selectedTab.tabPage })
    end

    local idx = table.find(window.tabs, self)
    if idx then
        table.remove(window.tabs, idx)
    end

    -- If this was the active tab, hand selection to the next visible tab
    if window.selectedTab == self then
        window.selectedTab = nil
        for _, tab in ipairs(window.tabs) do
            if not tab.neglectSelector then
                tab:Select()
                break
            end
        end
    end

    -- Tear every element down (flags + connections) so nothing points at, or fires on, what
    -- we're about to destroy. Groups nest, so walk their children too.
    teardownElements(window, self.elements)

    -- Tear down the UI; nil the refs so _applyVisual (which guards on self.topbarItem)
    -- no-ops instead of touching a destroyed instance.
    for _, connection in self.connections do
        window:Disconnect(connection)
    end
    self.connections = {}

    if self.topbarItem then
        window:DestroySubtree(self.topbarItem)
    end
    if self.tabPage then
        window:DestroySubtree(self.tabPage)
    end
    self.topbarItem = nil
    self.tabPage = nil
    self.elements = {}
end

return Tab
]=====]

sources["components/tabSection"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- A heading in the sidebar rail, grouping the tab rows under it. Same shape and props as the
-- section in a tab's element list, so a dev who has used one already knows this one. Ported
-- from upstream Rayfield Gen2 1.2's own Tab Sections feature.
--
-- The rail only exists in the sidebar layout, so this builds nothing under the top strip.

local TabSection = {}
TabSection.__index = TabSection
TabSection.__type = "TabSection"

local locale = require(script.Parent.Parent.utility.locale)
local log = require(script.Parent.Parent.utility.log)

-- Sections sit further in than the rows they label, so the heading reads as a heading rather
-- than a row that lost its pill. Rows inset by the sidebar's own row padding a side, these by
-- this.
local sectionInset = 20

-- What the heading becomes on a collapsed (icon-only) rail: a thin rule, inset to line up with
-- the icon rows rather than the wider heading text.
local collapsedInset = 15
local ruleHeight = 9 -- the rule itself is 1px, centred in this so it isn't glued to either row

-- Clearance above a section that follows something. The rail's own list spacing already
-- separates it from the row above; this is the extra that makes it read as a new group.
local spacingAbove = 6

-- And under every section, so the first row beneath it isn't sat tight against the heading.
local spacingBelow = 3

-- Whether anything is already sitting above this one in the rail. The settings tab never gets
-- a row, so it doesn't count, and a section that follows only another section still does.
local function anythingAbove(window)
    for _, tab in window.tabs do
        if not tab.neglectSelector then
            return true
        end
    end
    return #window.tabSections > 0
end

function TabSection.new(window, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
        name = properties.name or properties.Name or "Section",
        icon = properties.icon or properties.Icon,
    }, TabSection)

    -- the top strip has no rail to head, so there's nowhere to put this. say so once and hand
    -- back a handle that does nothing, rather than half-building something invisible.
    if window.tabsMode ~= "Sidebar" then
        if not window._warnedTabSection then
            window._warnedTabSection = true
            log.warn("Rayfield: Window:CreateSection needs the sidebar layout; it does nothing on the top strip.")
        end
        self.inert = true
        return self
    end

    -- height comes from the content and the padding, not a number picked to match them
    self.main = window:Create("Frame", {
        Name = self.name,
        Size = UDim2.new(1, -sectionInset * 2, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Visible = false, -- In = true

        Parent = window.tabList,
    })

    self.padding = window:Create("UIPadding", {
        PaddingTop = UDim.new(0, if anythingAbove(window) then spacingAbove else 0),
        PaddingBottom = UDim.new(0, spacingBelow),

        Parent = self.main,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        Padding = UDim.new(0, 6),
        SortOrder = Enum.SortOrder.LayoutOrder,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        VerticalAlignment = Enum.VerticalAlignment.Top,

        Parent = self.main,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            LayoutOrder = 0,

            -- Animation
            ImageTransparency = 1, -- In = 0.65

            Parent = self.main,
        }, { ImageColor3 = "ContentColor" })
    end

    -- Stands in for the heading once the rail collapses to icons - 24px of usable width is
    -- nowhere near enough for a readable label, but the grouping still has to read as a
    -- grouping, so it becomes a plain rule between the icon runs instead.
    self.rule = window:Create("Frame", {
        Name = "Rule",
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.new(1, 0, 0, 1),
        BorderSizePixel = 0,
        Visible = false,

        BackgroundTransparency = 1, -- In = 0.75

        Parent = self.main,
    }, { BackgroundColor3 = "SurfaceStroke" })

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),

        Size = UDim2.fromOffset(0, 15),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextYAlignment = Enum.TextYAlignment.Bottom,
        TextWrapped = true,
        LayoutOrder = 1,

        -- Animation
        TextTransparency = 1, -- In = 0.6

        Parent = self.main,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    return self
end

-- Fade with the rows around it. Visible is left alone here, the same way a row's is, so a
-- collapse can fade the rail out before it stops drawing it.
function TabSection:_setShown(shown, animate)
    if not self.main then
        return -- never built (top strip), or already removed
    end
    local w = self.window
    w:_reveal(self.title, { TextTransparency = if shown then 0.6 else 1 }, animate)
    if self.iconLabel then
        w:_reveal(self.iconLabel, { ImageTransparency = if shown then 0.65 else 1 }, animate)
    end
    if self.rule then
        w:_reveal(self.rule, { BackgroundTransparency = if shown then 0.75 else 1 }, animate)
    end
end

-- Swap between the full heading and the collapsed rule. Snaps, same as every other part of the
-- rail's own collapse (see tabSelector.setRowCollapsed).
function TabSection:_setCollapsed(collapsed: boolean)
    if not self.main then
        return
    end
    self.title.Visible = not collapsed
    if self.iconLabel then
        self.iconLabel.Visible = not collapsed
    end
    if self.rule then
        self.rule.Visible = collapsed
    end
    -- the rule wants the rail's own narrow width, the heading wants its reading inset
    local inset = if collapsed then collapsedInset else sectionInset
    self.main.Size = UDim2.new(1, -inset * 2, 0, if collapsed then ruleHeight else 0)
    self.main.AutomaticSize = if collapsed then Enum.AutomaticSize.None else Enum.AutomaticSize.Y
end

function TabSection:_setVisible(visible)
    if self.main then
        self.main.Visible = visible
    end
end

function TabSection:Remove()
    local index = table.find(self.window.tabSections, self)
    if index then
        table.remove(self.window.tabSections, index)
    end
    self.window:DestroySubtree(self.main)
    self.main = nil
end

return TabSection
]=====]

sources["components/tabSelector"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- The thing you click to change tab. A pill in the top strip, a row in the sidebar rail -
-- different shapes, same parts under the same names, so Tab drives either one without knowing
-- which it built. Both read TabBackground/TabStroke/TabColor, so a theme written for one
-- layout already fits the other. Ported from upstream Rayfield Gen2 1.2 (RF2-Sidebar.Window.
-- Sidebar.Options) - each row/pill owns and fades its own background/stroke/shadow, rather than
-- a shared external indicator sliding between them.

local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local functions = require(utility.functions)
local locale = require(utility.locale)

local tabSelector = {}

-- Sidebar row geometry, matching upstream's own layouts.luau numbers exactly.
tabSelector.layout = {
    rowHeight = 38,
    rowCornerRadius = 14,
    rowInset = 15,
    rowPadding = 10,
    rowContentSpacing = 6,
    rowIconSize = 20,
}

-- A tab needs a name or an icon, not both, so an icon rail has to have something to show for a
-- tab that only has a name. Its first letter stands in - the same thing an avatar or a
-- workspace switcher falls back to. utf8, not string.sub: a name can start with a multi-byte
-- character and half of one renders as nothing.
local function initialOf(name: string?): string
    if type(name) ~= "string" or name == "" then
        return "?"
    end
    local afterFirst = utf8.offset(name, 2)
    local first = if afterFirst then string.sub(name, 1, afterFirst - 1) else name
    return string.upper(first)
end

-- Transparencies per state. The gradients stay put; selection is only ever transparency. A
-- state with no shadow entry leaves the shadow alone, which is how the pill (which has none)
-- and the rail row (which does) share one apply path.
tabSelector.states = {
    top = {
        selected = { background = 0, stroke = 0, content = 0 },
        hover = { background = 0.4, stroke = 0.3, content = 0.3 },
        unselected = { background = 0.8, stroke = 0.65, content = 0.5 },
        hidden = { background = 1, stroke = 1, content = 1 },
    },
    -- the rail row sits on the window rather than on a strip, so its selected fill is lighter
    -- and an unselected row is bare text.
    sidebar = {
        selected = { background = 0.4, stroke = 0.5, content = 0, shadow = 0.8 },
        hover = { background = 0.7, stroke = 0.8, content = 0.3, shadow = 1 },
        unselected = { background = 1, stroke = 1, content = 0.5, shadow = 1 },
        hidden = { background = 1, stroke = 1, content = 1, shadow = 1 },
    },
}

-- Fill + stroke gradients, identical on both shapes. Split out so neither builder restates it.
local function addGradients(tab, host, stroke)
    tab.topbarItemGradient = tab.window:Create("UIGradient", {
        Rotation = 90,

        Parent = host,
    }, { Color = { "TabBackground", functions.toColorSequence } })

    tab.topbarItemStrokeGradient = tab.window:Create("UIGradient", {
        Rotation = 90,

        Parent = stroke,
    }, { Color = { "TabStroke", functions.toColorSequence } })
end

local function addContent(tab, iconSize, withInitial)
    -- stands in for the icon while the rail is collapsed; hidden the rest of the time. Only the
    -- rail ever collapses, so the pill has no use for one.
    if withInitial and not tab.icon then
        tab.topbarItemInitial = tab.window:Create("TextLabel", {
            Text = initialOf(tab.name),

            Size = UDim2.fromOffset(iconSize, iconSize),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            TextSize = iconSize - 4,
            TextXAlignment = Enum.TextXAlignment.Center,
            TextYAlignment = Enum.TextYAlignment.Center,
            Visible = false,

            -- Animation
            TextTransparency = 1, -- In = 0 / 0.5

            Parent = tab.topbarItemContainer,
        }, { TextColor3 = "TabColor", FontFace = "Font" })
    end

    if tab.icon then
        tab.topbarItemIcon = tab.window:Create("ImageLabel", {
            -- raw value: Create routes Image through image.resolve, which already handles
            -- numbers and rbxassetid strings (concat here would double the prefix)
            Image = tab.icon,

            Size = UDim2.fromOffset(iconSize, iconSize),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            ZIndex = 2, -- see topbarItemInteract for why this needs to be explicit

            -- Animation
            ImageTransparency = 1, -- In = 0 / 0.5

            Parent = tab.topbarItemContainer,
        }, { ImageColor3 = "TabColor" })
    end

    if tab.name then
        tab.topbarItemTitle = tab.window:Create("TextLabel", {
            Text = locale.t(tab.name), -- tab name

            Size = UDim2.fromOffset(0, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            TextSize = 16,
            AutomaticSize = Enum.AutomaticSize.XY,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
            LayoutOrder = 1,
            ZIndex = 2,

            -- Animation
            TextTransparency = 1, -- In = 0 / 0.5

            Parent = tab.topbarItemContainer,
        }, { TextColor3 = "TabColor", FontFace = "Font" })
    end
end

-- A pill in the horizontal strip: hugs its own content and grows with the label.
local function buildPill(tab)
    tab.topbarItem = tab.window:Create("Frame", {
        Name = tab.name,
        Size = UDim2.fromOffset(0, 34), -- min size, grows with content
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,

        -- Animation
        BackgroundTransparency = 1, -- In = 0 / 0.8
        Visible = false, -- In = true

        LayoutOrder = tab.customOrder or 0,

        Parent = tab.window.tabList,
    })

    tab.topbarItemInteract = tab.window:Create("TextButton", {
        Active = false,
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Text = "",
        TextTransparency = 1,
        -- explicit, above the shared indicator's old ZIndex 1: kept for anything that still
        -- reads this ZIndex convention elsewhere.
        ZIndex = 2,

        Parent = tab.topbarItem,
    })

    tab.window:Create("UICorner", {
        Parent = tab.topbarItem,
    }, { CornerRadius = "PillCornerRadius" })

    tab.topbarItemStroke = tab.window:Create("UIStroke", {
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Color = Color3.fromRGB(255, 255, 255),

        -- Animation
        Transparency = 1, -- In = 0 / 0.5

        Parent = tab.topbarItem,
    })

    addGradients(tab, tab.topbarItem, tab.topbarItemStroke)

    tab.topbarItemContainer = tab.window:Create("Frame", {
        Size = UDim2.fromOffset(0, 34),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = tab.topbarItem,
    })

    tab.window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 13),
        PaddingRight = UDim.new(0, 14),

        Parent = tab.topbarItemContainer,
    })

    tab.topbarItemLayout = tab.window:Create("UIListLayout", {
        Padding = UDim.new(0, 6),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = tab.topbarItemContainer,
    })

    addContent(tab, 16, false)
end

-- A row in the sidebar rail: the width of the rail, icon then label, left aligned.
local function buildRow(tab)
    local layout = tabSelector.layout

    tab.topbarItem = tab.window:Create("Frame", {
        Name = tab.name,
        Size = UDim2.new(1, -layout.rowInset * 2, 0, layout.rowHeight),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,

        -- Animation
        BackgroundTransparency = 1, -- In = 0.4 / 1
        Visible = false, -- In = true

        LayoutOrder = tab.customOrder or 0,

        Parent = tab.window.tabList,
    })

    tab.topbarItemInteract = tab.window:Create("TextButton", {
        Active = false,
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Text = "",
        TextTransparency = 1,

        Parent = tab.topbarItem,
    })

    tab.window:Create("UICorner", {
        CornerRadius = UDim.new(0, layout.rowCornerRadius),

        Parent = tab.topbarItem,
    })

    tab.topbarItemStroke = tab.window:Create("UIStroke", {
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        Color = Color3.fromRGB(255, 255, 255),

        -- Animation
        Transparency = 1, -- In = 0.5

        Parent = tab.topbarItem,
    })

    addGradients(tab, tab.topbarItem, tab.topbarItemStroke)

    -- lifts the selected row off the rail. Offset upward so the light reads as coming from
    -- above, the same direction the window's own shadow falls, and the spread pulls the glow
    -- wide and shallow so it hugs the row rather than pooling under it.
    tab.topbarItemShadow = tab.window:Create("UIShadow", {
        BlurRadius = UDim.new(0, 20),
        Color = Color3.fromRGB(255, 255, 255),
        Offset = UDim2.new(0, 0, 0, -15),
        Spread = UDim2.new(0, 10, 0, -30),
        ZIndex = -1,

        -- Animation
        Transparency = 1, -- In = 0.8

        Parent = tab.topbarItem,
    })

    tab.topbarItemContainer = tab.window:Create("Frame", {
        Size = UDim2.new(1, -layout.rowPadding, 0, 24),
        Position = UDim2.new(0, layout.rowPadding, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = tab.topbarItem,
    })

    tab.topbarItemLayout = tab.window:Create("UIListLayout", {
        Padding = UDim.new(0, layout.rowContentSpacing),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = tab.topbarItemContainer,
    })

    addContent(tab, layout.rowIconSize, true)
end

function tabSelector.build(tab, isSidebar: boolean)
    if isSidebar then
        buildRow(tab)
    else
        buildPill(tab)
    end
end

-- Drop the row's label so the rail reads as icons only, or put it back. Snaps rather than
-- tweens: this follows a window resize, which snaps too, so animating it would only ever trail
-- the edge it is meant to sit inside. Ported from upstream Rayfield Gen2 1.2.
function tabSelector.setRowCollapsed(tab, collapsed: boolean)
    if not tab.topbarItem or not tab.topbarItemContainer then
        return -- a pill (top strip) or a tab with no selector row at all
    end

    local layout = tabSelector.layout

    if tab.topbarItemTitle then
        tab.topbarItemTitle.Visible = not collapsed
    end
    -- a tab with no icon shows its initial in the icon's place, so the row is never blank
    if tab.topbarItemInitial then
        tab.topbarItemInitial.Visible = collapsed
    end

    local inset = if collapsed then 0 else layout.rowPadding
    tab.topbarItemContainer.Size = UDim2.new(1, -inset, 0, 24)
    tab.topbarItemContainer.Position = UDim2.new(0, inset, 0.5, 0)
    tab.topbarItemLayout.HorizontalAlignment = if collapsed
        then Enum.HorizontalAlignment.Center
        else Enum.HorizontalAlignment.Left
end

-- Apply one state's transparencies to whatever parts this selector actually has.
function tabSelector.applyVisual(tab, state, tweenInfo)
    local targets = {
        [tab.topbarItem] = { BackgroundTransparency = state.background },
        [tab.topbarItemStroke] = { Transparency = state.stroke },
    }

    if tab.topbarItemIcon then
        targets[tab.topbarItemIcon] = { ImageTransparency = state.content }
    end
    if tab.topbarItemTitle then
        targets[tab.topbarItemTitle] = { TextTransparency = state.content }
    end
    if tab.topbarItemInitial then
        targets[tab.topbarItemInitial] = { TextTransparency = state.content }
    end
    if tab.topbarItemShadow and state.shadow then
        targets[tab.topbarItemShadow] = { Transparency = state.shadow }
    end

    for instance, properties in targets do
        if tweenInfo then
            variables.tweenService:Create(instance, tweenInfo, properties):Play()
        else
            for property, value in properties do
                instance[property] = value
            end
        end
    end
end

return tabSelector
]=====]

sources["components/tabbox"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Nested tab switcher, usable inside a Tab or a Group - Fluent's own :AddTabbox(). Built for a
-- section with many parallel, similarly-shaped categories (a hub's own "Auto Farm Mob A/B/C",
-- say) where a flat list would just be one long scroll with no way to jump between categories.
--
-- Each page is a real Group instance (Vertical direction), built against a small fake "host"
-- table shaped like the Tab fields Group.new itself already reads (window/tabPage/direction/
-- forgetState - see group.luau's own header comment on this exact contract) - reuses every
-- CreateToggle/CreateButton/etc a page needs for free rather than reimplementing that machinery
-- a second time. Page switching is a plain Visible toggle (this is a small nested control, not
-- the window's own cross-fading UIPageLayout tab system - no reveal animation needed here).

local Tabbox = {}
Tabbox.__index = Tabbox
Tabbox.__type = "Tabbox"

local utility = script.Parent.Parent.utility
local assignOrder = require(utility.ordering)

local pillHeight = 26
local pillPadding = 4

function Tabbox.new(host, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        host = assert(host, "Missing argument #1 (Tab or Group expected)"),
        window = host.window,
        forgetState = host.forgetState,
        pages = {},
        selectedIndex = nil,
    }, Tabbox)

    local window = self.window

    self.main = window:Create("Frame", {
        Name = properties.name or properties.Name or "Tabbox",
        Size = UDim2.new(1, -20, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = host.tabPage,
    })

    -- children of a Group-hosted Tabbox share the row's flex the same way a nested Group does
    if host.direction == Enum.FillDirection.Horizontal then
        window:Create("UIFlexItem", { FlexMode = Enum.UIFlexMode.Fill, Parent = self.main })
    end

    self.pillRow = window:Create("ScrollingFrame", {
        Size = UDim2.new(1, 0, 0, pillHeight),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        AutomaticCanvasSize = Enum.AutomaticSize.X,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        ScrollingDirection = Enum.ScrollingDirection.X,
        ScrollBarThickness = 0,
        LayoutOrder = 1,

        Parent = self.main,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, pillPadding),

        Parent = self.pillRow,
    })

    self.pageContainer = window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 2,

        Parent = self.main,
    })

    window:Create("UIPadding", {
        PaddingTop = UDim.new(0, 8),
        Parent = self.pageContainer,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = self.main,
    })

    return self
end

function Tabbox:_selectIndex(index)
    if self.selectedIndex == index then
        return
    end
    self.selectedIndex = index
    for i, page in self.pages do
        local selected = i == index
        page.frame.Visible = selected
        local pill = page.pill
        pill.BackgroundColor3 = self.window.theme.AccentColor
        pill.BackgroundTransparency = if selected then 0.1 else 0.85
        pill.TextTransparency = if selected then 0 else 0.4
    end
end

-- One tab: a pill in the row + a page Group (direction "column") built against a fake Tab/Group
-- host so it gets every CreateX call for free. Returns the page (a real Group) directly - a dev
-- calls :CreateToggle/:CreateButton/etc on it exactly like any other Group.
function Tabbox:CreateTab(properties)
    properties = if typeof(properties) == "table" then properties else {}
    local name = properties.name or properties.Name or ("Tab " .. (#self.pages + 1))

    local pill = self.window:Create("TextButton", {
        Text = name,
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, pillHeight),
        BorderSizePixel = 0,
        TextSize = 13,
        Active = true,

        Parent = self.pillRow,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),
        Parent = pill,
    })
    self.window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 12),
        PaddingRight = UDim.new(0, 12),
        Parent = pill,
    })

    local pageFrame = self.window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Visible = false,

        Parent = self.pageContainer,
    })
    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 8),
        Parent = pageFrame,
    })

    -- fake host: exactly the fields Group.new itself reads off a Tab (see its own header
    -- comment) - window/tabPage/direction/forgetState. Vertical direction, same as any ordinary
    -- full-width column, so every element type builds normally inside a page.
    local fakeHost = {
        window = self.window,
        tabPage = pageFrame,
        direction = Enum.FillDirection.Vertical,
        forgetState = self.forgetState,
    }
    local page = require(script.Parent.group).new(fakeHost, { direction = "column" })
    page.frame = pageFrame
    page.pill = pill

    local index = #self.pages + 1
    table.insert(self.pages, page)
    assignOrder(page, index * 10)
    pill.LayoutOrder = index * 10

    self.window:Connect(pill.MouseButton1Click, function()
        self:_selectIndex(index)
    end)

    if index == 1 then
        self:_selectIndex(1)
    else
        pill.BackgroundColor3 = self.window.theme.AccentColor
        pill.BackgroundTransparency = 0.85
        pill.TextTransparency = 0.4
    end

    return page
end

-- forwards reveal/theme calls the same shape Group itself uses, so a Tabbox nested inside
-- another Group's reveal/theme pass reaches every page (and everything inside it)
function Tabbox:_setShown(shown, animate)
    for _, page in self.pages do
        page:_setShown(shown, animate)
    end
end

function Tabbox:_refreshTheme()
    for _, page in self.pages do
        if page._refreshTheme then
            page:_refreshTheme()
        end
    end
end

return Tabbox
]=====]

sources["components/tag"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Tag = {}
Tag.__index = Tag
Tag.__type = "Tag"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local image = require(utility.image)

local defaultColor = Color3.fromRGB(255, 175, 15)
local setTweenInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

function Tag.new(window, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
        text = properties.text or properties.Text or properties.title or properties.Title,
        icon = properties.icon or properties.Icon,
        color = properties.color or properties.Color or defaultColor,
    }, Tag)

    assert(self.icon or (self.text and self.text ~= ""), "A Tag requires an icon, text, or both.")

    self.main = self.window:Create("Frame", {
        Name = "Tag",
        Size = UDim2.fromOffset(10, 24),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundColor3 = self.color,
        BorderSizePixel = 0,
        LayoutOrder = properties.order or properties.Order or 0,

        -- Animation
        BackgroundTransparency = 1, -- In = 0

        Parent = self.window.tagContainer,
    })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),

        Parent = self.main,
    })

    self.window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 10),
        PaddingRight = UDim.new(0, 10),

        Parent = self.main,
    })

    self.window:Create("UIListLayout", {
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.main,
    })

    local contrast = functions.contrastColor(self.color)

    self.iconLabel = self.window:Create("ImageLabel", {
        Name = "Icon",
        Image = self.icon or "",
        ImageColor3 = contrast,
        Size = UDim2.fromOffset(16, 16),
        BackgroundTransparency = 1,
        Visible = self.icon ~= nil,
        ZIndex = 5,

        -- Animation
        ImageTransparency = 1, -- In = 0

        Parent = self.main,
    })

    self.title = self.window:Create("TextLabel", {
        Name = "Title",
        AnchorPoint = Vector2.new(0, 0.5),
        Size = UDim2.fromOffset(10, 15),
        AutomaticSize = Enum.AutomaticSize.X,
        BackgroundTransparency = 1,
        Text = self.text or "",
        TextColor3 = contrast,
        TextSize = 15,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        RichText = true,
        Visible = self.text ~= nil and self.text ~= "",
        LayoutOrder = 1,
        ZIndex = 5,

        -- Animation
        TextTransparency = 1, -- In = 0

        Parent = self.main,
    }, { FontFace = "Font" })

    self.window.tagContainer.Visible = true

    -- if the window's already up, fade in now; otherwise its show handles it
    if not self.window.hidden then
        self:_setShown(true, setTweenInfo)
    end

    return self
end

-- animate is a boolean like every other element's _setShown, or a TweenInfo when a caller
-- (the window's show/hide) wants its own timing. true uses the tag's default fade.
function Tag:_setShown(shown, animate)
    local target = if shown then 0 else 1
    local info = if typeof(animate) == "TweenInfo" then animate elseif animate then setTweenInfo else nil
    if info then
        variables.tweenService:Create(self.main, info, { BackgroundTransparency = target }):Play()
        variables.tweenService:Create(self.iconLabel, info, { ImageTransparency = target }):Play()
        variables.tweenService:Create(self.title, info, { TextTransparency = target }):Play()
    else
        self.main.BackgroundTransparency = target
        self.iconLabel.ImageTransparency = target
        self.title.TextTransparency = target
    end
end

function Tag:SetColor(color)
    self.color = color
    local contrast = functions.contrastColor(color)
    variables.tweenService:Create(self.main, setTweenInfo, { BackgroundColor3 = color }):Play()
    variables.tweenService:Create(self.iconLabel, setTweenInfo, { ImageColor3 = contrast }):Play()
    variables.tweenService:Create(self.title, setTweenInfo, { TextColor3 = contrast }):Play()
end

function Tag:SetText(text)
    self.text = text
    self.title.Text = text or ""
    self.title.Visible = text ~= nil and text ~= ""
end

function Tag:SetIcon(icon)
    self.icon = icon
    image.assign(self.iconLabel, "Image", icon)
    self.iconLabel.Visible = icon ~= nil
end

function Tag:Set(properties)
    if properties.color or properties.Color then
        self:SetColor(properties.color or properties.Color)
    end
    if properties.text or properties.Text or properties.title or properties.Title then
        self:SetText(properties.text or properties.Text or properties.title or properties.Title)
    end
    if properties.icon ~= nil or properties.Icon ~= nil then
        self:SetIcon(properties.icon or properties.Icon)
    end
end

function Tag:Remove()
    -- through the window so the tracked instances and theme entries go with it
    self.window:DestroySubtree(self.main)
    local idx = table.find(self.window.tags, self)
    if idx then
        table.remove(self.window.tags, idx)
    end
    if #self.window.tags == 0 then
        self.window.tagContainer.Visible = false
    end
end

return Tag
]=====]

sources["components/toast"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Toast = {}
Toast.__index = Toast
Toast.__type = "Toast"

-- Utility
local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local functions = require(utility.functions)
local constants = require(utility.constants)
local image = require(utility.image)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)

-- Timings (Exponential Out, matching the notification feel).
local slideInfo = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- entry travel
local growInfo = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- slot open/close
local fadeLong = TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- fill + stroke
local fadeShort = TweenInfo.new(0.3, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- content + shadow
local shrinkInfo = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out) -- exit scale

local iconSize = 24 -- a glyph icon
local avatarSize = 32 -- a user headshot (matches the old "signed in as" card)
local leftPadding = 18 -- inside the pill, before the icon/text
local rightPadding = 18 -- trailing room after the text
-- the avatar (profile-chip) variant sits its headshot closer to the edge like the old card
-- and gives the text extra trailing room
local avatarLeftPadding = 10
local avatarRightPadding = 28
local iconGap = 12 -- icon to text
local stackPadding = 8 -- gap between stacked toasts (lives inside each, so it collapses on exit)
local MIN_WIDTH, MAX_WIDTH = 140, 320

-- how far above its slot the pill starts, so it flies in from off the top of the screen
local offscreenAbove = UDim2.new(0.5, 0, 0.5, -180)
local offscreenBelow = UDim2.new(0.5, 0, 0.5, 180)
local centred = UDim2.new(0.5, 0, 0.5, 0)

-- Auto duration from the text length, clamped to a sensible window (matches notifications).
local function autoDuration(text)
    return math.clamp(#text * 0.05 + 3, 3, 8)
end

-- Accept a bare asset id (number) or any ready image string (rbxassetid/rbxthumb/http).
local function resolveImage(icon)
    if type(icon) == "number" then
        return "rbxassetid://" .. tostring(icon)
    end
    return icon
end

function Toast.new(window, properties, container)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        window = assert(window, "Missing argument #1 (Window expected)"),
        title = properties.title or properties.Title or "",
        subtitle = properties.subtitle or properties.Subtitle,
        icon = properties.icon or properties.Icon,
        -- a user id: shows that user's headshot as a larger, edge-hugging avatar (the profile
        -- chip look). takes precedence over icon.
        avatar = properties.avatar or properties.Avatar,
        -- floor the pill width (content is left-aligned, so the slack becomes right-hand room);
        -- the welcome toast uses this to match the old license card, others just hug
        minWidth = properties.minWidth or properties.MinWidth,
        -- put the subtitle line above the title (for label-over-value toasts like "Signed in
        -- as" / name); default is the usual title-on-top
        subtitleAbove = properties.subtitleAbove or properties.SubtitleAbove or false,
        position = properties.position or "Top",
        -- optional trailing pill button - { text, callback }. Runs the callback (guarded, same
        -- as every other element's) then dismisses the toast, the usual "Undo" snackbar shape.
        action = properties.action or properties.Action,
        _hovered = false,
        _overAction = false,
        _dismissed = false,
    }, Toast)

    self.duration = properties.duration or properties.Duration or autoDuration(self.title .. (self.subtitle or ""))

    -- an avatar is a bigger, edge-hugging headshot with roomier trailing padding; a plain icon
    -- is the compact glyph. these drive both the build below and _measure.
    local hasAvatar = self.avatar ~= nil and self.avatar ~= 0
    local hasIcon = hasAvatar or (self.icon ~= nil and self.icon ~= 0 and self.icon ~= "")
    -- headshots resolve to a local getcustomasset file in secure mode, fetched async - so it may
    -- land after the toast builds, hence the onReady that fills the icon in once it's ready
    self._iconImage = if hasAvatar
        then image.avatar(self.avatar, function(uri)
            -- a slow fetch can land after the toast is gone; dont write to a dead label
            if self.iconLabel and not self._dismissed and self.main.Parent then
                image.assign(self.iconLabel, "Image", uri)
            end
        end)
        elseif hasIcon then resolveImage(self.icon)
        else nil
    self._iconSize = if hasAvatar then avatarSize else iconSize
    self._leftPad = if hasAvatar then avatarLeftPadding else leftPadding
    self._rightPad = if hasAvatar then avatarRightPadding else rightPadding
    self._minWidth = math.max(self.minWidth or 0, MIN_WIDTH)
    local hasSubtitle = self.subtitle ~= nil and self.subtitle ~= ""

    -- Outer frame: the stack item. Invisible; only its height animates (open the slot on
    -- entry, collapse it on exit so neighbours slide up into the gap).
    self.main = self.window:Create("Frame", {
        Name = "Toast",
        BackgroundTransparency = 1,
        Size = UDim2.new(0, 0, 0, 0),
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.toast,

        Parent = container or self.window.toasts,
    })

    -- inter-toast gap lives here (not on the stack layout) so it collapses with the card
    self.window:Create("UIPadding", {
        PaddingTop = UDim.new(0, stackPadding),

        Parent = self.main,
    })

    -- Inner body: the visible pill. Centred so the exit width-shrink pulls in symmetrically.
    self.body = self.window:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        Size = UDim2.new(1, 0, 1, 0),
        Position = if self.position == "Bottom" then offscreenBelow else offscreenAbove,
        AnchorPoint = Vector2.new(0.5, 0.5),
        Active = true, -- takes clicks for click-to-dismiss
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.toast,

        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    })

    self.window:Create("UIGradient", {
        Rotation = 270,
        Offset = Vector2.new(0, -0.1),

        Parent = self.body,
    }, { Color = { "WindowColor", functions.toColorSequence } })

    self.window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),

        Parent = self.body,
    })

    self.stroke = self.window:Create("UIStroke", {
        Transparency = 1, -- In = 0.9

        Parent = self.body,
    }, { Color = "SurfaceStroke" })

    self.shadow = self.window:CreateGlow(self.body, "ShadowColor", 20, 1) -- In = 0.6

    self.window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, self._leftPad),
        PaddingRight = UDim.new(0, self._rightPad),

        Parent = self.body,
    })

    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, iconGap),

        Parent = self.body,
    })

    if hasIcon then
        -- glyph icons follow the theme's content colour; an avatar headshot stays untinted so the
        -- photo isn't recoloured. circular to suit both
        self.iconLabel = self.window:Create("ImageLabel", {
            Image = self._iconImage,
            Size = UDim2.fromOffset(self._iconSize, self._iconSize),
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            BorderSizePixel = 0,
            LayoutOrder = 1,
            ZIndex = constants.zIndex.toastContent,

            BackgroundTransparency = 1, -- In = 0.95 (a faint plate behind avatars)
            ImageTransparency = 1, -- In = 0

            Parent = self.body,
        }, if hasAvatar then nil else { ImageColor3 = "ContentColor" })

        self.window:Create("UICorner", {
            CornerRadius = UDim.new(1, 0),

            Parent = self.iconLabel,
        })
    end

    -- text column hugs its content; the body's AutomaticSize is off (we tween its width) so
    -- this fixed height keeps the row centred
    self.container = self.window:Create("Frame", {
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, hasSubtitle and 32 or 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 2,
        ZIndex = constants.zIndex.toastContent,

        Parent = self.body,
    })

    self.window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 1),

        Parent = self.container,
    })

    -- the semibold title rides the theme so it tracks secure mode's brand swap and a dev's
    -- fallbackFont; the measure below reads the same key so the hug-width always matches
    self.titleLabel = self.window:Create("TextLabel", {
        Text = self.title,
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, 16),
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = if self.subtitleAbove then 2 else 1,
        ZIndex = constants.zIndex.toastContent,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    if hasSubtitle then
        self.subtitleLabel = self.window:Create("TextLabel", {
            Text = self.subtitle,
            AutomaticSize = Enum.AutomaticSize.X,
            Size = UDim2.fromOffset(0, 14),
            BackgroundTransparency = 1,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            LayoutOrder = if self.subtitleAbove then 1 else 2,
            ZIndex = constants.zIndex.toastContent,

            TextTransparency = 1, -- In = 0.5

            Parent = self.container,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })
    end

    if self.action and self.action.text and self.action.text ~= "" then
        -- Small accent pill, same colour pair popup.luau's own "primary" button style uses
        -- (AccentColor fill / AccentStroke edge) - reads as the one thing on the toast that's
        -- actually a button, not just decoration, without introducing a third button style.
        self.actionButton = self.window:Create("TextButton", {
            Text = self.action.text,
            AutomaticSize = Enum.AutomaticSize.X,
            Size = UDim2.fromOffset(0, 22),
            BorderSizePixel = 0,
            TextSize = 13,
            LayoutOrder = 3,
            Active = true,
            ZIndex = constants.zIndex.toastContent,

            BackgroundTransparency = 1, -- In = 0.1
            TextTransparency = 1, -- In = 0

            Parent = self.body,
        }, { BackgroundColor3 = "AccentColor", TextColor3 = "ContentColor", FontFace = "Font" })

        self.window:Create("UICorner", {
            CornerRadius = UDim.new(1, 0),
            Parent = self.actionButton,
        })

        self.window:Create("UIPadding", {
            PaddingLeft = UDim.new(0, 12),
            PaddingRight = UDim.new(0, 12),
            Parent = self.actionButton,
        })
    end

    -- Newest on top: the container is top-anchored, so a smaller LayoutOrder sorts higher.
    self.window._toastCount = (self.window._toastCount or 0) + 1
    self.main.LayoutOrder = -self.window._toastCount

    self._connections = {
        self.window:Connect(self.body.MouseEnter, function()
            self._hovered = true
        end),
        self.window:Connect(self.body.MouseLeave, function()
            self._hovered = false
        end),
        -- InputBegan hit-tests the whole body, action button included - without this guard,
        -- pressing the button would ALSO fire the body's own click-to-dismiss underneath it at
        -- the same input, dismissing before (or instead of) the action's own callback ran.
        -- Mirrors the same MouseEnter/MouseLeave hover-tracking pattern _hovered above already
        -- uses, just scoped to the button's own bounds.
        self.window:Connect(self.body.InputBegan, function(input)
            if self._overAction then
                return
            end
            if
                input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch
            then
                self:_dismiss()
            end
        end),
    }

    if self.actionButton then
        table.insert(
            self._connections,
            self.window:Connect(self.actionButton.MouseEnter, function()
                self._overAction = true
            end)
        )
        table.insert(
            self._connections,
            self.window:Connect(self.actionButton.MouseLeave, function()
                self._overAction = false
            end)
        )
        table.insert(
            self._connections,
            self.window:Connect(self.actionButton.MouseButton1Click, function()
                hapticEngine.click()
                soundEngine.click()
                self.window:_runGuarded(self, self.action.callback)
                self:_dismiss()
            end)
        )
    end

    task.spawn(function()
        self:_show()
    end)

    return self
end

-- Width the pill needs to hug its content, measured without rendering so it grows into place
-- rather than snapping wide first. Height is fixed by line count (icon dictates the minimum).
function Toast:_measure()
    local titleWidth = functions.textWidth(self.window.theme.TitleFont, 16, self.title)
    local subtitleWidth = if self.subtitleLabel
        then functions.textWidth(self.window.theme.Font, 14, self.subtitle)
        else 0
    local textWidth = math.max(titleWidth, subtitleWidth)

    -- action pill's own hug-width: 12px padding either side of its text, same font/size the
    -- button itself uses, plus the row's own iconGap to separate it from the text column.
    local actionWidth = if self.actionButton
        then iconGap + 12 + functions.textWidth(self.window.theme.Font, 13, self.action.text) + 12
        else 0

    local left = if self.iconLabel then self._leftPad + self._iconSize + iconGap else self._leftPad
    local width = math.clamp(left + textWidth + actionWidth + self._rightPad, self._minWidth, MAX_WIDTH)

    local textHeight = if self.subtitleLabel then 16 + 1 + 14 else 16
    local height = math.max(textHeight, if self.iconLabel then self._iconSize else 0) + 18

    return width, height
end

-- Enter: open the slot to full height while the pill drops in from above and fades, staggering
-- the content the way a notification does.
function Toast:_show()
    if not self.main.Parent then
        return
    end

    hapticEngine.notify()
    soundEngine.notify()

    local width, height = self:_measure()
    self.main.Size = UDim2.new(0, width, 0, 0)

    -- +stackPadding because the outer's top padding holds the inter-toast gap
    variables.tweenService:Create(self.main, growInfo, { Size = UDim2.new(0, width, 0, height + stackPadding) }):Play()
    variables.tweenService:Create(self.body, slideInfo, { Position = centred }):Play()
    variables.tweenService:Create(self.body, fadeLong, { BackgroundTransparency = 0 }):Play()
    variables.tweenService:Create(self.stroke, fadeLong, { Transparency = 0.9 }):Play()
    variables.tweenService:Create(self.shadow, fadeShort, { Transparency = 0.6 }):Play()
    variables.tweenService:Create(self.titleLabel, fadeShort, { TextTransparency = 0 }):Play()
    if self.actionButton then
        variables.tweenService:Create(self.actionButton, fadeShort, { BackgroundTransparency = 0.1, TextTransparency = 0 }):Play()
    end

    task.wait(0.05)
    if self._dismissed or not self.main.Parent then
        return -- dismissed mid-stagger; dont fight the exit fade
    end
    if self.iconLabel then
        variables.tweenService:Create(self.iconLabel, fadeShort, { BackgroundTransparency = 0.95 }):Play()
        variables.tweenService:Create(self.iconLabel, fadeShort, { ImageTransparency = 0 }):Play()
    end

    task.wait(0.05)
    if self._dismissed or not self.main.Parent then
        return
    end
    if self.subtitleLabel then
        variables.tweenService:Create(self.subtitleLabel, fadeShort, { TextTransparency = 0.5 }):Play()
    end

    -- Dwell, pausing while hovered.
    local elapsed = 0
    while elapsed < self.duration and not self._dismissed and self.main.Parent do
        local dt = task.wait()
        if not self._hovered then
            elapsed += dt
        end
    end

    self:_dismiss()
end

-- Exit: fade out while the pill shrinks (width + height collapse) - the notification exit.
function Toast:_dismiss()
    if self._dismissed then
        return
    end
    self._dismissed = true

    if not self.main.Parent then
        return
    end

    variables.tweenService:Create(self.body, fadeLong, { BackgroundTransparency = 1 }):Play()
    variables.tweenService:Create(self.stroke, fadeLong, { Transparency = 1 }):Play()
    variables.tweenService:Create(self.shadow, fadeShort, { Transparency = 1 }):Play()
    variables.tweenService:Create(self.titleLabel, fadeShort, { TextTransparency = 1 }):Play()
    if self.subtitleLabel then
        variables.tweenService:Create(self.subtitleLabel, fadeShort, { TextTransparency = 1 }):Play()
    end
    if self.actionButton then
        variables.tweenService:Create(self.actionButton, fadeShort, { BackgroundTransparency = 1, TextTransparency = 1 }):Play()
    end
    if self.iconLabel then
        variables.tweenService
            :Create(self.iconLabel, fadeShort, { ImageTransparency = 1, BackgroundTransparency = 1 })
            :Play()
    end

    variables.tweenService:Create(self.body, shrinkInfo, { Size = UDim2.new(1, -60, 1, 0) }):Play()
    local collapse =
        variables.tweenService:Create(self.main, shrinkInfo, { Size = UDim2.new(0, self.main.Size.X.Offset, 0, 0) })
    collapse:Play()
    collapse.Completed:Wait()

    if not self.main.Parent then
        return
    end

    for _, connection in self._connections do
        self.window:Disconnect(connection)
    end
    self.window:DestroySubtree(self.main)
end

return Toast
]=====]

sources["components/toggle"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local Toggle = {}
Toggle.__index = Toggle
Toggle.__type = "Toggle"

-- Utility
local utility = script.Parent.Parent.utility

-- Variables
local variables = require(utility.variables)
local functions = require(utility.functions)
local moveable = require(utility.moveable)
local locale = require(utility.locale)
local hapticEngine = require(utility.HapticEngine)
local soundEngine = require(utility.sound)
local log = require(utility.log)

local defaultLoopInterval = 0.5

function Toggle.new(tab, properties)
    properties = if typeof(properties) == "table" then properties else {}

    local self = setmetatable({
        tab = assert(tab, "Missing argument #1 (Tab expected)"),
        window = tab.window,
        name = properties.name or properties.Name or "Switch",
        icon = properties.icon or properties.Icon,
        description = properties.description or properties.Description,
        tooltip = properties.tooltip or properties.Tooltip,
        forgetState = properties.forgetState or properties.ForgetState or tab.forgetState, -- dont save config for this element if true.
        compact = tab.compact or false, -- true when the host is a Row
        locked = properties.locked or properties.Locked or false,

        flag = properties.flag
            or properties.Flag
            or (
                not (properties.forgetState or properties.ForgetState or tab.forgetState)
                    and functions.deriveFlagFromName(properties.name or properties.Name or "Switch")
                or nil
            ),

        callback = properties.callback or properties.Callback or function() end,

        value = if (properties.value or properties.Value) ~= nil then (properties.value or properties.Value) else false,
    }, Toggle)

    -- register as a saveable control if flagged (works in a row too)
    self.window:_registerControl(self)

    if self.compact then
        self:_buildCompact()
    else
        self:_buildFull()
    end

    -- centred on the switch pill itself (works for both the fixed-offset full layout and the
    -- flex-positioned compact one, since functionContainer's own position tracks either way)
    self.lockIcon = self.window:_buildLockIcon(self.functionContainer, UDim2.fromScale(0.5, 0.5), Vector2.new(0.5, 0.5))
    self.prohibitedIcon = self.window:_buildProhibitedIcon(self.container)
    self:_applyLocked(false)

    self.window:_wireTooltip(self)

    if self.description and not self.compact then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = self.description })
    end

    -- Loop() below uses task.spawn/task.wait, not a Window:Connect signal, so Window:Unload's
    -- own connection-teardown never reaches it on its own - this closes that gap unconditionally
    -- (cheap no-op on a toggle that never calls Loop at all).
    self.window:OnUnload(function()
        self:_stopLoop()
    end)

    return self
end

-- Runs `fn(toggle)` on a repeating timer for as long as this toggle is on - starts immediately
-- if it's already on when this is called (e.g. autoLoad already restored `true` before your
-- script gets a chance to call this), stops the moment it's turned off, and restarts fresh every
-- time it's turned back on. fn can return a number to wait before the next call instead of
-- `interval` (default 0.5s) - the same "return your own next-tick delay" shape a hand-rolled
-- `while` loop already uses in most feature scripts, just managed.
--
-- The point of this over a hand-rolled `while toggle.value do task.wait() ... end` in the
-- toggle's own callback: an uncaught error in a raw loop like that kills its coroutine silently
-- (task.spawn swallows it) with nothing to restart it and nothing telling the toggle it's now
-- lying about the feature's real state - exactly the "turn it on and it does nothing, or it runs
-- for a while then quietly stops" symptom a hand-rolled loop is prone to. Loop() below pcalls
-- every single iteration instead of the whole loop, so one bad tick logs a warning and tries
-- again next tick rather than ending the feature for the rest of the session.
function Toggle:Loop(fn: (toggle: any) -> number?, interval: number?)
    self._loopFn = fn
    self._loopInterval = interval or defaultLoopInterval
    if self.value then
        self:_startLoop()
    end
end

function Toggle:_startLoop()
    if self._loopRunning or not self._loopFn then
        return
    end
    self._loopRunning = true
    -- stamped so a stale iteration that's mid-task.wait when the loop is stopped (and possibly
    -- restarted before that wait resumes) can tell it's no longer the current run and exit
    -- instead of doubling up with the fresh one.
    self._loopGeneration = (self._loopGeneration or 0) + 1
    local generation = self._loopGeneration
    task.spawn(function()
        while self._loopRunning and self._loopGeneration == generation do
            local ok, result = pcall(self._loopFn, self)
            if not ok then
                log.warn("Rayfield: Toggle '" .. tostring(self.name) .. "' loop errored - " .. tostring(result))
            end
            if self._loopGeneration ~= generation then
                break -- stopped (or restarted) while fn itself was running
            end
            local delay = if ok and typeof(result) == "number" then result else self._loopInterval
            task.wait(math.max(delay, 0.03))
        end
    end)
end

function Toggle:_stopLoop()
    self._loopRunning = false
    self._loopGeneration = (self._loopGeneration or 0) + 1
end

-- the pill switch. same in both layouts; caller places it (pinned right / flex item)
function Toggle:_buildSwitch(parent)
    local window = self.window

    self.functionContainer = window:Create("Frame", {
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(50, 21),

        BackgroundTransparency = 1, -- In = ToggleTrackTransparency

        Parent = parent,
    }, { BackgroundColor3 = "ToggleTrack" })

    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 15),
        Parent = self.functionContainer,
    })

    self.containerStroke = window:Create("UIStroke", {
        Transparency = 1, -- In = 0.85
        Parent = self.functionContainer,
    }, { Color = "SurfaceStroke" })

    self.indicator = window:Create("Frame", {
        BorderSizePixel = 0,
        Size = UDim2.fromOffset(25, 17),
        Position = self.value and UDim2.new(1, -28, 0.5, 0) or UDim2.new(1, -47, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundColor3 = self.value and self.window.theme.AccentColor or self.window.theme.ToggleKnobOff,

        BackgroundTransparency = 1, -- In = 0.8

        Parent = self.functionContainer,
    })

    window:Create("UICorner", {
        CornerRadius = UDim.new(1, 0),
        Parent = self.indicator,
    })

    self.indicatorStroke = window:Create("UIStroke", {
        Color = self.value and self.window.theme.AccentStroke or Color3.fromRGB(255, 255, 255),
        Transparency = 1, -- In = 0.7
        Parent = self.indicator,
    })

    -- Accent glow behind the selector; hidden until on (gated by Transparency: 1 hidden, AccentGlow shown)
    self.indicatorGlow = window:CreateGlow(self.indicator, "AccentColor", 20, 1)

    -- Dark wash over the switch for light themes (hidden on dark themes via DarkToggleOverlay).
    self.overlay = window:Create("Frame", {
        BorderSizePixel = 0,
        Size = UDim2.fromScale(1, 1),
        Position = UDim2.fromScale(0, 0),
        AnchorPoint = Vector2.new(0, 0),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1, -- In = 0

        Parent = self.functionContainer,
    }, { Visible = "DarkToggleOverlay" })

    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 15),
        Parent = self.overlay,
    })

    self.overlayGradient = window:Create("UIGradient", {
        Rotation = 90,
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(30, 30, 30)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(30, 30, 30)),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(1, 0.35),
        }),

        Parent = self.overlay,
    })

    return self.functionContainer
end

-- flip, animate, run callback (error-flash on fail), autosave. press anim is per-layout
-- Delegates to Set rather than duplicating its logic inline (this used to flip self.value,
-- animate, run the callback, and persist by hand, all separately from Set's own copy of the
-- same steps) - confirmed live that the duplication had actually drifted: a real click never
-- went through Set at all, so Toggle:Loop (which only hooks Set) silently never started or
-- stopped for an interactive toggle, only ever for a programmatic :Set() call. One path now,
-- so anything added to Set in the future reaches an interactive click for free too.
function Toggle:_performToggle()
    hapticEngine.click()
    soundEngine.click()
    self:Set(not self.value)
end

-- full-width: title/icon left, pill pinned right, width-bounce
function Toggle:_buildFull()
    local window = self.window

    self.main = window:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 41),
        BorderSizePixel = 0,
        Name = self.name,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),

        BackgroundTransparency = 1,

        Parent = self.tab.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    self.stroke = window:StyleElementBody(self.main)
    self.hoverOverlay = window:CreateHoverOverlay(self.main)

    self.container = window:Create("Frame", {
        BorderSizePixel = 0,

        Parent = self.main,
        Size = UDim2.new(0, 170, 0, 16),
        Position = UDim2.new(0, 20, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
    })

    self.containerLayout = window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(250, 16),
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        AutomaticSize = Enum.AutomaticSize.X,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextWrapped = true,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    self.interact = window:Create("TextButton", {
        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 1, 0),
        BorderSizePixel = 0,
        Position = UDim2.fromScale(1, 0.5),
        AnchorPoint = Vector2.new(1, 0.5),
        TextTransparency = 1,
        ZIndex = 10,

        Parent = self.main,
    })

    -- pill pinned to the right edge
    self:_buildSwitch(self.main)
    self.functionContainer.Position = UDim2.new(1, -15, 0, 20)
    self.functionContainer.AnchorPoint = Vector2.new(1, 0.5)

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        if self.locked then
            return
        end
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()
        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -26, 0, 41) }
            )
            :Play()

        self:_performToggle()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.main,
                TweenInfo.new(0.25, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { Size = UDim2.new(1, -20, 0, 41) }
            )
            :Play()
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

-- compact (row): title left, pill right (SpaceBetween)
function Toggle:_buildCompact()
    local window = self.window

    -- interact sits at ZIndex 10 so the switch pill layers cleanly over the row (see button.luau)
    self.main, self.stroke, self.interact = window:_buildCompactRow(self.tab, self.name, 10)
    self.hoverOverlay = self.interact

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 15),
        PaddingRight = UDim.new(0, 15),

        Parent = self.interact,
    })

    -- title left, pill right
    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,
        Padding = UDim.new(0, 10),

        Parent = self.interact,
    })

    self.container = window:Create("Frame", {
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, 16),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = 0,

        Parent = self.interact,
    })

    -- text gives up room to the pill when tight
    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.container,
    })

    window:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,

        Parent = self.container,
    })

    if self.icon then
        self.iconLabel = window:Create("ImageLabel", {
            Image = self.icon,
            Size = UDim2.fromOffset(16, 16),
            BorderSizePixel = 0,
            BackgroundTransparency = 1,
            LayoutOrder = 0,

            ImageTransparency = 1, -- In = 0

            Parent = self.container,
        }, { ImageColor3 = "ContentColor" })
    end

    self.title = window:Create("TextLabel", {
        Text = locale.t(self.name),
        Size = UDim2.fromOffset(0, 16),
        AutomaticSize = Enum.AutomaticSize.X,
        BorderSizePixel = 0,
        BackgroundTransparency = 1,
        TextSize = 16,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTruncate = Enum.TextTruncate.AtEnd,
        LayoutOrder = 1,

        TextTransparency = 1, -- In = 0

        Parent = self.container,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })

    -- grows to its text, shrinks + ellipsizes when tight
    window:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Shrink,
        Parent = self.title,
    })

    -- pill as the right-hand flex item
    self:_buildSwitch(self.interact)
    self.functionContainer.LayoutOrder = 1

    self.window:_wireElementHover(self)

    self.window:ConnectFor(self, self.interact.MouseButton1Click, function()
        if self.locked then
            return
        end
        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = 1 }
            )
            :Play()

        self:_performToggle()

        task.wait(0.11)

        variables.tweenService
            :Create(
                self.stroke,
                TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Transparency = self.window.theme.ElementStrokeTransparency }
            )
            :Play()
    end)
end

function Toggle:_applyLocked(animate)
    self.window:_applyLockedVisual(self, animate)
end

function Toggle:SetLocked(locked)
    locked = locked and true or false
    if locked == self.locked then
        return
    end
    self.locked = locked
    self:_applyLocked(true)
end

-- Lock/Unlock/IsLocked: the shared naming lockable.luau gives every other locking-capable
-- element (see that file's own header comment for why this one aliases straight into its own
-- SetLocked instead of using the mixin - Toggle already had its own padlock-icon dimming before
-- Element Locking was ported, and this keeps that look rather than adding a second scrim on
-- top of it). `reason` isn't supported here - only the elements using the mixin's own scrim
-- swap a description to show one.
function Toggle:Lock()
    self:SetLocked(true)
end
function Toggle:Unlock()
    self:SetLocked(false)
end
function Toggle:IsLocked(): boolean
    return self.locked == true
end

function Toggle:_animateIndicator()
    local info = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
    if self.indicatorGlow then
        variables.tweenService
            :Create(self.indicatorGlow, info, { Transparency = self.value and self.window.theme.AccentGlow or 1 })
            :Play()
    end
    if self.value then
        variables.tweenService
            :Create(self.indicator, info, {
                Position = UDim2.new(1, -28, 0.5, 0),
                BackgroundColor3 = self.window.theme.AccentColor,
                BackgroundTransparency = 0,
            })
            :Play()
        variables.tweenService
            :Create(self.indicatorStroke, info, { Color = self.window.theme.AccentStroke, Transparency = 0 })
            :Play()
    else
        variables.tweenService
            :Create(self.indicator, info, {
                Position = UDim2.new(1, -47, 0.5, 0),
                BackgroundColor3 = self.window.theme.ToggleKnobOff,
                BackgroundTransparency = self.window.theme.ToggleKnobOffTransparency,
            })
            :Play()
        variables.tweenService
            :Create(self.indicatorStroke, info, { Color = Color3.fromRGB(255, 255, 255), Transparency = 0.7 })
            :Play()
    end
end

local toggleReveal = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
-- glow delayed so it doesn't bleed through the fill fade-in on window open
local toggleGlowReveal = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out, 0, false, 0.35)
-- Live-caught: the knob (the actual on/off state - colour + position) faded in on the exact same
-- beat as the track it sits on, so a lit green knob could read as "there" before the track
-- underneath it had faded in enough to look like a real switch yet. A small delay - after the
-- track (toggleReveal, no delay) but before the glow (toggleGlowReveal, 0.35s) - puts the reveal
-- in the order it's actually built: track, then the knob sitting on it, then its glow.
local toggleStateReveal = TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out, 0, false, 0.12)

function Toggle:_setShown(shown, animate)
    local w = self.window
    if shown then
        w:_revealCommon(self, animate)
        -- carry the state colours here too, so revealing on a tab switch also picks up the theme
        w:_reveal(self.indicator, {
            BackgroundColor3 = self.value and w.theme.AccentColor or w.theme.ToggleKnobOff,
            BackgroundTransparency = self.value and 0 or w.theme.ToggleKnobOffTransparency,
        }, animate, toggleStateReveal)
        w:_reveal(self.indicatorStroke, {
            Color = self.value and w.theme.AccentStroke or Color3.fromRGB(255, 255, 255),
            Transparency = self.value and 0 or 0.7,
        }, animate, toggleStateReveal)
        w:_reveal(
            self.indicatorGlow,
            { Transparency = self.value and w.theme.AccentGlow or 1 },
            animate,
            toggleGlowReveal
        )
        w:_reveal(self.overlay, { BackgroundTransparency = 0 }, animate, toggleReveal)
        w:_reveal(self.containerStroke, { Transparency = 0.85 }, animate, toggleReveal)
        w:_reveal(
            self.functionContainer,
            { BackgroundTransparency = w.theme.ToggleTrackTransparency },
            animate,
            toggleReveal
        )
    else
        w:_hideCommon(self, animate)
        w:_reveal(self.indicator, { BackgroundTransparency = 1 }, animate, toggleReveal)
        w:_reveal(self.indicatorStroke, { Transparency = 1 }, animate, toggleReveal)
        w:_reveal(self.indicatorGlow, { Transparency = 1 }, animate, toggleGlowReveal)
        w:_reveal(self.overlay, { BackgroundTransparency = 1 }, animate, toggleReveal)
        w:_reveal(self.containerStroke, { Transparency = 1 }, animate, toggleReveal)
        w:_reveal(self.functionContainer, { BackgroundTransparency = 1 }, animate, toggleReveal)
    end
end

-- Re-apply the visuals that aren't plain themeProperties (the knob's state colour + the reveal
-- transparencies) so a runtime ChangeTheme reaches the switch. Called on the visible tab only.
function Toggle:_refreshTheme()
    local t = self.window.theme
    local info = TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local ts = variables.tweenService
    ts:Create(self.functionContainer, info, { BackgroundTransparency = t.ToggleTrackTransparency }):Play()
    ts:Create(self.indicator, info, {
        BackgroundColor3 = self.value and t.AccentColor or t.ToggleKnobOff,
        BackgroundTransparency = self.value and 0 or t.ToggleKnobOffTransparency,
    }):Play()
    ts:Create(self.indicatorStroke, info, {
        Color = self.value and t.AccentStroke or Color3.fromRGB(255, 255, 255),
    }):Play()
    if self.indicatorGlow then
        ts:Create(self.indicatorGlow, info, { Transparency = self.value and t.AccentGlow or 1 }):Play()
    end
end

-- Room the compact toggle needs: side padding + icon (and gap) if shown + title text
-- + the gap to the pill + the pill itself. Lets a horizontal group wrap sensibly.
function Toggle:_minWidth()
    local w = 30 + 10 + 50 -- 15+15 padding, 10 gap to pill, 50 pill
    if self.icon then
        w += 21 -- 16 icon + 5 gap
    end
    w += functions.textWidth(self.window.theme.Font, 16, self.name)
    return w
end

moveable(Toggle)

-- Live status line: like `description`, but meant to be updated repeatedly (an automation loop
-- reporting "12/48 claimed" every tick) rather than set once at creation. Reuses the same
-- descriptor slot description already uses - lazily creates one if this toggle didn't start with
-- a description, and reveals it immediately if the toggle's already on screen (a plain text swap
-- on an existing label, not a fresh element needing the tab's own reveal pass).
function Toggle:SetStatus(text)
    if self.compact then
        return -- no room for a status line in a row layout
    end
    if not self.descriptor then
        self.descriptor = require(script.Parent.descriptor).new(self.tab, { description = text })
        self.descriptor.main.LayoutOrder = self.main.LayoutOrder + 1
        if not self.window.hidden then
            self.window:_reveal(self.descriptor.titleLabel, { TextTransparency = 0.7 }, false)
        end
    else
        self.descriptor.description = text
        self.descriptor.titleLabel.Text = text
    end
end

function Toggle:Set(value, skipCallback)
    local changed = self.value ~= value
    self.value = value

    if changed then
        self:_animateIndicator()
        -- Loop is part of "what being on actually does", same as callback - a skipCallback Set
        -- (syncing the visual/value state without triggering side effects, e.g. the F9 shortcut
        -- keeping its own Settings toggle in sync) shouldn't start or stop the feature either.
        if self._loopFn and not skipCallback then
            if value then
                self:_startLoop()
            else
                self:_stopLoop()
            end
        end
    end

    -- fire even when unchanged: config load calls Set and relies on the callback to apply
    if not skipCallback then
        self.window:_runGuarded(self, self.callback, self.value)
        self.window:_persist(self) -- skipCallback means apply quietly, so dont autosave either
    end
end

return Toggle
]=====]

sources["components/tour"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Guided onboarding tour: a dev-supplied sequence of steps, each pointing at a real element
-- (whatever CreateToggle/CreateButton/etc handed back), played once automatically on a window's
-- first show (see Window:_firstShow's own tour block) and re-playable from Settings. Each step
-- gets a bright accent ring around its target plus a description bubble with Back/Next/Skip -
-- no true dim-with-cutout mask (a much heavier UI trick, and this project's own resize/drag work
-- this session is a long track record of how expensive getting screen-space math wrong is to
-- live-debug) - a dimmed backdrop plus a glowing ring around the real element already reads as
-- "look here" without needing to punch an actual hole in an overlay.
--
-- Cross-tab steps: a step's target can live on any tab, not just whichever one happens to be
-- open when the tour reaches it - findOwningTab below walks the target's own ancestry to find
-- which tab actually owns it and auto-Selects that tab first, so a dev writing a tour that spans
-- multiple tabs doesn't have to manually Select() before each block of steps just to keep the
-- ring pointed at something actually on screen.

local Tour = {}
Tour.__index = Tour
Tour.__type = "Tour"

local utility = script.Parent.Parent.utility
local variables = require(utility.variables)
local constants = require(utility.constants)
local locale = require(utility.locale)
local functions = require(utility.functions)

local fadeInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local moveInfo = TweenInfo.new(0.35, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local ringPad = 8 -- px the ring sits outside the target's own edges, each side
local bubbleGap = 14 -- px between the ring and the bubble
local bubbleWidth = 280

-- Walk up from a step's target to whichever of the window's tabs actually owns it, if any -
-- nil for a target that isn't parented under any tab's page at all (the floating HUD, a Popup,
-- window chrome itself), which just skips the auto-switch below and behaves exactly as before.
local function findOwningTab(window, target)
    if not target or not target.main then
        return nil
    end
    local instance = target.main
    while instance do
        for _, tab in window.tabs do
            if tab.tabPage == instance then
                return tab
            end
        end
        instance = instance.Parent
    end
    return nil
end

-- Force open any collapsed Collapsible section sitting between a step's target and its tab page,
-- so the ring never ends up pointing at something still hidden inside a closed one. Walks every
-- collapsible the window knows about (collapsible.luau's own window.collapsibles) and expands
-- (instantly, not the section's own animated toggle - popping a section open while the tour's own
-- dim/ring reveal is also animating in doesn't need two overlapping motions competing) any whose
-- content wrapper actually contains the target. Returns whether anything was actually expanded,
-- so the caller knows whether a settle frame is needed before trusting geometry off of it.
local function expandAncestors(window, target): boolean
    if not target or not target.main then
        return false
    end
    local expandedAny = false
    for _, collapsible in window.collapsibles or {} do
        if not collapsible.expanded and collapsible.contentWrapper then
            local ancestor = target.main
            while ancestor do
                if ancestor == collapsible.contentWrapper then
                    collapsible:SetExpanded(true, true)
                    expandedAny = true
                    break
                end
                ancestor = ancestor.Parent
            end
        end
    end
    return expandedAny
end

-- Scroll a tab's own scrolling page so a step's target actually sits inside the visible viewport
-- before the ring tries to point at it - most tab pages auto-grow past one screen, so a target
-- further down could still be off-screen even after the tab-switch/section-expand above land on
-- the right tab and section. Only moves the canvas when the target isn't already fully visible,
-- so revisiting a step whose target is already on screen doesn't cause a needless jump. Returns
-- whether it actually scrolled, for the same "does the caller need to wait a frame" reason as
-- expandAncestors above.
local function scrollIntoView(tab, target): boolean
    local tabPage = tab and tab.tabPage
    if not tabPage or not tabPage:IsA("ScrollingFrame") then
        return false
    end
    local viewTop = tabPage.AbsolutePosition.Y
    local viewBottom = viewTop + tabPage.AbsoluteSize.Y
    local targetTop = target.AbsolutePosition.Y
    local targetBottom = targetTop + target.AbsoluteSize.Y
    if targetTop >= viewTop and targetBottom <= viewBottom then
        return false
    end

    -- Centre the target in the viewport rather than just nudging it to the nearest edge - reads
    -- better with the ring's own padding/glow around it than the target sitting flush against
    -- the very top or bottom edge of the visible area.
    local canvasY = tabPage.CanvasPosition.Y + (targetTop - viewTop) - (tabPage.AbsoluteSize.Y - target.AbsoluteSize.Y) / 2
    -- Confirmed live: AutomaticCanvasSize doesn't keep CanvasSize itself readable - it stays
    -- whatever was explicitly set at construction (UDim2.new(0,0,0,0) here), never the computed
    -- content height, so clamping against it always clamped to 0 and silently ate every scroll.
    -- The tab page's own UIListLayout.AbsoluteContentSize is the real content height instead.
    local contentHeight = if tab.tabPageLayout then tab.tabPageLayout.AbsoluteContentSize.Y else tabPage.AbsoluteSize.Y
    local maxCanvasY = math.max(0, contentHeight - tabPage.AbsoluteSize.Y)
    tabPage.CanvasPosition = Vector2.new(tabPage.CanvasPosition.X, math.clamp(canvasY, 0, maxCanvasY))
    return true
end

local function insetOffset(window): Vector2
    -- same correction drag.luau/resize.luau already use: main/absolute screen-space offsets are
    -- shifted from AbsolutePosition by the gui inset even though the ScreenGui ignores it.
    local screenGui = window.screenGui
    if screenGui and screenGui.IgnoreGuiInset then
        return variables.guiService:GetGuiInset()
    end
    return Vector2.zero
end

function Tour.new(window)
    local self = setmetatable({
        window = window,
        active = false,
        steps = {},
        index = 0,
    }, Tour)

    local screenGui = window.screenGui

    self.dim = window:Create("Frame", {
        Name = "TourDim",
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(0, 0, 0),
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.tourDim,
        Active = true, -- swallows clicks to whatever's behind a step instead of leaking through
        Visible = false,

        BackgroundTransparency = 1, -- shown = 0.55

        Parent = screenGui,
    })

    self.ring = window:Create("Frame", {
        Name = "TourRing",
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.tourDim + 1,
        Visible = false,

        Parent = screenGui,
    })
    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 12),
        Parent = self.ring,
    })
    self.ringStroke = window:Create("UIStroke", {
        Thickness = 2,
        Transparency = 0,
        Parent = self.ring,
    }, { Color = "AccentColor" })
    self.ringGlow = window:CreateGlow(self.ring, "AccentColor", 18, 0.4)

    -- Bubble: same visual language as a toast pill (WindowColor gradient card), just a rectangle
    -- instead of a hug-width capsule since this holds a title + a full description + buttons.
    self.bubble = window:Create("Frame", {
        Name = "TourBubble",
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        Size = UDim2.fromOffset(bubbleWidth, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BorderSizePixel = 0,
        Active = true,
        ZIndex = constants.zIndex.tourBubble,
        Visible = false,

        Parent = screenGui,
    })

    window:Create("UIGradient", {
        Rotation = 270,
        Parent = self.bubble,
    }, { Color = { "WindowColor", functions.toColorSequence } })

    window:Create("UICorner", {
        CornerRadius = UDim.new(0, 16),
        Parent = self.bubble,
    })

    self.bubbleStroke = window:Create("UIStroke", {
        Thickness = 1,
        Parent = self.bubble,
    }, { Color = "SurfaceStroke", Transparency = "ElementStrokeTransparency" })

    self.bubbleShadow = window:CreateGlow(self.bubble, "ShadowColor", 20, 0.6)

    window:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 18),
        PaddingRight = UDim.new(0, 18),
        PaddingTop = UDim.new(0, 16),
        PaddingBottom = UDim.new(0, 16),
        Parent = self.bubble,
    })

    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 8),
        Parent = self.bubble,
    })

    self.progressLabel = window:Create("TextLabel", {
        Text = "",
        AutomaticSize = Enum.AutomaticSize.Y,
        Size = UDim2.new(1, 0, 0, 12),
        BackgroundTransparency = 1,
        TextSize = 12,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 1,
        ZIndex = constants.zIndex.tourBubble,
        Parent = self.bubble,
    }, { TextColor3 = "AccentColor", FontFace = "Font" })

    self.titleLabel = window:Create("TextLabel", {
        Text = "",
        AutomaticSize = Enum.AutomaticSize.Y,
        Size = UDim2.new(1, 0, 0, 18),
        BackgroundTransparency = 1,
        TextSize = 16,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 2,
        ZIndex = constants.zIndex.tourBubble,
        Parent = self.bubble,
    }, { TextColor3 = "ContentColor", FontFace = "TitleFont" })

    self.descriptionLabel = window:Create("TextLabel", {
        Text = "",
        AutomaticSize = Enum.AutomaticSize.Y,
        Size = UDim2.new(1, 0, 0, 14),
        BackgroundTransparency = 1,
        TextSize = 13,
        TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left,
        LayoutOrder = 3,
        ZIndex = constants.zIndex.tourBubble,
        Parent = self.bubble,
    }, { TextColor3 = "ContentColor", FontFace = "Font" })
    self.descriptionLabel.TextTransparency = 0.3

    self.buttonRow = window:Create("Frame", {
        Size = UDim2.new(1, 0, 0, 30),
        BackgroundTransparency = 1,
        LayoutOrder = 4,
        ZIndex = constants.zIndex.tourBubble,
        Parent = self.bubble,
    })
    window:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Right,
        Padding = UDim.new(0, 8),
        -- Roblox's real default here is Enum.SortOrder.Name, not LayoutOrder - this row happened
        -- to still read right with just Skip/Next (both plain unnamed TextButtons, so Name-sort's
        -- tie-break fell back to creation order, which matched anyway). Adding Back as a third
        -- button before them would be trusting that same luck a third time - explicit instead,
        -- same fix the player card needed for exactly this (see buildPlayerCard's own comment).
        SortOrder = Enum.SortOrder.LayoutOrder,
        Parent = self.buttonRow,
    })

    local function makeButton(order, primary)
        -- Window:Create applies themeProperties *first*, literal properties second - a literal
        -- BackgroundColor3 here would permanently win over the themed Accent/NeutralButton
        -- colour below instead of just seeding a start-state, the exact mistake this project's
        -- own tabDock background fix ran into earlier this session. No literal BackgroundColor3
        -- in this table at all; the theme binding is the only thing that ever sets it.
        local btn = window:Create("TextButton", {
            AutomaticSize = Enum.AutomaticSize.X,
            Size = UDim2.fromOffset(0, 28),
            BorderSizePixel = 0,
            Text = "",
            TextSize = 13,
            LayoutOrder = order,
            ZIndex = constants.zIndex.tourBubble,
            Parent = self.buttonRow,
        }, if primary
            then { BackgroundColor3 = "AccentColor", TextColor3 = "ContentColor", FontFace = "Font" }
            else { BackgroundColor3 = "NeutralButton", TextColor3 = "ContentColor", FontFace = "Font" })
        window:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = btn })
        window:Create("UIPadding", {
            PaddingLeft = UDim.new(0, 14),
            PaddingRight = UDim.new(0, 14),
            Parent = btn,
        })
        return btn
    end

    -- Back sits leftmost of the right-aligned cluster (Back / Skip / Next) - hidden on step 1
    -- (see :_show), since there's nothing behind the first step to go back to.
    self.backButton = makeButton(0, false)
    self.skipButton = makeButton(1, false)
    self.nextButton = makeButton(2, true)

    window:Connect(self.backButton.MouseButton1Click, function()
        self:_back()
    end)
    window:Connect(self.skipButton.MouseButton1Click, function()
        self:finish()
    end)
    window:Connect(self.nextButton.MouseButton1Click, function()
        self:_advance()
    end)

    return self
end

-- Position the ring around, and the bubble beside, whatever step.target currently is - called
-- once per step and again if the window itself moves/resizes mid-tour (see :_reposition).
function Tour:_layout()
    local step = self.steps[self.index]
    if not step or not step.target or not step.target.main then
        return
    end

    local target = step.target.main
    local abs = target.AbsolutePosition
    local size = target.AbsoluteSize
    local offset = insetOffset(self.window)

    local ringPos = abs - Vector2.new(ringPad, ringPad) + offset
    local ringSize = size + Vector2.new(ringPad * 2, ringPad * 2)
    self.ring.Position = UDim2.fromOffset(ringPos.X, ringPos.Y)
    self.ring.Size = UDim2.fromOffset(ringSize.X, ringSize.Y)

    -- Prefer sitting to the right of the target; flip to the left if that would run the bubble
    -- off the screen, same "flip if it doesn't fit" idea as a dropdown menu opening upward.
    local screen = self.window.screenGui.AbsoluteSize
    local spaceRight = screen.X - (ringPos.X + ringSize.X)
    local bubbleX = if spaceRight >= bubbleWidth + bubbleGap
        then ringPos.X + ringSize.X + bubbleGap
        else ringPos.X - bubbleWidth - bubbleGap
    local bubbleY = math.clamp(ringPos.Y, 10, math.max(10, screen.Y - 200))

    local targetPos = UDim2.fromOffset(bubbleX, bubbleY)
    if self.bubble.Visible then
        variables.tweenService:Create(self.bubble, moveInfo, { Position = targetPos }):Play()
    else
        self.bubble.Position = targetPos
    end
end

-- Shared by _advance/_back below - jumps straight to a given step index rather than only ever
-- stepping +/-1, so both directions (and a future "jump to step N" if one's ever needed) share
-- one path instead of duplicating the tab-switch/copy/layout logic per direction.
function Tour:_show(index: number)
    self.index = index
    local step = self.steps[self.index]
    if not step then
        self:finish()
        return
    end

    -- Auto-switch to whichever tab actually owns this step's target, if it isn't the one
    -- already open (see findOwningTab above), and force open any collapsed section standing
    -- between the target and its page (expandAncestors). task.wait() once after either: the
    -- new tab/section's layout needs a frame to actually settle before anything below - the
    -- scroll math, then _layout's own ring placement - trusts its AbsolutePosition/AbsoluteSize,
    -- the same "read geometry one frame late" rule the sidebar drag's own release handler
    -- already follows for the exact same reason.
    local owningTab = findOwningTab(self.window, step.target)
    local switched = false
    if owningTab and self.window.selectedTab ~= owningTab then
        owningTab:Select()
        switched = true
    end
    local expanded = expandAncestors(self.window, step.target)
    if switched or expanded then
        task.wait()
    end

    -- Scroll the target into view within its own tab's page, now that the right tab/section is
    -- actually showing. Same settle-then-trust-geometry reasoning if it actually had to move the
    -- canvas: _layout below reads the target's AbsolutePosition, which the scroll itself just
    -- changed.
    if owningTab and step.target and step.target.main and scrollIntoView(owningTab, step.target.main) then
        task.wait()
    end

    self.progressLabel.Text = string.format(locale.resolve("Step %d of %d"), self.index, #self.steps)
    self.titleLabel.Text = locale.resolve(step.title or "")
    self.descriptionLabel.Text = locale.resolve(step.description or "")
    self.nextButton.Text = if self.index == #self.steps then locale.resolve("Finish") else locale.resolve("Next")
    self.skipButton.Text = locale.resolve("Skip")
    self.backButton.Text = locale.resolve("Back")
    -- Nothing to go back to from the first step.
    self.backButton.Visible = self.index > 1

    self:_layout()

    self.ring.Visible = true
    self.bubble.Visible = true
end

function Tour:_advance()
    self:_show(self.index + 1)
end

-- Revisit the previous step - re-runs the same tab-switch/layout path _advance uses, just -1
-- instead of +1, so stepping back across a tour boundary lands back on the right tab too.
function Tour:_back()
    if self.index > 1 then
        self:_show(self.index - 1)
    end
end

-- Play a dev-supplied step list. steps = { { target, title, description }, ... } - target is
-- whatever CreateToggle/CreateButton/etc itself returned (anything with a .main).
function Tour:start(steps)
    if self.active or type(steps) ~= "table" or #steps == 0 then
        return
    end
    self.active = true
    self.steps = steps
    self.index = 0

    self.dim.Visible = true
    variables.tweenService:Create(self.dim, fadeInfo, { BackgroundTransparency = 0.55 }):Play()

    self:_advance()
end

function Tour:finish()
    if not self.active then
        return
    end
    self.active = false

    variables.tweenService:Create(self.dim, fadeInfo, { BackgroundTransparency = 1 }):Play()
    self.ring.Visible = false
    self.bubble.Visible = false
    task.delay(fadeInfo.Time, function()
        if not self.active then
            self.dim.Visible = false
        end
    end)

    if self.window.settings then
        self.window.settings.tourSeen = true
        self.window:SaveSettings()
    end
end

-- Re-run the layout math against wherever the current step's target is *now* - called if the
-- window itself moves/resizes mid-tour, so the ring doesn't drift off the element it's pointing
-- at. Cheap enough to just call unconditionally; it no-ops without an active step.
function Tour:reposition()
    if self.active and self.index >= 1 then
        self:_layout()
    end
end

return Tour
]=====]

sources["components/window"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Window.new lives here; every Window:X method lives in windowMethods.luau or windowExtra.luau
-- instead, split off once this file alone tripped Roblox's 200,000 character Source limit on a
-- ModuleScript (see windowCore.luau's own header comment for the full story and why a shared
-- core module, not a circular require, is what stitches the three back into one class). This
-- file requiring the other two at its own tail - after Window.new is fully defined, right before
-- returning - is what guarantees every method is attached before anyone holding the returned
-- Window table can ever call .new on it.

local core = require(script.Parent.windowCore)
local Window = core.Window

-- Utility (aliased off windowCore so every split file shares the exact same module instances -
-- see windowCore.luau's own header comment)
local image = core.image
local functions = core.functions
local persistence = core.persistence
local constants = core.constants
local locale = core.locale
local log = core.log
local hapticEngine = core.hapticEngine
local soundEngine = core.soundEngine
local windowSizing = core.windowSizing
local icons = core.icons
local acrylic = core.acrylic
local clipboard = core.clipboard
local chrome = core.chrome
local search = core.search
local filesystem = core.filesystem
local path = core.path
local squircle = core.squircle
local variables = core.variables
local themes = core.themes

-- Shared constants/helpers (see windowCore.luau)
local revealInfo = core.revealInfo
local collapsedSize = core.collapsedSize
local collapsedTop = core.collapsedTop
local maxToastWidth = core.maxToastWidth
local compactRowHeight = core.compactRowHeight
local viewportReconcileInterval = core.viewportReconcileInterval
local fitWindowSize = core.fitWindowSize
local resolveCustomSize = core.resolveCustomSize
local fontChoices = core.fontChoices
local fontOptionNames = core.fontOptionNames
local fontAtWeight = core.fontAtWeight
local gradientKeys = core.gradientKeys
local coerceThemeValue = core.coerceThemeValue
local firstColor = core.firstColor
local edgeShade = core.edgeShade
local deriveStrokes = core.deriveStrokes
local themeOverrides = core.themeOverrides
local resolveTheme = core.resolveTheme
local WINDOW_REGISTRY_KEY = core.WINDOW_REGISTRY_KEY
local windowRegistry = core.windowRegistry


function Window.new(properties)
    properties = if typeof(properties) == "table" then properties else {}

    -- Localization is global to the running UI: a dev translator (if any) and the active locale
    -- live on the locale module. Default the locale to the player's language unless the dev pins
    -- one. Set before any label is built so the first render is already in the right language.
    if properties.translations or properties.Translations then
        locale.register(properties.translations or properties.Translations)
    end
    if properties.translator or properties.Translator then
        locale.translator = properties.translator or properties.Translator
    end
    -- autoTranslate: live machine translation for every dev string, zero manual table-writing
    -- (see locale.resolve's own comment on where this sits in the resolution order). Only ever
    -- turns it ON here, same as translator above - a second window built without the property
    -- shouldn't silently disable what an earlier one already opted into.
    do
        local auto = properties.autoTranslate
        if auto == nil then
            auto = properties.AutoTranslate
        end
        if auto ~= nil then
            locale.autoTranslate = auto and true or false
        end
    end
    locale.setActive(properties.locale or properties.Locale or locale.detect())

    -- a dev can pick the stand-in font shown while the brand font downloads in secure mode; set it
    -- before resolveTheme below so the theme's brandFont picks it up
    local fallbackFont = properties.fallbackFont or properties.FallbackFont
    if fallbackFont then
        variables.setFallbackFont(fallbackFont)
    end

    local customSize = resolveCustomSize(properties.size or properties.Size)

    local self = setmetatable({
        name = properties.name or properties.Name or "Rayfield Window",
        subheading = properties.subtitle or properties.Subtitle,
        size = fitWindowSize(customSize),
        customSize = customSize,
        -- Devlog 8 corner grip: the dev-supplied/built-in size from construction, kept untouched
        -- by any later resize-grip drag so double-clicking the grip always has the *original*
        -- target to snap back to, not whatever the most recent drag happened to land on.
        defaultSize = customSize,
        fontChoice = "auto",
        windowOpacity = 1, -- Devlog 7 "window transparency": 1 = fully opaque (default)
        acrylicEnabled = false,
        instances = {},
        connections = {},

        icon = properties.icon or properties.Icon,
        showName = properties.showName or properties.ShowName or "Rayfield",
        showIcon = properties.showIcon or properties.ShowIcon or constants.icons.rayfield,

        -- "Loading animation": a dev-configured splash (icon/title/optional cycling tip text)
        -- played once on the very first Show(), before the window's own staged content reveal.
        -- Dev-only surface by design - present only if the dev opts in by passing `loading` at
        -- all, so the player's Settings toggle (added below, same conditional) only exists when
        -- there's actually something for it to turn on or off.
        loading = (function()
            local cfg = properties.loading or properties.Loading
            if not cfg then
                return nil
            end
            return {
                enabled = cfg.enabled ~= false and cfg.Enabled ~= false,
                icon = cfg.icon or cfg.Icon,
                title = cfg.title or cfg.Title,
                tips = cfg.tips or cfg.Tips or {},
                tipHoldTime = cfg.tipHoldTime or cfg.TipHoldTime or 0.9,
                duration = cfg.duration or cfg.Duration or 1.1,
            }
        end)(),

        -- Guided onboarding tour: a dev-supplied sequence of { target, title, description } steps
        -- (target is whatever CreateToggle/CreateButton/etc itself returned), played once
        -- automatically on the very first Show() - see _firstShow's own tour block - and
        -- re-playable from Settings. Dev-only surface, same reasoning as loading above: only
        -- present (and only shown in Settings) if the dev actually passed one.
        tourSteps = properties.tour or properties.Tour,

        -- Escape closes the window, on top of the normal toggle key - dev-set at CreateWindow
        -- (Fluent's own EnableEscapeToClose), not a player Settings toggle, since it's a fixed
        -- convention a dev opts an experience into rather than a per-player preference.
        escapeToClose = properties.escapeToClose or properties.EscapeToClose or false,

        themeProperties = {},
        localeProperties = {},
        tabs = {},
        -- Headings in the sidebar rail (Window:CreateSection, sidebar layout only - see
        -- tabSection.luau) grouping the tab rows created after them, ported from upstream
        -- Rayfield Gen2 1.2's own Tab Sections.
        tabSections = {},
        tags = {},
        selectedTab = nil,
        theme = resolveTheme(properties.theme or properties.Theme),

        controls = {},

        configuration = (function()
            local cfg = properties.configuration or properties.Configuration
            if not cfg then
                return {}
            end
            return {
                autoSave = cfg.autoSave or cfg.AutoSave,
                autoLoad = cfg.autoLoad or cfg.AutoLoad,
                fileName = cfg.fileName or cfg.FileName,
                customFolder = cfg.customFolder or cfg.CustomFolder,
                ignoreFlags = cfg.ignoreFlags or cfg.IgnoreFlags,
                scopeByPlace = cfg.scopeByPlace or cfg.ScopeByPlace,
            }
        end)(),
    }, Window)

    -- Direct per-window visual overrides (see WindowProps' own comment on each) - applied by
    -- mutating self.theme itself, right after it's resolved and before anything reads it to
    -- build, rather than poking instance properties after the fact. CornerRoundness/SurfaceStroke
    -- Color/WindowColor/ShadowColor are all already theme-bound properties every relevant
    -- instance picks up naturally through the normal binding path this way - no separate
    -- override step needed for those four. The rest (gradient rotation, border/shadow thickness,
    -- whether the border shows at all) aren't theme fields, just plain literals at their own
    -- construction sites below - stashed on self here so those sites can read them instead of a
    -- hardcoded number.
    --
    -- Stashed as fields, not just applied once here, so a later Window:ChangeTheme() call
    -- (including the player's own Settings "Color theme" dropdown) can re-apply them after it
    -- re-resolves self.theme from scratch - see Window:_applyThemeOverrides (windowMethods.luau),
    -- called right below and again from ChangeTheme itself. Previously documented as a known
    -- limitation that silently dropped these on any theme swap; this is the actual fix.
    self._cornerRadiusOverride = properties.cornerRadius or properties.CornerRadius
    self._borderColorOverride = properties.borderColor or properties.BorderColor
    self._gradientColorOverride = if (properties.gradient or properties.Gradient)
        then (properties.gradientColorSequence or properties.GradientColorSequence)
        else nil
    self._shadowColorOverride = properties.shadowColor or properties.ShadowColor
    self:_applyThemeOverrides()

    self._borderThickness = properties.borderThickness or properties.BorderThickness
    self._gradientRotation = properties.gradientRotation or properties.GradientRotation
    self._shadowBlur = properties.shadowThickness or properties.ShadowThickness
    self._shadowTransparency = properties.shadowTransparency or properties.ShadowTransparency
    self._rainbowBorder = properties.rainbowBorder or properties.RainbowBorder or false
    self._rainbowBorderSpeed = properties.rainbowBorderSpeed or properties.RainbowBorderSpeed or 0.14
    if self._rainbowBorder then
        self._showBorder = true
    end
    -- Squircle corners: the window body's own fill switches from a plain Frame+UICorner (a
    -- circular arc) to an image-based squircle (see utility/squircle.luau for what that actually
    -- means and why it can't just be an Instance property). Opt-in and scoped to the window body
    -- only for now, not every rounded corner in the library - see squircle.luau's own header for
    -- the reused-asset story, and self.main's construction below for what combining this with an
    -- explicit border color doesn't handle yet (the stroke still outlines a plain rounded rect,
    -- not the squircle curve).
    self._squircleCorners = properties.squircleCorners or properties.SquircleCorners or false
    -- The Settings tab's own "Session" card (player name/players online/uptime/FPS, refreshed
    -- every second - see _buildSessionDashboard) is on by default, but a hub that already shows
    -- most of that on its own Dashboard tab ends up with the same numbers twice, one click apart.
    self._showSessionDashboard = if properties.sessionDashboard ~= nil
        then properties.sessionDashboard
        elseif properties.SessionDashboard ~= nil then properties.SessionDashboard
        else true
    -- A consumer script that bakes self.theme.AccentColor into its own RichText (e.g. accentTag
    -- helpers like the hub template's own) has no way to hear about a later Settings > Color
    -- theme swap - ChangeTheme retints every Rayfield-built element on its own, but a plain
    -- TextLabel a dev built by hand with a literal <font color="..."> baked into its Text string
    -- is invisible to that. OnThemeChanged(callback) - see windowMethods.luau - gives it a hook to
    -- rebuild that text instead.
    self._themeChangedCallbacks = {}
    -- A consumer script that wants to persist a player's dragged sidebar width across sessions
    -- (see Window:RegisterFlag in windowExtra.luau) needs to hear about every real width change,
    -- not just the ones it made itself - OnSidebarWidthChanged (windowMethods.luau) is that hook.
    -- Fired from _applySidebarWidth itself so drag, SetSidebarWidth, and CreateTab's own
    -- re-application all reach it through the one funnel.
    self._sidebarWidthChangedCallbacks = {}
    -- Window:Unload() already tears down every instance/connection it owns on its own - this is
    -- for the part it has no way to know about: a consumer script's own state that needs
    -- resetting (stop a loop's flag, put the character back at spawn, drop a highlight) rather
    -- than just disconnected. Fired synchronously, before anything is torn down, so a callback
    -- can still safely read/use every instance the window built.
    self._unloadCallbacks = {}
    -- Settings > General toggles a hub can hide when it wants that behaviour pinned rather than
    -- player-adjustable (e.g. a "Welcome toast" a dev always wants on, or "Haptics"/"Sound
    -- Effects" it never wants on at all) - hiding the toggle doesn't itself change
    -- self.settings.X's own default, only whether a player can flip it from here.
    self._showWelcomeToastToggle = if properties.showWelcomeToastToggle ~= nil
        then properties.showWelcomeToastToggle
        elseif properties.ShowWelcomeToastToggle ~= nil then properties.ShowWelcomeToastToggle
        else true
    self._showHapticsToggle = if properties.showHapticsToggle ~= nil
        then properties.showHapticsToggle
        elseif properties.ShowHapticsToggle ~= nil then properties.ShowHapticsToggle
        else true
    self._showSoundEffectsToggle = if properties.showSoundEffectsToggle ~= nil
        then properties.showSoundEffectsToggle
        elseif properties.ShowSoundEffectsToggle ~= nil then properties.ShowSoundEffectsToggle
        else true
    self._showLoadingAnimationToggle = if properties.showLoadingAnimationToggle ~= nil
        then properties.showLoadingAnimationToggle
        elseif properties.ShowLoadingAnimationToggle ~= nil then properties.ShowLoadingAnimationToggle
        else true
    -- Opt-in (default false, unlike the toggles above) since this one is destructive rather
    -- than a preference - a "Destroy UI" hold-button in Settings that fully Unload()s the
    -- window. Off unless a dev explicitly wants players able to tear the whole thing down
    -- themselves (e.g. a hub that would rather a player fully close it than leave it running
    -- half-configured).
    self._showUnloadButton = properties.showUnloadButton or properties.ShowUnloadButton or false
    self.notifySide = properties.notifySide or properties.NotifySide or "Right"
    -- "Top" (default, everything this file always did) or "Sidebar" - a vertical tab list down
    -- the left edge instead of the horizontal strip under the header, for a section list too
    -- long to read comfortably as a single scrolling row of pills. Dev-only, set once at
    -- CreateWindow (Fluent's own TabsMode) - not a runtime/player Settings toggle, since
    -- switching layout live would mean re-deriving every position below from scratch anyway.
    self.tabsMode = properties.tabsMode or properties.TabsMode or "Top"
    -- The line under the player's name in the sidebar's profile chip ("Premium", a rank, a
    -- tier) - Sidebar tabsMode only, see the profile block built below. Ported from upstream
    -- Rayfield Gen2 1.2's own sidebar profile subtitle; nil means the name stands on its own.
    self.profileText = properties.profile or properties.Profile
    -- mobileHitScale: multiplies a handful of touch-target sizes (the window's own resize grip -
    -- see resize.luau's own gripSize - and the sidebar's resize grip below) when Window:IsMobile()
    -- reads true. Scoped to hit areas specifically rather than a full mobile/desktop pass over
    -- every button's size across the whole library - a much bigger retrofit than this pass.
    self.mobileHitScale = properties.mobileHitScale or properties.MobileHitScale or 1.4

    -- Public, always-live view of every saved control, keyed by flag. Reading returns the
    -- control's current value; assigning routes through its Set so the UI and callback fire.
    self.Flags = setmetatable({}, {
        __index = function(_, flag)
            local control = self.controls[flag]
            return control and control.value
        end,
        __newindex = function(_, flag, value)
            local control = self.controls[flag]
            if not control then
                log.warn("Rayfield: no flag '" .. tostring(flag) .. "' to set")
                return
            end
            control:Set(value)
        end,
        __iter = function()
            local flag
            return function()
                local control
                flag, control = next(self.controls, flag)
                if flag then
                    return flag, control.value
                end
                return nil
            end
        end,
    })

    -- Auto-unload a same-named window left over from an earlier run of this script (or an
    -- earlier reload) before building this one - see windowRegistry's own comment above. A dev
    -- who genuinely wants two windows open at once just gives them different names; nothing here
    -- fires unless a name collides with one still alive.
    do
        local registry = windowRegistry()
        local previous = registry[self.name]
        if previous and previous ~= self and previous.Unload then
            pcall(previous.Unload, previous)
        end
        registry[self.name] = self
    end

    -- A live translation lands async, well after resolve() already had to answer with a
    -- fallback (see locale.resolve's own comment) - this is how this window hears about it and
    -- re-applies (SetLocale already re-resolves every localeProperties entry in place, so a
    -- landed translation upgrades the exact labels showing the fallback, with no rebuild).
    -- Deregistered in Unload so a dead window's closure doesn't linger in locale's listener list.
    self._localeRefresh = function()
        if not self.unloaded then
            self:SetLocale(locale.current)
        end
    end
    locale.addListener(self._localeRefresh)

    -- Rayfield Gen2 Screen
    self.screenGui = self:Create("ScreenGui", {
        Name = variables.httpService:GenerateGUID(false),
        IgnoreGuiInset = true,
        ResetOnSpawn = false,
        Enabled = true,
        DisplayOrder = constants.displayOrder.window,
        ZIndexBehavior = Enum.ZIndexBehavior.Global,
        -- Roblox auto-translates plain Text/PlaceholderText on any descendant that hasn't set
        -- its own AutoLocalize, using its own generic crowd-sourced word list, entirely outside
        -- Rayfield's own locale system - live-caught this turning "Delete"/"Haptics" into
        -- "Excluir"/"Vibrar ao tocar" on a pt-BR client with nothing in locale.luau's own tables
        -- asking for that. AutoLocalize is inherited down the tree, so false here on the root
        -- covers every descendant that doesn't explicitly override it - which is everything
        -- Rayfield builds. locale.luau stays the only thing that ever translates this UI.
        AutoLocalize = false,

        Parent = variables.guiContainer,
    })

    -- Window
    self.main = self:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        Name = self.name,
        ZIndex = 1,
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, 0, 0.5, 0),
        -- Devlog 7 fix: without this, a plain Frame's default Active (false) means it stops
        -- blocking/capturing input in its own bounds the moment BackgroundTransparency actually
        -- reaches 1 - which SetTransparency(100) does on purpose now that this exists. Explicit
        -- Active = true keeps the window (and everything inside it) clickable at any
        -- transparency, glass or not.
        Active = true,
        -- Animations
        Size = UDim2.fromOffset((self.size.X.Offset - 50), 0),
        BackgroundTransparency = 1, -- In = 0
        Visible = false, -- In == true

        Parent = self.screenGui,
    })

    self.drag = require(script.Parent.drag).new(self)

    -- Squircle mode: no UICorner at all on self.main - it stays permanently transparent (see
    -- _mainVisual below, which is what every reveal/opacity call site now goes through instead
    -- of touching self.main.BackgroundTransparency directly) and a separate image-backed frame
    -- carries the actual fill, rounded by utility/squircle.luau instead of a circular arc.
    if self._squircleCorners then
        self.mainSquircle = self:Create("ImageLabel", {
            Name = "Squircle",
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ImageColor3 = Color3.fromRGB(255, 255, 255),
            ZIndex = 0, -- behind every real child of self.main, which all default to ZIndex 1+

            ImageTransparency = 1, -- In = 0, same reveal convention self.main's fill used to carry

            Parent = self.main,
        })
        squircle.apply(self.mainSquircle, self.theme.CornerRoundness.Offset)

        -- Border in squircle mode: a plain UIStroke (below) can only ever draw a straight-edged
        -- rectangle - it has no way to follow an image-based curve - which previously left a
        -- sharp-cornered outline sitting visibly outside this fill's own rounded corners whenever
        -- a dev combined squircleCorners with borderColor (documented as unhandled, never fixed
        -- until now). Fixed the same way a stroke gets faked behind any image-masked shape: a
        -- second copy of the exact same squircle image, tinted with the border colour, sized
        -- outward by the stroke thickness on every side and sitting behind the real fill - only
        -- the thin ring that pokes out past the fill's own edge ends up visible.
        if self._showBorder then
            local thickness = self._borderThickness or 1
            self.mainSquircleStroke = self:Create("ImageLabel", {
                Name = "SquircleStroke",
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.new(1, thickness * 2, 1, thickness * 2),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ZIndex = -1, -- behind the fill (ZIndex 0 on mainSquircle above)

                Parent = self.main,
            }, { ImageColor3 = "SurfaceStroke" })
            squircle.apply(self.mainSquircleStroke, self.theme.CornerRoundness.Offset + thickness)
        end
    else
        self.windowCorner = self:Create("UICorner", {

            Parent = self.main,
        }, { CornerRadius = "CornerRoundness" })
    end

    self.windowStroke = self:Create("UIStroke", {
        Thickness = self._borderThickness or 1,
        -- Live-caught reading this file: nothing else ever tweens this Transparency toward the
        -- "In = 0.95" the old comment here promised - it's never referenced anywhere past this
        -- one construction. Shown outright (0) when a dev explicitly asked for a border at all
        -- (self._showBorder, set alongside borderColor above) and squircle mode isn't drawing its
        -- own border instead (mainSquircleStroke above); otherwise left exactly as before,
        -- permanently at 1 (invisible), so this fix doesn't change anything for a window that
        -- never opted in.
        Transparency = if self._showBorder and not self._squircleCorners then 0 else 1,

        Parent = self.main,
    }, { Color = "SurfaceStroke" })

    -- Rainbow border: continuously cycles the stroke's own Color through the hue wheel instead
    -- of the themed SurfaceStroke it'd otherwise ride. Plain RenderStepped read/write, not a
    -- tween - there's no fixed destination color to tween toward, just a clock-driven hue that
    -- never stops moving. self.windowStroke.Parent guards the loop the same way shimmerlabel.luau's
    -- own shimmer loop guards on its gradient's Parent - it winds down on its own once the
    -- window's torn down, nothing else has to explicitly stop it.
    if self._rainbowBorder then
        self:Connect(variables.runService.RenderStepped, function()
            if not self.windowStroke.Parent then
                return
            end
            local hue = (os.clock() * self._rainbowBorderSpeed) % 1
            self.windowStroke.Color = Color3.fromHSV(hue, 1, 1)
        end)
    end

    self.windowGradient = self:Create("UIGradient", {
        Rotation = self._gradientRotation or 270,
        Offset = Vector2.new(0, -0.1),

        Parent = self.mainSquircle or self.main,
    }, { Color = { "WindowColor", functions.toColorSequence } })

    -- Bottom fade - gradient overlay so elements scroll out softly at the window's base
    self.bottomFade = self:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        AnchorPoint = Vector2.new(0, 1),
        Position = UDim2.fromScale(0, 1),
        Size = UDim2.new(1, 0, -0.093, 100),
        ZIndex = constants.zIndex.bottomFade,

        -- Animation
        BackgroundTransparency = 1, -- In = 0

        Parent = self.main,
    })

    self:Create("UICorner", {
        Parent = self.bottomFade,
    }, { CornerRadius = "CornerRoundness" })

    self.bottomFadeGradient = self:Create("UIGradient", {
        Rotation = 270,
        Offset = Vector2.new(0, 0.2),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0),
            NumberSequenceKeypoint.new(0.4414, 0),
            NumberSequenceKeypoint.new(0.7007, 0.631),
            NumberSequenceKeypoint.new(1, 1),
        }),

        Parent = self.bottomFade,
    }, {
        -- Track the window's colour at its base (keypoint 0 sits at the bottom under Rotation 270)
        -- so elements dissolve into the window instead of a fixed dark smudge on light themes.
        Color = {
            "WindowColor",
            function(color)
                return ColorSequence.new(functions.toColorSequence(color).Keypoints[1].Value)
            end,
        },
    })

    -- Top fade - same softening, mirrored: content scrolling up under the tab dock got a hard
    -- ClipsDescendants edge with nothing to ease it, while the bottom of that same list already
    -- dissolved gently into the window. Sits right at the tab dock's own bottom edge (65+38=103)
    -- rather than at main's literal top edge, since it's the content clip that needs softening,
    -- not the header/dock above it - no UICorner here, unlike bottomFade: this frame isn't
    -- sitting on any of main's own rounded corners.
    --
    -- First attempt copied bottomFade's Size formula wholesale (1, 0, -0.093, 100) without
    -- noticing the -0.093 *scale* term was there to make bottomFade shrink from the anchored
    -- bottom edge, not something to carry over - on a top anchor it added instead of subtracting,
    -- so this rendered at ~160px tall instead of a reasonable transition strip, eating a big
    -- chunk of actual content space. Second attempt overcorrected the other way - shrank it to
    -- 24px *and* swapped in a plain two-point linear fade, which at that size read as a visible
    -- cut/seam rather than a dissolve (that turned out to also be a colour mismatch against
    -- tabDock, not just size/curve - see topFadeGradient's own comment). 34px with
    -- bottomFadeGradient's own eased keypoint shape is the settled middle ground - small enough
    -- not to eat the content area, tall enough for that curve to still read as gradual.
    -- Sidebar mode has no such seam to hide in the first place - its dock runs down the left
    -- edge, not across the top, so content never scrolls "under" it the way Top mode's
    -- horizontal strip requires softening for. Left unconditional, this rendered anyway: a flat
    -- full-width dark band frozen at y=103 (Top mode's dock-to-content handoff point) that in
    -- Sidebar mode just cuts across the sidebar and content pane alike with nothing to justify
    -- it - the exact "bgl that's supposed to fade away doesn't fade away over here" seam the
    -- Sidebar layout was live-reported to show. Sized to nothing rather than skipped outright so
    -- every other reference to self.topFade/topFadeGradient below still resolves to a real
    -- (just invisible and zero-size) instance instead of nil.
    local isSidebarMode = self.tabsMode == "Sidebar"

    -- Live-reported as a cheap-looking "elements dissolve at the top edge" effect once v1.2's
    -- own bordered elements card gave the content area a real edge of its own to scroll against -
    -- this seam-hiding fade isn't needed against a border the way it was against open space.
    -- Sized to nothing rather than removed outright, same reasoning Sidebar mode already used:
    -- every other reference to self.topFade/topFadeGradient below still resolves to a real (just
    -- invisible and zero-size) instance instead of nil.
    self.topFade = self:Create("Frame", {
        -- Flat colour, same literal RGB as tabDock (24,24,24) - not a themed WindowColor, and
        -- not a gradient into one either (that was tried and looked worse: a colour ramp toward
        -- the theme reads as "the fade is the wrong colour" right where it meets the dock, since
        -- the dock itself never ramps - it's one flat colour throughout, transparency aside).
        -- Matching that flat colour exactly and only ever varying transparency (see
        -- topFadeGradient) is what actually makes the seam disappear.
        BackgroundColor3 = Color3.fromRGB(24, 24, 24),
        BorderSizePixel = 0,
        AnchorPoint = Vector2.new(0, 0),
        Position = UDim2.new(0, 0, 0, 103),
        Size = UDim2.new(),
        ZIndex = constants.zIndex.bottomFade,

        -- Animation
        BackgroundTransparency = 1, -- In = 0.2, matching tabDock's own resting transparency

        Parent = self.main,
    })

    self.topFadeGradient = self:Create("UIGradient", {
        -- Rotation 90 instead of bottomFade's 270 - flips which end keypoint 0 sits at (top
        -- instead of bottom), so this fades the *same* shape (opaque where it meets the header,
        -- transparent by the time it reaches open content) rather than reusing 270 and getting
        -- the mapping backwards for a frame anchored to the top instead of the bottom. Starts at
        -- 0.2, not fully opaque (0) - matches tabDock's own resting BackgroundTransparency, so
        -- the seam between them is two things at the same opacity, not a jump from "however
        -- opaque the dock reads" to "fully solid". Same eased Transparency shape as
        -- bottomFadeGradient past that point. Transparency only - no Color property here at all,
        -- see self.topFade's own comment on why a colour ramp made this look worse, not better.
        Rotation = 90,
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.2),
            NumberSequenceKeypoint.new(0.4414, 0.2),
            NumberSequenceKeypoint.new(0.7007, 0.7),
            NumberSequenceKeypoint.new(1, 1),
        }),

        Parent = self.topFade,
    })

    -- Topbar
    self.topbar = self:Create("Frame", {

        BackgroundTransparency = 1,
        Size = UDim2.new(1, 0, 0, 66),
        -- Active so empty topbar space can catch input directly - tabs/actions/search sit on
        -- top and still get first pick, this is just the backdrop becoming a drag handle
        Active = true,

        Parent = self.main,
    })

    self.topContainer = self:Create("Frame", {
        Size = UDim2.new(0, 300, 0, 24),
        Position = UDim2.new(0, 25, 0.5, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,

        Parent = self.topbar,
    })

    self.topContainerLayout = self:Create("UIListLayout", {
        Padding = UDim.new(0, 8),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.topContainer,
    })

    self.titleContainer = self:Create("Frame", {
        Size = UDim2.fromOffset(50, 24),
        Position = UDim2.new(0, 25, 0.5, 0),
        AutomaticSize = Enum.AutomaticSize.XY,
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        LayoutOrder = 1,

        Parent = self.topContainer,
    })

    self.titleContainerLayout = self:Create("UIListLayout", {
        Padding = UDim.new(0, 3),
        FillDirection = Enum.FillDirection.Vertical,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.titleContainer,
    })

    if self.name then
        self.title = self:Create("TextLabel", {
            -- Configurables
            Text = locale.t(self.name), -- window name

            FontFace = variables.brandFont(Enum.FontWeight.Medium),

            Size = UDim2.fromOffset(50, 20),
            AutomaticSize = Enum.AutomaticSize.X,

            BackgroundTransparency = 1,
            TextSize = 20,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,

            -- Animations
            TextTransparency = 1, -- In = 0

            Parent = self.titleContainer,
        }, { FontFace = "Font", TextColor3 = "TitlingColor" })
    end

    if self.icon then
        self.topbarIcon = self:Create("ImageLabel", {
            Image = self.icon,

            BackgroundTransparency = 1,
            Size = UDim2.fromOffset(32, 32),

            -- Animation
            ImageTransparency = 1, -- In = 0

            Parent = self.topContainer,
        }, { ImageColor3 = "TitlingColor" })
    end

    if self.subheading then
        self.subtitle = self:Create("TextLabel", {
            -- Configurables
            Text = locale.t(self.subheading), -- window name

            Size = UDim2.fromOffset(50, 12),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            TextSize = 12,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,

            -- Animations
            TextTransparency = 1, -- In = 0.7

            Parent = self.titleContainer,
        }, { TextColor3 = "TitlingColor", FontFace = "Font" })
    end

    self.tagContainer = self:Create("Frame", {
        AnchorPoint = Vector2.new(0, 0.5),
        Position = UDim2.new(0, 25, 0.5, 0),
        Size = UDim2.fromOffset(50, 24),
        AutomaticSize = Enum.AutomaticSize.XY,
        BackgroundTransparency = 1,
        LayoutOrder = 2,
        Visible = false,

        Parent = self.topContainer,
    })

    self.tagContainerLayout = self:Create("UIListLayout", {
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.tagContainer,
    })

    -- Shadow (Transparency 1 here, tweened to self._shadowTransparency/0.6 on show)
    self.windowShadow = self:CreateGlow(self.main, "ShadowColor", self._shadowBlur or 20, 1)

    -- Elements Preparation

    -- Same isSidebar this whole block computes again further down for tabDock's own
    -- construction (self.elements is built first, before that local exists yet) - cheap to
    -- recompute rather than hoist the whole tabDock block above this one just to share it.
    local elementsSidebar = self.tabsMode == "Sidebar"
    -- Rail geometry, all upstream Rayfield Gen2 1.2's own numbers. Not player-draggable (see the
    -- removed resize grip) - the only thing that changes it is the window's own width: under
    -- sidebarCollapseBelow the rail drops its labels and becomes an icon rail, which is the
    -- difference between a usable content card and an unusable one on a narrow window.
    self.sidebarFullWidth = 219
    self.sidebarCollapsedWidth = 64
    self.sidebarCollapseBelow = 589
    -- nil = follow the window's own width; true/false pins it either way (also settable live
    -- via Window:SetSidebarCollapsed).
    self._sidebarCollapsedOverride = if properties.sidebarCollapsed ~= nil then properties.sidebarCollapsed == true
        elseif properties.SidebarCollapsed ~= nil then properties.SidebarCollapsed == true
        else nil
    self.sidebarWidth = if self._sidebarCollapsedOverride == true
        then self.sidebarCollapsedWidth
        else self.sidebarFullWidth

    -- Reserves 118px at the top for the header + tabDock (which itself ends at 65+38=103) - was
    -- 106, only a ~3px gap below the dock. Live-caught: harmless while the dock's own background
    -- was nearly invisible (StatBackground, since fixed - see tabDock's own comment), but once it
    -- reads as an actual dark card, that 3px gap wasn't enough to keep it from looking welded
    -- straight onto the first section's content below it. 118 opens the same ~15px breathing room
    -- other card-to-card spacing in this file uses.
    --
    -- Sidebar mode: content fills the remaining space to the *right* of the sidebar instead of
    -- everything below the header - top-left anchored fill rather than the bottom-anchored fill
    -- Top mode uses, since there's no separate horizontal tab strip height to reserve above it,
    -- just the header.
    self.elements = self:Create("Frame", {
        -- Sidebar: flush against the window's own right and bottom edges - matches upstream
        -- Rayfield Gen2 1.2's own card exactly (AnchorPoint (1,1), Size (1,0,1,-chromeHeight),
        -- zero margin on those two sides) rather than floating with a gap all around it, so the
        -- card visually runs into the window's own edge instead of stopping short of it.
        Size = if elementsSidebar
            then UDim2.new(1, -self.sidebarWidth, 1, -70)
            else UDim2.new(1, 0, 1, -118),
        Position = if elementsSidebar then UDim2.fromScale(1, 1) else UDim2.fromScale(0.5, 1),
        AnchorPoint = if elementsSidebar then Vector2.new(1, 1) else Vector2.new(0.5, 1),
        -- Sidebar mode: a card around the content, matching upstream Rayfield Gen2 1.2's own
        -- exact recipe - a near-invisible white fill (98% transparent, just a hint of lift off
        -- the window's own base gradient) with a subtle gradient-transparency stroke doing the
        -- actual "this is a card" work, not a solid dark fill (that read as flat/plain next to
        -- the reference's own subtler look). Top mode stays exactly as it was - one cohesive
        -- surface with the tabDock above it, no card of its own here.
        BackgroundTransparency = if elementsSidebar then 0.98 else 1,
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ClipsDescendants = true,

        Parent = self.main,
    })

    if elementsSidebar then
        -- Only the two corners that don't butt against something else round at all - top-right
        -- sits under the topbar, bottom-left sits against the sidebar rail, so both stay square;
        -- top-left (facing into open space) and bottom-right (the window's own actual corner)
        -- round to match it. Matches upstream Rayfield Gen2 1.2's own cardCorners exactly -
        -- rounding all four the way a plain CornerRadius does was the "curved at the tip" gap
        -- from a flush, run-into-the-wall corner the reference's own card has there.
        self:Create("UICorner", {
            TopLeftRadius = self.theme.CornerRoundness,
            TopRightRadius = UDim.new(),
            BottomLeftRadius = UDim.new(),
            BottomRightRadius = self.theme.CornerRoundness,

            Parent = self.elements,
        })

        self.elementsStroke = self:Create("UIStroke", {
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
            Transparency = 0,

            Parent = self.elements,
        }, { Color = "SurfaceStroke" })

        -- The rim is this gradient's job, not the stroke's own flat transparency above (that
        -- stays 0/opaque) - a diagonal sweep from a hint of visible edge to fully gone, same
        -- shape and numbers as upstream's own cardStrokeRotation/cardStrokeTransparency.
        self:Create("UIGradient", {
            Rotation = 55,
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 0.9),
                NumberSequenceKeypoint.new(0.128, 0.95),
                NumberSequenceKeypoint.new(0.414, 0.985),
                NumberSequenceKeypoint.new(1, 1),
            }),

            Parent = self.elementsStroke,
        })
    end

    -- UI Scale setting: parented to self.elements specifically, not self.main - main itself
    -- (and everything measured directly off it: resize.luau's corner math, drag.luau's own
    -- follow target, _clampedPosition, _syncDragBar) stays completely unscaled, so none of that
    -- carefully-tuned physics has to become scale-aware. Only the tab content visually grows/
    -- shrinks. Deliberately NOT giving self.main its own ClipsDescendants to cap an oversized
    -- scale at the window's edge - the resize grip depends on main staying unclipped to straddle
    -- the corner (see resize.luau's own header comment: "main has no ClipsDescendants, so a
    -- child is free to render past its edge"), and clipping main would cut that grip in half.
    -- The slider's own range (see the Settings toggle below) is kept modest specifically so this
    -- never needs testing at a scale extreme enough for the overflow to matter in practice.
    self.contentScale = self:Create("UIScale", {
        Scale = 1,
        Parent = self.elements,
    })

    self.elementsLayout = self:Create("UIPageLayout", {
        Padding = UDim.new(0, 0),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Center,
        SortOrder = Enum.SortOrder.LayoutOrder,

        -- Tabs switch via the topbar only. Kill the built-in input so scrolling a long page
        -- (or a nudge on a controller) never flips to another tab under you.
        ScrollWheelInputEnabled = false,
        GamepadInputEnabled = false,
        TouchInputEnabled = false,

        EasingStyle = Enum.EasingStyle.Exponential,
        TweenTime = 0.4,

        Parent = self.elements,
    })

    -- Tabs Preparation - each tab builds its own row/pill (see tabSelector.luau) and owns its own
    -- selected/hover/unselected background, ported from upstream Rayfield Gen2 1.2. Sidebar mode:
    -- everything below branches on this rather than a separate code path per mode, so "Top" (the
    -- default every line here already served before this existed) reaches the exact same
    -- construction it always did whenever isSidebar is false.
    local isSidebar = self.tabsMode == "Sidebar"

    self.tabDock = self:Create("Frame", {
        Name = "TabDock",
        -- 20px total inset, same margin every other card-shaped element on the window uses -
        -- flush edge-to-edge (the original tabList's own sizing) read as glued to the window's
        -- corner once it had a visible fill behind it. Sidebar: a vertical strip down the left
        -- edge instead, from just under the header to just above the bottom fade, full height -
        -- tabList and the profile chip below both live inside it, and the resize grip is
        -- parented here too, grabbable anywhere down the whole strip.
        -- Sidebar: flush against the window's own left edge (x = 0), matching upstream Rayfield
        -- Gen2 1.2's own rail - the 20px inset every other card in this file uses stacked on top
        -- of each row's own 15px rowInset, live-reported as a huge dead margin down that side.
        Size = if isSidebar then UDim2.new(0, self.sidebarWidth, 1, -85) else UDim2.new(1, -40, 0, 38),
        Position = if isSidebar then UDim2.new(0, 0, 0, 65) else UDim2.new(0.5, 0, 0, 65),
        AnchorPoint = if isSidebar then Vector2.new(0, 0) else Vector2.new(0.5, 0),
        BorderSizePixel = 0,
        -- Without this, selecting (or scrolling to) a tab near either end of the strip let the
        -- indicator render fully outside the dock - even outside the window entirely, not just
        -- past the rounded corners. The un-clipped glow's own hard-edged blur line was the
        -- lesser problem; brought clipping back and shrank the glow instead (see CreateGlow
        -- call below) so its blur has less reach to clip in the first place.
        ClipsDescendants = true,
        -- same reasoning as self.main's own Active = true - stays clickable at any transparency
        Active = true,

        -- In Top mode this frame IS the visible card (background set directly below). Sidebar
        -- mode has no visible fill at all - tabs and the profile chip float directly on the
        -- window, matching the reference sidebar's own look (live-reported: a dark panel
        -- wrapping the whole rail read as an unwanted background nobody asked for).
        BackgroundTransparency = if isSidebar then 1 else 0.2,
        BackgroundColor3 = Color3.fromRGB(24, 24, 24),

        Parent = self.main,
    })

    -- PillCornerRadius is UDim.new(1, 0) - scale-based, so it rounds to a full pill relative to
    -- whichever side is shorter. Top mode's dock is a short horizontal bar, so that's the right
    -- look. Sidebar mode has no visible fill of its own to round at all (self.tabDock's own
    -- BackgroundTransparency above is 1 there - tabs and the profile chip below float directly
    -- on the window, matching the reference sidebar's look) - this still runs for it, just
    -- against an invisible frame, rather than special-casing corners on/off per mode.
    self:Create("UICorner", {
        Parent = self.tabDock,
    }, { CornerRadius = if isSidebar then "CornerRoundness" else "PillCornerRadius" })

    -- Whether this window gets a profile chip at all - Sidebar layout and a real player to
    -- build one for (nil in a Studio server view or a headless run). Computed before tabList
    -- below since its own height already needs to know whether to reserve the footer for it.
    local localPlayer = if isSidebar then game:GetService("Players").LocalPlayer else nil
    -- The profile chip's fixed height - see the block that builds it further down. A field, not
    -- a local, so windowMethods.luau's "Show profile" toggle can reclaim/release the same strip
    -- from tabList on demand. _tabListFooterReserve is what tabList itself gives up for it: the
    -- chip hangs off main's own bottom edge, 20px below where tabDock (and so tabList) already
    -- stops, so the list only has to clear the part that actually overlaps it.
    self.profileFooterHeight = 68
    -- How far the chip's own bottom sits above main's (clear of the window's bottom fade - see
    -- its construction below).
    self._profileBottomOffset = 6
    -- tabDock already stops 20px above main's bottom, so the list only gives up the part of the
    -- chip that actually reaches into it. Derived, not a magic number: getting this wrong by even
    -- a few px let a scrolled row show inside the chip's own strip, which has no fill to hide it.
    self._tabListFooterReserve = self.profileFooterHeight + self._profileBottomOffset - 20

    self.tabList = self:Create("ScrollingFrame", {
        Name = "Tabs",
        Active = true,
        -- Sidebar: a real fixed-height scrolling rail, the reference sidebar's own shape - tabs
        -- scroll inside it once there are too many to fit, rather than the dock growing/shrinking
        -- to match however many exist. Only as tall as the window minus the profile chip's own
        -- reserved footer strip when one was actually built. Top mode is unchanged.
        Size = if isSidebar
            then UDim2.new(1, 0, 1, if localPlayer then -self._tabListFooterReserve else 0)
            else UDim2.fromScale(1, 1),
        Position = if isSidebar then UDim2.new(0, 0, 0, 0) else UDim2.fromScale(0.5, 0.5),
        AnchorPoint = if isSidebar then Vector2.new(0, 0) else Vector2.new(0.5, 0.5),

        BackgroundTransparency = 1,
        CanvasSize = UDim2.new(0, 0, 0, 0),
        ScrollBarThickness = 0,
        ScrollBarImageTransparency = 1,
        ClipsDescendants = true,
        -- Sidebar: canvas tracks content along the scrolling (Y) axis now that the frame's own
        -- Size.Y is fixed rather than auto-hugging it. Top mode is unchanged (X, its own scroll
        -- axis).
        AutomaticCanvasSize = if isSidebar then Enum.AutomaticSize.Y else Enum.AutomaticSize.X,
        ScrollingDirection = if isSidebar then Enum.ScrollingDirection.Y else Enum.ScrollingDirection.X,

        Parent = self.tabDock,
    })

    self.tabListLayout = self:Create("UIListLayout", {
        -- Devlog 7: tighter gap between tabs (was 4) - closer, more "Segmented Picker" feel
        -- 4px between sidebar rows matches upstream Rayfield Gen2 1.2's own rowSpacing exactly;
        -- Top's pills keep their own tighter gap.
        Padding = UDim.new(0, if isSidebar then 4 else 2),
        FillDirection = if isSidebar then Enum.FillDirection.Vertical else Enum.FillDirection.Horizontal,
        -- Center is right for Top mode - it centers a short horizontal row within the (equally
        -- short) dock. Sidebar's dock runs almost the full window height though, so the same
        -- Center vertically centered the *whole column* of tabs inside that tall space - live-
        -- reported as tabs "starting from the middle" instead of stacking down from the top the
        -- way every reference sidebar (Discord, VS Code, the reference framework's own) does.
        VerticalAlignment = if isSidebar then Enum.VerticalAlignment.Top else Enum.VerticalAlignment.Center,
        -- Sidebar: each row is already narrower than tabList by rowInset*2 (tabSelector.luau's
        -- own buildRow) - Center is what actually splits that gap evenly on both sides. Left
        -- alignment (still right for Top's own hug-to-content pills) put the entire gap on the
        -- row's right edge only, live-reported as a lopsided, oversized margin on one side.
        HorizontalAlignment = if isSidebar then Enum.HorizontalAlignment.Center else Enum.HorizontalAlignment.Left,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.tabList,
    })

    self:Create("UIPadding", {
        -- Sidebar: no horizontal padding here at all - each row already insets itself by
        -- rowInset*2 in tabSelector.luau's own buildRow (matching upstream Rayfield Gen2 1.2
        -- exactly), so padding here too was a double inset, live-reported as a huge dead gap
        -- down both edges of the rail. Only top/bottom (railPadding) belongs on the list itself -
        -- clears the selected row's own glow, which reaches a bit past its top edge. Top's pills
        -- keep their own tighter, unrelated inset.
        PaddingLeft = UDim.new(0, if isSidebar then 0 else 5),
        PaddingRight = UDim.new(0, if isSidebar then 0 else 5),
        PaddingTop = UDim.new(0, if isSidebar then 17 else 0),
        PaddingBottom = UDim.new(0, if isSidebar then 17 else 0),

        Parent = self.tabList,
    })

    -- Sidebar profile chip: the signed-in player pinned to the base of the rail, ported from
    -- upstream Rayfield Gen2 1.2's own sidebar profile (localPlayer/profileFooterHeight computed
    -- above tabList, since its own height already reserves this strip).
    if localPlayer then
        -- Bigger than upstream's own 34/15 - live-reported as reading too small and too far off
        -- the window's corner at that size next to the reference.
        local avatarSize, rowInset = 40, 12

        -- Parented to main, not tabDock: it runs right into the window's own bottom-left corner
        -- (tabDock is inset from that edge, so anchoring inside it left a visible margin the
        -- reference doesn't have). No fill of its own - live-reported that any backing here read
        -- as heavy and wrong; tabList already stops short of this strip and clips its own rows
        -- (see _tabListFooterReserve), so nothing can scroll through behind it anyway.
        self.profile = self:Create("Frame", {
            Name = "Profile",
            AnchorPoint = Vector2.new(0, 1),
            -- Lifted clear of the window's own bottom fade (see self.bottomFade - it hangs ~47px
            -- off the bottom edge and paints over anything under it at zIndex.bottomFade), which
            -- was washing the chip out at the very bottom. The ZIndex below keeps it crisp even
            -- where the two still overlap.
            Position = UDim2.new(0, 0, 1, -self._profileBottomOffset),
            Size = UDim2.fromOffset(self.sidebarWidth, self.profileFooterHeight),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ZIndex = constants.zIndex.bottomFade + 1,

            -- self.settings doesn't exist yet this early in construction (assigned further
            -- down) - defaults shown, same as the resize grip's own construction-time Visible;
            -- both get the real saved value applied at Show() time instead (see windowExtra.luau
            -- and windowMethods.luau's own resizeGripEnabled sync points).
            Visible = true,

            Parent = self.main,
        })

        -- Global ZIndexBehavior: a child doesn't inherit its parent's ZIndex, so every part of
        -- the chip has to carry the same one to stay above the bottom fade.
        local profileZIndex = constants.zIndex.bottomFade + 1

        self.profileContainer = self:Create("Frame", {
            AnchorPoint = Vector2.new(0, 0.5),
            Position = UDim2.new(0, rowInset, 0.5, 0),
            Size = UDim2.new(1, -rowInset, 1, 0),
            BackgroundTransparency = 1,
            ZIndex = profileZIndex,

            Parent = self.profile,
        })

        self.profileLayout = self:Create("UIListLayout", {
            Padding = UDim.new(0, 10),
            FillDirection = Enum.FillDirection.Horizontal,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            HorizontalAlignment = Enum.HorizontalAlignment.Left,
            SortOrder = Enum.SortOrder.LayoutOrder,

            Parent = self.profileContainer,
        })

        -- headshots resolve async (a local getcustomasset file in secure mode) - onReady fills
        -- it in whenever it actually lands, same pattern as CreateHUD's own avatar.
        self.profileAvatar = self:Create("ImageLabel", {
            Name = "Avatar",
            Image = image.avatar(localPlayer.UserId, function(uri)
                if self.profileAvatar and not self.unloaded then
                    image.assign(self.profileAvatar, "Image", uri)
                end
            end),
            Size = UDim2.fromOffset(avatarSize, avatarSize),
            BorderSizePixel = 0,
            ZIndex = profileZIndex,

            Parent = self.profileContainer,
        }, { BackgroundColor3 = "StatBackground" })

        self:Create("UICorner", {
            CornerRadius = UDim.new(1, 0),
            Parent = self.profileAvatar,
        })

        self.profileLabels = self:Create("Frame", {
            Size = UDim2.fromOffset(50, avatarSize),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            LayoutOrder = 1,
            ZIndex = profileZIndex,

            Parent = self.profileContainer,
        })

        self:Create("UIListLayout", {
            Padding = UDim.new(0, 2),
            FillDirection = Enum.FillDirection.Vertical,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            HorizontalAlignment = Enum.HorizontalAlignment.Left,
            SortOrder = Enum.SortOrder.LayoutOrder,

            Parent = self.profileLabels,
        })

        self.profileName = self:Create("TextLabel", {
            Text = localPlayer.DisplayName,
            Size = UDim2.fromOffset(50, 18),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            TextSize = 18,
            TextXAlignment = Enum.TextXAlignment.Left,
            ZIndex = profileZIndex,

            Parent = self.profileLabels,
        }, { TextColor3 = "TitlingColor", FontFace = "Font" })

        -- The dev's line under the name (properties.profile/Profile - see self.profileText
        -- above). Nothing set means the name stands on its own rather than inventing a second
        -- line to fill the space.
        self.profileSubtitle = self:Create("TextLabel", {
            Text = if self.profileText and self.profileText ~= "" then locale.resolve(self.profileText) else "",
            Size = UDim2.fromOffset(50, 15),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            TextSize = 15,
            TextXAlignment = Enum.TextXAlignment.Left,
            LayoutOrder = 1,
            Visible = self.profileText ~= nil and self.profileText ~= "",
            TextTransparency = 0.3,
            ZIndex = profileZIndex,

            Parent = self.profileLabels,
        }, { TextColor3 = "TitlingColor", FontFace = "Font" })
    end

    -- No shared sliding indicator anymore - ported from upstream Rayfield Gen2 1.2, each tab row/
    -- pill owns and fades its own background/stroke/shadow (see tabSelector.luau and Tab's own
    -- _applyVisual) instead of one pill sliding between them.

    -- No player-facing sidebar resize handle anymore - live-reported as getting in the way more
    -- than it helped. The rail is a fixed width now (see self.sidebarWidth's own construction-
    -- time comment, matching upstream Rayfield Gen2 1.2's own railWidth), not something a player
    -- drags live.

    -- Actions
    self.actionContainer = self:Create("Frame", {

        AnchorPoint = Vector2.new(1, 0.5),
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, 24),
        Position = UDim2.new(1, -20, 0.5, 0),
        BackgroundTransparency = 1,

        Parent = self.topbar,
    })

    self.actionsListLayout = self:Create("UIListLayout", {
        Padding = UDim.new(0, 5),
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalAlignment = Enum.HorizontalAlignment.Right,
        SortOrder = Enum.SortOrder.LayoutOrder,

        Parent = self.actionContainer,
    })

    self.rfSettings = self:CreateTab({
        name = "Rayfield Settings",
        customOrder = 1000,

        neglectSelector = true,
        -- everything here is ephemeral: these controls persist to rayfield.rfld via SaveSettings,
        -- never the user's config. children inherit this, so none of them opt out individually.
        forgetState = true,
    })

    require(script.Parent.action).new(self, {
        name = "Close",
        icon = constants.icons.close,
        order = 1,

        callback = function()
            self:ToggleHide()
        end,
    })

    self.minimiseAction = require(script.Parent.action).new(self, {
        name = "Minimise",
        icon = constants.icons.minimise,
        order = 2,

        callback = function()
            self:ToggleMinimise()
        end,
    })

    self.settingsAction = require(script.Parent.action).new(self, {
        name = "Settings",
        icon = constants.icons.settings,
        order = 3,
        linkedTab = self.rfSettings,

        callback = function()
            self.rfSettings:Select()
        end,
    })

    search.build(self)

    self.unloaded = false
    self.minimised = false
    self.hidden = true
    self.animating = false
    self._revealing = false
    self.hasShownOnce = false

    self.settings = {
        toggleKeybind = Enum.KeyCode.K,
        mouseOverride = true, -- free the cursor while the menu is open (for FPS games that lock it)
        keepOnScreen = true, -- clamp the drag so the window cant be pulled off screen
        welcomeToast = true, -- the "signed in as" toast on first open for a new/changed account
        -- On by default (matches upstream Rayfield Gen2 1.2) - buzzes on presses/notifications,
        -- silent on devices with no haptics support regardless. A player can still opt out from
        -- Settings.
        haptics = true,
        soundEffects = false, -- off by default, same reasoning as haptics above - opt in from
        -- settings rather than a sound just starting the moment a window opens
        resizeGripEnabled = true, -- Devlog 8: shows the corner drag-to-resize handle
        showProfile = true, -- the player chip at the base of the sidebar rail (Sidebar tabsMode
        -- only - see the profile block built below); ported from upstream Rayfield Gen2 1.2
        debugLogging = false, -- off by default; gates Window:DebugLog - a player flips this (or
        -- presses F9) only when asked to reproduce a bug, so a dev's DebugLog calls stay silent
        -- for everyone else the rest of the time
        -- only meaningful when self.loading exists (the Settings toggle is conditional on that
        -- too) - defaults to whatever the dev set, the player can still flip it off from there
        loadingAnimationEnabled = if self.loading then self.loading.enabled else false,
        uiScale = 100, -- percent; self.contentScale.Scale = uiScale / 100
        tourSeen = false, -- flips true once the guided tour (if the dev configured one) has
        -- played through or been skipped - see _firstShow's own tour block
        -- customWindowSize starts absent (nil): no saved drag yet, so sizing still comes from
        -- self.defaultSize/customSize the normal way. Set once the resize grip is dragged, see
        -- resize.luau, and read right below once a saved one exists.
    }

    self:LoadSettings()
    self.contentScale.Scale = self.settings.uiScale / 100

    -- Devlog 8 corner grip: a size saved from a previous session becomes the new basis for every
    -- size decision from here on (the reveal target, _applyWindowSize's own viewport refit) -
    -- self.defaultSize is deliberately left alone so double-clicking the grip can still get back
    -- to the window's original size after this.
    if self.settings.customWindowSize then
        self.customSize = Vector2.new(self.settings.customWindowSize.X, self.settings.customWindowSize.Y)
        self.size = fitWindowSize(self.customSize)
    end

    hapticEngine.setContainer(self.screenGui) -- effects live with the interface, not the workspace
    hapticEngine.setEnabled(self.settings.haptics) -- honour a saved off before any interaction
    soundEngine.setContainer(self.screenGui)
    soundEngine.setEnabled(self.settings.soundEffects)
    chrome.buildCollapsedFace(self)
    self.resize = require(script.Parent.resize).new(self)
    self.tour = require(script.Parent.tour).new(self)
    self:_bindKeybind()
    self:_bindMouseOverride()
    self:_bindTopbarDrag()
    self:_watchViewport()
    self:_buildSettingsUI()

    self:_syncLiveAnimation()

    return self
end

-- The instance + property every reveal/hide/opacity call site targets for "the window body's
-- own fill", instead of every one of them hardcoding self.main/BackgroundTransparency directly -
-- in squircle mode self.main itself stays permanently transparent (see its own construction
-- above) and self.mainSquircle's ImageTransparency carries the fill instead. Centralising this
-- here is what let squircleCorners slot in without touching Show/Hide/SetTransparency's own
-- logic at each of their several call sites, just the one line at each that used to say
-- `self.main, "BackgroundTransparency"`.
function Window:_mainVisual(): (GuiObject, string)
    if self.mainSquircle then
        return self.mainSquircle, "ImageTransparency"
    end
    return self.main, "BackgroundTransparency"
end

-- Every Window:X method past this point lives in one of these two files (pure side effect:
-- attaching more methods onto the same shared Window table from windowCore) - see this file's
-- own header comment and windowCore.luau's for why.
require(script.Parent.windowMethods)
require(script.Parent.windowExtra)

return Window
]=====]

sources["components/windowCore"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Shared foundation for window.luau/windowMethods.luau/windowExtra.luau - the Window class got
-- split across those three files because a single window.luau finally tripped Roblox's 200,000
-- character Source limit on a ModuleScript (confirmed live: `Unable to assign property Source.
-- Provided string length (202980) is greater than or equal to max length (200000)` - the dev
-- loader couldn't even inject it anymore, so this wasn't a someday problem, it was already
-- broken). Splitting by top-level function is easy; the part that isn't is that a good few
-- module-locals (constants, theme/font helpers, the singleton registry) are read by methods on
-- both sides of every split point. Rather than duplicate them (and risk one copy drifting from
-- the other) or thread them through a real circular require (window.luau -> windowMethods.luau
-- -> window.luau, which neither Roblox's require nor this project's own dev-loader customRequire
-- - see scripts/dev-loadstring.luau - actually supports), every one of them lives here instead:
-- one shared, dependency-free module every split file requires, holding the empty Window table
-- itself plus everything that used to be a bare local at the top of the old window.luau.
--
-- Window.new (window.luau) explicitly requires windowMethods.luau and windowExtra.luau at its
-- own tail, purely for their side effect of attaching more `function Window:X` methods to this
-- same shared table - by the time anyone can actually call Window.new (which requires having
-- required window.luau itself first, which only finishes after both those requires do), every
-- method from all three files is already attached. See window.luau's own closing comment.

local utility = script.Parent.Parent.utility

local core = {}

core.image = require(utility.image)
core.functions = require(utility.functions)
core.persistence = require(utility.persistence)
core.constants = require(utility.constants)
core.locale = require(utility.locale)
core.log = require(utility.log)
core.hapticEngine = require(utility.HapticEngine)
core.soundEngine = require(utility.sound)
core.windowSizing = require(utility.windowSizing)
core.icons = require(utility.icons)
core.acrylic = require(utility.acrylic)
core.clipboard = require(utility.clipboard)
core.chrome = require(script.Parent.chrome)
core.search = require(script.Parent.search)
core.filesystem = require(utility.filesystem)
core.path = require(utility.path)
core.squircle = require(utility.squircle)
core.variables = require(utility.variables)
core.themes = script.Parent.Parent.themes

local variables = core.variables
local windowSizing = core.windowSizing
local log = core.log
local themes = core.themes

-- Module
local Window = {}
Window.__index = Window
core.Window = Window

-- Default entrance-reveal tween (elements override with their own where needed)
core.revealInfo = TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)

-- The collapsed "pill" main morphs into on Hide, top-anchored the way the old standalone
-- restore button used to sit.
core.collapsedSize = UDim2.fromOffset(185, 50)
core.collapsedTop = UDim2.new(0.5, 0, 0, 20)

-- Width of the top-centre toast stack container. Toasts hug their own content and centre
-- within it, so this just needs to be at least the toast's own max width.
core.maxToastWidth = 320

-- Standard element row height, shared by the compact button/toggle scaffold.
core.compactRowHeight = 41

-- How often the backstop re-checks the fit, for anything the viewport signal misses.
core.viewportReconcileInterval = 2

-- The size the current screen calls for. Everything downstream (the reveal target, drag
-- clamp, collapse) reads self.size, so it all inherits whatever this returns.
function core.fitWindowSize(customSize: Vector2?): UDim2
    local camera = variables.workspace.CurrentCamera
    return windowSizing.fit(camera and camera.ViewportSize, customSize)
end

-- WindowProps.size: a dev-supplied starting size, still screen-fit the same way the built-in
-- default is (see windowSizing.fit). Accepts a Vector2, a UDim2 (its offset component), or a
-- plain {width, height}/{X, Y}/{x, y} table so a dev doesn't have to reach for Vector2.new.
function core.resolveCustomSize(value): Vector2?
    if typeof(value) == "Vector2" then
        return value
    end
    if typeof(value) == "UDim2" then
        return Vector2.new(value.X.Offset, value.Y.Offset)
    end
    if typeof(value) == "table" then
        local x = value.width or value.Width or value.X or value.x or value[1]
        local y = value.height or value.Height or value.Y or value.y or value[2]
        if typeof(x) == "number" and typeof(y) == "number" then
            return Vector2.new(x, y)
        end
    end
    return nil
end

-- Devlog 6/7 Settings > Font picker. "auto" is the brand font (the default - a custom-downloaded
-- family via variables.brandFont); every other entry is a plain built-in Roblox font, all of
-- them (Devlog 7 "complete font picker", was just 4) via Enum.Font:GetEnumItems(). Keyed
-- lowercase so SetFont can match case-insensitively the same way ChangeTheme's theme names do;
-- fontOptionNames keeps the proper-cased names for the Settings dropdown, which already has its
-- own live search built in - exactly what "filter by name" asks for, no new search UI needed.
core.fontChoices = {} :: { [string]: Enum.Font }
core.fontOptionNames = { "Auto" }
for _, item in Enum.Font:GetEnumItems() do
    core.fontChoices[string.lower(item.Name)] = item
    table.insert(core.fontOptionNames, item.Name)
end
table.sort(core.fontOptionNames, function(a, b)
    if a == "Auto" then
        return true
    elseif b == "Auto" then
        return false
    end
    return a < b
end)

-- Same family, a different weight - Font.fromEnum only ever gives the enum's own default
-- weight, so re-derive a Font at the weight we actually want from its family name instead.
function core.fontAtWeight(enumFont: Enum.Font, weight: Enum.FontWeight): Font
    return Font.new(Font.fromEnum(enumFont).Family, weight)
end

-- Keys that drive a UIGradient and so want a ColorSequence. A dev may pass a plain Color3 for
-- any of these and we widen it to a flat sequence, so a theme reads the same either way.
core.gradientKeys = {
    WindowColor = true,
    ElementGradient = true,
    ElementStrokeGradient = true,
    TabBackground = true,
    TabStroke = true,
    SliderProgress = true,
}

function core.coerceThemeValue(key, value)
    if core.gradientKeys[key] and typeof(value) == "Color3" then
        return ColorSequence.new(value)
    end
    return value
end

function core.firstColor(value)
    return if typeof(value) == "ColorSequence" then value.Keypoints[1].Value else value
end

-- A subtle raised edge for a fill: lighten a dark fill, darken a light one.
function core.edgeShade(color, amount)
    local luminance = 0.299 * color.R + 0.587 * color.G + 0.114 * color.B
    local target = if luminance > 0.5 then Color3.new(0, 0, 0) else Color3.new(1, 1, 1)
    return color:Lerp(target, amount)
end

-- Give a custom theme sensible strokes for free: when it recolours a surface but leaves the
-- matching stroke unset, derive one from the fill so a colours-only theme still reads coherently.
function core.deriveStrokes(resolved, overrides)
    if overrides.ElementGradient then
        local fill = core.firstColor(resolved.ElementGradient)
        if overrides.ElementStroke == nil then
            resolved.ElementStroke = core.edgeShade(fill, 0.28)
        end
        if overrides.ElementStrokeGradient == nil then
            resolved.ElementStrokeGradient = ColorSequence.new(core.edgeShade(fill, 0.4))
        end
        if overrides.ElementStrokeHover == nil then
            resolved.ElementStrokeHover = core.edgeShade(fill, 0.52)
        end
    end
    if overrides.TabBackground and overrides.TabStroke == nil then
        resolved.TabStroke = ColorSequence.new(core.edgeShade(core.firstColor(resolved.TabBackground), 0.4))
    end
end

-- Resolve a theme arg to its raw key set: a table is taken as-is (partial is fine), a known
-- name is required, anything else falls back to default. Read-only - callers never mutate it,
-- so the require()-cached module stays clean for other windows.
function core.themeOverrides(value)
    if typeof(value) == "table" then
        return value
    elseif typeof(value) == "string" then
        local named = themes:FindFirstChild(string.lower(value))
        if named then
            return require(named)
        end
        -- a typo'd name shouldnt crash the menu; warn and fall back so the UI still builds
        log.warn("Rayfield: unknown theme '" .. value .. "', using default")
    elseif value ~= nil then
        log.warn("Rayfield: invalid theme (expected a built-in name or a theme table), using default")
    end
    return require(themes["default"])
end

-- A complete theme for first paint: default filled in with the given overrides, so a partial
-- custom theme only needs the keys it wants to change and the rest fall back to default.
function core.resolveTheme(value)
    local resolved = table.clone(require(themes["default"]))
    local overrides = core.themeOverrides(value)
    for key, override in overrides do
        resolved[key] = core.coerceThemeValue(key, override)
    end
    -- only a hand-written table gets derived strokes; a named built-in ships its own.
    if typeof(value) == "table" then
        core.deriveStrokes(resolved, overrides)
    end

    -- theme modules call brandFont at first require and are cached from then on, so a
    -- fallbackFont set afterwards would never reach them. recompute against the current
    -- stand-in, unless the dev named a font themselves.
    local userTable = if typeof(value) == "table" then value else nil
    if not (userTable and (userTable.Font or userTable.font)) then
        resolved.Font = variables.brandFont(Enum.FontWeight.Medium)
    end
    if not (userTable and (userTable.TitleFont or userTable.titleFont)) then
        resolved.TitleFont = variables.brandFont(Enum.FontWeight.SemiBold)
    end

    return resolved
end

-- Singleton window registry, keyed by window name. Deliberately lives in _G rather than a plain
-- module-local: a dev-loader/executor re-run of the whole script rebuilds this entire file as a
-- brand new module (fresh table, fresh Window class) - a module-local would forget every window
-- from the previous run instantly. _G is the one thing that actually survives that boundary, the
-- same trick a hot-reloaded hub script needs for its own UI. See Window.new's own use of this
-- for what it's for: auto-unloading a same-named window left over from an earlier run, so
-- re-running a script twice can't leave its old window's connections leaking forever (exactly
-- the "zombie window" failure mode this project's own dev workflow kept hitting by hand).
core.WINDOW_REGISTRY_KEY = "__RayfieldGen3WindowRegistry"

function core.windowRegistry()
    local reg = _G[core.WINDOW_REGISTRY_KEY]
    if typeof(reg) ~= "table" then
        reg = {}
        _G[core.WINDOW_REGISTRY_KEY] = reg
    end
    return reg
end

return core
]=====]

sources["components/windowExtra"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Part of the Window class - see window.luau's own header comment for why this file exists
-- (Roblox's 200,000 character ModuleScript Source limit) and windowCore.luau's for how the split
-- actually holds together (a shared core module, not a circular require). Every `function
-- Window:X` below attaches to the exact same table window.luau's Window.new builds instances
-- against - this file is required purely for that side effect, from window.luau's own tail.

local core = require(script.Parent.windowCore)
local Window = core.Window

-- Utility (aliased off windowCore so every split file shares the exact same module instances -
-- see windowCore.luau's own header comment)
local image = core.image
local functions = core.functions
local persistence = core.persistence
local constants = core.constants
local locale = core.locale
local log = core.log
local hapticEngine = core.hapticEngine
local soundEngine = core.soundEngine
local windowSizing = core.windowSizing
local icons = core.icons
local acrylic = core.acrylic
local clipboard = core.clipboard
local chrome = core.chrome
local search = core.search
local filesystem = core.filesystem
local path = core.path
local variables = core.variables
local themes = core.themes

-- Shared constants/helpers (see windowCore.luau)
local revealInfo = core.revealInfo
local collapsedSize = core.collapsedSize
local collapsedTop = core.collapsedTop
local maxToastWidth = core.maxToastWidth
local compactRowHeight = core.compactRowHeight
local viewportReconcileInterval = core.viewportReconcileInterval
local fitWindowSize = core.fitWindowSize
local resolveCustomSize = core.resolveCustomSize
local fontChoices = core.fontChoices
local fontOptionNames = core.fontOptionNames
local fontAtWeight = core.fontAtWeight
local gradientKeys = core.gradientKeys
local coerceThemeValue = core.coerceThemeValue
local firstColor = core.firstColor
local edgeShade = core.edgeShade
local deriveStrokes = core.deriveStrokes
local themeOverrides = core.themeOverrides
local resolveTheme = core.resolveTheme
local WINDOW_REGISTRY_KEY = core.WINDOW_REGISTRY_KEY
local windowRegistry = core.windowRegistry

function Window:SaveSettings()
    return persistence.saveSettings(self)
end

function Window:LoadSettings()
    return persistence.loadSettings(self)
end

-- Fade the open tab's elements out - the only ones actually on screen, since the page
-- navigation keeps the other tabs' elements invisible. Shared by Hide and minimise.
function Window:_fadeSelectedElementsOut()
    if self.selectedTab then
        for _, element in ipairs(self.selectedTab.elements) do
            element:_setShown(false, true)
        end
    end
end

-- Reveal the open tab's elements with a quick top-to-bottom stagger, but only for the ones
-- actually within the scroll viewport - whatever's scrolled off (above or below) just snaps in,
-- since nobody's looking at it. So reopening a page scrolled halfway down animates from where
-- you left off, not from the very top. Everything is measured live off the scrolling frame's
-- real viewport + each element's real position, so it's correct at any window size, any scroll.
-- Other tabs snap ready off-screen too. `budget` caps how long the stagger runs before the
-- remaining on-screen elements come in together, so a tall viewport doesn't crawl.
function Window:_revealElements(perElementDelay, budget)
    for _, tab in pairs(self.tabs) do
        if tab ~= self.selectedTab then
            for _, element in ipairs(tab.elements) do
                element:_setShown(true, false)
            end
        end
    end

    local tab = self.selectedTab
    if not tab then
        return
    end

    local page = tab.tabPage
    local viewTop = page.AbsolutePosition.Y
    local viewBottom = viewTop + page.AbsoluteWindowSize.Y

    local maxStaggered = math.floor(budget / perElementDelay)
    local staggered = 0
    for _, element in ipairs(tab.elements) do
        local top = element.main.AbsolutePosition.Y
        local onScreen = (top + element.main.AbsoluteSize.Y) > viewTop and top < viewBottom
        if onScreen then
            element:_setShown(true, true)
            staggered += 1
            if staggered <= maxStaggered then
                task.wait(perElementDelay)
            end
        else
            element:_setShown(true, false) -- off-screen: no point animating what isn't visible
        end
    end
end

function Window:Show()
    -- idempotent: replaying the restore on a visible window teleports it to a stale position
    if self.animating or not self.hidden then
        return
    end
    self.animating = true
    self._revealing = true

    -- autoLoad reflects the saved config once, on first open. Re-loading on every show would
    -- wipe any changes the user made and closed without saving. a load that throws must not
    -- strand animating=true, or the window could never open again.
    -- Auto Load Config (see the Configurations section in windowMethods.luau's
    -- _buildSettingsUI): its own button already calls _applyNamedConfig, which both applies the
    -- chosen configuration live and re-saves the default file to match - so the plain Load right
    -- here already restores whatever that button last committed, with nothing extra needed on
    -- this end.
    if self.configuration.autoLoad and not self._autoLoaded then
        self._autoLoaded = true
        local ok, err = pcall(self.Load, self)
        if not ok then
            log.warn("Rayfield: Failed to load configuration - " .. tostring(err))
        end
    end

    self.hidden = false
    self.minimised = false

    -- a ChangeTheme landed while we were collapsed; apply it before anything fades back in
    if self._themeRefreshPending then
        self._themeRefreshPending = false
        self:_refreshElementThemes()
    end

    self.collapsedInteract.Visible = false -- first thing on click: stop it eating any more input

    if self._freeMouse then
        self._freeMouse()
    end

    if self.hasShownOnce then
        self:_quickRestore()
    else
        self.hasShownOnce = true
        self:_firstShow()
    end
end

function Window:_quickRestore()
    -- the screen can have changed while we were hidden, so where it sat may no longer fit
    local target = self:_clampedPosition(self._restorePosition or UDim2.new(0.5, 0, 0.5, 0))
    self._restorePosition = target

    -- slowed down from 0.35/0.28 (read as too fast, opening almost instantly) - kept in named
    -- locals so the task.delay staging below stays in step with the new pacing
    local growDuration, fadeDuration = 0.5, 0.38
    -- "Open from Pill": the mirror of Hide's own Quint/Out collapse - same curve family so the
    -- open and close read as one continuous motion reversed, not two differently-paced animations
    local growInfo = TweenInfo.new(growDuration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local cornerInfo = TweenInfo.new(growDuration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local fadeInfo = TweenInfo.new(fadeDuration, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)

    -- Phase 1: nothing but the pill morphing back into the window frame. The collapsed face
    -- fades off, main grows + un-rounds. No chrome, no content - so you never see the topbar,
    -- tabs or bottom fade floating over a frame that isn't a window yet.
    chrome.setCollapsedShown(self, false, TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out))
    self:_setTopToastPosition(TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out))
    variables.tweenService:Create(self.main, growInfo, { Size = self.size, Position = target }):Play()
    -- squircle mode has no windowCorner to un-round back from the pill's fully-round corner -
    -- the squircle shape just stays at its own normal radius throughout the restore (a known,
    -- disclosed gap: the pill-collapse animation isn't squircle-aware yet, see Hide's own note).
    if self.windowCorner then
        variables.tweenService:Create(self.windowCorner, cornerInfo, { CornerRadius = self.theme.CornerRoundness }):Play()
    end

    -- Phase 2: once the frame actually reads as a window, fade its chrome in and stagger the
    -- open tab's elements. Other tabs snap ready off-screen - nobody's looking, so no animation.
    task.delay(growDuration * 0.63, function()
        -- respects the setting rather than hardcoding true, same as the minimise restore path
        self.resize.grip.Visible = self.settings.resizeGripEnabled
        if self.profile then
            self.profile.Visible = self.settings.showProfile
            self.tabList.Size =
                UDim2.new(1, 0, 1, if self.settings.showProfile then -self._tabListFooterReserve else 0)
        end
        self.topbar.Visible = true
        self.tabList.Visible = true
        self.tabDock.Visible = true
        self.elements.Visible = true

        variables.tweenService:Create(self.windowShadow, fadeInfo, { Transparency = self._shadowTransparency or 0.6 }):Play()
        variables.tweenService:Create(self.bottomFade, fadeInfo, { BackgroundTransparency = 0 }):Play()
        variables.tweenService:Create(self.topFade, fadeInfo, { BackgroundTransparency = 0 }):Play()

        if self.topbarIcon then
            variables.tweenService:Create(self.topbarIcon, fadeInfo, { ImageTransparency = 0 }):Play()
        end
        if self.title then
            variables.tweenService:Create(self.title, fadeInfo, { TextTransparency = 0 }):Play()
        end
        if self.subtitle then
            variables.tweenService:Create(self.subtitle, fadeInfo, { TextTransparency = 0.7 }):Play()
        end

        for _, action in ipairs(self.actionContainer:GetChildren()) do
            if action:IsA("Frame") then
                variables.tweenService:Create(action.ImageLabel, fadeInfo, { ImageTransparency = 0.6 }):Play()
            end
        end

        -- if we were hidden with the settings page open, bring its cog back lit (its open
        -- state) rather than the default resting brightness the loop above just set
        if self.settingsAction and self.selectedTab == self.rfSettings then
            variables.tweenService:Create(self.settingsAction.iconLabel, fadeInfo, { ImageTransparency = 0.2 }):Play()
        end

        for _, tag in self.tags do
            tag:_setShown(true, fadeInfo)
        end

        for _, tab in pairs(self.tabs) do
            if not tab.neglectSelector and tab.topbarItem then
                tab.topbarItem.Visible = true
                tab:_applyVisual(if self.selectedTab == tab then "selected" else "unselected", fadeInfo)
            end
        end
        self:_setTabSectionsVisible(true)
        self:_setTabSectionsShown(true, fadeInfo)

        self:_revealElements(0.035, 0.4)
    end)

    -- Drag handle grows in with the chrome, same width sweep it uses on first reveal. Position
    -- is recalculated against the full restored size - if the window was minimised (a shorter
    -- bar-hang offset) before hiding, it would otherwise reappear at the old, wrong height.
    task.delay(growDuration * 0.63, function()
        self.drag.drag.Position =
            UDim2.new(target.X.Scale, target.X.Offset, target.Y.Scale, target.Y.Offset + self.size.Y.Offset / 2 + 15)
        self.drag.dragCosmetic.Size = UDim2.fromOffset(0, 4)
        self.drag.dragCosmetic.BackgroundTransparency = 1
        self.drag.drag.Visible = true
        variables.tweenService
            :Create(self.drag.dragCosmetic, growInfo, { Size = UDim2.fromOffset(100, 4), BackgroundTransparency = 0.7 })
            :Play()
    end)

    task.delay(growDuration * 1.71, function()
        self.animating = false
        self._revealing = false
    end)
end

local loadingFadeInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
-- Back/Out overshoots past the target then settles back - the "pop" on the icon. Safe to animate
-- Size here specifically because this overlay is a free-floating Frame with hand-placed
-- (Position-offset, not UIListLayout) children - nothing here reflows a sibling the way animating
-- Size inside a UIListLayout-managed row would (see resize.luau/label.luau's own notes on that
-- class of bug elsewhere in this codebase). None of that risk applies to a one-off splash with
-- three fixed-position children.
local loadingPopInfo = TweenInfo.new(0.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
local loadingTipSlideInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local loadingIconSize = 48
local loadingIconStartSize = 22

-- Vertical rhythm for the splash's stacked text - fixed pixel box heights with top-aligned text,
-- not the UDim2.fromScale heights this had before. Live-caught: a Scale height ties the box to
-- the *whole window's* height, not the font, so at a normal window size the box came out far
-- taller than the one line of text inside it - and with the default TextYAlignment (Center), the
-- glyphs sat in the middle of that oversized box while every offset below still assumed a small,
-- tightly-wrapping one. The visible symptom was the progress bar reading as glued to the tip
-- above it: the bar's own Y already accounted for a gap that existed in the data, just not on
-- screen, because the tip's real glyphs extended further down than the box's "size" implied.
local loadingTitleHeight = 26
local loadingTipHeight = 18
local loadingBarGap = 18 -- deliberately roomy - requested outright, was reading as glued before

-- The dev-configured loading splash (see self.loading, set from WindowProps.loading in .new):
-- icon pops in (scale bounce + a soft accent glow) over the still-blank window card, the title
-- fades in with it, an optional tip line cycles under them - crossfading with a slight upward
-- slide, like a ticker - while a thin progress bar underneath fills across the splash's real
-- total duration. Everything fades back out before _firstShow's own staged reveal takes over.
-- Unlike PlayGreeting there's no shrink/corner-round wipe here - nothing underneath is visible
-- yet for one to reveal, so a plain fade in and back out is the whole trick.
function Window:_playLoadingSplash()
    local config = self.loading
    local icon = config.icon or self.icon
    local title = config.title or self.name
    local tips = config.tips

    -- Opaque, not just "on top" - live-caught toggle tracks and other resting-state chrome (not
    -- part of the staged reveal's own fade-in chain, styled visible at construction regardless
    -- of self.hidden) showing straight through a transparent-background overlay, and the overlay
    -- not filling the full card the way PlayGreeting's own opaque one does. Same white-base +
    -- WindowColor-gradient recipe main itself uses (see main's own creation above) so this reads
    -- as "the window itself, just showing loading content" rather than a mismatched flash, and
    -- its own UICorner matches the window's rounding so a square overlay corner never pokes past
    -- main's rounded one.
    local overlay = self:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.loading,

        Parent = self.main,
    })

    self:Create("UICorner", {
        Parent = overlay,
    }, { CornerRadius = "CornerRoundness" })

    -- the gradient (not BackgroundColor3 itself) is what actually recolours the white base to
    -- the theme's WindowColor - a Frame's BackgroundColor3 wants a Color3, not the ColorSequence
    -- toColorSequence produces, same reason main's own gradient is a separate child instead
    self:Create("UIGradient", {
        Rotation = 270,
        Offset = Vector2.new(0, -0.1),

        Parent = overlay,
    }, { Color = { "WindowColor", functions.toColorSequence } })

    local iconLabel, iconGlow
    if icon then
        iconLabel = self:Create("ImageLabel", {
            Image = icon,
            Size = UDim2.fromOffset(loadingIconStartSize, loadingIconStartSize),
            Position = UDim2.new(0.5, 0, 0.5, -18),
            AnchorPoint = Vector2.new(0.5, 1),
            BackgroundTransparency = 1,
            ImageTransparency = 1,
            ZIndex = constants.zIndex.loading,

            Parent = overlay,
        }, { ImageColor3 = "ContentColor" })

        -- soft glow behind the icon, same helper every other accent glow in this codebase uses
        iconGlow = self:CreateGlow(iconLabel, "AccentColor", 22, 1)
    end

    local titleY = if icon then 4 else -10
    local titleLabel = self:Create("TextLabel", {
        Text = locale.t(title or ""),

        Size = UDim2.new(0.85, 0, 0, loadingTitleHeight),
        Position = UDim2.new(0.5, 0, 0.5, titleY),
        AnchorPoint = Vector2.new(0.5, 0),
        BackgroundTransparency = 1,
        TextSize = 22,
        TextWrapped = true,
        TextYAlignment = Enum.TextYAlignment.Top,
        TextTransparency = 1,
        FontFace = self.theme.TitleFont,
        ZIndex = constants.zIndex.loading,

        Parent = overlay,
    }, { TextColor3 = "ContentColor" })

    local tipRestY = titleY + loadingTitleHeight + 8
    local tipLabel
    if #tips > 0 then
        tipLabel = self:Create("TextLabel", {
            Size = UDim2.new(0.8, 0, 0, loadingTipHeight),
            Position = UDim2.new(0.5, 0, 0.5, tipRestY + 6), -- starts a hair low, slides up as it fades in
            AnchorPoint = Vector2.new(0.5, 0),
            BackgroundTransparency = 1,
            TextSize = 14,
            TextWrapped = true,
            TextYAlignment = Enum.TextYAlignment.Top,
            TextTransparency = 1,
            FontFace = self.theme.Font,
            ZIndex = constants.zIndex.loading,

            Parent = overlay,
        }, { TextColor3 = "ContentColor" })
    end

    -- Thin fill bar under everything else, tracking real elapsed time against the splash's own
    -- total duration - an actual progress readout, not just a decorative loop. barY starts from
    -- whichever text actually sits above it (tip if there is one, title otherwise) plus a
    -- deliberately roomy gap, rather than the cramped one this had before.
    local barY = (if #tips > 0 then tipRestY + loadingTipHeight else titleY + loadingTitleHeight) + loadingBarGap
    local progressTrack = self:Create("Frame", {
        Size = UDim2.fromOffset(120, 3),
        Position = UDim2.new(0.5, 0, 0.5, barY),
        AnchorPoint = Vector2.new(0.5, 0),
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.loading,

        BackgroundTransparency = 1, -- In = 0.85

        Parent = overlay,
    }, { BackgroundColor3 = "SurfaceStroke" })
    self:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = progressTrack })

    local progressFill = self:Create("Frame", {
        Size = UDim2.fromScale(0, 1),
        BorderSizePixel = 0,
        ZIndex = constants.zIndex.loading,

        BackgroundTransparency = 1, -- In = 0

        Parent = progressTrack,
    }, { BackgroundColor3 = "AccentColor" })
    self:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = progressFill })

    -- Soft sheen riding across the fill, same loop technique shimmerlabel.luau uses for its own
    -- sweep (a tween back and forth on a UIGradient's Offset, re-armed via Completed:Wait() - not
    -- RenderStepped, and self-terminating the moment progressFill is gone, which overlay:Destroy()
    -- at the very end of this function takes care of).
    local fillShimmer = self:Create("UIGradient", {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(0.4, 1),
            NumberSequenceKeypoint.new(0.5, 0.5),
            NumberSequenceKeypoint.new(0.6, 1),
            NumberSequenceKeypoint.new(1, 1),
        }),
        Offset = Vector2.new(-1, 0),

        Parent = progressFill,
    })
    task.spawn(function()
        while fillShimmer.Parent do
            fillShimmer.Offset = Vector2.new(-1, 0)
            local tween = variables.tweenService:Create(
                fillShimmer,
                TweenInfo.new(1.1, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut),
                { Offset = Vector2.new(1, 0) }
            )
            tween:Play()
            tween.Completed:Wait()
            task.wait(0.15)
        end
    end)

    -- Percentage readout, right of the track - a plain task.wait loop against a wall-clock
    -- start time (not RenderStepped), so it's cheap and self-terminates the same way the shimmer
    -- above does once the overlay (and this label with it) is destroyed.
    local percentLabel = self:Create("TextLabel", {
        Text = "0%",
        Size = UDim2.fromOffset(34, 14),
        Position = UDim2.new(1, 10, 0.5, 0),
        AnchorPoint = Vector2.new(0, 0.5),
        BackgroundTransparency = 1,
        TextSize = 11,
        TextXAlignment = Enum.TextXAlignment.Left,
        TextTransparency = 1,
        FontFace = self.theme.Font,
        ZIndex = constants.zIndex.loading,

        Parent = progressTrack,
    }, { TextColor3 = "PlaceholderColor" })

    -- Real total time the splash stays up: the tip cycle's own length, floored by `duration` so
    -- a single (or zero) tip doesn't flash by. The fill bar's own tween is timed to this exact
    -- number, so it always finishes right as the splash starts fading out, never early or late.
    local tipCycleTime = if #tips > 0 then #tips * config.tipHoldTime + (#tips - 1) * 0.15 else 0
    local totalTime = math.max(config.duration, tipCycleTime)

    task.spawn(function()
        local start = os.clock()
        while percentLabel.Parent and os.clock() - start < totalTime do
            percentLabel.Text = math.floor(math.clamp((os.clock() - start) / totalTime, 0, 1) * 100) .. "%"
            task.wait(0.1)
        end
        if percentLabel.Parent then
            percentLabel.Text = "100%"
        end
    end)

    if iconLabel then
        variables.tweenService
            :Create(iconLabel, loadingPopInfo, { Size = UDim2.fromOffset(loadingIconSize, loadingIconSize) })
            :Play()
        variables.tweenService:Create(iconLabel, loadingFadeInfo, { ImageTransparency = 0 }):Play()
        if iconGlow then
            variables.tweenService:Create(iconGlow, loadingFadeInfo, { Transparency = 0.75 }):Play()
        end
    end
    variables.tweenService:Create(titleLabel, loadingFadeInfo, { TextTransparency = 0 }):Play()
    variables.tweenService:Create(progressTrack, loadingFadeInfo, { BackgroundTransparency = 0.85 }):Play()
    variables.tweenService:Create(progressFill, loadingFadeInfo, { BackgroundTransparency = 0 }):Play()
    variables.tweenService:Create(percentLabel, loadingFadeInfo, { TextTransparency = 0.3 }):Play()
    variables.tweenService
        :Create(progressFill, TweenInfo.new(totalTime, Enum.EasingStyle.Linear), { Size = UDim2.fromScale(1, 1) })
        :Play()

    -- Cycle the tips (if any) the same way PlayGreeting cycles its texts, crossfading with a
    -- slight upward slide (ticker feel) instead of a plain opacity swap. Tracks how long this
    -- actually took so the wait below only ever makes up the difference to `totalTime`.
    local elapsed = 0
    if tipLabel then
        for i, tip in tips do
            tipLabel.Text = locale.resolve(tostring(tip))
            tipLabel.Position = UDim2.new(0.5, 0, 0.5, tipRestY + 6)
            variables.tweenService:Create(tipLabel, loadingTipSlideInfo, {
                TextTransparency = 0.4,
                Position = UDim2.new(0.5, 0, 0.5, tipRestY),
            }):Play()
            task.wait(config.tipHoldTime)
            elapsed += config.tipHoldTime
            if i < #tips then
                variables.tweenService:Create(tipLabel, loadingTipSlideInfo, {
                    TextTransparency = 1,
                    Position = UDim2.new(0.5, 0, 0.5, tipRestY - 6),
                }):Play()
                task.wait(0.15)
                elapsed += 0.15
            end
        end
    end

    if elapsed < totalTime then
        task.wait(totalTime - elapsed)
    end

    if iconLabel then
        variables.tweenService:Create(iconLabel, loadingFadeInfo, { ImageTransparency = 1 }):Play()
        if iconGlow then
            variables.tweenService:Create(iconGlow, loadingFadeInfo, { Transparency = 1 }):Play()
        end
    end
    variables.tweenService:Create(titleLabel, loadingFadeInfo, { TextTransparency = 1 }):Play()
    variables.tweenService:Create(progressTrack, loadingFadeInfo, { BackgroundTransparency = 1 }):Play()
    variables.tweenService:Create(progressFill, loadingFadeInfo, { BackgroundTransparency = 1 }):Play()
    variables.tweenService:Create(percentLabel, loadingFadeInfo, { TextTransparency = 1 }):Play()
    if tipLabel then
        variables.tweenService:Create(tipLabel, loadingFadeInfo, { TextTransparency = 1 }):Play()
    end
    task.wait(loadingFadeInfo.Time)

    overlay:Destroy()
end

function Window:_firstShow()
    -- Intro animation
    self.elements.Visible = true
    self.tabList.Visible = true
    self.tabDock.Visible = true
    self.drag.drag.Visible = false
    self.main.Visible = true

    if self.loading and self.settings.loadingAnimationEnabled then
        -- Loading splash: main snaps straight to its resting size/opacity instead of growing in
        -- - nothing else on it is visible yet anyway (every bit of chrome below is still at its
        -- hidden transparency, untouched until the splash clears), so there's nothing to hide
        -- and nothing lost by skipping the grow tween here. The splash plays centred on that
        -- otherwise-blank card, then fades itself out, and the rest of this function's own
        -- staged reveal (shadow, icon, title, tabs, elements, ...) runs exactly as it always did.
        local target, prop = self:_mainVisual()
        target[prop] = 1 - self.windowOpacity
        self.main.Size = self.size
        self:_playLoadingSplash()
    else
        -- Size always animates on self.main itself (mainSquircle just fills it via
        -- Size = fromScale(1,1) and rides along) - only the opacity property/target differs
        -- between plain and squircle mode, via _mainVisual.
        local target, prop = self:_mainVisual()
        local growInfo = TweenInfo.new(1, Enum.EasingStyle.Exponential, Enum.EasingDirection.InOut)
        variables.tweenService:Create(self.main, growInfo, { Size = self.size }):Play()
        variables.tweenService:Create(target, growInfo, { [prop] = 1 - self.windowOpacity }):Play()
        -- let the frame actually read as a window before anything shows on top of it. Trimmed
        -- from 0.85 - the grow tween itself still runs its full second underneath, this is only
        -- how long the chrome waits before starting to fade in over it.
        task.wait(0.45)
    end

    -- Live-caught: drag.luau computes the bar's very first rest position once, at construction,
    -- against whatever self.size happened to be *then* - if a persisted custom size loads and
    -- changes self.size afterward (the normal case: settings load after Drag.new runs), main
    -- ends up at that larger/smaller size above but the bar is never told to recompute, so it
    -- stays parked wherever the construction-time size put it - which, for a saved size bigger
    -- than the default, lands it well inside the window instead of hanging under its real bottom
    -- edge. Read as "the drag bar sometimes ends up inside the UI" (regrabbing it "fixes" it only
    -- because InputBegan's own getTargets() call forces a fresh read). Resyncing here, now that
    -- main is actually at its true resting size, is the first point that value is reliably known.
    self:_syncDragBar()
    variables.tweenService
        :Create(
            self.windowShadow,
            TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            { Transparency = self._shadowTransparency or 0.6 }
        )
        :Play()
    variables.tweenService
        :Create(
            self.bottomFade,
            TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            { BackgroundTransparency = 0 }
        )
        :Play()
    variables.tweenService
        :Create(
            self.topFade,
            TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            { BackgroundTransparency = 0 }
        )
        :Play()
    task.wait(0.15)

    if self.icon then
        variables.tweenService
            :Create(
                self.topbarIcon,
                TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { ImageTransparency = 0 }
            )
            :Play()
    end
    if self.title then
        variables.tweenService
            :Create(
                self.title,
                TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { TextTransparency = 0 }
            )
            :Play()
    end
    task.wait(0.1)
    if self.subtitle then
        variables.tweenService
            :Create(
                self.subtitle,
                TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                { TextTransparency = 0.7 }
            )
            :Play()
    end

    for _, action in ipairs(self.actionContainer:GetChildren()) do
        if action:IsA("Frame") then
            task.wait(0.02)
            variables.tweenService
                :Create(
                    action.ImageLabel,
                    TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
                    { ImageTransparency = 0.6 }
                )
                :Play()
        end
    end

    for _, tag in self.tags do
        tag:_setShown(true, TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out))
    end

    task.wait(0.2)

    task.spawn(function()
        for _, tab in pairs(self.tabs) do
            if not tab.neglectSelector then
                tab.topbarItem.Visible = true
                tab:_applyVisual(
                    if self.selectedTab == tab then "selected" else "unselected",
                    TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
                )

                -- 0.15s each meant a 16-tab hub spent 2.4s just staggering its own tab list in -
                -- live-reported as the window taking far too long to finish appearing. Still a
                -- visible cascade at 0.035s, just one that scales to a real hub's tab count.
                task.wait(0.035)
            end
        end
        self:_setTabSectionsVisible(true)
        self:_setTabSectionsShown(true, TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out))
    end)

    self:_revealElements(0.03, 2)

    -- the drag bar is the last thing in; 1s here was pure dead time at the end of an open that
    -- already looks finished by this point
    task.wait(0.35)

    self.drag.drag.Visible = true
    variables.tweenService
        :Create(
            self.drag.dragCosmetic,
            TweenInfo.new(0.6, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            { BackgroundTransparency = 0.7 }
        )
        :Play()
    variables.tweenService
        :Create(
            self.drag.dragCosmetic,
            TweenInfo.new(1, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out),
            { Size = UDim2.fromOffset(100, 4) }
        )
        :Play()
    -- Same grow-and-fade, same moment - explicit ask to have the resize corner wake up
    -- alongside the drag bar instead of just always having been there.
    if self.resize then
        self.resize:_reveal()
    end

    self.animating = false
    self._revealing = false

    -- Welcome the user once if this is a new/changed account on this device (unless they've
    -- turned it off in settings). Just a toast now - the profile chip is a toast like any other.
    local localPlayer = variables.localPlayer
    if localPlayer and self.settings.welcomeToast and chrome.isNewUser() then
        self:Toast({
            title = localPlayer.DisplayName,
            subtitle = locale.resolve("Signed in as"),
            subtitleAbove = true, -- reads "Signed in as" / name, label over value
            avatar = localPlayer.UserId,
            minWidth = 220, -- match the old license card's width for that roomy right-hand space
        })
    end

    -- Guided tour, after everything else has finished revealing (animating/_revealing both
    -- false above) so it isn't racing the staged fade-in for the very elements it's about to
    -- point at. Once per player - self.settings.tourSeen flips true the moment the tour ends
    -- (finished or skipped, see Tour:finish) and persists from there.
    if self.tourSteps and not self.settings.tourSeen then
        self.tour:start(self.tourSteps)
    end
end

function Window:GetPath()
    return persistence.getPath(self)
end

-- name saves to a specific config; omit it to save the default file.
function Window:Save(name)
    if name ~= nil and (type(name) ~= "string" or name == "") then
        return false
    end
    return persistence.save(self, name)
end

-- name loads a specific config; omit it to load the default file.
function Window:Load(name)
    if name ~= nil and (type(name) ~= "string" or name == "") then
        return false
    end
    return persistence.load(self, name)
end

-- Load a named config and make it the live state autoLoad restores next session. Loading only
-- applies to the running UI; writing it back to the default file is what carries it across
-- sessions, so the config manager can pick a config once and have it stick.
function Window:_applyNamedConfig(name)
    if not self:Load(name) then
        return false
    end
    self:Save()
    return true
end

-- Public name for _applyNamedConfig - Fluent calls this shape "autoload" (SaveManager:
-- LoadAutoloadConfig, picking one saved config to be what loads automatically next session).
-- _applyNamedConfig already *is* that: load the named config live, then Save() to the default
-- file so it's what a plain Load()/autoLoad picks up from here on. This is just the
-- discoverable public name for calling that on demand, same as the Settings "Load" button does.
function Window:SetAutoloadConfig(name)
    return self:_applyNamedConfig(name)
end

-- Play a guided tour on demand - the same thing that plays automatically on first show if the
-- dev configured one (see _firstShow), just callable any time (a "Replay Tour" settings button,
-- a help menu, whatever). Omit steps to replay whatever was configured at CreateWindow.
function Window:StartTour(steps)
    self.tour:start(steps or self.tourSteps)
end

function Window:ListConfigs()
    return persistence.list(self)
end

function Window:DeleteConfig(name)
    return persistence.delete(self, name)
end

-- Encode every control's current value to a JSON string and, best-effort, put it on the
-- clipboard (silently a no-op copy if the executor has no setclipboard-shaped function - see
-- clipboard.luau). Always returns the string too, so a dev can hand it to the player some other
-- way (a text box to select-all-copy from) when the clipboard write itself didn't take.
function Window:ExportConfig(): (boolean, string?)
    local ok, encoded = persistence.encode(self)
    if not ok or not encoded then
        return false, nil
    end
    clipboard.copy(encoded)
    return true, encoded
end

-- Parse a pasted config string (the exact shape ExportConfig produces) and apply it to every
-- currently-built control. Doesn't touch the config *file* - same relationship Load() has to
-- Save(), importing only changes the running UI unless the caller also calls Save() to carry it
-- across sessions the way the Settings "Configurations" UI's own Load button does.
function Window:ImportConfig(raw: string): boolean
    local flags = persistence.decode(raw)
    if not flags then
        return false
    end
    return persistence.applyFlags(self, flags)
end

-- Read a flag's current value, or nil if nothing is registered under it.
function Window:Get(flag)
    local control = self.controls[flag]
    return control and control.value
end

-- Set a flag's value, routing through the control so the UI updates and the callback fires.
-- Returns false if no control is registered under the flag.
function Window:Set(flag, value)
    local control = self.controls[flag]
    if not control then
        return false
    end
    control:Set(value)
    return true
end

-- Register a plain value under a flag so it rides the window's own config persistence
-- (Save/Load/autoSave/autoLoad) exactly like a visible control's value, without needing an
-- on-screen toggle/slider to hang the flag off of - e.g. a consumer script's own dragged sidebar
-- width or a floating HUD's dragged position, both real per-player state with nothing built-in
-- to persist them. onChanged (optional) fires with the value any time it changes - both from a
-- live Window:Set(flag, ...)/control:Set(...) call and from a config Load() restoring a saved
-- one - so the caller has one place to apply it back onto whatever it actually controls.
-- The returned control's own :Set(value) is what a consumer wires its live changes through (see
-- Window:OnSidebarWidthChanged/Hud:OnPositionChanged for the pattern) so those changes get saved.
function Window:RegisterFlag(flag: string, initial: unknown, onChanged: ((unknown) -> ())?)
    local window = self
    local control = { value = initial, flag = flag }
    function control:Set(value)
        self.value = value
        if onChanged then
            onChanged(value)
        end
        window:_persist(self)
    end
    window:_registerControl(control)
    return control
end

-- Jump to a tab by handle, name, or its page instance. No-ops on an unknown tab rather
-- than handing JumpTo something it cant resolve.
-- Move the page view only. Tab:Select owns the selection state and the pill, and calls this
-- for the scroll; nothing else should jump pages without going through it.
function Window:_jumpTo(page)
    if page then
        self.elementsLayout:JumpTo(page)
    end
end

-- Go to a tab, by name or by the tab itself. Routes through Tab:Select so the selection,
-- the pill and the page all agree; jumping the page alone would leave the wrong tab lit and
-- the reveal animations pointed at the wrong elements.
function Window:Navigate(tab)
    if tab == nil then
        return
    end

    local target
    for _, candidate in self.tabs do
        -- by name, by the tab itself, or by the page instance a caller held onto
        if candidate == tab or candidate.name == tab or candidate.tabPage == tab then
            target = candidate
            break
        end
    end

    if not target then
        return
    end
    target:Select()
end

function Window:Create(className, properties, themeProperties)
    assert(typeof(className) == "string", "Invalid argument #1 (string expected)")
    local instance = Instance.new(className)

    -- Themed properties apply first so animation start-states in `properties` (e.g. a hidden
    -- BackgroundTransparency = 1) still win at build; the theme value is the reveal target.
    if themeProperties and self.theme then
        for property, value in themeProperties do
            instance[property] = (
                if typeof(value) == "table" then value[2](self.theme[value[1]]) else self.theme[value]
            )
        end

        self.themeProperties[instance] = themeProperties
    end

    if properties then
        for property, value in properties do
            if locale.isToken(value) then
                self:_bindLocale(instance, property, locale.sourceOf(value))
            else
                image.assign(instance, property, value)
            end
        end
    end

    table.insert(self.instances, instance)
    return instance
end

-- Bind instance[property] to a source string: set it to the active locale's form now and remember
-- it so SetLocale can re-resolve in place without rebuilding anything. Mirrors how themeProperties
-- lets ChangeTheme re-apply themed values later.
function Window:_bindLocale(instance, property, source)
    instance[property] = locale.resolve(source)

    local entries = self.localeProperties[instance]
    if not entries then
        entries = {}
        self.localeProperties[instance] = entries
    end
    entries[property] = source
end

-- Swap every localized label to `localeId` in place. Element values, slider readouts and other
-- data aren't copy, so they're untouched. AutomaticSize reflows widths for us; the few manually
-- measured labels (toasts) are transient enough not to need a re-measure.
function Window:SetLocale(localeId)
    locale.setActive(localeId)
    for instance, entries in self.localeProperties do
        for property, source in entries do
            instance[property] = locale.resolve(source)
        end
    end
end

-- Swap the dev translation hook (source, localeId) -> string?. Follow with SetLocale (or pass the
-- same locale back) to re-resolve everything already on screen through the new hook.
function Window:SetTranslator(translator)
    locale.translator = translator
end

-- Merge more translation tables in at runtime ({ [localeId] = { [source] = translated } }) and
-- re-apply the active locale, so a language pack added after the UI is built lands immediately.
function Window:RegisterTranslations(tables)
    locale.register(tables)
    self:SetLocale(locale.current)
end

-- Soft glow behind a GuiObject via a native UIShadow (no image). ZIndex -1 keeps it behind.
-- `color` is a Color3 for a fixed glow, or a theme key (string) for a shadow that tracks the
-- theme and re-tints on ChangeTheme - a ColorSequence key resolves to its first keypoint.
function Window:CreateGlow(parent, color, blur, transparency)
    local properties = {
        BlurRadius = UDim.new(0, blur),
        Transparency = transparency,
        ZIndex = -1,

        Parent = parent,
    }

    if typeof(color) == "string" then
        return self:Create("UIShadow", properties, {
            Color = {
                color,
                function(value)
                    return if typeof(value) == "ColorSequence" then value.Keypoints[1].Value else value
                end,
            },
        })
    end

    properties.Color = color
    return self:Create("UIShadow", properties)
end

-- Flash an element's inset box + glow to signal a set landed: green for a good set, red for a
-- rejected one, then settle back to the box's idle look. green/red are our universal accents.
-- The element supplies `box`, an optional `glow`, and its idle transparencies (_boxIdle/_glowIdle).
function Window:_flashResult(element, ok)
    local box = element.box
    if not box then
        return
    end
    local glow = element.glow
    local stroke = element.boxStroke
    local fill = ok and constants.accent.on or self.theme.ErrorColor
    local edge = ok and constants.accent.onStroke or self.theme.ErrorStrokeColor
    local inInfo = TweenInfo.new(0.1, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local outInfo = TweenInfo.new(0.45, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

    -- a quick coloured pulse: box fill tints (transparency untouched), edge + glow brighten
    variables.tweenService:Create(box, inInfo, { BackgroundColor3 = fill }):Play()
    if stroke then
        variables.tweenService:Create(stroke, inInfo, { Color = edge, Transparency = 0.4 }):Play()
    end
    if glow then
        variables.tweenService:Create(glow, inInfo, { Color = edge, Transparency = 0.6 }):Play()
    end

    -- token so a quick re-set restarts the flash instead of an old revert cutting it short
    element._flashToken = (element._flashToken or 0) + 1
    local token = element._flashToken
    task.delay(0.22, function()
        if element._flashToken ~= token then
            return
        end
        variables.tweenService:Create(box, outInfo, { BackgroundColor3 = self.theme.FieldBackground }):Play()
        if stroke then
            variables.tweenService
                :Create(stroke, outInfo, { Color = self.theme.SurfaceStroke, Transparency = 0.85 })
                :Play()
        end
        if glow then
            variables.tweenService
                :Create(glow, outInfo, { Color = self.theme.FieldGlow, Transparency = element._glowIdle or 1 })
                :Play()
        end
    end)
end

-- Additive white hover-brighten overlay filling an element (fill colour comes from the gradient).
-- Tween its BackgroundTransparency 1 -> ~0.97 on hover.
function Window:CreateHoverOverlay(parent)
    local overlay = self:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 1,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        ZIndex = 1,

        Parent = parent,
    })

    self:Create("UICorner", {
        Parent = overlay,
    }, { CornerRadius = "ElementCornerRadius" })

    return overlay
end

-- hover: brighten stroke + title (+ overlay). shared by button/toggle
function Window:_wireElementHover(element)
    local info = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local theme = self.theme

    self:Connect(element.main.MouseEnter, function()
        if not self:_interactive() then
            return -- window still revealing/hiding: dont light up mid-animation
        end
        variables.tweenService
            :Create(
                element.stroke,
                info,
                { Transparency = theme.ElementStrokeHoverTransparency, Color = theme.ElementStrokeHover }
            )
            :Play()
        variables.tweenService:Create(element.title, info, { TextColor3 = theme.ElementTextHoverColor }):Play()
        if element.hoverOverlay then
            variables.tweenService:Create(element.hoverOverlay, info, { BackgroundTransparency = 0.97 }):Play()
        end
    end)

    self:Connect(element.main.MouseLeave, function()
        variables.tweenService
            :Create(
                element.stroke,
                info,
                { Transparency = theme.ElementStrokeTransparency, Color = theme.ElementStroke }
            )
            :Play()
        variables.tweenService:Create(element.title, info, { TextColor3 = theme.ContentColor }):Play()
        if element.hoverOverlay then
            variables.tweenService:Create(element.hoverOverlay, info, { BackgroundTransparency = 1 }):Play()
        end
    end)
end

-- Tooltip: one shared bubble per window, repositioned and reused for whichever element is
-- currently hovered. Held white regardless of theme - it needs to read clearly against any
-- card colour, not blend into it.
local tooltipShowDelay = 0.5
local tooltipFadeIn = TweenInfo.new(0.2, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local tooltipFadeOut = TweenInfo.new(0.12, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local tooltipMaxWidth = 220
local tooltipCursorGap = 14 -- clears the cursor's own hotspot/hand icon

-- Screen-space mouse position, in the same coordinate space as our GuiObjects' AbsolutePosition.
-- Sounds like it should just be GetMouseLocation() as-is: our ScreenGui sets IgnoreGuiInset =
-- true, so its children's AbsolutePosition is inset-free, and GetMouseLocation() is documented
-- to already exclude the inset too - two things already in the same space needing no correction
-- between them. Measured wrong on the live test client though: with no correction at all, a
-- GuiObject's rendered AbsolutePosition still comes out exactly GetGuiInset().Y (58px) SMALLER
-- than the Y its own Position was set to - i.e. this ScreenGui is silently still applying the
-- inset shift on this executor regardless of IgnoreGuiInset. Confirmed the fix the same way:
-- placed the tooltip with no correction, read its real AbsolutePosition back, and it was short
-- by exactly GetGuiInset().Y - so it has to be ADDED back on the way in to land where intended,
-- the opposite of the subtraction this used to do (which made the shortfall twice as bad).
function Window:_mouseAbsolutePosition()
    local mouse = variables.userInputService:GetMouseLocation()
    local topLeftInset = variables.guiService:GetGuiInset()
    return Vector2.new(mouse.X, mouse.Y + topLeftInset.Y)
end

function Window:_ensureTooltip()
    if self.tooltipFrame then
        return
    end

    self.tooltipFrame = self:Create("Frame", {
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        AutomaticSize = Enum.AutomaticSize.XY,
        Size = UDim2.fromOffset(0, 0),
        Visible = false,
        ZIndex = constants.zIndex.tooltip,

        Parent = self.screenGui,
    })

    self:Create("UICorner", {
        CornerRadius = UDim.new(0, 8),
        Parent = self.tooltipFrame,
    })

    self:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 10),
        PaddingRight = UDim.new(0, 10),
        PaddingTop = UDim.new(0, 6),
        PaddingBottom = UDim.new(0, 6),

        Parent = self.tooltipFrame,
    })

    self.tooltipLabel = self:Create("TextLabel", {
        Text = "",
        BackgroundTransparency = 1,
        AutomaticSize = Enum.AutomaticSize.XY,
        Size = UDim2.fromOffset(0, 0),
        TextSize = 13,
        TextWrapped = true,
        TextColor3 = Color3.fromRGB(25, 25, 25),
        ZIndex = constants.zIndex.tooltip,

        TextTransparency = 1,

        Parent = self.tooltipFrame,
    }, { FontFace = "Font" })

    -- caps the wrap width so long copy wraps onto more lines instead of one wide bubble
    self:Create("UISizeConstraint", {
        MaxSize = Vector2.new(tooltipMaxWidth, math.huge),
        Parent = self.tooltipLabel,
    })
end

function Window:_showTooltip(text)
    self:_ensureTooltip()

    self.tooltipLabel.Text = locale.resolve(text)

    local mouse = self:_mouseAbsolutePosition()
    self.tooltipFrame.AnchorPoint = Vector2.new(0.5, 1)
    self.tooltipFrame.Position = UDim2.fromOffset(mouse.X, mouse.Y - tooltipCursorGap)
    self.tooltipFrame.Visible = true
    self.tooltipFrame.BackgroundTransparency = 1
    self.tooltipLabel.TextTransparency = 1

    self._tooltipToken = (self._tooltipToken or 0) + 1

    variables.tweenService:Create(self.tooltipFrame, tooltipFadeIn, { BackgroundTransparency = 0.05 }):Play()
    variables.tweenService:Create(self.tooltipLabel, tooltipFadeIn, { TextTransparency = 0 }):Play()
end

function Window:_hideTooltip()
    if not self.tooltipFrame or not self.tooltipFrame.Visible then
        return
    end

    self._tooltipToken = (self._tooltipToken or 0) + 1
    local token = self._tooltipToken

    variables.tweenService:Create(self.tooltipFrame, tooltipFadeOut, { BackgroundTransparency = 1 }):Play()
    variables.tweenService:Create(self.tooltipLabel, tooltipFadeOut, { TextTransparency = 1 }):Play()

    task.delay(tooltipFadeOut.Time, function()
        if self._tooltipToken == token and self.tooltipFrame then
            self.tooltipFrame.Visible = false
        end
    end)
end

-- Wires a hover-hold tooltip onto element.main (or element.tooltipTarget, for an element whose
-- main is a transparent wrapper - see the dropdown) if element.tooltip is set. Independent of
-- _wireElementHover so it applies uniformly whether or not the element wires its own hover
-- tint (the slider, dropdown, colorpicker etc. all do that separately).
function Window:_wireTooltip(element)
    if not element.tooltip or element.tooltip == "" then
        return
    end

    local target = element.tooltipTarget or element.main
    local pending = 0

    self:ConnectFor(element, target.MouseEnter, function()
        if not self:_interactive() then
            return -- window still revealing/hiding: dont pop a tooltip mid-animation
        end
        pending += 1
        local token = pending
        task.delay(tooltipShowDelay, function()
            if pending == token then
                self:_showTooltip(element.tooltip)
            end
        end)
    end)

    self:ConnectFor(element, target.MouseLeave, function()
        pending += 1 -- invalidates any pending show, whether or not it had already fired
        self:_hideTooltip()
    end)
end

-- run a callback with the red error-flash on failure, debounced via element._errored so a
-- slider firing every frame flashes once. shared by every interactive element. elements whose
-- `main` is a transparent wrapper (the dropdown) set `flashTarget` to the frame to tint.
function Window:_runGuarded(element, fn, ...)
    local args = table.pack(...)
    task.spawn(function()
        local ok, err = pcall(function()
            return fn(table.unpack(args, 1, args.n))
        end)
        if ok or element._errored then
            return
        end
        element._errored = true

        local flashFrame = element.flashTarget or element.main
        local quickOut = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
        variables.tweenService:Create(flashFrame, quickOut, { BackgroundColor3 = self.theme.ErrorColor }):Play()
        variables.tweenService:Create(element.stroke, quickOut, { Color = self.theme.ErrorStrokeColor }):Play()
        -- minimal elements build without a label, and the flash must survive that
        if element.title then
            element.title.Text = locale.resolve("Error, log recorded in console.")
        end

        log.warn(
            `Rayfield encountered an error, with the callback for a {element.__type} component named '{element.name}':`
        )
        log.print(err)

        task.wait(1)

        if element.title then
            element.title.Text = locale.resolve(element.name)
        end
        variables.tweenService
            :Create(
                flashFrame,
                TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.In),
                { BackgroundColor3 = Color3.fromRGB(255, 255, 255) }
            )
            :Play()
        variables.tweenService
            :Create(
                element.stroke,
                TweenInfo.new(0.6, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                { Color = self.theme.ElementStroke }
            )
            :Play()
        element._errored = false
    end)
end

-- Runs fn(...) in a pcall and logs a warning on failure instead of letting it fail silently or
-- propagate uncaught - the general-purpose version of the same "never let an error just
-- disappear" principle _runGuarded/Toggle:Loop apply to a callback/loop tick specifically. Meant
-- for any one-off risky call a feature makes on its own (an instance lookup that might not
-- exist, a remote invoke) that isn't already wrapped by one of those. Returns exactly what pcall
-- returns (ok, result...) - this doesn't swallow the failure, just makes sure it's never
-- invisible, so the caller can still branch on `ok` itself.
function Window:Safe(fn, ...)
    local results = table.pack(pcall(fn, ...))
    if not results[1] then
        log.warn("Rayfield: Window:Safe call errored - " .. tostring(results[2]))
    end
    return table.unpack(results, 1, results.n)
end

-- Retries fn(attempt) up to options.attempts times (default 3), waiting
-- options.baseDelay * 2^(attempt-1) seconds between each (default 1s base: 1s, 2s, 4s, ...),
-- capped at options.maxDelay (default 10s) - exponential backoff so a flaky remote call/HTTP
-- request gets a few real chances to recover from a transient hiccup without hammering it (or a
-- rate limit) on a tight retry loop. Returns the same (ok, result) shape pcall/Safe do: true plus
-- fn's own result the moment it succeeds, or false plus the last error once every attempt is
-- spent. Only for something worth retrying at all - a resource that's actually gone for good
-- (an instance that got destroyed, a bad argument) just fails the same way every attempt and
-- burns the whole backoff for nothing; reach for Window:Safe instead for those.
function Window:RetryWithBackoff(fn, options: { attempts: number?, baseDelay: number?, maxDelay: number? }?)
    options = if typeof(options) == "table" then options else {}
    local attempts = options.attempts or 3
    local baseDelay = options.baseDelay or 1
    local maxDelay = options.maxDelay or 10

    local lastError
    for attempt = 1, attempts do
        local ok, result = pcall(fn, attempt)
        if ok then
            return true, result
        end
        lastError = result
        if attempt < attempts then
            task.wait(math.min(baseDelay * (2 ^ (attempt - 1)), maxDelay))
        end
    end
    log.warn(
        "Rayfield: Window:RetryWithBackoff gave up after " .. attempts .. " attempts - " .. tostring(lastError)
    )
    return false, lastError
end

-- Standard element body: white base + gradient fill + rounded corner + flat stroke (hidden until shown).
-- Returns the stroke; call after creating `main` with a white BackgroundColor3.
function Window:StyleElementBody(main)
    -- Devlog 7 fix: every card's fill rides ElementTransparency, which SetTransparency now
    -- scales all the way to 1 on purpose (a fully "glass" window) - a plain Frame's default
    -- Active is false, and per Roblox's own rule that stops it blocking/capturing input in its
    -- own bounds the instant BackgroundTransparency actually reaches 1, same as self.main's own
    -- fix. Centralized here rather than touching every component's own main creation, since
    -- every card-shaped element already calls this right after building main.
    (main :: any).Active = true

    self:Create("UIGradient", {
        Rotation = 270,

        Parent = main,
    }, { Color = "ElementGradient" })

    self:Create("UICorner", {
        Parent = main,
    }, { CornerRadius = "ElementCornerRadius" })

    return self:Create("UIStroke", {
        Transparency = 1,

        Parent = main,
    }, { Color = "ElementStroke", Transparency = "ElementStrokeTransparency" })
end

-- Devlog 6 lock system -------------------------------------------------------------------
-- A small padlock. Tries the real Lucide "lock" icon first (see icons.luau - fetched from this
-- project's own pinned-commit GitHub mirror, the same HttpGet + loadstring approach every other
-- dev-loadstring asset in this codebase already uses, not a server RemoteFunction like WindUI's
-- own loader leans on, since an executor-injected library can't stand one of those up in
-- someone else's game). Falls back to drawing one from two plain frames (a rounded body + a
-- thin rounded shackle arc) if the
-- pack isn't reachable, so a dead repo dims a locked element's glyph in quality, never removes
-- it outright. Shared by every lockable element (Button, Toggle, Dropdown, Tab, HoldButton) so
-- the glyph and its math live in exactly one place.
function Window:_buildLockIcon(parent, position, anchorPoint)
    local holder = self:Create("Frame", {
        AnchorPoint = anchorPoint or Vector2.new(1, 0.5),
        Position = position or UDim2.new(1, -16, 0.5, 0),
        Size = UDim2.fromOffset(14, 14),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,
        Visible = false,

        Parent = parent,
    })

    local lockIcon = icons.find("lock", "lucide")
    if lockIcon then
        self:Create("ImageLabel", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Image = lockIcon.Image,
            ZIndex = 5,

            Parent = holder,
        }, { ImageColor3 = "PlaceholderColor" })

        return holder
    end

    local body = self:Create("Frame", {
        Position = UDim2.new(0.5, 0, 1, 0),
        AnchorPoint = Vector2.new(0.5, 1),
        Size = UDim2.fromOffset(14, 9),
        BorderSizePixel = 0,
        ZIndex = 5,

        Parent = holder,
    }, { BackgroundColor3 = "PlaceholderColor" })
    self:Create("UICorner", { CornerRadius = UDim.new(0, 3), Parent = body })

    local shackle = self:Create("Frame", {
        Position = UDim2.new(0.5, 0, 1, -8),
        AnchorPoint = Vector2.new(0.5, 1),
        Size = UDim2.fromOffset(9, 8),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 5,

        Parent = holder,
    })
    self:Create("UIStroke", {
        Thickness = 2,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,

        Parent = shackle,
    }, { Color = "PlaceholderColor" })
    self:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = shackle })

    return holder
end

-- The "no entry" glyph shown to the left of a locked element's title. Tries the real Lucide
-- "ban" icon first, same fallback story as the padlock above (a hand-drawn ring + diagonal
-- slash if the pack isn't reachable). A plain flowed child of `parent`'s own icon/title row:
-- toggling .Visible re-flows the row around it automatically, no absolute positioning to keep
-- in sync.
function Window:_buildProhibitedIcon(parent, layoutOrder)
    local holder = self:Create("Frame", {
        Size = UDim2.fromOffset(14, 14),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        LayoutOrder = layoutOrder or -1,
        Visible = false,

        Parent = parent,
    })

    local banIcon = icons.find("ban", "lucide")
    if banIcon then
        self:Create("ImageLabel", {
            Size = UDim2.fromScale(1, 1),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            Image = banIcon.Image,

            Parent = holder,
        }, { ImageColor3 = "PlaceholderColor" })

        return holder
    end

    local ring = self:Create("Frame", {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,

        Parent = holder,
    })
    self:Create("UICorner", { CornerRadius = UDim.new(1, 0), Parent = ring })
    self:Create("UIStroke", {
        Thickness = 2,
        ApplyStrokeMode = Enum.ApplyStrokeMode.Border,

        Parent = ring,
    }, { Color = "PlaceholderColor" })

    self:Create("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(16, 2),
        Rotation = 45,
        BorderSizePixel = 0,

        Parent = holder,
    }, { BackgroundColor3 = "PlaceholderColor" })

    return holder
end

-- Dim title/icon, show/hide the padlock built above (and the "no entry" glyph, if the caller
-- built one too). `element` needs .locked, .title, .lockIcon, and optionally .iconLabel/
-- .prohibitedIcon. Doesn't touch input - callers guard their own click/drag handlers with
-- `if element.locked then return end`.
function Window:_applyLockedVisual(element, animate)
    local info = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local set = function(instance, props)
        if not instance then
            return
        end
        if animate then
            variables.tweenService:Create(instance, info, props):Play()
        else
            for prop, value in props do
                instance[prop] = value
            end
        end
    end

    if element.lockIcon then
        element.lockIcon.Visible = true
    end
    if element.prohibitedIcon then
        element.prohibitedIcon.Visible = element.locked
    end
    set(element.title, { TextTransparency = if element.locked then 0.6 else 0 })
    if element.iconLabel then
        set(element.iconLabel, { ImageTransparency = if element.locked then 0.6 else 0 })
    end
    if not element.locked and element.lockIcon then
        task.delay(if animate then info.Time else 0, function()
            if not element.locked and element.lockIcon then
                element.lockIcon.Visible = false
            end
        end)
    end
end

-- Shared scaffold for the compact button/toggle row: the white body + stroke, the fill flex
-- so it shares the row width, and the click surface. Callers add their own padding + content
-- into the returned interact, keeping the two elements identical where they should be.
function Window:_buildCompactRow(host, name, interactZIndex)
    local main = self:Create("Frame", {
        Name = name,
        Size = UDim2.fromOffset(0, compactRowHeight),
        AutomaticSize = Enum.AutomaticSize.X,
        ClipsDescendants = true, -- overflow guard
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BorderSizePixel = 0,

        BackgroundTransparency = 1, -- In = ElementTransparency

        Parent = host.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })

    local stroke = self:StyleElementBody(main)

    -- share the row width (grow + shrink)
    self:Create("UIFlexItem", {
        FlexMode = Enum.UIFlexMode.Fill,
        Parent = main,
    })

    -- main flows + fills the interact
    self:Create("UIListLayout", {
        SortOrder = Enum.SortOrder.LayoutOrder,
        FillDirection = Enum.FillDirection.Horizontal,
        VerticalAlignment = Enum.VerticalAlignment.Center,
        HorizontalFlex = Enum.UIFlexAlignment.Fill,

        Parent = main,
    })

    -- clickable wrapper, doubles as the hover-brighten surface
    local interact = self:Create("TextButton", {
        Text = "",
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 1, -- hover fades to 0.97
        AutomaticSize = Enum.AutomaticSize.X,
        Size = UDim2.fromOffset(0, compactRowHeight),
        BorderSizePixel = 0,
        TextTransparency = 1,
        ZIndex = interactZIndex or 1,

        Parent = main,
    })

    self:Create("UICorner", {
        Parent = interact,
    }, { CornerRadius = "ElementCornerRadius" })

    return main, stroke, interact
end

-- Like StyleElementBody but with a gradient stroke (subtle sheen) instead of a flat one.
-- White stroke base tinted by the ElementStrokeGradient. Used by the dropdown's header +
-- options cards. Returns the stroke.
function Window:StyleElementPanel(frame)
    self:Create("UIGradient", {
        Rotation = 270,

        Parent = frame,
    }, { Color = "ElementGradient" })

    self:Create("UICorner", {
        Parent = frame,
    }, { CornerRadius = "ElementCornerRadius" })

    local stroke = self:Create("UIStroke", {
        Color = Color3.fromRGB(255, 255, 255),
        Transparency = 1, -- In = ElementStrokeTransparency

        Parent = frame,
    })

    self:Create("UIGradient", {
        Rotation = 270,

        Parent = stroke,
    }, { Color = "ElementStrokeGradient" })

    return stroke
end

-- Reveal a single instance: instantly set props when animate is false, else tween them with info.
function Window:_reveal(instance, props, animate, info)
    if not instance then
        return
    end
    if animate then
        variables.tweenService:Create(instance, info or revealInfo, props):Play()
    else
        for property, value in props do
            instance[property] = value
        end
    end
end

-- Reveal the parts every non-Section element shares (fill/stroke/title/icon/descriptor).
function Window:_revealCommon(element, animate)
    -- locked-aware: an element flagged .locked dims to the same 0.6 _applyLockedVisual uses,
    -- computed as this call's own target instead of a second tween chasing it in afterward -
    -- two simultaneous tweens on the same property fight each other frame to frame instead of
    -- one cleanly winning (the same class of bug as the tab indicator's own tween race), which
    -- is exactly what calling _applyLocked right after this used to do.
    local titleTransparency = if element.locked then 0.6 else 0
    self:_reveal(element.stroke, { Transparency = self.theme.ElementStrokeTransparency }, animate)
    self:_reveal(element.title, { TextTransparency = titleTransparency }, animate)
    self:_reveal(element.main, { BackgroundTransparency = self.theme.ElementTransparency or 0 }, animate)
    if element.iconLabel then
        self:_reveal(element.iconLabel, { ImageTransparency = titleTransparency }, animate)
    end
    if element.descriptor then
        self:_reveal(element.descriptor.titleLabel, { TextTransparency = 0.7 }, animate)
    end
end

-- The reverse of _revealCommon: fade the same shared parts back out to fully transparent.
function Window:_hideCommon(element, animate)
    self:_reveal(element.stroke, { Transparency = 1 }, animate)
    self:_reveal(element.title, { TextTransparency = 1 }, animate)
    self:_reveal(element.main, { BackgroundTransparency = 1 }, animate)
    if element.iconLabel then
        self:_reveal(element.iconLabel, { ImageTransparency = 1 }, animate)
    end
    if element.descriptor then
        self:_reveal(element.descriptor.titleLabel, { TextTransparency = 1 }, animate)
    end
end

-- The rect main morphs into once collapsed: the same top-centre spot the old standalone
-- restore pill used to sit at, translated into main's own centre-anchored space (main never
-- changes AnchorPoint, so its Position always addresses its centre, not its top edge).
function Window:_collapsedRect()
    local size = collapsedSize
    local home = UDim2.new(
        collapsedTop.X.Scale,
        collapsedTop.X.Offset,
        collapsedTop.Y.Scale,
        collapsedTop.Y.Offset + size.Y.Offset / 2
    )
    return home, size
end

-- true only when the window is fully shown and idle. hover/press animations gate on this so
-- nothing lights up mid show/hide/minimise reveal, while elements are still tweening in.
function Window:_interactive()
    return not self.animating and not self.hidden
end

-- Touch-primary heuristic: TouchEnabled with no mouse says "phone/tablet" more reliably than
-- TouchEnabled alone (a touch-screen laptop has both). Exposed publicly so a dev's own script
-- can branch on it too, not just the library's own resize-grip scaling (see mobileHitScale).
function Window:IsMobile(): boolean
    local uis = variables.userInputService
    return uis.TouchEnabled and not uis.MouseEnabled
end

-- Detects a frozen render thread: RenderStepped stops firing while Heartbeat keeps ticking (a
-- stalled render is often invisible to a plain "is the game still running" check, since
-- physics/server-driven Heartbeat can carry on fine while the screen itself is stuck). Fires
-- `callback(secondsSinceLastRender)` once RenderStepped has been silent for longer than
-- thresholdSeconds (default 5) while the window is actually focused - a legitimately unfocused
-- client (alt-tabbed, minimized) throttles RenderStepped on its own and that's not a freeze, so
-- it's exempted rather than tripping a false positive. This only detects; it never acts on its
-- own (no forced rejoin, no teleport) - what to do about a freeze (log it, notify the player,
-- attempt a reconnect) is entirely the caller's call.
function Window:OnRenderFreeze(callback, thresholdSeconds)
    thresholdSeconds = thresholdSeconds or 5
    local lastRender = os.clock()
    local focused = true
    local tripped = false

    self:Connect(variables.userInputService.WindowFocused, function()
        focused = true
    end)
    self:Connect(variables.userInputService.WindowFocusReleased, function()
        focused = false
    end)
    self:Connect(variables.runService.RenderStepped, function()
        lastRender = os.clock()
        tripped = false
    end)
    self:Connect(variables.runService.Heartbeat, function()
        if not focused then
            lastRender = os.clock() -- dont accumulate frozen-time while legitimately unfocused
            return
        end
        local frozenFor = os.clock() - lastRender
        if frozenFor >= thresholdSeconds and not tripped then
            tripped = true
            task.spawn(callback, frozenFor)
        end
    end)
end

-- true when the window is up and not mid reveal or hide. action icons settle on this rather
-- than _interactive: minimise animates too, but it never repaints the icons the way show and
-- hide do, so an icon settling during it has nothing to fight and would otherwise stay lit.
function Window:_settled()
    return not self.hidden and not self._revealing
end

function Window:Connect(signal, callback)
    local connection = signal:Connect(callback)
    table.insert(self.connections, connection)
    return connection
end

-- Like Connect, but also files the connection on the element that owns it, so Tab:Remove can
-- tear an element's connections down instead of leaving them tracked until Unload. Every
-- persistent element connection funnels through here.
function Window:ConnectFor(owner, signal, callback)
    local connection = self:Connect(signal, callback)
    owner.connections = owner.connections or {}
    table.insert(owner.connections, connection)
    return connection
end

-- Disconnect a connection from Window:Connect and drop it from the tracked list.
-- Transient UI (dropdown popups, removed tabs) calls this so open/close churn doesnt
-- pile up dead entries that only get cleared at Unload.
function Window:Disconnect(connection)
    if not connection then
        return
    end
    local index = table.find(self.connections, connection)
    if index then
        table.remove(self.connections, index)
    end
    connection:Disconnect()
end

-- Destroy a subtree and forget every tracked instance inside it. Transient elements
-- (notifications) use this instead of a bare Destroy so self.instances doesnt grow
-- for the whole session.
function Window:DestroySubtree(root)
    if not root then
        return
    end

    local inSubtree = { [root] = true }
    for _, descendant in root:GetDescendants() do
        inSubtree[descendant] = true
    end
    for i = #self.instances, 1, -1 do
        local instance = self.instances[i]
        if inSubtree[instance] then
            table.remove(self.instances, i)
            self.themeProperties[instance] = nil
            self.localeProperties[instance] = nil
        end
    end

    root:Destroy()
end

function Window:Unload()
    -- Run every OnUnload callback first, while every instance is still alive and self.unloaded is
    -- still false - a callback that reads window state (a toggle's own .value, an element still
    -- on screen) sees it exactly as it was the moment Unload was called. pcall'd individually so
    -- one throwing dev callback can't stop the rest from running or strand the real teardown below.
    for _, callback in self._unloadCallbacks do
        local ok, err = pcall(callback)
        if not ok then
            log.warn("Rayfield: an OnUnload callback errored - " .. tostring(err))
        end
    end

    self.unloaded = true
    -- drop our own slot in the singleton registry, but only if it's still us - a newer window
    -- with the same name may have already replaced us there (that's what called us in the first
    -- place), and we mustn't clobber its entry.
    local registry = windowRegistry()
    if registry[self.name] == self then
        registry[self.name] = nil
    end
    if self._localeRefresh then
        locale.removeListener(self._localeRefresh)
        self._localeRefresh = nil
    end
    -- Acrylic is a global Lighting effect, not scoped to this window's own ScreenGui - leaving
    -- it on here would leak a permanent blur into the game with nothing left to ever turn it
    -- back off.
    if self.acrylicEnabled then
        acrylic.setEnabled(false)
    end
    -- drop our effects and release the gui they hung on, but leave the enabled flag alone -
    -- another window may still be open and haptics arent ours to switch off for it
    hapticEngine.teardown()
    hapticEngine.releaseContainer(self.screenGui)
    soundEngine.releaseContainer(self.screenGui)
    if self._liveTween then
        self._liveTween:Cancel() -- unparks the LiveAnimation loop before we destroy the gradient
        self._liveTween = nil
    end
    for i = #self.connections, 1, -1 do
        self.connections[i]:Disconnect()
    end
    for i = #self.instances, 1, -1 do
        self.instances[i]:Destroy()
    end

    -- destroying isnt forgetting: a hub that loads and unloads repeatedly would keep the whole
    -- dead instance graph reachable through the handle it still holds. DestroySubtree already
    -- clears as it goes, so match it here.
    table.clear(self.connections)
    table.clear(self.instances)
    table.clear(self.themeProperties)
    table.clear(self.localeProperties)
    table.clear(self.controls)
    table.clear(self.tabs)
end

-- Register cleanup for your own state that Window:Unload has no way to know about on its own -
-- stopping a loop's flag, putting the character back at spawn, dropping a highlight, whatever a
-- feature needs undone. Fires synchronously, in registration order, right as Unload starts -
-- before self.unloaded flips true and before any instance is torn down, so a callback can still
-- safely read anything (a toggle's own .value, an element still on screen) exactly as it was the
-- moment Unload was called. A throwing callback is caught and logged, not left to strand the
-- real teardown that follows it.
function Window:OnUnload(callback: () -> ())
    table.insert(self._unloadCallbacks, callback)
end

return Window
]=====]

sources["components/windowMethods"] = [=====[
--!nonstrict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Part of the Window class - see window.luau's own header comment for why this file exists
-- (Roblox's 200,000 character ModuleScript Source limit) and windowCore.luau's for how the split
-- actually holds together (a shared core module, not a circular require). Every `function
-- Window:X` below attaches to the exact same table window.luau's Window.new builds instances
-- against - this file is required purely for that side effect, from window.luau's own tail.

local core = require(script.Parent.windowCore)
local Window = core.Window

-- Utility (aliased off windowCore so every split file shares the exact same module instances -
-- see windowCore.luau's own header comment)
local image = core.image
local functions = core.functions
local persistence = core.persistence
local constants = core.constants
local locale = core.locale
local log = core.log
local hapticEngine = core.hapticEngine
local soundEngine = core.soundEngine
local windowSizing = core.windowSizing
local icons = core.icons
local acrylic = core.acrylic
local clipboard = core.clipboard
local chrome = core.chrome
local search = core.search
local tabSelector = require(script.Parent.tabSelector)
local filesystem = core.filesystem
local path = core.path
local variables = core.variables
local themes = core.themes

-- Shared constants/helpers (see windowCore.luau)
local revealInfo = core.revealInfo
local collapsedSize = core.collapsedSize
local collapsedTop = core.collapsedTop
local maxToastWidth = core.maxToastWidth
-- Ported from upstream Rayfield Gen2 1.2's own fix: a top-centre toast used to land at the same
-- spot the collapsed "Tap to show" pill rests at, live-overlapping it. Closed, the stack drops
-- to just below the pill instead; open, it sits back at its normal spot under the topbar.
local topToastOpenPosition = UDim2.new(0.5, 0, 0, 12)
local topToastClosedPosition = UDim2.new(0.5, 0, 0, collapsedTop.Y.Offset + collapsedSize.Y.Offset + 12)
local compactRowHeight = core.compactRowHeight
local viewportReconcileInterval = core.viewportReconcileInterval
local fitWindowSize = core.fitWindowSize
local resolveCustomSize = core.resolveCustomSize
local fontChoices = core.fontChoices
local fontOptionNames = core.fontOptionNames
local fontAtWeight = core.fontAtWeight
local gradientKeys = core.gradientKeys
local coerceThemeValue = core.coerceThemeValue
local firstColor = core.firstColor
local edgeShade = core.edgeShade
local deriveStrokes = core.deriveStrokes
local themeOverrides = core.themeOverrides
local resolveTheme = core.resolveTheme
local WINDOW_REGISTRY_KEY = core.WINDOW_REGISTRY_KEY
local windowRegistry = core.windowRegistry

function Window:_syncLiveAnimation()
    if not self.theme.LiveAnimation then
        self._liveAnimating = false -- the running loop sees this and stops after its current leg
        return
    end
    if self._liveAnimating then
        return -- already drifting
    end

    self._liveAnimating = true
    -- generation stamp: an old loop parked in Completed:Wait() through a static->animated
    -- swap wakes up stale and exits, instead of drifting alongside the new loop
    self._liveGeneration = (self._liveGeneration or 0) + 1
    local generation = self._liveGeneration
    task.spawn(function()
        local out = true
        local tweenInfo = TweenInfo.new(10, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

        while self._liveGeneration == generation and self._liveAnimating and not self.unloaded do
            local tweenW = variables.tweenService:Create(self.windowGradient, tweenInfo, {
                Offset = Vector2.new(if out then 0.4 else -0.2, 0),
                Rotation = (if out then 220 else 280),
            })

            self._liveTween = tweenW
            tweenW:Play()
            tweenW.Completed:Wait()
            out = not out
        end
        if self._liveGeneration == generation then
            self._liveAnimating = false
            self._liveTween = nil
        end
    end)
end

-- Re-applies the per-window visual overrides passed at CreateWindow (cornerRadius/borderColor/
-- gradientColorSequence/shadowColor - see window.luau's own construction-time comment on these)
-- on top of self.theme. Called once at construction and again from ChangeTheme below, which
-- otherwise re-resolves self.theme from scratch and would silently drop them right back to
-- whatever the newly-picked theme's own defaults are.
function Window:_applyThemeOverrides()
    if self._cornerRadiusOverride then
        self.theme.CornerRoundness = UDim.new(0, self._cornerRadiusOverride)
    end
    if self._borderColorOverride then
        self.theme.SurfaceStroke = self._borderColorOverride
        self._showBorder = true
    end
    if self._gradientColorOverride then
        self.theme.WindowColor = self._gradientColorOverride
    end
    if self._shadowColorOverride then
        self.theme.ShadowColor = self._shadowColorOverride
    end
end

function Window:ChangeTheme(theme)
    -- A named theme fully switches: resolve against default so keys it omits reset rather than
    -- lingering from the previous theme. A partial table just overrides the keys it names.
    local overrides = if typeof(theme) == "table" then theme else resolveTheme(theme)
    for name, value in overrides do
        self.theme[name] = coerceThemeValue(name, value)
    end
    -- match the constructor: a hand-written table gets derived strokes for the keys it changes
    if typeof(theme) == "table" then
        deriveStrokes(self.theme, overrides)
    end
    -- re-pin this window's own per-window overrides on top of whatever the swap just resolved -
    -- see _applyThemeOverrides' own comment for why this has to happen here too, not just once.
    self:_applyThemeOverrides()

    for instance, properties in self.themeProperties do
        for property, value in properties do
            local targetValue = if typeof(value) == "table" then value[2](self.theme[value[1]]) else self.theme[value]

            if typeof(targetValue) == "Color3" or typeof(targetValue) == "number" then
                variables.tweenService
                    :Create(
                        instance,
                        TweenInfo.new(0.5, Enum.EasingStyle.Quint, Enum.EasingDirection.Out),
                        { [property] = targetValue }
                    )
                    :Play()
            else
                instance[property] = targetValue
            end
        end
    end

    -- themeProperties above only carry plain colours; reveal-driven transparencies and state
    -- colours (the toggle knob, field fills, glows) aren't, so refresh the elements to reach
    -- them on a live swap. Every tab's elements stay shown (just page-clipped), settings
    -- included, so refresh them all; groups forward the call to their children.
    if self.hidden then
        -- a hidden window has nothing to animate into, so defer the refresh to the next Show
        -- rather than dropping it and reopening with the old themes state colours
        self._themeRefreshPending = true
    else
        self:_refreshElementThemes()
    end

    self:_syncLiveAnimation()

    -- see OnThemeChanged's own comment - a dev's own hand-built RichText (baked-in <font
    -- color="..."> literals) needs telling explicitly, unlike every Rayfield-built element above.
    for _, callback in self._themeChangedCallbacks do
        task.spawn(callback, self.theme)
    end
end

-- Register a callback for whenever the active theme changes (ChangeTheme, including a player's
-- own Settings > Color theme swap) - fires with the new theme table. Rayfield's own elements
-- already retint themselves via themeProperties/refreshElementThemes; this is for a consumer
-- script's own hand-built RichText (e.g. a `<font color="rgb(...)">` baked from theme.AccentColor
-- at label-creation time) that has no other way to hear about a later swap.
function Window:OnThemeChanged(callback: (theme: { [string]: any }) -> ())
    table.insert(self._themeChangedCallbacks, callback)
end

-- Devlog 6/7 Settings > Font picker: "Auto" (the brand font) or any built-in Roblox font by
-- name. Just a partial ChangeTheme under the hood - Font/TitleFont are already ordinary
-- themeProperties (every FontFace = "Font"/"TitleFont" binding made via Create), so swapping
-- them through here reaches every live element the same way any other theme change does.
function Window:SetFont(name)
    local key = string.lower(tostring(name or "auto"))
    if key ~= "auto" and fontChoices[key] == nil then
        log.warn("Rayfield: unknown font '" .. tostring(name) .. "', using Auto")
        key = "auto"
    end
    self.fontChoice = key

    local titleFont, bodyFont
    if key == "auto" then
        titleFont = variables.brandFont(Enum.FontWeight.SemiBold)
        bodyFont = variables.brandFont(Enum.FontWeight.Medium)
    else
        local enumFont = fontChoices[key]
        titleFont = fontAtWeight(enumFont, Enum.FontWeight.SemiBold)
        bodyFont = fontAtWeight(enumFont, Enum.FontWeight.Medium)
    end

    self:ChangeTheme({ Font = bodyFont, TitleFont = titleFont })
end

-- Devlog 7 "glass window": 0 (fully opaque, default) to 100 (fully invisible). Scales the
-- window frame, the tab dock, and every card uniformly so it all reads as one sheet of glass
-- rather than a stack of independently-faded pieces. Cards ride along for free: ElementTransparency
-- is an ordinary themeProperty already, so pushing a scaled value through ChangeTheme reaches
-- every card the same way any other live theme change does. self.main and self.tabDock aren't
-- theme-bound (their own baselines - fully opaque and 0.2 - are plain literals set once at
-- creation, not read from the theme), so those two get tweened directly instead.
--
-- Reaching literal BackgroundTransparency 1 is safe: a plain Frame's default Active is false,
-- and per Roblox's own rule that stops it blocking/capturing input in its own bounds the moment
-- transparency hits exactly 1 - live-caught this at 100%, the whole window (and every card,
-- ElementTransparency-bound the same way) went click-through to the game behind it, which is
-- what "can't drag the handle back" and "the UI goes into the game's background" both were.
-- Fixed at the source instead of just avoiding the value: self.main, self.tabDock, and every
-- card (via Window:StyleElementBody, or directly where a component styles its own card outside
-- that helper) now set Active = true explicitly, so they stay clickable at any transparency.
function Window:SetTransparency(percent)
    percent = math.clamp(percent, 0, 100)
    self.windowOpacity = 1 - percent / 100

    self:ChangeTheme({ ElementTransparency = 1 - self.windowOpacity })

    local info = TweenInfo.new(0.3, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local target, prop = self:_mainVisual()
    variables.tweenService:Create(target, info, { [prop] = 1 - self.windowOpacity }):Play()
    -- Sidebar mode's own visible fill lives on tabDockCard now, not tabDock itself (see its own
    -- construction comment) - tabDock there stays permanently transparent as a plain structural
    -- container, so tweening it directly would visibly do nothing.
    variables.tweenService
        :Create(self.tabDockCard or self.tabDock, info, { BackgroundTransparency = 1 - 0.8 * self.windowOpacity })
        :Play()
end

-- Devlog 7 "Acrylic Blur": frosts the game behind the window via a Lighting.BlurEffect (see
-- acrylic.luau for why that, and not the DepthOfFieldEffect trick some other UI libraries lean
-- on, is the right tool here). size is BlurEffect.Size (roughly 0-56); omit for a sane default.
function Window:SetAcrylic(enabled, size)
    self.acrylicEnabled = enabled and true or false
    acrylic.setEnabled(self.acrylicEnabled, size)
end

function Window:_refreshElementThemes()
    for _, tab in self.tabs do
        for _, element in tab.elements do
            if element._refreshTheme then
                element:_refreshTheme()
            end
        end
    end
end

function Window:CreateTab(properties)
    local newTab = require(script.Parent.tab).new(self, properties)

    table.insert(self.tabs, newTab)

    -- Tab.new's own construction always builds a visible title (it has no way to know the
    -- sidebar's current width yet, since self.tabs doesn't include this tab until the line
    -- above) - re-applying the window's already-known width immediately covers a tab created
    -- collapsed-by-default (sidebarCollapsed/sidebarWidth at CreateWindow) or one added later
    -- while a player's already dragged the rail down to icon-only.
    if self.tabsMode == "Sidebar" then
        self:_applySidebarWidth(self.sidebarWidth)
    end

    if not newTab.neglectSelector then
        local isFirstVisible = true
        for _, tab in self.tabs do
            if tab ~= newTab and not tab.neglectSelector then
                isFirstVisible = false
                break
            end
        end
        if isFirstVisible then
            newTab:Select(true)
        end

        -- a tab built after the window is already open reveals its pill right away, the
        -- same way _register shows late elements. hidden/minimised windows reveal on restore.
        if not self.hidden and not self.minimised then
            newTab.topbarItem.Visible = true
            newTab:_applyVisual(
                if self.selectedTab == newTab then "selected" else "unselected",
                TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
            )
        end
    end

    return newTab
end

-- A heading in the sidebar rail (Sidebar tabsMode only - see tabSection.luau's own header
-- comment for why it does nothing on the top strip). Same props as a Tab's own CreateSection,
-- and it groups the tab rows created after it the way that one groups elements. Ported from
-- upstream Rayfield Gen2 1.2's own Tab Sections.
function Window:CreateSection(properties)
    assert(not self.unloaded, "Cannot create a section on an unloaded window.")
    local section = require(script.Parent.tabSection).new(self, properties)
    table.insert(self.tabSections, section)

    -- a section built while the rail is already collapsed has to come up as a rule, not a
    -- heading nobody can read
    if not section.inert then
        section:_setCollapsed(self.sidebarWidth <= self.sidebarCollapsedWidth)
    end

    -- built after the window is already open: reveal it now, the same way a late tab reveals
    -- its row rather than waiting for the next open
    if not section.inert and not self.hidden and not self.minimised then
        section:_setVisible(true)
        section:_setShown(true, TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out))
    end

    return section
end

-- Sections ride with the rows they label, so every path that fades or hides the rail's rows
-- says the same thing to them.
function Window:_setTabSectionsShown(shown, tweenInfo)
    for _, section in self.tabSections do
        section:_setShown(shown, tweenInfo)
    end
end

function Window:_setTabSectionsVisible(visible)
    for _, section in self.tabSections do
        section:_setVisible(visible)
    end
end

-- Element Locking, ported from upstream Rayfield Gen2 1.2. Lock or unlock one element - it
-- dims and an opaque scrim (see _buildLockScrim) physically covers it, so a real click never
-- reaches the control underneath and its own callback simply never runs. `reason` replaces the
-- element's description while it's locked, so the UI can say why without covering the element
-- up to do it. Reached through the lockable.luau mixin's own Lock/Unlock/IsLocked - see that
-- file's header comment for which components use this directly vs. their own bespoke
-- SetLocked.
local lockScrimTransparency = 0.55
local lockedDescriptionTransparency = 0.55

function Window:_setElementLocked(element, locked, reason)
    locked = locked == true
    -- locked starts out nil, so compare against a real boolean: `nil == false` is false, and
    -- Unlock on an element that was never locked would otherwise build a scrim just to fade it
    -- straight back out. A fresh reason on an already-locked element is still worth applying.
    local wasLocked = element.locked == true
    if wasLocked == locked and not (locked and reason) then
        return
    end
    element.locked = locked

    if not element.lockScrim then
        self:_buildLockScrim(element)
    end

    local info = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

    if locked then
        element.lockScrim.Visible = true
    end
    variables.tweenService
        :Create(element.lockScrim, info, {
            BackgroundTransparency = if locked then lockScrimTransparency else 1,
        })
        :Play()
    if not locked then
        task.delay(info.Time, function()
            if not element.locked and element.lockScrim then
                element.lockScrim.Visible = false -- out of hit-testing once it has faded
            end
        end)
    end

    -- say why in the description, and put the element's own back when it unlocks
    local descriptor = element.descriptor
    if not descriptor then
        return
    end

    if locked then
        -- `or`, not plain assignment: re-locking with a new reason must not remember the old
        -- reason as though it were the element's own description
        element._descriptionBefore = element._descriptionBefore or descriptor.titleLabel.Text
        descriptor.titleLabel.Text = locale.resolve(reason or "This element is locked.")
    elseif element._descriptionBefore then
        descriptor.titleLabel.Text = element._descriptionBefore
        element._descriptionBefore = nil
    end

    variables.tweenService
        :Create(descriptor.titleLabel, info, {
            TextTransparency = if locked then lockedDescriptionTransparency else 0.7,
        })
        :Play()
end

-- The scrim: a sheet of the window's own colour over the element, dimming it. It carries
-- nothing itself - it's the dimming and the description that say what's happened. It is an
-- Active button, so it swallows anything aimed at the element underneath rather than leaving
-- each element to check a flag on every input path.
local function firstColor(value)
    return if typeof(value) == "ColorSequence" then value.Keypoints[1].Value else value
end

function Window:_buildLockScrim(element)
    element.lockScrim = self:Create("TextButton", {
        Name = "ElementLock",
        Active = true,
        AutoButtonColor = false,
        Size = UDim2.fromScale(1, 1),
        BorderSizePixel = 0,
        Text = "",
        TextTransparency = 1,
        ZIndex = 60, -- over the element's own content, so a locked element cant be reached through it
        Visible = false,

        -- no literal BackgroundColor3 here: Create applies the theme first and plain properties
        -- second, so setting it both ways would paint straight over the themed colour
        BackgroundTransparency = 1, -- In = lockScrimTransparency

        Parent = element.main,
    }, { BackgroundColor3 = { "WindowColor", firstColor } })

    self:Create("UICorner", {
        Parent = element.lockScrim,
    }, { CornerRadius = "ElementCornerRadius" })
end

-- Alias for CreateTab({ neglectSelector = true }) - a tab left out of the normal tab dock,
-- reachable only by calling :Select() on it yourself (typically from a button/stat elsewhere -
-- "See full details" -> detailsTab:Select()). Good for a drill-down screen (full diagnostics, an
-- expanded account view) that would clutter the main tab list if it sat there permanently.
-- neglectSelector itself already existed (it's how the built-in Rayfield Settings tab stays out
-- of the dock) - this is just a clearer public name for a dev reaching for the same thing on
-- purpose, matching the "hidden tab + a card linking into it" pattern both hub scripts land on
-- independently for the same reason.
-- A small draggable status chip independent of the main window (see hud.luau's own header
-- comment) - stays visible and keeps updating even while the window itself is hidden. Returns a
-- handle with :SetText(text) and :Destroy().
function Window:CreateHUD(properties)
    return require(script.Parent.hud).new(self, properties)
end

function Window:CreateHiddenTab(properties)
    properties = if typeof(properties) == "table" then table.clone(properties) else {}
    properties.neglectSelector = true
    return self:CreateTab(properties)
end

-- Sidebar mode only. self.sidebarWidth is a fixed constant now (no more player drag handle -
-- see window.luau's own comment) - this just re-derives tabDock and the content pane's Size/
-- Position from it, the same formula window.luau's constructor used in the first place. Kept as
-- its own method (rather than inlined at each call site) since CreateTab's own re-application
-- and the public SetSidebarWidth wrapper below both still need to call it.
-- The sidebar is a fixed width now (self.sidebarWidth, matching upstream Rayfield Gen2 1.2's own
-- railWidth) - no more player drag handle or icon-only collapse state, so this just applies
-- self.sidebarWidth itself regardless of what's asked for. Kept (rather than removed outright)
-- so SetSidebarWidth/OnSidebarWidthChanged/CreateTab's own re-application still have a real,
-- harmless method to call instead of erroring.
function Window:_applySidebarWidth(_width: number?)
    -- The window's own width is the only input: narrow enough and the rail collapses to icons
    -- (upstream's railCollapseBelow/railCollapsedWidth), otherwise it's the full rail.
    local windowWidth = self.size and self.size.X.Offset or self.main.AbsoluteSize.X
    -- A dev (or SetSidebarCollapsed) can pin it either way; nil means follow the window's width.
    local collapsed = if self._sidebarCollapsedOverride ~= nil
        then self._sidebarCollapsedOverride
        else windowWidth < self.sidebarCollapseBelow
    local width = if collapsed then self.sidebarCollapsedWidth else self.sidebarFullWidth
    self.sidebarWidth = width

    self.tabDock.Size = UDim2.new(0, width, 1, -85)
    -- self.elements is anchored (1,1) now (flush against the window's own right/bottom edges -
    -- see window.luau's own construction comment), so only its Size needs re-deriving here.
    self.elements.Size = UDim2.new(1, -width, 1, -70)

    for _, tab in self.tabs do
        if not tab.neglectSelector then
            tabSelector.setRowCollapsed(tab, collapsed)
        end
    end

    -- Section headings have nowhere near enough width to read on a collapsed rail, so they
    -- become a plain rule between the icon runs instead (see tabSection.luau).
    for _, section in self.tabSections do
        section:_setCollapsed(collapsed)
    end

    -- the search field sits beside the rail in this layout, so it moves with it
    search.railWidth(self, width)

    -- Profile chip follows the same collapse: avatar alone, centred, once there's no room for
    -- the name/subtitle column beside it.
    if self.profile then
        self.profile.Size = UDim2.fromOffset(width, self.profileFooterHeight)
        self.profileContainer.Position = UDim2.new(0, if collapsed then 0 else 12, 0.5, 0)
        self.profileContainer.Size = UDim2.new(1, if collapsed then 0 else -12, 1, 0)
        self.profileLayout.HorizontalAlignment = if collapsed
            then Enum.HorizontalAlignment.Center
            else Enum.HorizontalAlignment.Left
        self.profileLabels.Visible = not collapsed
    end
end

-- Hear about every real sidebar-width change (drag, SetSidebarWidth, or CreateTab's own
-- re-application), regardless of who caused it - e.g. a consumer script mirroring the live width
-- into its own persisted flag (see Window:RegisterFlag in windowExtra.luau).
function Window:OnSidebarWidthChanged(callback: (width: number) -> ())
    table.insert(self._sidebarWidthChangedCallbacks, callback)
end

-- Public wrapper - a dev can call this directly (e.g. restoring a player's last dragged width
-- from their own saved data) without reaching into the underscore-prefixed method above.
function Window:SetSidebarWidth(width: number)
    self:_applySidebarWidth(width)
end

-- Pin the rail to its compact (icon-only + avatar-only) shape, or back to the full one. Pass nil
-- to hand it back to the window's own width (collapses under sidebarCollapseBelow on its own).
function Window:SetSidebarCollapsed(collapsed: boolean?)
    self._sidebarCollapsedOverride = if collapsed == nil then nil else collapsed == true
    self:_applySidebarWidth()
end

-- Set the line under the player's name in the sidebar profile chip ("Premium", a rank, a tier).
-- Empty (or nil) drops the line entirely. Sidebar tabsMode only - no-op if this window has no
-- profile chip to put it in (Top mode, or no LocalPlayer to build one for). Ported from
-- upstream Rayfield Gen2 1.2.
function Window:SetProfile(text: string?)
    self.profileText = text
    if not self.profileSubtitle then
        return
    end
    local resolved = if type(text) == "string" and text ~= "" then locale.resolve(text) else nil
    self.profileSubtitle.Text = resolved or ""
    self.profileSubtitle.Visible = resolved ~= nil
end

function Window:CreateTag(properties)
    local newTag = require(script.Parent.tag).new(self, properties)
    table.insert(self.tags, newTag)
    return newTag
end

-- Register a saveable control under its flag. Keeps flags unique so two same-named
-- elements dont clobber each other's saved value. Updates control.flag to the key we
-- actually stored under and returns it.
function Window:_registerControl(control)
    if not control.flag or control.flag == "" or control.forgetState then
        return
    end

    local flag = control.flag
    if self.controls[flag] then
        local n = 2
        while self.controls[flag .. n] do
            n += 1
        end
        flag = flag .. n
        log.warn(
            "Rayfield: duplicate config flag '"
                .. control.flag
                .. "', saving this one as '"
                .. flag
                .. "'. Set a unique flag to keep it stable across sessions."
        )
    end

    control.flag = flag
    self.controls[flag] = control
    return flag
end

-- Restore an element built after the config was already loaded. autoLoad only fires once on
-- first Show, so without this a late element (one built after a remote fetch, say) keeps its
-- default and the next autosave writes that default over the saved value.
-- Called from the CreateX tails once the element is fully built, since _registerControl runs
-- mid-construction and :Set would touch instances that dont exist yet.
function Window:_restoreLate(element)
    if not self._loadedConfig or not element.flag or element.forgetState then
        return
    end

    local wasLoading = self._loading
    self._loading = true -- dont autosave the value we just read back
    persistence.applyTo(element, self._loadedConfig[element.flag])
    self._loading = wasLoading
end

-- Autosave a control's value after an interactive or programmatic change, when the window is
-- set to autoSave and the control opts into persistence. Every Set/commit path funnels here so
-- persistence stays uniform across elements.
function Window:_persist(control)
    -- _loading: a config restore fires every control's callback, but must not autosave back over
    -- the file it's reading (or storm Save once per control)
    if not control.flag or control.forgetState or self._loading then
        return
    end
    if self.configuration.autoSave then
        self:_scheduleAutoSave()
    end
    -- Auto Save Config (see the Configurations section in _buildSettingsUI): additionally keeps
    -- whichever named configuration is currently selected up to date, independent of the single
    -- default file above. self._autoSaveConfigEnabled/_selectedConfigName are plain fields rather
    -- than reads through a control specifically so this works even before that UI section has
    -- built (or if a consumer script sets them directly without ever showing it).
    if self._autoSaveConfigEnabled then
        self:_scheduleAutoSaveConfig()
    end
end

-- How long a debounced autosave waits for the burst to go quiet before actually writing.
local autoSaveDebounce = 0.2

-- Collapses a burst of rapid _persist calls (dragging a slider fires one per frame) into a
-- single deferred Save - generation-stamped so only the *last* call in a burst is the one that
-- actually survives to write the file; every earlier one's delayed write finds itself stale and
-- skips. Re-checks self._loading at fire time too, not just at the call site above, in case a
-- config Load starts mid-debounce (a real risk here: a Load's control-by-control apply is
-- exactly the kind of rapid-fire burst this debounce exists to collapse in the first place).
function Window:_scheduleAutoSave()
    self._autoSaveGeneration = (self._autoSaveGeneration or 0) + 1
    local generation = self._autoSaveGeneration
    task.delay(autoSaveDebounce, function()
        if self._autoSaveGeneration == generation and not self._loading then
            self:Save()
        end
    end)
end

-- Same debounce/generation shape as _scheduleAutoSave, targeting self._selectedConfigName
-- instead of the default file. Re-reads both the enabled flag and the target name at fire time
-- (not just at schedule time) since either can change mid-debounce - e.g. switching the
-- dropdown's selection again before the first save actually lands.
function Window:_scheduleAutoSaveConfig()
    self._autoSaveConfigGeneration = (self._autoSaveConfigGeneration or 0) + 1
    local generation = self._autoSaveConfigGeneration
    task.delay(autoSaveDebounce, function()
        local name = self._selectedConfigName
        if self._autoSaveConfigGeneration == generation and not self._loading and self._autoSaveConfigEnabled and name and name ~= "" then
            self:Save(name)
        end
    end)
end

-- Drop a control from the flag registry when its element is removed, so Save/Load and the
-- Flags view never touch a destroyed instance.
function Window:_unregisterControl(control)
    if control.flag and self.controls[control.flag] == control then
        self.controls[control.flag] = nil
    end
end

-- Recurses into anything that can host its own nested elements (Group, and a Collapsible/Tabbox
-- via the Group(s) underneath them), so a Keybind buried inside a row/column/panel is still
-- found. Used to matter less when Group had no CreateKeybind at all; now that it does, a plain
-- top-level-only scan would silently miss any Keybind not sitting directly in a tab.
local function forEachElement(elements, visit)
    for _, element in elements do
        visit(element)
        if element.__type == "Group" and element.elements then
            forEachElement(element.elements, visit)
        elseif element.__type == "Collapsible" and element._group then
            forEachElement(element._group.elements, visit)
        elseif element.__type == "Tabbox" and element.pages then
            for _, page in element.pages do
                forEachElement(page.elements, visit)
            end
        end
    end
end

-- find a keybind element currently bound to `key`, skipping `exclude` and unbound keys - lets
-- the menu-toggle keybind refuse a key an element keybind already owns, wherever that keybind
-- actually lives (a tab directly, or nested in a Group/Collapsible/Tabbox).
function Window:_keybindUsing(key, exclude)
    if typeof(key) ~= "EnumItem" or key == Enum.KeyCode.Unknown then
        return nil
    end
    local found = nil
    for _, tab in self.tabs do
        if found then
            break
        end
        forEachElement(tab.elements, function(element)
            if not found and element ~= exclude and element.__type == "Keybind" and element.value == key then
                found = element
            end
        end)
    end
    return found
end

function Window:Notify(properties)
    if self.unloaded then
        return -- nothing to parent into once the ScreenGui is gone
    end
    if not self.notifications then
        -- notifySide: Right (default, matches every prior version of this) or Left - the whole
        -- stack's own corner, not a per-call option, since notifications share one growing
        -- container built once on first use.
        local onLeft = self.notifySide == "Left"
        self.notifications = self:Create("Frame", {
            Name = "Notifications",
            Size = UDim2.new(0, 300, 0, 800),
            Position = if onLeft then UDim2.new(0, 20, 1, -20) else UDim2.new(1, -20, 1, -20),
            AnchorPoint = if onLeft then Vector2.new(0, 1) else Vector2.new(1, 1),
            BackgroundTransparency = 1,

            Parent = self.screenGui,
        })

        self:Create("UIListLayout", {
            FillDirection = Enum.FillDirection.Vertical,
            VerticalAlignment = Enum.VerticalAlignment.Bottom,
            HorizontalAlignment = Enum.HorizontalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder,
            -- No padding here: the gap lives inside each notification so removing
            -- one doesn't drop an external gap and jolt the stack.
            Padding = UDim.new(0, 0),

            Parent = self.notifications,
        })
    end

    return require(script.Parent.notification).new(self, properties)
end

-- Notify, but silently no-ops if the same `key` fired within `cooldownSeconds` - a loop that
-- would otherwise flood identical toasts (a recurring error, a repeated warning every tick)
-- fires this once per cooldown window instead. `key` is any string the caller picks - unrelated
-- to the notification's own title, so callers control the dedup granularity themselves (e.g. one
-- key per error message, or one key shared across a whole feature). Returns nil (no
-- Notification object) when suppressed, the live Notification otherwise.
function Window:NotifyOnce(key, properties, cooldownSeconds)
    cooldownSeconds = cooldownSeconds or 5
    self._notifyOnceAt = self._notifyOnceAt or {}
    local now = os.clock()
    local last = self._notifyOnceAt[key]
    if last and (now - last) < cooldownSeconds then
        return nil
    end
    self._notifyOnceAt[key] = now
    return self:Notify(properties)
end

-- Consumer-facing debug logging, gated on the player's own "Debug Logging" Settings toggle (or
-- the F9 shortcut - see _bindKeybind) rather than always-on: a dev's script sprinkles DebugLog
-- calls through its own logic same as they would a print, and nothing shows up in anyone's
-- console until a player actually flips the switch to help reproduce a bug, tags every line so
-- multiple concurrent systems logging at once stay readable, and is deliberately separate from
-- this library's own internal `log` module (that one is Rayfield's own output, silenced under
-- secure mode; this one is the dev's, silenced by player opt-in instead).
function Window:DebugLog(tag, ...)
    if not self.settings.debugLogging then
        return
    end
    print(("[%s]"):format(tostring(tag)), ...)
end

-- Typed shortcuts onto Notify, matching Fluent's own NotifySuccess/NotifyWarning/NotifyInfo/
-- NotifyError shape (Title/Description/Time, all accepted as aliases already - see
-- notification.luau) - a preset icon + accentColor per type so a script switching from Fluent
-- can call these with the exact same properties table and get a sensibly-coloured result,
-- without hand-picking an icon/colour every call. Any of the presets are still overridable by
-- passing icon/accentColor explicitly - table.clone before mutating so the caller's own table
-- is never touched.
--
-- Icons use the "pack:icon-name" shorthand image.resolve() understands (see icons.luau/
-- image.luau) - each name below was live-verified against the actual Lucide pack data before
-- shipping (a past pack rename bit a few other icons this same session; see the icon-name
-- verification note in window.luau's Settings section for the method), so this doesn't repeat
-- the earlier resize.luau saga of guessing a bad-fitting rbxassetid.
local function typedNotify(self, properties, icon, color)
    properties = if typeof(properties) == "table" then table.clone(properties) else {}
    properties.icon = properties.icon or properties.Icon or icon
    properties.accentColor = properties.accentColor or properties.AccentColor or color
    return self:Notify(properties)
end

function Window:NotifySuccess(properties)
    return typedNotify(self, properties, "lucide:circle-check", constants.accent.on)
end

function Window:NotifyWarning(properties)
    return typedNotify(self, properties, "lucide:triangle-alert", Color3.fromRGB(235, 175, 55))
end

function Window:NotifyInfo(properties)
    return typedNotify(self, properties, "lucide:info", Color3.fromRGB(80, 150, 235))
end

function Window:NotifyError(properties)
    return typedNotify(self, properties, "lucide:circle-x", self.theme.ErrorColor)
end

-- Slides the top-centre toast stack clear of the collapsed pill (or back to its normal spot) -
-- call this wherever chrome.setCollapsedShown is, so the two always agree. No-op if no top
-- toast has ever fired (container built lazily by Toast itself).
function Window:_setTopToastPosition(animate)
    local container = self._toastsTop
    if not container then
        return
    end
    local target = if self.hidden then topToastClosedPosition else topToastOpenPosition
    if animate then
        variables.tweenService:Create(container, animate, { Position = target }):Play()
    else
        container.Position = target
    end
end

-- Top-centre / bottom-centre toast stack. Like Notify but for brief, centred messages that drop
-- in from the top (or rise from the bottom) of the screen (newest on top). Each toast takes
-- { title, subtitle?, icon?, duration?, position? }.
function Window:Toast(properties)
    if self.unloaded then
        return
    end

    local position = (properties or {}).position or "Top"
    local isTop = position == "Top"
    local containerKey = if isTop then "_toastsTop" else "_toastsBottom"
    local container = self[containerKey]

    if not container then
        container = self:Create("Frame", {
            Name = "Toasts",
            Size = UDim2.new(0, maxToastWidth, 1, -24),
            Position = if isTop
                then (if self.hidden then topToastClosedPosition else topToastOpenPosition)
                else UDim2.new(0.5, 0, 1, -12),
            AnchorPoint = if isTop then Vector2.new(0.5, 0) else Vector2.new(0.5, 1),
            BackgroundTransparency = 1,
            ZIndex = constants.zIndex.toast,

            Parent = self.screenGui,
        })

        self:Create("UIListLayout", {
            FillDirection = Enum.FillDirection.Vertical,
            VerticalAlignment = if isTop then Enum.VerticalAlignment.Top else Enum.VerticalAlignment.Bottom,
            HorizontalAlignment = Enum.HorizontalAlignment.Center,
            SortOrder = Enum.SortOrder.LayoutOrder,
            -- gap lives inside each toast so removing one collapses its gap with it
            Padding = UDim.new(0, 0),

            Parent = container,
        })

        self[containerKey] = container
    end

    return require(script.Parent.toast).new(self, properties, container)
end

-- Centred modal over a dimmed backdrop. Takes { title, subtitle?, icon?, content?, boxes?,
-- options?, dismissable? } - give it options for a choice dialog, or boxes for a changelog.
-- Returns the popup handle (call :Close() to dismiss it yourself).
function Window:Popup(properties)
    if self.unloaded then
        return
    end
    return require(script.Parent.popup).new(self, properties)
end

local function keySystemFile(self)
    local dir = variables.fileSystemManager:getPath("KeySystem")
    return dir, path.join(dir, path.sanitizeFile(self.name) .. ".key")
end

-- A gate: nothing past this point runs until validator (or a plain key/list match) accepts
-- what's typed, or the dev's own Exit button fires. Not dismissable by backdrop-click or Escape
-- on purpose (see Popup's own dismissable property) - a gate that closes for free isn't one.
-- Built on Popup's input field (see popup.luau's own inputConfig comment) rather than a bespoke
-- screen, so it gets the same chrome/animations/theme everything else in the library already has.
--
-- saveKey persists an *accepted* key to disk (Rayfield/KeySystem/<window name>.key) so a
-- returning player isn't asked again - but it's re-checked against validator/key every launch
-- rather than trusted blindly, so a key that stops validating (rotated, revoked, expired) can't
-- let someone in forever just because it worked once.
function Window:KeySystem(properties)
    properties = if typeof(properties) == "table" then properties else {}

    local validator = properties.validator or properties.Validator
    local keyList = properties.key or properties.Key or properties.keys or properties.Keys
    local saveKey = properties.saveKey or properties.SaveKey
    local onSuccess = properties.onSuccess or properties.OnSuccess or function() end
    local onFailure = properties.onFailure or properties.OnFailure

    local function isValid(key)
        if type(key) ~= "string" or key == "" then
            return false
        end
        if validator then
            local ok, result = pcall(validator, key)
            return ok and result == true
        end
        if typeof(keyList) == "table" then
            return table.find(keyList, key) ~= nil
        end
        return keyList ~= nil and key == keyList
    end

    local keyDir, keyFile = keySystemFile(self)
    if saveKey and filesystem.isfile(keyFile) then
        local ok, saved = pcall(filesystem.readfile, keyFile)
        if ok and isValid(saved) then
            task.spawn(onSuccess)
            return
        end
    end

    self:Popup({
        title = properties.title or properties.Title or "Key Required",
        subtitle = properties.subtitle or properties.Subtitle,
        icon = properties.icon or properties.Icon,
        content = properties.note or properties.Note,
        dismissable = false,
        input = { placeholder = properties.placeholder or properties.Placeholder or "Enter key" },
        options = {
            {
                text = properties.exitText or properties.ExitText or "Exit",
                style = "neutral",
                callback = function()
                    if onFailure then
                        onFailure()
                    end
                end,
            },
            {
                text = properties.submitText or properties.SubmitText or "Submit",
                style = "primary",
                callback = function(key)
                    if not isValid(key) then
                        return false -- rejected: Popup keeps the gate open and flashes the field
                    end
                    if saveKey then
                        pcall(filesystem.ensureFolder, keyDir)
                        pcall(filesystem.writefile, keyFile, key)
                    end
                    onSuccess()
                    return true
                end,
            },
        },
    })
end

local greetingFadeInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

-- A white overlay, matching the window's own rounded corners, that cycles a short greeting in
-- each of `texts` and then sweeps away in a curved (circular) wipe to reveal the menu - the
-- overlay shrinks toward its centre while its own corner radius grows to fully round at the same
-- time, so a plain rectangle becomes an iris closing rather than needing any actual masking.
-- Takes { texts = {"Hello", "Bonjour", ...}, holdTime?, wipeTime? }. Safe to call on demand (a
-- "Play greeting" button) as well as once on first show - re-entrant calls no-op while one's
-- already running rather than fighting it for the same overlay.
function Window:PlayGreeting(properties)
    if self.unloaded or self._greetingPlaying then
        return
    end
    properties = if typeof(properties) == "table" then properties else {}
    local texts = properties.texts or properties.Texts or { "Hello" }
    local holdTime = properties.holdTime or properties.HoldTime or 0.85
    local wipeTime = properties.wipeTime or properties.WipeTime or 0.7
    if #texts == 0 then
        return
    end
    self._greetingPlaying = true

    if not self._greetingOverlay then
        self._greetingOverlay = self:Create("Frame", {
            Size = UDim2.fromScale(1, 1),
            Position = UDim2.fromScale(0.5, 0.5),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = Color3.fromRGB(255, 255, 255),
            BorderSizePixel = 0,
            ZIndex = constants.zIndex.greeting,

            Parent = self.main,
        })

        self._greetingCorner = self:Create("UICorner", {
            Parent = self._greetingOverlay,
        })

        self._greetingLabel = self:Create("TextLabel", {
            Size = UDim2.fromScale(0.85, 0.3),
            Position = UDim2.fromScale(0.5, 0.5),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 28,
            TextColor3 = Color3.fromRGB(20, 20, 20),
            TextTransparency = 1,
            FontFace = self.theme.TitleFont,
            -- ZIndexBehavior is Global, so this child doesn't inherit/get elevated by the
            -- overlay's own high ZIndex - without its own explicit bump above the overlay's,
            -- the overlay's opaque white background paints right over it (confirmed live: the
            -- whole thing just read as a blank white card, the text was there the whole time,
            -- just painted under its own background).
            ZIndex = constants.zIndex.greeting + 1,

            Parent = self._greetingOverlay,
        })
    end

    local overlay, corner, label = self._greetingOverlay, self._greetingCorner, self._greetingLabel
    overlay.Size = UDim2.fromScale(1, 1)
    overlay.Position = UDim2.fromScale(0.5, 0.5)
    overlay.BackgroundTransparency = 0
    corner.CornerRadius = self.theme.CornerRoundness
    label.TextTransparency = 1
    overlay.Visible = true

    for i, text in texts do
        label.Text = locale.resolve(tostring(text))
        variables.tweenService:Create(label, greetingFadeInfo, { TextTransparency = 0 }):Play()
        task.wait(holdTime)
        if i < #texts then
            variables.tweenService:Create(label, greetingFadeInfo, { TextTransparency = 1 }):Play()
            task.wait(0.15)
        end
    end

    variables.tweenService:Create(label, greetingFadeInfo, { TextTransparency = 1 }):Play()
    local wipeInfo = TweenInfo.new(wipeTime, Enum.EasingStyle.Exponential, Enum.EasingDirection.InOut)
    variables.tweenService:Create(overlay, wipeInfo, { Size = UDim2.fromScale(0, 0) }):Play()
    variables.tweenService:Create(corner, wipeInfo, { CornerRadius = UDim.new(1, 0) }):Play()
    task.wait(wipeTime)

    overlay.Visible = false
    self._greetingPlaying = false
end

function Window:Hide()
    -- idempotent: a second Hide while collapsed would capture the pill spot as the
    -- restore position and teleport the window there on the next Show
    if self.animating or self.hidden then
        return
    end

    -- drop out of search first so we grow back into the normal tab view on next show. tabList
    -- stays hidden here since the collapse hides it anyway; Show re-enables it.
    if self._searching then
        search.close(self, { showTabs = false, jumpTo = self.selectedTab and self.selectedTab.tabPage })
    end

    self.animating = true
    self._revealing = true
    self.hidden = true
    self.collapsedInteract.Visible = false -- re-shown once the collapse settles, below

    -- main morphs straight into the collapsed pill rather than handing off to a separate
    -- instance - the resize grip is parented to main too, so without this it rides along and
    -- sits there over the "Tap to show" pill, live-caught as a stray corner glyph with nothing
    -- to resize while hidden.
    self.resize.grip.Visible = false

    -- closing while minimised closes properly rather than leaving a stale minimised state -
    -- Show always grows back to the full (non-minimised) layout, so the flag and icon need
    -- to agree with that
    if self.minimised then
        self.minimised = false
        image.assign(self.minimiseAction.iconLabel, "Image", constants.icons.minimise) -- back to the minimise icon
    end

    -- remember where the window sat so Show grows it back to the same spot
    self._restorePosition = self.main.Position

    local home, size = self:_collapsedRect()

    -- named so the task.delay staging below can stay in lockstep with however long these
    -- actually run - slowed down from 0.18/0.35 (read as too fast, closing almost instantly)
    local fadeDuration, moveDuration = 0.26, 0.5
    local fadeInfo = TweenInfo.new(fadeDuration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    -- "Closing to the pill": one continuous move for the whole collapse, size and position
    -- tweening together on the same curve so they stay perfectly in sync, no seam between
    -- separate legs. Quint/Out (was Exponential/InOut) reads as the window getting sucked
    -- straight into the pill - fast off the mark, settling smoothly into place, rather than
    -- easing gently out of its starting size the way InOut does.
    local moveInfo = TweenInfo.new(moveDuration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local cornerInfo = TweenInfo.new(moveDuration, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local faceInfo = TweenInfo.new(0.28, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

    -- shrink the drag bar back down the same way it grows in on first reveal, instead of
    -- just cutting it
    variables.tweenService
        :Create(self.drag.dragCosmetic, fadeInfo, { Size = UDim2.fromOffset(0, 4), BackgroundTransparency = 1 })
        :Play()
    task.delay(fadeDuration, function()
        if not self.hidden then
            return
        end
        self.drag.drag.Visible = false
    end)

    -- fade the window's own chrome out; main keeps its own background/gradient/corner the
    -- whole time, it just reshapes underneath - there's nothing to hand off to
    variables.tweenService:Create(self.windowShadow, fadeInfo, { Transparency = 1 }):Play()
    variables.tweenService:Create(self.bottomFade, fadeInfo, { BackgroundTransparency = 1 }):Play()
    variables.tweenService:Create(self.topFade, fadeInfo, { BackgroundTransparency = 1 }):Play()

    if self.title then
        variables.tweenService:Create(self.title, fadeInfo, { TextTransparency = 1 }):Play()
    end
    if self.subtitle then
        variables.tweenService:Create(self.subtitle, fadeInfo, { TextTransparency = 1 }):Play()
    end
    if self.topbarIcon then
        variables.tweenService:Create(self.topbarIcon, fadeInfo, { ImageTransparency = 1 }):Play()
    end

    for _, action in ipairs(self.actionContainer:GetChildren()) do
        if action:IsA("Frame") then
            variables.tweenService:Create(action.ImageLabel, fadeInfo, { ImageTransparency = 1 }):Play()
        end
    end

    for _, tag in self.tags do
        tag:_setShown(false, fadeInfo)
    end

    for _, tab in pairs(self.tabs) do
        if not tab.neglectSelector and tab.topbarItem then
            tab:_applyVisual("hidden", fadeInfo)
        end
    end
    self:_setTabSectionsShown(false, fadeInfo)

    self:_fadeSelectedElementsOut()

    -- collapse into the pill in one continuous move - size and position tweened together
    -- so they stay perfectly in sync throughout
    variables.tweenService:Create(self.main, moveInfo, { Size = size, Position = home }):Play()
    -- squircle mode has no windowCorner to round into the pill's fully-round corner - the
    -- squircle shape just stays at its own normal radius while collapsed (a known, disclosed
    -- gap: the pill-collapse animation isn't squircle-aware yet - would need the separate
    -- Circle asset squircle.luau doesn't carry, since a squircle can't itself express a true
    -- fully-round pill the way UDim.new(1,0) on a plain UICorner can).
    if self.windowCorner then
        variables.tweenService:Create(self.windowCorner, cornerInfo, { CornerRadius = UDim.new(1, 0) }):Play()
    end

    -- once the chrome's faded, drop it and the scrolling content so nothing squashes/pokes
    -- out as the frame shrinks around it, then bring the collapsed face up over the top
    task.delay(fadeDuration, function()
        if not self.hidden then
            return
        end
        self.topbar.Visible = false
        self.elements.Visible = false
        self.tabList.Visible = false
        self.tabDock.Visible = false
        -- the profile chip hangs off main, not tabDock (see its own construction comment), so
        -- hiding the dock doesn't take it with it
        if self.profile then
            self.profile.Visible = false
        end
        self:_setTabSectionsVisible(false)
        chrome.setCollapsedShown(self, true, faceInfo)
        self:_setTopToastPosition(faceInfo)
    end)

    -- once the move's settled the pill is done morphing: hand clicks to it
    task.delay(moveDuration, function()
        if not self.hidden then
            return
        end
        self.collapsedInteract.Visible = true
        self.animating = false
        self._revealing = false
    end)
end

function Window:ToggleHide()
    if self.animating then
        return
    end
    if self.hidden then
        self:Show()
    else
        self:Hide()
    end
end

function Window:ToggleMinimise()
    if self.animating or self.hidden then
        return
    end

    -- minimising drops out of search back to the tab view first, so it grows back normally
    if self._searching then
        search.close(self, { showTabs = true })
    end

    self.animating = true

    local sizeInfo = TweenInfo.new(0.5, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)
    local fadeInfo = TweenInfo.new(0.4, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out)

    if self.minimised then
        self.minimised = false
        image.assign(self.minimiseAction.iconLabel, "Image", constants.icons.minimise) -- back to the minimise icon

        variables.tweenService:Create(self.main, sizeInfo, { Size = self.size }):Play()
        variables.tweenService:Create(self.windowShadow, fadeInfo, { Transparency = self._shadowTransparency or 0.6 }):Play()
        variables.tweenService:Create(self.bottomFade, fadeInfo, { BackgroundTransparency = 0 }):Play()
        variables.tweenService:Create(self.topFade, fadeInfo, { BackgroundTransparency = 0 }):Play()

        variables.tweenService
            :Create(self.drag.drag, sizeInfo, {
                Position = UDim2.new(
                    self.main.Position.X.Scale,
                    self.main.Position.X.Offset,
                    self.main.Position.Y.Scale,
                    self.main.Position.Y.Offset + self.size.Y.Offset / 2 + 15
                ),
            })
            :Play()

        -- once the window's grown back, fade the content and tab pills in rather than
        -- snapping them visible
        task.delay(0.2, function()
            if self.minimised or self.hidden then
                return -- re-minimised or hidden mid animation
            end
            self.elements.Visible = true
            self.tabList.Visible = true
            self.tabDock.Visible = true
            self.resize.grip.Visible = self.settings.resizeGripEnabled
            if self.profile then
                self.profile.Visible = self.settings.showProfile
                self.tabList.Size =
                    UDim2.new(1, 0, 1, if self.settings.showProfile then -self._tabListFooterReserve else 0)
            end
            for _, tab in pairs(self.tabs) do
                if not tab.neglectSelector and tab.topbarItem then
                    tab.topbarItem.Visible = true
                    tab:_applyVisual(if self.selectedTab == tab then "selected" else "unselected", fadeInfo)
                end
            end
            self:_setTabSectionsVisible(true)
            self:_setTabSectionsShown(true, fadeInfo)

            self:_revealElements(0.035, 0.4)
        end)

        task.delay(0.5, function()
            self.animating = false
        end)
    else
        self.minimised = true
        image.assign(self.minimiseAction.iconLabel, "Image", constants.icons.maximise) -- maximise icon while minimised

        -- fade the content + tab pills out instead of cutting them, then hide them once faded
        -- so they don't sit clipped under the collapsed bar
        self:_fadeSelectedElementsOut()
        for _, tab in pairs(self.tabs) do
            if not tab.neglectSelector and tab.topbarItem then
                tab:_applyVisual("hidden", fadeInfo)
            end
        end
        self:_setTabSectionsShown(false, fadeInfo)

        task.delay(0.3, function()
            if not self.minimised then
                return -- restored mid animation
            end
            self.elements.Visible = false
            self.tabList.Visible = false
            self.tabDock.Visible = false
            -- same story as Hide's own: the profile chip is parented to main, so it needs
            -- hiding by hand alongside the dock
            if self.profile then
                self.profile.Visible = false
            end
            self:_setTabSectionsVisible(false)
            -- a collapsed bar isn't something you'd resize, and the grip would otherwise sit
            -- oversized on its now much shorter (66px) height
            self.resize.grip.Visible = false
            for _, tab in pairs(self.tabs) do
                if not tab.neglectSelector and tab.topbarItem then
                    tab.topbarItem.Visible = false
                end
            end
        end)

        variables.tweenService:Create(self.windowShadow, fadeInfo, { Transparency = 1 }):Play()
        variables.tweenService:Create(self.bottomFade, fadeInfo, { BackgroundTransparency = 1 }):Play()
        variables.tweenService:Create(self.topFade, fadeInfo, { BackgroundTransparency = 1 }):Play()
        variables.tweenService:Create(self.main, sizeInfo, { Size = UDim2.fromOffset(self.size.X.Offset, 66) }):Play()

        variables.tweenService
            :Create(self.drag.drag, sizeInfo, {
                Position = UDim2.new(
                    self.main.Position.X.Scale,
                    self.main.Position.X.Offset,
                    self.main.Position.Y.Scale,
                    self.main.Position.Y.Offset + 66 / 2 + 15
                ),
            })
            :Play()

        task.delay(0.5, function()
            self.animating = false
        end)
    end
end

-- Park the drag bar under the window's bottom edge, matching whichever positioning the window
-- itself uses so a centred window stays centred and a dragged one stays where it was left.
function Window:_syncDragBar()
    local bar = self.drag and self.drag.drag
    if not bar then
        return
    end
    local position = self.main.Position
    local below = self.size.Y.Offset / 2 + 15
    bar.Position = UDim2.new(position.X.Scale, position.X.Offset, position.Y.Scale, position.Y.Offset + below)
end

-- Pull a dragged window back on screen after a re-fit, the same way a drag clamps. A window
-- parked near an edge would otherwise end up half off it when the viewport shrinks underneath.
-- Where a position ends up once the current size has to fit on the current screen. Returns it
-- unchanged when theres nothing to do, so callers can compare.
function Window:_clampedPosition(position: UDim2): UDim2
    if not self.settings or not self.settings.keepOnScreen then
        return position
    end
    -- untouched windows sit on scale and are centred, so theyre on screen by construction -
    -- clamping would only freeze them to offsets and stop them recentring later
    if position.X.Scale ~= 0 or position.Y.Scale ~= 0 then
        return position
    end

    local screen = self.screenGui.AbsoluteSize
    local halfX, halfY = self.size.X.Offset / 2, self.size.Y.Offset / 2
    local margin = 8
    -- math.max in case the window is bigger than the screen
    local x = math.clamp(position.X.Offset, halfX + margin, math.max(halfX + margin, screen.X - halfX - margin))
    local y = math.clamp(position.Y.Offset, halfY + margin, math.max(halfY + margin, screen.Y - halfY - margin))
    if x == position.X.Offset and y == position.Y.Offset then
        return position
    end
    return UDim2.fromOffset(x, y)
end

function Window:_clampToScreen()
    self.main.Position = self:_clampedPosition(self.main.Position)
end

-- Take the size the current screen calls for. Only a live window is resized on the spot;
-- hidden, minimised or mid-animation ones just bank the size and pick it up on their next
-- show, so a rotation cant yank a collapsed pill back open.
function Window:_applyWindowSize()
    if self.unloaded then
        return
    end

    local size = fitWindowSize(self.customSize)
    local changed = size ~= self.size
    self.size = size

    -- a window mid-animation is already tweening toward the old size, so bank the change and
    -- let the reconcile apply it once the tween is done rather than fighting it
    if self.hidden or self.minimised or self.animating or self._revealing then
        self._pendingResize = self._pendingResize or changed
        return
    end

    if not changed and not self._pendingResize then
        return
    end
    self._pendingResize = false

    self.main.Size = size
    self:_clampToScreen()
    self:_syncDragBar()
end

-- Follow the screen. The property signal is the fast path, but CurrentCamera gets swapped
-- (respawn, or a game replacing it) and a listener bound to the old camera dies silently, so
-- rebind on the swap and keep a slow reconcile behind it as the backstop.
function Window:_watchViewport()
    local cameraConnection: RBXScriptConnection? = nil
    local pending = false

    local function request()
        -- a rotation fires a burst of intermediate sizes, so settle on the last one
        if pending then
            return
        end
        pending = true
        task.defer(function()
            pending = false
            self:_applyWindowSize()
        end)
    end

    local function bind()
        if cameraConnection then
            self:Disconnect(cameraConnection)
            cameraConnection = nil
        end
        local camera = variables.workspace.CurrentCamera
        if camera then
            cameraConnection = self:Connect(camera:GetPropertyChangedSignal("ViewportSize"), request)
        end
        request()
    end

    self:Connect(variables.workspace:GetPropertyChangedSignal("CurrentCamera"), bind)
    bind()

    -- Backstop for anything the signals miss. Heartbeat rather than a wait loop so it rides the
    -- normal connection cleanup and cant spin if the scheduler hands back a wait that never yields.
    local sinceReconcile = 0
    self:Connect(variables.runService.Heartbeat, function(delta: number)
        sinceReconcile += delta
        if sinceReconcile < viewportReconcileInterval then
            return
        end
        sinceReconcile = 0
        self:_applyWindowSize()
    end)
end

function Window:_bindKeybind()
    self:Connect(variables.userInputService.InputBegan, function(input, processed)
        if processed or self._recordingKeybind then
            return -- a keybind element is mid-rebind, dont eat its capture
        end
        if input.KeyCode == self.settings.toggleKeybind or input.UserInputType == self.settings.toggleKeybind then
            -- Live-caught: the default toggle key is plain K, and Ctrl+K (below) is a *different*
            -- shortcut - but InputBegan fires on the K keydown regardless of what else is held,
            -- so pressing Ctrl+K matched here too and closed the window in the same beat the
            -- search shortcut was trying to open it, netting "nothing happened but the menu
            -- closed". Skip the plain-toggle match while Ctrl is held, unless the toggle key
            -- itself *is* Ctrl (a player could rebind it to that) - only guard against a
            -- modifier stealing a *different* key's plain binding, not break a deliberate one.
            local uis = variables.userInputService
            local ctrlHeld = uis:IsKeyDown(Enum.KeyCode.LeftControl) or uis:IsKeyDown(Enum.KeyCode.RightControl)
            local toggleIsCtrl = self.settings.toggleKeybind == Enum.KeyCode.LeftControl
                or self.settings.toggleKeybind == Enum.KeyCode.RightControl
            if not (ctrlHeld and not toggleIsCtrl) then
                self:ToggleHide()
            end
        end
    end)

    -- Ctrl+K: the same "search all pages" the topbar's own Search action already opens/closes
    -- (search.toggle) - just a keyboard shortcut onto a feature that already existed, not a new
    -- search system. Fixed to Ctrl+K rather than reading a configurable setting the way the menu
    -- toggle key does - this is meant to be the one predictable shortcut every window shares
    -- (the same convention a browser's or VS Code's own Ctrl+K carries), not something a dev or
    -- player would want to rebind per window.
    self:Connect(variables.userInputService.InputBegan, function(input, processed)
        if processed or self._recordingKeybind then
            return
        end
        if input.KeyCode ~= Enum.KeyCode.K then
            return
        end
        local uis = variables.userInputService
        if not (uis:IsKeyDown(Enum.KeyCode.LeftControl) or uis:IsKeyDown(Enum.KeyCode.RightControl)) then
            return
        end
        if self.minimised or not self:_interactive() then
            return
        end
        search.toggle(self)
    end)

    -- Escape: closes search first if it's open (backs out one level, the same convention most
    -- apps use for Escape), otherwise closes the window - only when the dev opted in via
    -- escapeToClose (see its own comment on why this is dev-set, not a player Settings toggle).
    self:Connect(variables.userInputService.InputBegan, function(input, processed)
        if processed or self._recordingKeybind then
            return
        end
        if input.KeyCode ~= Enum.KeyCode.Escape then
            return
        end
        if self.minimised or not self:_interactive() then
            return
        end
        if self._searching then
            search.close(self, { showTabs = true })
            return
        end
        if self.escapeToClose and not self.hidden then
            self:Hide()
        end
    end)

    -- F9: flips debug logging on/off from anywhere, not just the Settings toggle - the point is
    -- a player can turn it on the moment a bug happens without hunting through menus first, then
    -- reproduce it and hand the dev script's own console output (see DebugLog below) straight
    -- over. Fixed to F9 for the same reason Ctrl+K is fixed above: one shortcut every window
    -- shares, not a per-player rebind.
    self:Connect(variables.userInputService.InputBegan, function(input, processed)
        if processed or self._recordingKeybind then
            return
        end
        if input.KeyCode ~= Enum.KeyCode.F9 then
            return
        end
        self.settings.debugLogging = not self.settings.debugLogging
        self:SaveSettings()
        if self._debugLoggingToggleControl then
            self._debugLoggingToggleControl:Set(self.settings.debugLogging, true)
        end
        self:Toast({
            title = locale.resolve(if self.settings.debugLogging then "Debug logging on" else "Debug logging off"),
            icon = "lucide:bug",
        })
    end)
end

function Window:_bindMouseOverride()
    local uis = variables.userInputService

    local function active()
        return self.settings.mouseOverride and not self.hidden and not self.minimised
    end

    local function free()
        if not active() then
            return
        end
        -- hands off while the right button is held: thats the camera panning in third person,
        -- and it needs to lock the mouse to do it. we free again the moment it lets go.
        if uis:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
            return
        end
        if uis.MouseBehavior ~= Enum.MouseBehavior.Default then
            uis.MouseBehavior = Enum.MouseBehavior.Default
        end
        if not uis.MouseIconEnabled then
            uis.MouseIconEnabled = true
        end
    end

    -- react to the game re-locking instead of racing it each frame. it sets LockCenter, we set
    -- it back, so we always get the last word. same deal if it hides the mouse icon.
    self:Connect(uis:GetPropertyChangedSignal("MouseBehavior"), free)
    self:Connect(uis:GetPropertyChangedSignal("MouseIconEnabled"), free)

    -- right-release doesnt always flip MouseBehavior back (so the signals above wouldnt fire),
    -- so re-free explicitly once the pan ends
    self:Connect(uis.InputEnded, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton2 then
            free()
        end
    end)

    -- Show calls this on open to free the cursor immediately (the signals above only fire on change)
    self._freeMouse = free
end

-- Grabbing the topbar drags the whole window too, its own separate handle from the bar
-- underneath - tracks the cursor 1:1 with no lag, unlike the bars own deliberate smoothing, and
-- the bar just glues to wherever main currently is each frame so it never drifts off on its own
function Window:_bindTopbarDrag()
    local uis = variables.userInputService
    local dragging = false
    local relative = Vector2.zero

    -- main.Position lives in a space shifted from AbsolutePosition by the gui inset, even
    -- though the ScreenGui ignores it - add it back or the window jumps on the first move
    local offset = Vector2.zero
    if self.screenGui and self.screenGui.IgnoreGuiInset then
        offset = variables.guiService:GetGuiInset()
    end

    local function getTarget()
        local position = uis:GetMouseLocation() + relative + offset
        local x, y = position.X, position.Y

        if self.settings and self.settings.keepOnScreen then
            local size = self.main.AbsoluteSize
            local screen = self.screenGui.AbsoluteSize
            local margin = 8
            local halfX, halfY = size.X / 2, size.Y / 2
            x = math.clamp(x, halfX + margin, math.max(halfX + margin, screen.X - halfX - margin))
            y = math.clamp(y, halfY + margin, math.max(halfY + margin, screen.Y - halfY - margin))
        end

        return UDim2.fromOffset(x, y)
    end

    -- Global ZIndexBehavior still delivers InputBegan to an Active ancestor even when a child
    -- button covers that exact pixel, so checking the event alone isnt enough - a press over the
    -- tabs or the actions has to be rejected by where it actually landed, not just left to bubble
    local function overInteractiveChild(x, y)
        for _, region in { self.tabList, self.actionContainer } do
            local position, size = region.AbsolutePosition, region.AbsoluteSize
            if x >= position.X and x <= position.X + size.X and y >= position.Y and y <= position.Y + size.Y then
                return true
            end
        end
        return false
    end

    self:Connect(self.topbar.InputBegan, function(input, processed)
        if processed then
            return
        end

        local inputType = input.UserInputType.Name
        if inputType ~= "MouseButton1" and inputType ~= "Touch" then
            return
        end

        if overInteractiveChild(input.Position.X, input.Position.Y) then
            return
        end

        -- a grab started mid-reveal would fight the tween thats still moving the window
        if not self:_interactive() then
            return
        end

        dragging = true

        if self.screenGui and self.screenGui.IgnoreGuiInset then
            offset = variables.guiService:GetGuiInset()
        end

        relative = self.main.AbsolutePosition + self.main.AbsoluteSize * self.main.AnchorPoint - uis:GetMouseLocation()
    end)

    self:Connect(uis.InputEnded, function(input)
        local inputType = input.UserInputType.Name
        if inputType == "MouseButton1" or inputType == "Touch" then
            dragging = false
        end
    end)

    -- alt-tabbing with the button still down never delivers InputEnded, so without this the
    -- grab stays armed and the window snaps to the cursor the moment youre back
    self:Connect(uis.WindowFocusReleased, function()
        dragging = false
    end)

    self:Connect(variables.runService.RenderStepped, function()
        if not dragging then
            return
        end

        -- hidden or mid-animation means the grab went stale under us, so drop it here rather
        -- than let it wake up later and yank the window to wherever the cursor drifted
        if not self:_interactive() then
            dragging = false
            return
        end

        self.main.Position = getTarget()

        if self.drag and self.drag.drag then
            local mainPosition = self.main.Position
            self.drag.drag.Position = UDim2.new(
                mainPosition.X.Scale,
                mainPosition.X.Offset,
                mainPosition.Y.Scale,
                mainPosition.Y.Offset + (self.main.Size.Y.Offset / 2 + 15)
            )
        end
    end)
end

-- Programmatic equivalent of the Settings "Haptics" toggle - for a hub that hides that toggle
-- (showHapticsToggle = false) but still wants to pin the value one way or the other, since
-- hapticEngine keeps its own enabled flag separate from self.settings.haptics (only synced at
-- construction and from the toggle's own callback otherwise).
function Window:SetHaptics(enabled)
    enabled = enabled == true
    self.settings.haptics = enabled
    hapticEngine.setEnabled(enabled)
    self:SaveSettings()
end

function Window:_buildSettingsUI()
    self.rfSettings:CreateSection({ name = "General" })

    self.rfSettings:CreateKeybind({
        name = "Toggle Keybind",
        -- was constants.icons.search - a leftover mismatch (a magnifying glass for a keybind
        -- setting), fixed to an icon that actually matches what this does.
        icon = "lucide:keyboard",
        value = self.settings.toggleKeybind,
        isMenuToggle = true, -- reject keys already owned by an element keybind
        onChanged = function(key)
            self.settings.toggleKeybind = key
            self:SaveSettings()
        end,
    })

    self.rfSettings:CreateToggle({
        name = "Unlock cursor while open",
        icon = "lucide:mouse-pointer-2",
        description = "Unlocks the cursor while the menu is open so you can configure in FPS games that lock it.",
        value = self.settings.mouseOverride,
        callback = function(state)
            self.settings.mouseOverride = state
            self:SaveSettings()
        end,
    })

    if self._showWelcomeToastToggle then
        self.rfSettings:CreateToggle({
            name = "Welcome toast",
            icon = "lucide:hand",
            description = "Shows a 'Signed in as' toast the first time you open the menu on a new account.",
            value = self.settings.welcomeToast,
            callback = function(state)
                self.settings.welcomeToast = state
                self:SaveSettings()
            end,
        })
    end

    if self._showHapticsToggle then
        self.rfSettings:CreateToggle({
            name = "Haptics",
            icon = "lucide:vibrate",
            description = "A subtle tap as you interact, on devices that support haptics.",
            value = self.settings.haptics,
            callback = function(state)
                self:SetHaptics(state)
            end,
        })
    end

    if self._showSoundEffectsToggle then
        self.rfSettings:CreateToggle({
            name = "Sound Effects",
            icon = "lucide:volume-2",
            description = "A soft click as you interact with toggles, buttons, and tabs.",
            value = self.settings.soundEffects,
            callback = function(state)
                self.settings.soundEffects = state
                soundEngine.setEnabled(state)
                self:SaveSettings()
            end,
        })
    end

    -- Debug Logging: gates Window:DebugLog (see its own comment) - off by default, a player
    -- flips it (or presses F9, same effect - see _bindKeybind) only when a dev asks them to
    -- reproduce a bug with it on. Captured into self._debugLoggingToggleControl so the F9
    -- shortcut can push its own toggles back into this control without it drifting out of sync.
    self._debugLoggingToggleControl = self.rfSettings:CreateToggle({
        name = "Debug Logging (F9)",
        icon = "lucide:bug",
        description = "Prints extra diagnostic output to the console - turn this on if a dev asked you to reproduce a bug.",
        value = self.settings.debugLogging,
        callback = function(state)
            self.settings.debugLogging = state
            self:SaveSettings()
        end,
    })

    self.rfSettings:CreateSection({ name = "Appearance" })

    -- "Amber" is the one preset name that doesn't match its theme file 1:1 (ember.luau) - every
    -- other option here is both the picker label and the real theme name, case-insensitively.
    local themeFileFor = { Amber = "ember", ["High Contrast"] = "highcontrast" }

    self.rfSettings:CreateDropdown({
        name = "Color theme",
        icon = "lucide:palette",
        options = {
            "Default",
            "Ocean",
            "Amber",
            "Rose",
            "Emerald",
            "Amethyst",
            "Midnight",
            "High Contrast",
        },
        value = "Default",
        callback = function(value)
            self:ChangeTheme(themeFileFor[value] or value)
        end,
    })

    self.rfSettings:CreateDropdown({
        name = "Font",
        icon = "lucide:type",
        placeholder = "Search fonts...",
        options = fontOptionNames,
        value = "Auto",
        callback = function(value)
            self:SetFont(value)
        end,
    })

    -- Player-facing language for the library's own chrome (search, config messages, keybind
    -- clash toasts, and so on - see builtinLocales.luau's own header comment on exactly what's
    -- covered and what isn't). Not element names a dev supplies - those were never routed
    -- through locale.t() to begin with, so switching this doesn't touch them.
    do
        local languageNameFor = { en = "English", pt = "Português", es = "Español" }
        local languageIdFor = { English = "en", ["Português"] = "pt", ["Español"] = "es" }
        local currentLanguage = string.match(locale.current, "^(%a+)") or "en"

        self.rfSettings:CreateDropdown({
            name = "Language",
            icon = "lucide:languages",
            options = { "English", "Português", "Español" },
            value = languageNameFor[currentLanguage] or "English",
            callback = function(value)
                self:SetLocale(languageIdFor[value] or "en")
            end,
        })
    end

    self.rfSettings:CreateSlider({
        name = "Window transparency",
        icon = "lucide:layers",
        range = { 0, 100 },
        value = 0,
        suffix = "%",
        callback = function(value)
            self:SetTransparency(value)
        end,
    })

    -- Kept to 85-115 rather than a wider range on purpose - see self.contentScale's own
    -- construction comment on why an extreme scale isn't safe to let the content area reach
    -- (main has no ClipsDescendants, deliberately, for the resize grip's sake).
    self.rfSettings:CreateSlider({
        name = "UI Scale",
        icon = "lucide:scale",
        range = { 85, 115 },
        value = self.settings.uiScale,
        suffix = "%",
        callback = function(value)
            self.settings.uiScale = value
            self.contentScale.Scale = value / 100
            self:SaveSettings()
        end,
    })

    self.rfSettings:CreateToggle({
        name = "Acrylic blur",
        icon = "lucide:droplet",
        description = "Frost the game behind a see-through window.",
        value = false,
        callback = function(value)
            self:SetAcrylic(value)
        end,
    })

    self.rfSettings:CreateSection({ name = "Window" })

    self.rfSettings:CreateToggle({
        name = "Keep window on screen",
        icon = "lucide:pin",
        description = "Stops the window being dragged off the edge of the screen and lost.",
        value = self.settings.keepOnScreen,
        callback = function(state)
            self.settings.keepOnScreen = state
            self:SaveSettings()
        end,
    })

    -- Only shown when the dev actually configured a loading splash (self.loading) AND hasn't
    -- pinned it via _showLoadingAnimationToggle - otherwise there's nothing for this to turn on
    -- or off, or the dev wants it always on with no player override.
    if self.loading and self._showLoadingAnimationToggle then
        self.rfSettings:CreateToggle({
            name = "Loading Animation",
            icon = "lucide:sparkles",
            description = "Shows a brief splash the first time the window opens.",
            value = self.settings.loadingAnimationEnabled,
            callback = function(state)
                self.settings.loadingAnimationEnabled = state
                self:SaveSettings()
            end,
        })
    end

    -- Same conditional-on-the-dev-opting-in shape as Loading Animation above - only shown at
    -- all if there's actually a tour configured to replay.
    if self.tourSteps then
        self.rfSettings:CreateButton({
            name = "Replay Tour",
            icon = "lucide:compass",
            description = "Show the guided tour again.",
            callback = function()
                self:StartTour()
            end,
        })
    end

    self.rfSettings:CreateToggle({
        name = "Resizable window",
        icon = "lucide:expand",
        description = "Shows a grip in the bottom-right corner that drags the window's size.",
        value = self.settings.resizeGripEnabled,
        callback = function(state)
            self.settings.resizeGripEnabled = state
            self.resize:SetEnabled(state)
            self:SaveSettings()
        end,
    })

    self.rfSettings:CreateButton({
        name = "Reset Window Size",
        icon = "lucide:maximize",
        callback = function()
            self.resize:ResetSize()
        end,
    })

    self.rfSettings:CreateButton({
        name = "Reset Window Position",
        icon = "lucide:move",
        callback = function()
            variables.tweenService
                :Create(self.main, TweenInfo.new(0.5, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
                    Position = UDim2.new(0.5, 0, 0.5, 0),
                })
                :Play()
            variables.tweenService
                :Create(self.drag.drag, TweenInfo.new(0.5, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
                    Position = UDim2.new(0.5, 0, 0.5, self.size.Y.Offset / 2 + 15),
                })
                :Play()
        end,
    })

    -- Only the sidebar layout has somewhere to put a profile chip, and only once it actually
    -- built one (a real LocalPlayer to build it for - see window.luau's own profile block).
    -- Ported from upstream Rayfield Gen2 1.2.
    if self.profile then
        self.rfSettings:CreateToggle({
            name = "Show profile",
            icon = "lucide:user",
            description = "Shows your avatar and name at the base of the sidebar.",
            value = self.settings.showProfile,
            callback = function(state)
                self.settings.showProfile = state
                self.profile.Visible = state
                -- Give the rows back the height the profile isn't using (and vice versa), so a
                -- hidden profile leaves no dead strip at the base of the rail.
                self.tabList.Size = UDim2.new(1, 0, 1, if state then -self._tabListFooterReserve else 0)
                self:SaveSettings()
            end,
        })
    end

    -- Configurations: save the current setup under a name and switch between saved ones.
    -- Only shown once the developer opts into config saving.
    if next(self.configuration) ~= nil then
        self.rfSettings:CreateSection({ name = "Configurations" })

        local selected = self:ListConfigs()[1]
        local configDropdown, nameInput, autoTargetLabel

        local function autoTargetText()
            if selected and selected ~= "" then
                return locale.resolve("Applies to") .. ": " .. selected
            end
            return locale.resolve("Applies to: no configuration selected")
        end

        -- Persist which configuration is "selected" here across restarts - same
        -- Window:RegisterFlag pattern the hub template's own sidebar width/HUD position use for a
        -- plain value with no visible control of its own (see its doc comment). Window:_persist
        -- reads self._selectedConfigName to know which file Auto Save Config should target, and
        -- the Auto Load Config button below reads plain `selected` to know what to commit - both
        -- point at this exact same selection, which is also what autoTargetLabel below exists to
        -- make visible next to them.
        local selectedFlag = self:RegisterFlag("_SelectedConfig", selected, function(name)
            selected = name
            self._selectedConfigName = name
            if configDropdown and name and configDropdown.value ~= name then
                configDropdown:Set(name, true)
            end
            if autoTargetLabel then
                autoTargetLabel:Set(autoTargetText())
            end
        end)
        self._selectedConfigName = selected

        -- Auto Save Config: when on, Window:_persist also re-saves straight into whichever
        -- configuration is currently selected (self._autoSaveConfigEnabled, checked there) any
        -- time a registered control changes - not just the single default file
        -- `configuration.autoSave` already keeps current, so switching to "PvP Loadout" and
        -- tweaking a slider keeps "PvP Loadout" itself up to date without a manual Save click.
        local autoSaveConfigFlag = self:RegisterFlag("_AutoSaveConfig", false, function(value)
            self._autoSaveConfigEnabled = value
        end)
        self._autoSaveConfigEnabled = autoSaveConfigFlag.value

        local function refreshConfigs()
            local names = self:ListConfigs()
            configDropdown:Refresh(names)
            if selected and not table.find(names, selected) then
                selected = names[1]
            end
            if selected then
                selectedFlag:Set(selected)
            end
        end

        configDropdown = self.rfSettings:CreateDropdown({
            name = "Saved Configurations",
            icon = constants.icons.config,
            options = self:ListConfigs(),
            value = selected,
            placeholder = "No saved configurations",
            callback = function(value)
                selectedFlag:Set(value)
            end,
        })

        nameInput = self.rfSettings:CreateInput({
            name = "Configuration Name",
            icon = "lucide:tag",
            description = "Name a new configuration, or leave blank to overwrite the selected one.",
            placeholder = "e.g. PvP Loadout",
            clearOnFocus = false,
        })

        local actions = self.rfSettings:CreateGroup()

        actions:CreateButton({
            name = "Save",
            icon = "lucide:save",
            callback = function()
                local name = nameInput.value
                if name == "" then
                    name = selected
                end
                if not name or name == "" then
                    self:Toast({ title = locale.resolve("Name your configuration first") })
                    return
                end
                if self:Save(name) then
                    nameInput:Set("")
                    selectedFlag:Set(name)
                    refreshConfigs()
                    self:Toast({
                        title = locale.resolve("Saved configuration"),
                        subtitle = name,
                        icon = constants.icons.config,
                    })
                else
                    self:Toast({ title = locale.resolve("Couldn't save configuration"), subtitle = name })
                end
            end,
        })

        actions:CreateButton({
            name = "Load",
            icon = "lucide:folder-open",
            callback = function()
                if not selected or selected == "" then
                    self:Toast({ title = locale.resolve("Pick a configuration to load") })
                    return
                end
                if self:_applyNamedConfig(selected) then
                    self:Toast({ title = locale.resolve("Loaded configuration"), subtitle = selected })
                else
                    self:Toast({ title = locale.resolve("Couldn't load configuration"), subtitle = selected })
                end
            end,
        })

        actions:CreateButton({
            name = "Delete",
            icon = "lucide:trash-2",
            callback = function()
                local deleting = selected
                if not deleting or deleting == "" then
                    self:Toast({ title = locale.resolve("Pick a configuration to delete") })
                    return
                end
                if self:DeleteConfig(deleting) then
                    refreshConfigs()
                    self:Toast({ title = locale.resolve("Deleted configuration"), subtitle = deleting })
                else
                    self:Toast({ title = locale.resolve("Couldn't delete configuration"), subtitle = deleting })
                end
            end,
        })

        -- Clipboard export/import: a text-based sibling to the file-based Save/Load/Delete above,
        -- for sharing a config outside the executor's own file system (Discord, a text box, a
        -- config a friend sends over). Import pastes into an ordinary input rather than reading
        -- the clipboard directly - see ImportConfig's own comment for why.
        actions:CreateButton({
            name = "Export",
            icon = "lucide:share-2",
            callback = function()
                local ok, encoded = self:ExportConfig()
                if ok then
                    self:Toast({
                        title = locale.resolve("Configuration copied"),
                        subtitle = locale.resolve("Paste it anywhere to share it"),
                        icon = constants.icons.config,
                    })
                else
                    self:Toast({ title = locale.resolve("Couldn't export configuration") })
                end
            end,
        })

        local importInput = self.rfSettings:CreateInput({
            name = "Import Configuration",
            icon = "lucide:clipboard",
            description = "Paste a configuration string here, then Import.",
            placeholder = "Paste here...",
            clearOnFocus = false,
        })

        actions:CreateButton({
            name = "Import",
            icon = "lucide:clipboard-paste",
            callback = function()
                local raw = importInput.value
                if raw == "" then
                    self:Toast({ title = locale.resolve("Paste a configuration first") })
                    return
                end
                if self:ImportConfig(raw) then
                    importInput:Set("")
                    self:Save()
                    refreshConfigs()
                    self:Toast({ title = locale.resolve("Imported configuration") })
                else
                    self:Toast({ title = locale.resolve("That doesn't look like a valid configuration") })
                end
            end,
        })

        -- Both controls below only ever act on whatever's picked in "Saved Configurations" above -
        -- easy to lose track of once you've scrolled past it, so this stays in view right next to
        -- them and updates live off the same selectedFlag everything else here reads.
        autoTargetLabel = self.rfSettings:CreateLabel({
            text = autoTargetText(),
            icon = constants.icons.config,
        })

        -- A row Group (its default direction) sits the button and toggle side by side instead of
        -- each taking the full row - see group.luau's own compactCapable table for why Button/
        -- Toggle can do this and most other element types can't.
        local autoGroup = self.rfSettings:CreateGroup()

        -- A one-shot action rather than a toggle: press it once, with the configuration you want
        -- selected above, and *that* becomes what this script opens with from here on - not a
        -- live on/off state that would otherwise keep re-pointing itself at whatever you're just
        -- browsing to in the dropdown above (live-reported: switching configs while this was a
        -- toggle silently changed what would auto-load, with no separate action to "commit" one).
        -- Same underlying call as Window:SetAutoloadConfig/the Load button above - loads it live
        -- immediately too, and that's what makes the default file (what plain autoLoad restores
        -- next session) reflect it from here on.
        autoGroup:CreateButton({
            name = "Auto Load Config",
            icon = "lucide:download",
            description = "Makes the configuration above the one this script opens with automatically.",
            callback = function()
                if not selected or selected == "" then
                    self:Toast({ title = locale.resolve("Pick a configuration first") })
                    return
                end
                if self:SetAutoloadConfig(selected) then
                    self:Toast({ title = locale.resolve("Set as Auto Load Config"), subtitle = selected })
                else
                    self:Toast({ title = locale.resolve("Couldn't set Auto Load Config"), subtitle = selected })
                end
            end,
        })

        autoGroup:CreateToggle({
            name = "Auto Save Config",
            icon = "lucide:refresh-cw",
            description = "Keeps the configuration above updated as you change things.",
            value = autoSaveConfigFlag.value,
            callback = function(state)
                autoSaveConfigFlag:Set(state)
            end,
        })
    end

    -- Opt-in only (self._showUnloadButton, default false - see window.luau's own comment on it):
    -- a hold-to-confirm destructive action, so it's never one accidental click away. Danger Zone
    -- section lands last, after Configurations, so a player has already seen every save/export
    -- option before reaching the one button that throws all of it away for this session.
    if self._showUnloadButton then
        self.rfSettings:CreateSection({ name = "Danger Zone" })
        self.rfSettings:CreateHoldButton({
            name = "Destroy UI",
            icon = "lucide:trash-2",
            description = "Fully closes and unloads this menu. You'll need to run the script again to bring it back.",
            holdDuration = 1.5,
            danger = true,
            callback = function()
                self:Unload()
            end,
        })
    end

    if self._showSessionDashboard then
        self:_buildSessionDashboard()
    end
end

-- Devlog 7 "live session dashboard": player name, players on the server, uptime, and FPS,
-- refreshed every second. A plain card built straight onto rfSettings.tabPage rather than
-- through Tab:_register - it's a settings-only utility display, not a real element type devs
-- create, so it skips the reveal-fade system entirely and just renders opaque from the start.
function Window:_buildSessionDashboard()
    self.rfSettings:CreateSection({ name = "Session" })

    local card = self:Create("Frame", {
        Size = UDim2.new(1, -20, 0, 0),
        AutomaticSize = Enum.AutomaticSize.Y,
        BorderSizePixel = 0,
        Name = "SessionDashboard",
        BackgroundColor3 = Color3.fromRGB(255, 255, 255),
        BackgroundTransparency = 0,

        Parent = self.rfSettings.tabPage,
    }, { BackgroundTransparency = "ElementTransparency" })
    self:StyleElementBody(card)

    self:Create("UIPadding", {
        PaddingLeft = UDim.new(0, 20),
        PaddingRight = UDim.new(0, 20),
        PaddingTop = UDim.new(0, 14),
        PaddingBottom = UDim.new(0, 14),

        Parent = card,
    })

    self:Create("UIListLayout", {
        FillDirection = Enum.FillDirection.Vertical,
        SortOrder = Enum.SortOrder.LayoutOrder,
        Padding = UDim.new(0, 8),

        Parent = card,
    })

    local function buildRow(order, labelText)
        local row = self:Create("Frame", {
            Size = UDim2.new(1, 0, 0, 16),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            LayoutOrder = order,

            Parent = card,
        })
        self:Create("UIListLayout", {
            SortOrder = Enum.SortOrder.LayoutOrder,
            FillDirection = Enum.FillDirection.Horizontal,
            VerticalAlignment = Enum.VerticalAlignment.Center,
            HorizontalFlex = Enum.UIFlexAlignment.SpaceBetween,

            Parent = row,
        })
        self:Create("TextLabel", {
            Text = locale.t(labelText),
            Size = UDim2.fromOffset(0, 16),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,

            Parent = row,
        }, { TextColor3 = "PlaceholderColor", FontFace = "Font" })
        local value = self:Create("TextLabel", {
            Text = "-",
            Size = UDim2.fromOffset(0, 16),
            AutomaticSize = Enum.AutomaticSize.X,
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Right,
            LayoutOrder = 1,

            Parent = row,
        }, { TextColor3 = "ContentColor", FontFace = "Font" })
        return value
    end

    local playerValue = buildRow(1, "Player")
    local playersValue = buildRow(2, "Players online")
    local uptimeValue = buildRow(3, "Uptime")
    local fpsValue = buildRow(4, "FPS")

    local playersService = game:GetService("Players")
    local localPlayer = playersService.LocalPlayer
    local sessionStart = os.clock()
    local frameCount = 0

    self:Connect(variables.runService.RenderStepped, function()
        frameCount += 1
    end)

    local function formatUptime(seconds)
        seconds = math.floor(seconds)
        local h = math.floor(seconds / 3600)
        local m = math.floor((seconds % 3600) / 60)
        local s = seconds % 60
        if h > 0 then
            return string.format("%d:%02d:%02d", h, m, s)
        end
        return string.format("%d:%02d", m, s)
    end

    task.spawn(function()
        while not self.unloaded do
            playerValue.Text = if localPlayer then localPlayer.Name else "-"
            playersValue.Text = tostring(#playersService:GetPlayers())
            uptimeValue.Text = formatUptime(os.clock() - sessionStart)
            fpsValue.Text = tostring(frameCount) -- frames counted over the last ~1s window
            frameCount = 0
            task.wait(1)
        end
    end)
end


return Window
]=====]

sources["init"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local variables = require(script.utility.variables)
local image = require(script.utility.image)
local locale = require(script.utility.locale)
local constants = require(script.utility.constants)
local types = require(script.types)

-- re-export public types so consumers can annotate against Rayfield.Window etc
export type Theme = types.Theme
export type Translator = types.Translator
export type Translations = types.Translations
export type WindowConfiguration = types.WindowConfiguration

export type WindowProps = types.WindowProps
export type LoadingProps = types.LoadingProps
export type TabProps = types.TabProps
export type TagProps = types.TagProps
export type SectionProps = types.SectionProps
export type GroupProps = types.GroupProps
export type ButtonProps = types.ButtonProps
export type FlipButtonProps = types.FlipButtonProps
export type CopyButtonProps = types.CopyButtonProps
export type RippleButtonProps = types.RippleButtonProps
export type ToggleProps = types.ToggleProps
export type CheckboxProps = types.CheckboxProps
export type SliderProps = types.SliderProps
export type DropdownSection = types.DropdownSection
export type DropdownProps = types.DropdownProps
export type InputProps = types.InputProps
export type KeybindProps = types.KeybindProps
export type ColorPickerProps = types.ColorPickerProps
export type GradientStop = types.GradientStop
export type GradientPickerProps = types.GradientPickerProps
export type StatProps = types.StatProps
export type StatusCardRow = types.StatusCardRow
export type StatusCardProps = types.StatusCardProps
export type ProgressBarProps = types.ProgressBarProps
export type ScrollHintProps = types.ScrollHintProps
export type SegmentedPickerProps = types.SegmentedPickerProps
export type SegmentedPickerOption = types.SegmentedPickerOption
export type ShimmerLabelProps = types.ShimmerLabelProps
export type NotifyProps = types.NotifyProps
export type ToastProps = types.ToastProps
export type ToastAction = types.ToastAction
export type TourStep = types.TourStep
export type PopupBox = types.PopupBox
export type PopupOption = types.PopupOption
export type PopupProps = types.PopupProps
export type GreetingProps = types.GreetingProps
export type HoldButtonProps = types.HoldButtonProps
export type ChangelogEntry = types.ChangelogEntry
export type ChangelogProps = types.ChangelogProps
export type CollapsibleProps = types.CollapsibleProps
export type SpacerProps = types.SpacerProps

export type Moveable = types.Moveable
export type Window = types.Window
export type Tab = types.Tab
export type Group = types.Group
export type Button = types.Button
export type FlipButton = types.FlipButton
export type CopyButton = types.CopyButton
export type RippleButton = types.RippleButton
export type Toggle = types.Toggle
export type Checkbox = types.Checkbox
export type Slider = types.Slider
export type Dropdown = types.Dropdown
export type Input = types.Input
export type Keybind = types.Keybind
export type ColorPicker = types.ColorPicker
export type GradientPicker = types.GradientPicker
export type Stat = types.Stat
export type StatusCard = types.StatusCard
export type Section = types.Section
export type ProgressBar = types.ProgressBar
export type ScrollHint = types.ScrollHint
export type SegmentedPicker = types.SegmentedPicker
export type ShimmerLabel = types.ShimmerLabel
export type Tag = types.Tag
export type Popup = types.Popup
export type HoldButton = types.HoldButton
export type Changelog = types.Changelog
export type Collapsible = types.Collapsible
export type Spacer = types.Spacer
export type Rayfield = types.Rayfield

-- the components are untyped luau, so this is where the window module meets the public contract
type WindowModule = { new: (types.WindowProps) -> types.Window }

local rayfield = {} :: Rayfield

local function createBanner()
    local ui = Instance.new("ScreenGui")
    ui.Name = variables.httpService:GenerateGUID(false)
    ui.ClipToDeviceSafeArea = false
    ui.DisplayOrder = constants.displayOrder.banner
    ui.IgnoreGuiInset = true
    ui.ResetOnSpawn = false
    ui.Enabled = true
    ui.SafeAreaCompatibility = Enum.SafeAreaCompatibility.None
    ui.ScreenInsets = Enum.ScreenInsets.DeviceSafeInsets
    ui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    ui.Parent = variables.guiContainer

    local banner = Instance.new("ImageLabel")
    banner.Name = "Banner"
    banner.AnchorPoint = Vector2.new(0.5, 0.5)
    banner.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    banner.BackgroundTransparency = 1
    banner.BorderColor3 = Color3.fromRGB(0, 0, 0)
    banner.BorderSizePixel = 0
    banner.Image = image.resolve(constants.icons.banner)
    banner.Position = UDim2.fromScale(0.5, 0.5)
    banner.Size = UDim2.fromOffset(262, 60)
    banner.Parent = ui

    return ui
end

function rayfield:CreateWindow(properties: types.WindowProps): types.Window
    -- Opt-out for the brief Rayfield-branded splash that otherwise always flashes for ~0.5s
    -- between this call and the real window finishing construction - previously had no toggle
    -- at all. Read directly off the raw properties table (not something Window.new resolves)
    -- since the banner exists and is destroyed entirely within this function, before any Window
    -- instance is even built.
    local showBanner = properties.showBanner ~= false and properties.ShowBanner ~= false
    local banner = if showBanner then createBanner() else nil

    local window: types.Window? -- forward declared so the settle callback below can reach it
    -- preload can settle before the window is built; hold the notify until it is
    local queuedNotify: (() -> ())?

    if variables.secureMode then
        -- cache icons locally so secureMode doesnt leak asset ids. non-blocking: whats already on
        -- disk applies now, the rest download in the background and rebind once ready. if any never
        -- cache, tell the dev once - on screen only, secure mode stays off the console
        image.preload(function(failed)
            if failed <= 0 then
                return
            end
            local function notify()
                if not window or window.unloaded then
                    return
                end
                window:Notify({
                    title = locale.resolve("Secure mode"),
                    content = if failed == 1
                        then locale.resolve("An asset couldn't be cached and won't appear.")
                        else locale.resolve("Some assets couldn't be cached and won't appear."),
                })
            end
            if window then
                notify()
            else
                queuedNotify = notify
            end
        end)
    end

    -- the banner is only torn down once the window is up, so a throw in here (bad props) would
    -- otherwise strand it in the gui container for the rest of the session
    local made, result = pcall(function()
        return (require(script.components.window) :: WindowModule).new(properties)
    end)
    if not made then
        if banner then
            banner:Destroy()
        end
        error(result, 0)
    end

    local built = result :: types.Window
    window = built

    if queuedNotify then
        task.spawn(queuedNotify)
        queuedNotify = nil
    end

    if variables.secureMode then
        -- secure mode renders the fallback up front (variables.brandFont), then downloads the real
        -- brand faces off the main thread and swaps them in once ready, so startup never blocks
        task.spawn(function()
            local body = variables.fontManager:loadFont(constants.fontAsset, Enum.FontWeight.Medium)
            local title = variables.fontManager:loadFont(constants.fontAsset, Enum.FontWeight.SemiBold)
            -- the download can outlast the window; dont swap into one thats been unloaded
            if
                not built.unloaded
                and body
                and title
                and body ~= variables.fallbackFont
                and title ~= variables.fallbackFont
            then
                built:ChangeTheme({ Font = body, TitleFont = title })
            end
        end)
    end

    task.spawn(function()
        -- No banner to sit through when the dev opted out of it (showBanner = false) - waiting
        -- out its lifetime anyway was half a second of nothing before the window could appear.
        if banner then
            task.wait(0.5)
            banner:Destroy()
        end

        task.wait(0.25)
        -- the window can be unloaded inside this delay; showing it then would fire
        -- saved-config callbacks and build toasts on destroyed instances
        if not built.unloaded then
            built:Show()
        end
    end)

    return built
end

return rayfield
]=====]

