sources["types"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Public API types. camelCase is the documented surface; PascalCase keys still work.

export type Theme = string | { [string]: any }

-- Optional dev hook: given a source string (the English copy, which doubles as its key) and the
-- active locale id, return the translation, or nil/"" to fall through to the built-in tables.
export type Translator = (source: string, localeId: string) -> string?

-- Translation tables keyed by locale id, each mapping a source string to its translation, e.g.
-- { fr = { ["Close"] = "Fermer" }, ["pt-br"] = { ["Close"] = "Fechar" } }.
export type Translations = { [string]: { [string]: string } }

export type WindowConfiguration = {
    autoSave: boolean?,
    autoLoad: boolean?,
    fileName: string?,
    customFolder: string?,
    -- flags excluded from every save/load, config export/import included - Fluent's own
    -- SaveManager:SetIgnoreIndexes(), for things like a menu keybind or a one-off server action
    -- that shouldn't round-trip through a saved config at all. Per-element forgetState already
    -- covers the single-element case; this is the same idea as a standing list instead.
    ignoreFlags: { string }?,
    -- nests configs one folder deeper, named after game.PlaceId (or a Studio-safe stand-in) -
    -- so a multi-place experience, or a hub script reused across several games, never mixes one
    -- place's saved configs into another's. Opt-in: flipping this on for a window that already
    -- has saved configs at the old, unscoped path won't find them there anymore.
    scopeByPlace: boolean?,
}

-- Dev-configured splash (icon/title/optional cycling tip) played once, on the window's very
-- first Show(), before its own staged content reveal. Omit `loading` entirely on WindowProps to
-- skip the feature outright - passing it (even {}) turns it on and adds the player's Settings
-- toggle ("Loading Animation") to switch it back off per-session.
export type LoadingProps = {
    enabled: boolean?, -- dev's own default for the Settings toggle (default true)
    icon: (string | number)?, -- defaults to the window's own `icon`
    title: string?, -- defaults to the window's own `name`
    tips: { string }?, -- cycles like PlayGreeting's texts; omit/empty = no tip line at all
    tipHoldTime: number?, -- seconds each tip holds before crossfading to the next (default 0.9)
    duration: number?, -- minimum total time the splash stays up (default 1.1)
}

-- One step of a guided tour: target is whatever CreateToggle/CreateButton/etc itself returned
-- (anything with a .main), title/description are the bubble's copy for that step. Steps can
-- freely mix targets from different tabs - the tour auto-Selects whichever tab actually owns
-- the next step's target (see tour.luau's own findOwningTab), no per-step tab field needed.
export type TourStep = {
    target: any,
    title: string?,
    description: string?,
}

export type WindowProps = {
    name: string?,
    subtitle: string?,
    theme: Theme?,
    icon: (string | number)?,
    showName: string?,
    showIcon: (string | number)?,
    loading: LoadingProps?,
    -- guided onboarding tour, played once automatically on first show; omit entirely to skip
    -- the feature (no Settings "Replay Tour" button either) - see tour.luau
    tour: { TourStep }?,
    configuration: WindowConfiguration?,
    fallbackFont: (Font | Enum.Font)?, -- built-in stand-in shown in secure mode while the brand font downloads
    locale: string?, -- pin the UI language; defaults to the player's Roblox locale
    translations: Translations?, -- language tables keyed by locale id; the easy, table-first path
    translator: Translator?, -- resolve copy yourself; falls back to the built-in tables
    -- Live machine translation for every dev string (see autoTranslate.luau) - no table, no
    -- translator function, nothing to maintain: turn it on and every name/description a script
    -- writes gets translated automatically the first time a player sees it in another language,
    -- then cached forever after. translator/translations above still win when both are set -
    -- this only fills in what neither of those already answers.
    autoTranslate: boolean?,
    -- Squircle corners (see utility/squircle.luau) on the window body only, instead of a plain
    -- UICorner circular arc - a smoother, more "premium" curve, at the cost of a couple of known
    -- gaps: an explicit borderColor/rainbowBorder still outlines a plain rounded rect (not the
    -- squircle curve), and the minimize-to-pill collapse animation keeps the squircle's normal
    -- radius throughout rather than rounding into a true pill.
    squircleCorners: boolean?,
    -- The Settings tab's own "Session" card (player name/players online/uptime/FPS, live-updated)
    -- - default true. Set false when a hub's own Dashboard tab already shows the same numbers, so
    -- a player doesn't see the same session info twice.
    sessionDashboard: boolean?,
    -- Settings > General toggles a hub can hide when it wants the behaviour pinned instead of
    -- player-adjustable - hiding one doesn't change self.settings' own default, only whether a
    -- player can flip it from Settings. All default true (unchanged from every toggle always
    -- showing, today's behaviour).
    showWelcomeToastToggle: boolean?,
    showHapticsToggle: boolean?,
    showSoundEffectsToggle: boolean?,
    showLoadingAnimationToggle: boolean?,
    -- initial window size (Vector2, a UDim2's offset component, or a {width,height}/{X,Y} table)
    -- - still screen-fit the same way the built-in default is, see windowSizing.luau
    size: (Vector2 | UDim2 | { [string]: number } | { number })?,

    -- Direct per-window visual overrides, layered on top of whatever the theme already draws -
    -- for a dev who wants one specific window's look tweaked without writing a whole custom
    -- theme table. Omit any of these and that piece stays exactly as the theme already renders
    -- it. gradient gates whether gradientColorSequence/gradientRotation apply at all, the same
    -- two-step shape Fluent's own Gradient/GradientColorSequence/GradientRotation properties use.
    gradient: boolean?,
    gradientColorSequence: ColorSequence?,
    gradientRotation: number?,
    borderColor: Color3?,
    borderThickness: number?,
    shadowColor: Color3?,
    shadowThickness: number?,
    shadowTransparency: number?,
    cornerRadius: number?, -- pixels

    -- Cycles the window's own border stroke through the hue wheel continuously. Forces the
    -- border visible the same way borderColor does (no need to also set one) - implies a border,
    -- doesn't just recolour an already-explicit one. Scoped to the window's own border only, not
    -- Fluent's full per-surface RainbowBorderTargets table (popups/groupboxes/cards) - the
    -- window itself is the only target actually turned on across every real CreateWindow call
    -- this was modelled from.
    rainbowBorder: boolean?,
    rainbowBorderSpeed: number?, -- full hue cycles per second (default 0.14, matching Fluent's own)

    -- Which bottom corner Window:Notify's stack grows from (default "Right", matching every
    -- prior version of this). Toast's own Top/Bottom is a separate, per-call `position` already.
    notifySide: ("Left" | "Right")?,

    -- Multiplies the resize grip's touch target on a touch-primary device (Window:IsMobile()) -
    -- default 1.4. See Window:IsMobile's own comment; also usable from a dev's own script.
    mobileHitScale: number?,

    -- The brief Rayfield-branded splash shown between this call and the window itself finishing
    -- construction - default true (unchanged). Set false to skip it outright.
    showBanner: boolean?,

    -- Adds a "Danger Zone" section to Settings with a hold-to-confirm "Destroy UI" button that
    -- calls Window:Unload(). Default false - destructive, so it's opt-in unlike the toggle-hide
    -- properties above.
    showUnloadButton: boolean?,
}

export type TabProps = {
    name: string?,
    icon: (string | number)?,
    locked: boolean?,
}

export type TagProps = {
    text: string?,
    title: string?,
    icon: (string | number)?,
    color: Color3?,
    order: number?,
}

export type SectionProps = {
    name: string?,
    icon: (string | number)?,
}

export type LabelProps = {
    text: string?,
    icon: (string | number)?,
}

export type ParagraphProps = {
    title: string?,
    content: string?,
    icon: (string | number)?,
}

export type DividerProps = {
    text: string?,
    line: boolean?, -- default true; false = spacing-only, no visible rule
    spacing: string?, -- "tight" | "normal" (default) | "loose" - vertical padding around the line
    height: number?, -- gap height in px when line = false (default 24)
}

export type GroupProps = {
    direction: string?, -- "row" | "column" (default row); "horizontal"/"vertical" also work
    -- Dependency group: hides/shows every child together based on another control's value -
    -- Fluent's own DependencyGroupbox. dependsOn is whatever CreateToggle/CreateDropdown/etc
    -- itself returned; condition defaults to a plain truthy check (built for a toggle) - pass
    -- one explicitly for a dropdown/slider-driven group, e.g. function(v) return v == "Advanced"
    -- end.
    dependsOn: any?,
    condition: ((value: any) -> boolean)?,
}

-- tooltip is shared by every card element (see Window:_wireTooltip): hold the mouse a moment
-- and it fades in above the cursor, wrapping for longer text.
export type ButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    locked: boolean?,
    -- a cheap destructive-action confirm: the first click just arms the button (its title flips
    -- to confirmText for a few seconds), the callback only fires on the confirming second click
    doubleClick: boolean?,
    confirmText: string?, -- default "Click again to confirm"
    callback: (() -> ())?,
}

export type ToggleProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    value: boolean?,
    locked: boolean?,
    forgetState: boolean?,
    callback: ((value: boolean) -> ())?,
}

-- A compact alternative to Toggle: same flag/config/description contract, a check box instead
-- of a pill switch.
export type CheckboxProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    value: boolean?,
    forgetState: boolean?,
    callback: ((value: boolean) -> ())?,
}

export type CopyButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?, -- shown inside the well; the well still works without one
    tooltip: string?,
    text: string?, -- the string copied to the clipboard
    callback: ((success: boolean) -> ())?, -- fires after every press with whether the copy landed
}

export type FlipButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    secondaryName: string?, -- the back face; hovering flips the title to this and back
    callback: (() -> ())?,
}

-- A Button whose press feedback is a ripple from the exact point pressed (mouse or touch),
-- clipped to the card's rounded corners, instead of Button's stroke-ghost + width-bounce.
export type RippleButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    callback: (() -> ())?,
}

export type ProgressBarProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    value: number?,
    max: number?, -- default 100
    suffix: string?, -- set this to switch the readout to "{value} {suffix} out of {max}"
}

export type ScrollHintProps = {
    text: string?,
}

export type ConsoleProps = {
    name: string?,
    description: string?,
    text: string?,
    height: number?, -- default 120
    follow: boolean?, -- pin to the newest line as output arrives, like a real log
    maxLines: number?, -- default 200; oldest lines roll off past this
}

export type SegmentedPickerOption = string | {
    text: string?,
    Text: string?,
    -- nested sub-options, expanded inline within this segment's own slot once it's selected
    options: { (string | { text: string?, Text: string? }) }?,
    Options: { (string | { text: string?, Text: string? }) }?,
}

export type SegmentedPickerProps = {
    options: { SegmentedPickerOption }?,
    value: string?, -- a leaf's text - a top-level option's own, or a nested child's
    description: string?,
    flag: string?,
    forgetState: boolean?,
    callback: ((value: string) -> ())?,
}

export type ShimmerLabelProps = {
    text: string?,
    speed: number?, -- seconds per sweep (default 1.4)
    spread: number?, -- 0..1, width of the bright band (default 0.2)
    angle: number?, -- gradient rotation in degrees (default 20)
    textSize: number?,
}

export type SliderProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    range: { number }?, -- { min, max }
    increment: number?,
    value: number?,
    suffix: string?,
    minimal: boolean?, -- track only, no name/value (for dense rows)
    forgetState: boolean?,
    callback: ((value: number) -> ())?,
}

export type DropdownSection = {
    name: string?,
    options: { string }?,
}

export type DropdownProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    options: { string }?,
    -- section headers (e.g. "MELEE"/"RANGED") - when given, takes over from `options` above,
    -- which is instead derived by flattening every section's own option list in order
    sections: { DropdownSection }?,
    value: (string | { string })?,
    multiSelect: boolean?,
    placeholder: string?,
    locked: boolean?,
    forgetState: boolean?,
    callback: ((value: any) -> ())?,
}

export type InputProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    value: string?,
    placeholder: string?,
    numeric: boolean?,
    clearOnFocus: boolean?,
    forgetState: boolean?,
    callback: ((value: string) -> ())?,
}

export type KeybindProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    value: (EnumItem | string)?, -- an Enum.KeyCode / mouse button, or a KeyCode name
    forgetState: boolean?,
    isMenuToggle: boolean?, -- internal: the settings menu-toggle keybind, clash check runs in reverse
    hold: boolean?, -- fire callback(true) once held, callback(false) on release
    holdThreshold: number?, -- seconds to hold before it counts (default 0.2)
    callback: ((value: EnumItem | boolean) -> ())?, -- bound key on press, or true/false in hold mode
    onChanged: ((key: EnumItem) -> ())?, -- fires when the binding is changed
}

export type ColorPickerProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    color: Color3?, -- initial colour (accepts a hex string too)
    alpha: number?, -- initial alpha 0..1 (default 1, no dedicated control in this layout - set via code)
    presets: { Color3 }?, -- quick-pick swatches under the RGB row
    glow: boolean?, -- ambient glow behind the card (default true)
    forgetState: boolean?,
    callback: ((value: Color3, alpha: number) -> ())?,
}

export type GradientStop = {
    time: number,
    color: Color3,
}

export type GradientPickerProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    gradient: (ColorSequence | { Color3 } | { GradientStop })?, -- initial value
    glow: boolean?, -- ambient glow behind the card (default true)
    forgetState: boolean?,
    callback: ((value: ColorSequence) -> ())?,
}

export type HoldButtonProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    flag: string?,
    holdDuration: number?, -- seconds the fill takes to complete (default 1)
    danger: boolean?, -- tint the fill red instead of the accent colour
    locked: boolean?,
    callback: (() -> ())?,
}

export type ChangelogEntry = {
    tag: string?, -- "ADDED" | "FIXED" | "CHANGED" | "REMOVED", or any custom tag
    text: string?,
}

export type ChangelogProps = {
    name: string?, -- card title (default "Update Log")
    version: string?,
    date: string?,
    entries: { ChangelogEntry }?,
}

export type CollapsibleProps = {
    name: string?,
    icon: (string | number)?,
    expanded: boolean?, -- start open (default false)
}

export type SpacerProps = {
    height: number?, -- pixel gap (default 12)
}

export type StatProps = {
    name: string?,
    description: string?,
    icon: (string | number)?,
    tooltip: string?,
    prefix: string?,
    suffix: string?,
    value: number?,
    display: string?, -- "value" | "change"
    compact: boolean?,
    changeMode: string?, -- "percentage" | "absolute"
    changeBaseline: string?, -- "previous" | "initial"
    numberEasing: boolean?,
}

-- One line of a StatusCard: label (dim, translated like any other dev-authored copy) · value
-- (live data - never auto-translated, since it changes at runtime). key defaults to `label` if
-- omitted; give it explicitly when the label itself might repeat or change.
export type StatusCardRow = {
    key: string?,
    label: string,
    value: string,
    muted: boolean?, -- renders the value in a plain, unremarkable colour instead of the theme accent
}

export type StatusCardProps = {
    name: string?, -- header title, default "Status"
    icon: (string | number)?,
    width: number?, -- card width in pixels, default 260 - fixed-width by design, not full tab width
    collapsible: boolean?, -- shows the header chevron, default true
    expanded: boolean?, -- default true
    glow: boolean?, -- ambient glow behind the card, default true
    rows: { StatusCardRow }?,
}

export type NotifyProps = {
    title: string?,
    content: string?,
    icon: (string | number)?,
    duration: number?,
    accentColor: Color3?,
    -- skip the auto-dismiss dwell entirely; the caller owns this notification's lifetime and
    -- must call :Destroy() on the returned handle themselves. Pair with :SetProgress/
    -- :ChangeTitle/:ChangeDescription for a long job's in-place progress card.
    persist: boolean?,
}

export type ToastAction = {
    text: string,
    callback: () -> (),
}

export type ToastProps = {
    title: string?,
    subtitle: string?, -- optional second line
    subtitleAbove: boolean?, -- render the subtitle above the title (label-over-value)
    icon: (string | number)?, -- optional; asset id or ready image string (rbxthumb works)
    avatar: number?, -- optional user id; shows that user's headshot as a larger avatar
    minWidth: number?, -- floor the pill width; slack becomes right-hand room (content is left-aligned)
    duration: number?,
    position: "Top" | "Bottom"?,
    -- optional trailing pill button (e.g. "Undo") - runs callback (guarded), then dismisses
    action: ToastAction?,
}

export type PopupBox = {
    title: string?,
    description: string?,
    icon: (string | number)?,
}

export type PopupOption = {
    text: string?,
    style: string?, -- "neutral" (default) | "primary" | "danger"
    -- receives the popup's current input value (see PopupProps.input) - "" when there's no
    -- input field. Return false to reject and keep the popup open (flashes the field red)
    -- instead of closing - the mechanism Window:KeySystem itself is built on.
    callback: ((value: string) -> boolean?)?,
}

export type PopupInputProps = {
    placeholder: string?,
    value: string?,
}

export type PopupProps = {
    title: string?,
    subtitle: string?,
    icon: (string | number)?,
    content: string?, -- a body paragraph
    boxes: { PopupBox }?, -- a list of cards (the changelog layout)
    -- a full-width text field between the content and the buttons, turning a plain confirm
    -- dialog into a "type something and submit" prompt. A plain string is shorthand for
    -- { placeholder = string }.
    input: (string | PopupInputProps)?,
    options: { PopupOption }?, -- footer buttons; defaults to a single dismiss button
    dismissable: boolean?, -- click the dim or press Escape to close (default true)
}

export type KeySystemProps = {
    title: string?,
    subtitle: string?,
    icon: (string | number)?,
    note: string?, -- body text above the field (a hint, a link to get a key, etc)
    placeholder: string?,
    submitText: string?,
    exitText: string?,
    -- exactly one of these decides what counts as a valid key: validator wins if given, else
    -- key/keys. validator is pcall'd - a throw counts as rejected, not a crash.
    validator: ((key: string) -> boolean)?,
    key: string?,
    keys: { string }?,
    -- persist an *accepted* key to disk so a returning player skips the gate - re-checked
    -- against validator/key every launch, not trusted blindly, so a revoked/rotated key can't
    -- let someone in forever just because it worked once.
    saveKey: boolean?,
    onSuccess: (() -> ())?,
    onFailure: (() -> ())?,
}

-- Handles ------------------------------------------------------------------
-- Every element can be reordered within its tab.
export type Moveable = {
    MoveTo: (self: any, index: number) -> (),
    MoveToTop: (self: any) -> (),
    MoveToBottom: (self: any) -> (),
    MoveUp: (self: any) -> (),
    MoveDown: (self: any) -> (),
    -- Devlog 7: shows/hides the element at runtime, independent of tab switching or the window
    -- itself hiding - pulls it out of layout entirely rather than just fading it.
    SetVisible: (self: any, visible: boolean) -> (),
}

export type Button = Moveable & {
    locked: boolean,
    SetLocked: (self: Button, locked: boolean) -> (),
    -- Shared Lock/Unlock/IsLocked naming, aliased into SetLocked - see lockable.luau.
    Lock: (self: Button) -> (),
    Unlock: (self: Button) -> (),
    IsLocked: (self: Button) -> boolean,
}

export type RippleButton = Moveable & {}

export type ProgressBar = Moveable & {
    value: number,
    Set: (self: ProgressBar, value: number, skipAnimation: boolean?) -> (),
}

export type Console = Moveable & {
    Get: (self: Console) -> string,
    Set: (self: Console, text: string) -> (),
    Append: (self: Console, line: string) -> (),
    Clear: (self: Console) -> (),
    Copy: (self: Console) -> boolean,
    SetHeight: (self: Console, height: number) -> (),
}

export type ScrollHint = Moveable & {
    Set: (self: ScrollHint, text: string) -> (),
}

export type SegmentedPicker = Moveable & {
    value: string,
    Set: (self: SegmentedPicker, value: string, skipCallback: boolean?) -> (),
}

export type ShimmerLabel = Moveable & {
    text: string,
    Set: (self: ShimmerLabel, text: string) -> (),
    SetSpeed: (self: ShimmerLabel, seconds: number) -> (),
    SetSpread: (self: ShimmerLabel, fraction: number) -> (),
    SetAngle: (self: ShimmerLabel, degrees: number) -> (),
    SetTextSize: (self: ShimmerLabel, size: number) -> (),
}

export type CopyButton = Moveable & {
    text: string,
    Set: (self: CopyButton, text: string) -> (),
}

export type FlipButton = Moveable & {
    Set: (self: FlipButton, front: string?, back: string?) -> (),
}

export type Toggle = Moveable & {
    value: boolean,
    locked: boolean,
    Set: (self: Toggle, value: boolean, skipCallback: boolean?) -> (),
    SetLocked: (self: Toggle, locked: boolean) -> (),
    -- Element Locking (ported from upstream Rayfield Gen2 1.2): shared Lock/Unlock/IsLocked
    -- naming, aliased into this component's own SetLocked - see lockable.luau's own comment.
    Lock: (self: Toggle) -> (),
    Unlock: (self: Toggle) -> (),
    IsLocked: (self: Toggle) -> boolean,
    SetStatus: (self: Toggle, text: string) -> (),
    -- Runs fn(toggle) on a repeating timer for as long as this toggle is on; fn can return a
    -- number to override the wait before the next call instead of `interval` (default 0.5s).
    -- Managed and error-isolated per tick - see toggle.luau's own comment on why this beats a
    -- hand-rolled while loop in the toggle's own callback.
    Loop: (self: Toggle, fn: (toggle: any) -> number?, interval: number?) -> (),
}

export type Checkbox = Moveable & {
    value: boolean,
    Set: (self: Checkbox, value: boolean, skipCallback: boolean?) -> (),
}

export type Slider = Moveable & {
    value: number,
    locked: boolean,
    Set: (self: Slider, value: number, skipCallback: boolean?) -> (),
    -- Element Locking (ported from upstream Rayfield Gen2 1.2): dims the element and covers it
    -- with an input-blocking scrim. `reason` replaces its description while locked.
    Lock: (self: Slider, reason: string?) -> (),
    Unlock: (self: Slider) -> (),
    IsLocked: (self: Slider) -> boolean,
}

export type Dropdown = Moveable & {
    value: { string }, -- always stored pruned to the current options, even single-select
    locked: boolean,
    Set: (self: Dropdown, value: string | { string }, skipCallback: boolean?) -> (),
    Reset: (self: Dropdown, skipCallback: boolean?) -> (), -- clears back to the placeholder
    SetLocked: (self: Dropdown, locked: boolean) -> (),
    -- Shared Lock/Unlock/IsLocked naming, aliased into SetLocked - see lockable.luau.
    Lock: (self: Dropdown) -> (),
    Unlock: (self: Dropdown) -> (),
    IsLocked: (self: Dropdown) -> boolean,
}

export type Input = Moveable & {
    value: string,
    locked: boolean,
    Set: (self: Input, value: string, skipCallback: boolean?) -> (),
    -- Element Locking (ported from upstream Rayfield Gen2 1.2): dims the element and covers it
    -- with an input-blocking scrim. `reason` replaces its description while locked.
    Lock: (self: Input, reason: string?) -> (),
    Unlock: (self: Input) -> (),
    IsLocked: (self: Input) -> boolean,
}

export type Keybind = Moveable & {
    value: EnumItem,
    locked: boolean,
    Set: (self: Keybind, value: EnumItem | string, skipChanged: boolean?) -> (),
    -- Element Locking (ported from upstream Rayfield Gen2 1.2): dims the element and covers it
    -- with an input-blocking scrim. `reason` replaces its description while locked.
    Lock: (self: Keybind, reason: string?) -> (),
    Unlock: (self: Keybind) -> (),
    IsLocked: (self: Keybind) -> boolean,
}

export type ColorPicker = Moveable & {
    value: Color3,
    alpha: number,
    locked: boolean,
    Set: (self: ColorPicker, value: Color3 | string, skipCallback: boolean?) -> (),
    SetAlpha: (self: ColorPicker, alpha: number, skipCallback: boolean?) -> (),
    SetGlow: (self: ColorPicker, shown: boolean) -> (),
    -- Element Locking (ported from upstream Rayfield Gen2 1.2): dims the element and covers it
    -- with an input-blocking scrim. `reason` replaces its description while locked.
    Lock: (self: ColorPicker, reason: string?) -> (),
    Unlock: (self: ColorPicker) -> (),
    IsLocked: (self: ColorPicker) -> boolean,
}

export type GradientPicker = Moveable & {
    value: ColorSequence,
    Set: (self: GradientPicker, value: (ColorSequence | { Color3 } | { GradientStop }), skipCallback: boolean?) -> (),
    SetGlow: (self: GradientPicker, shown: boolean) -> (),
}

export type Stat = Moveable & {
    value: number,
    Set: (self: Stat, value: number) -> (),
    ResetBaseline: (self: Stat, value: number?) -> (),
}

export type StatusCard = Moveable & {
    expanded: boolean,
    SetRow: (self: StatusCard, key: string, value: string, muted: boolean?) -> (),
    AddRow: (self: StatusCard, row: StatusCardRow, index: number?) -> (),
    RemoveRow: (self: StatusCard, key: string) -> (),
    Set: (self: StatusCard, rows: { StatusCardRow }) -> (),
    SetExpanded: (self: StatusCard, expanded: boolean) -> (),
    Toggle: (self: StatusCard) -> (),
}

export type Section = Moveable & {}

export type Label = Moveable & {
    Set: (self: Label, text: string) -> (),
}

export type Paragraph = Moveable & {
    Set: (self: Paragraph, props: { title: string?, content: string? }) -> (),
    SetTitle: (self: Paragraph, text: string) -> (),
    SetContent: (self: Paragraph, text: string) -> (),
}

export type Divider = Moveable & {
    Set: (self: Divider, text: string) -> (),
}

export type HoldButton = Moveable & {
    locked: boolean,
    SetLocked: (self: HoldButton, locked: boolean) -> (),
    -- Shared Lock/Unlock/IsLocked naming, aliased into SetLocked - see lockable.luau.
    Lock: (self: HoldButton) -> (),
    Unlock: (self: HoldButton) -> (),
    IsLocked: (self: HoldButton) -> boolean,
}

export type Changelog = Moveable & {}

export type Spacer = Moveable & {
    height: number,
    SetHeight: (self: Spacer, height: number, animate: boolean?) -> (),
}

-- A collapsible section hosts its own nested elements through the same reduced CreateX surface
-- as a Group (see Group above) - it wraps one internally.
export type Collapsible = Moveable & {
    expanded: boolean,
    Toggle: (self: Collapsible) -> (),
    SetExpanded: (self: Collapsible, expanded: boolean) -> (),
    CreateButton: (self: Collapsible, props: ButtonProps) -> Button,
    CreateFlipButton: (self: Collapsible, props: FlipButtonProps) -> FlipButton,
    CreateCopyButton: (self: Collapsible, props: CopyButtonProps) -> CopyButton,
    CreateRippleButton: (self: Collapsible, props: RippleButtonProps) -> RippleButton,
    CreateToggle: (self: Collapsible, props: ToggleProps) -> Toggle,
    CreateSwitch: (self: Collapsible, props: ToggleProps) -> Toggle,
    CreateCheckbox: (self: Collapsible, props: CheckboxProps) -> Checkbox,
    CreateStat: (self: Collapsible, props: StatProps) -> Stat,
    CreateStatusCard: (self: Collapsible, props: StatusCardProps) -> StatusCard,
    CreateSlider: (self: Collapsible, props: SliderProps) -> Slider,
    CreateDropdown: (self: Collapsible, props: DropdownProps) -> Dropdown,
    CreateSection: (self: Collapsible, props: SectionProps) -> Section,
    CreateLabel: (self: Collapsible, props: LabelProps?) -> Label,
    CreateParagraph: (self: Collapsible, props: ParagraphProps?) -> Paragraph,
    CreateDivider: (self: Collapsible, props: DividerProps?) -> Divider,
    CreateGroup: (self: Collapsible, props: GroupProps?) -> Group,
}

-- Tags sit in the window's title bar and order themselves, so they aren't Moveable.
export type Tag = {
    Set: (self: Tag, props: TagProps) -> (),
    SetColor: (self: Tag, color: Color3) -> (),
    SetText: (self: Tag, text: string?) -> (),
    SetIcon: (self: Tag, icon: (string | number)?) -> (),
    Remove: (self: Tag) -> (),
}

export type Popup = {
    Close: (self: Popup) -> (),
}

-- A group lays elements along one axis and nests, so a row of columns builds a grid.
-- A row accepts the compact elements
-- (button/toggle/stat/checkbox/copybutton/flipbutton/ripplebutton) + slider; a column also
-- takes dropdown and section. Input, keybind, colorpicker, progressbar and scrollhint stay
-- tab-level for now.
export type Group = Moveable & {
    CreateButton: (self: Group, props: ButtonProps) -> Button,
    CreateFlipButton: (self: Group, props: FlipButtonProps) -> FlipButton,
    CreateCopyButton: (self: Group, props: CopyButtonProps) -> CopyButton,
    CreateRippleButton: (self: Group, props: RippleButtonProps) -> RippleButton,
    CreateToggle: (self: Group, props: ToggleProps) -> Toggle,
    CreateSwitch: (self: Group, props: ToggleProps) -> Toggle,
    CreateCheckbox: (self: Group, props: CheckboxProps) -> Checkbox,
    CreateStat: (self: Group, props: StatProps) -> Stat,
    CreateStatusCard: (self: Group, props: StatusCardProps) -> StatusCard,
    CreateSlider: (self: Group, props: SliderProps) -> Slider,
    CreateDropdown: (self: Group, props: DropdownProps) -> Dropdown,
    CreateSection: (self: Group, props: SectionProps) -> Section,
    CreateLabel: (self: Group, props: LabelProps?) -> Label,
    CreateParagraph: (self: Group, props: ParagraphProps?) -> Paragraph,
    CreateDivider: (self: Group, props: DividerProps?) -> Divider,
    CreateGroup: (self: Group, props: GroupProps?) -> Group,
}

export type Tab = {
    CreateButton: (self: Tab, props: ButtonProps) -> Button,
    CreateFlipButton: (self: Tab, props: FlipButtonProps) -> FlipButton,
    CreateCopyButton: (self: Tab, props: CopyButtonProps) -> CopyButton,
    CreateRippleButton: (self: Tab, props: RippleButtonProps) -> RippleButton,
    CreateToggle: (self: Tab, props: ToggleProps) -> Toggle,
    CreateSwitch: (self: Tab, props: ToggleProps) -> Toggle,
    CreateCheckbox: (self: Tab, props: CheckboxProps) -> Checkbox,
    CreateSlider: (self: Tab, props: SliderProps) -> Slider,
    CreateDropdown: (self: Tab, props: DropdownProps) -> Dropdown,
    CreateInput: (self: Tab, props: InputProps) -> Input,
    CreateKeybind: (self: Tab, props: KeybindProps) -> Keybind,
    CreateColorPicker: (self: Tab, props: ColorPickerProps) -> ColorPicker,
    CreateGradientPicker: (self: Tab, props: GradientPickerProps?) -> GradientPicker,
    CreateStat: (self: Tab, props: StatProps) -> Stat,
    CreateStatusCard: (self: Tab, props: StatusCardProps) -> StatusCard,
    CreateSection: (self: Tab, props: SectionProps) -> Section,
    CreateLabel: (self: Tab, props: LabelProps?) -> Label,
    CreateParagraph: (self: Tab, props: ParagraphProps?) -> Paragraph,
    CreateDivider: (self: Tab, props: DividerProps?) -> Divider,
    CreateProgressBar: (self: Tab, props: ProgressBarProps) -> ProgressBar,
    CreateConsole: (self: Tab, props: ConsoleProps) -> Console,
    CreateScrollHint: (self: Tab, props: ScrollHintProps?) -> ScrollHint,
    CreateSegmentedPicker: (self: Tab, props: SegmentedPickerProps?) -> SegmentedPicker,
    CreateShimmerLabel: (self: Tab, props: ShimmerLabelProps?) -> ShimmerLabel,
    CreateGroup: (self: Tab, props: GroupProps?) -> Group,
    CreateHoldButton: (self: Tab, props: HoldButtonProps?) -> HoldButton,
    CreateCollapsible: (self: Tab, props: CollapsibleProps?) -> Collapsible,
    CreateChangelog: (self: Tab, props: ChangelogProps?) -> Changelog,
    CreateSpacer: (self: Tab, props: SpacerProps?) -> Spacer,
    locked: boolean,
    SetLocked: (self: Tab, locked: boolean) -> (),
}

export type GreetingProps = {
    texts: { string }?,
    holdTime: number?, -- seconds each greeting stays fully shown (default 0.85)
    wipeTime: number?, -- duration of the closing curved wipe (default 0.7)
}

export type Window = {
    unloaded: boolean, -- true once Unload has run; the handle is spent
    CreateTab: (self: Window, props: TabProps) -> Tab,
    -- Sidebar tabsMode only - a heading in the tab rail grouping the rows created after it. See
    -- tabSection.luau's own header comment for why it's inert on the top strip.
    CreateSection: (self: Window, props: SectionProps) -> Section,
    -- Programmatic equivalent of the Settings "Haptics" toggle - for pinning it one way or the
    -- other when showHapticsToggle hides that control. Haptics default on as of this fork's port
    -- of upstream Rayfield Gen2 1.2 (was off).
    SetHaptics: (self: Window, enabled: boolean) -> (),
    CreateTag: (self: Window, props: TagProps) -> Tag,
    Notify: (self: Window, props: NotifyProps) -> (),
    Toast: (self: Window, props: ToastProps) -> (),
    Popup: (self: Window, props: PopupProps) -> Popup,
    PlayGreeting: (self: Window, props: GreetingProps?) -> (),
    Show: (self: Window) -> (),
    Hide: (self: Window) -> (),
    ToggleHide: (self: Window) -> (),
    ToggleMinimise: (self: Window) -> (),
    Navigate: (self: Window, tab: string | Tab) -> (),
    ChangeTheme: (self: Window, theme: Theme) -> (),
    -- live font swap: "Auto" (brand font) or any built-in Roblox font name
    SetFont: (self: Window, name: string) -> (),
    -- Devlog 7 "glass window": 0 (opaque, default) to 100 (fully invisible)
    SetTransparency: (self: Window, percent: number) -> (),
    -- Devlog 7: frosts the game behind the window via a Lighting blur
    SetAcrylic: (self: Window, enabled: boolean, size: number?) -> (),
    SetLocale: (self: Window, localeId: string) -> (),
    SetTranslator: (self: Window, translator: Translator?) -> (),
    RegisterTranslations: (self: Window, translations: Translations) -> (),
    Save: (self: Window, name: string?) -> boolean,
    Load: (self: Window, name: string?) -> boolean,
    ListConfigs: (self: Window) -> { string },
    DeleteConfig: (self: Window, name: string) -> boolean,
    Unload: (self: Window) -> (),
    OnUnload: (self: Window, callback: () -> ()) -> (),
    -- pcalls fn(...) and logs a warning on failure instead of letting it fail silently - returns
    -- exactly what pcall returns (ok, result...).
    Safe: (self: Window, fn: (...any) -> ...any, ...any) -> ...any,
    -- Retries fn(attempt) with exponential backoff (default 3 attempts, 1s/2s/4s...) - for a
    -- flaky remote call/HTTP request worth a few real chances before giving up.
    RetryWithBackoff: (
        self: Window,
        fn: (attempt: number) -> any,
        options: { attempts: number?, baseDelay: number?, maxDelay: number? }?
    ) -> (boolean, any),
}

export type Rayfield = {
    CreateWindow: (self: Rayfield, props: WindowProps) -> Window,
}

return {}
]=====]

sources["utility/HapticEngine"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Haptic feedback. A thin wrapper over HapticEffect that buzzes the player's device
-- (phone, gamepad, VR controller) on two interactions: a press and a notification. We map
-- them to the presets that feel best in practice - the softer UIHover tick for a press, the
-- crisper UIClick for a notification. No-ops on devices without haptics, off from settings.

local variables = require(script.Parent.variables)

local hapticEngine = {}

hapticEngine.enabled = false -- off by default; the settings toggle flips it (see setEnabled)

-- Resolve the presets once. HapticEffect (and its enum) only exist on newer clients, so
-- everything below is gated on this: on an old client `types` stays empty and every call
-- is a no-op. pcall guards the enum lookup too, since indexing a missing value would throw.
type HapticTypes = {
    click: Enum.HapticEffectType?,
    notify: Enum.HapticEffectType?,
}

local types: HapticTypes = {}
local supported, resolvedTypes = pcall(function()
    Instance.new("HapticEffect"):Destroy() -- probe: errors on clients without the class
    return {
        click = Enum.HapticEffectType.UIHover, -- presses use the softer hover tick
        notify = Enum.HapticEffectType.UIClick, -- notifications use the crisper click
    }
end)
if supported then
    types = resolvedTypes
end

-- One reusable effect per preset, made on first use and kept parented for the session.
--
-- These live with the interface, not in the Workspace the docs examples use. Workspace is
-- readable by the game's own scripts, so a pooled effect sitting there is the one piece of
-- Rayfield a game could find by walking the tree - everything else hides behind gethui with
-- a random name. An effect only needs *a* parent to play, not a world one.
local effects: { [Enum.HapticEffectType]: Instance } = {}
local container: Instance? = nil

-- Where new effects get parented. The window hands us its ScreenGui; until then (or after it
-- goes away) fall back to the container every Rayfield gui lives in.
function hapticEngine.setContainer(target: Instance?)
    container = target
end

-- Let go of a gui thats being torn down, without stamping on a container another window may
-- have set since. Passing nil clears whatever is held.
function hapticEngine.releaseContainer(target: Instance?)
    if target == nil or container == target then
        container = nil
    end
end

local function containerFor(): Instance
    if container and container.Parent then
        return container
    end
    return variables.guiContainer
end

local function effectFor(hapticType: Enum.HapticEffectType): Instance?
    local effect = effects[hapticType]
    -- recreate if it was never made, or got destroyed out from under us (Parent goes nil)
    if effect and effect.Parent then
        return effect
    end
    local ok, made = pcall(Instance.new, "HapticEffect")
    if not ok then
        return nil
    end
    local hapticEffect = made :: any
    hapticEffect.Type = hapticType
    local parented = pcall(function()
        made.Parent = containerFor()
    end)
    if not parented then
        made:Destroy()
        return nil
    end
    effects[hapticType] = made
    return made
end

local function play(hapticType: Enum.HapticEffectType?)
    if not hapticType or not hapticEngine.enabled then
        return
    end
    local effect = effectFor(hapticType)
    if effect then
        local hapticEffect = effect :: any
        pcall(hapticEffect.Play, effect)
    end
end

-- tap for a button, switch, tab or any discrete press
function hapticEngine.click()
    play(types.click)
end

-- attention buzz for a notification, toast or popup
function hapticEngine.notify()
    play(types.notify)
end

-- Global on/off for the settings toggle. Turning it off tears the pooled effects down so
-- nothing lingers behind; they're remade lazily if it's turned back on.
function hapticEngine.setEnabled(state: boolean?)
    hapticEngine.enabled = state and true or false
    if not hapticEngine.enabled then
        hapticEngine.teardown()
    end
end

-- Drop the pool without touching the enabled flag, so a window can clean up after itself
-- without deciding haptics for anyone else.
function hapticEngine.teardown()
    for hapticType, effect in effects do
        pcall(effect.Destroy, effect)
        effects[hapticType] = nil
    end
end

return hapticEngine
]=====]

sources["utility/acrylic"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Devlog 7 "frost the game behind the window": a Lighting.BlurEffect toggled on/off. Works
-- because post-processing effects in Lighting only ever touch the 3D viewport render - the 2D
-- GUI layer composites on top afterward untouched - so the game world blurs while the window
-- itself (and every other ScreenGui) stays perfectly crisp, reading as a frosted sheet of glass
-- sitting in front of a soft-focus world. BlurEffect over DepthOfFieldEffect (the technique
-- WindUI/Fluent use, see WindUI's src/utils/Acrylic) on purpose: DepthOfField's blur strength
-- varies with distance from the in-focus point, which is the wrong shape for "uniformly frost
-- everything" - BlurEffect's single Size property blurs the whole frame evenly regardless of
-- depth. Uses its own dedicated, uniquely-named effect instance rather than touching (or
-- disabling) any BlurEffect the game itself already has in Lighting, so this never fights with
-- or clobbers a host game's own visual effects.

local acrylic = {}

local effectName = "__RayfieldAcrylicBlur"
local blurInfo = TweenInfo.new(0.4, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)

local lighting = game:GetService("Lighting")
local tweenService = game:GetService("TweenService")

local effect: BlurEffect? = nil

local function ensure(): BlurEffect
    if effect and effect.Parent then
        return effect
    end
    local existing = lighting:FindFirstChild(effectName)
    if existing and existing:IsA("BlurEffect") then
        effect = existing
        return existing
    end
    local blur = Instance.new("BlurEffect")
    blur.Name = effectName
    blur.Size = 0
    blur.Parent = lighting
    effect = blur
    return blur
end

-- size: blur radius in Roblox's own BlurEffect.Size units (0-56ish is the sane range; defaults
-- to a moderate 18 - noticeably frosted without turning the background to mush).
function acrylic.setEnabled(enabled: boolean, size: number?)
    local blur = ensure()
    tweenService:Create(blur, blurInfo, { Size = if enabled then (size or 18) else 0 }):Play()
end

function acrylic.isEnabled(): boolean
    return effect ~= nil and effect.Size > 0
end

return acrylic
]=====]

sources["utility/assetResolver"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

local network = require(script.Parent.network)
local log = require(script.Parent.log)

export type AssetId = number | string
export type AssetDownloadUrl = string
export type CacheKey = AssetId
export type ResolvedAsset = AssetId
export type AssetRequestPayload = {
    Url: string,
    Method: string,
}
local assetResolver = {
    Enum = {
        AssetDownloadUrl = {
            RobloxDownloadUrl = "https://assetdelivery.roblox.com/v1/asset/?id=%d" :: AssetDownloadUrl,
            RoProxyDownloadUrl = "https://assetdelivery.roproxy.com/v1/asset?id=%d" :: AssetDownloadUrl,
        },
    },
}
assetResolver.__index = assetResolver
assetResolver.__type = "assetResolver"
type AssetResolverState = {
    contentCache: { [CacheKey]: string }?,
    contentCacheOrder: { CacheKey }?,
    contentDownloadUrl: AssetDownloadUrl,
}
export type AssetResolver = AssetResolverState & {
    resolve: (self: AssetResolver, value: unknown) -> ResolvedAsset?,
    getAssetContentFromUrl: (self: AssetResolver, url: string, cacheKey: CacheKey?, forced: boolean?) -> string?,
    getAssetContentFromId: (self: AssetResolver, id: AssetId, forced: boolean?) -> string?,
}
-- example asset ids:
--[[
rbxassetid://12187277209,
rbxassetid://12187293441
]]

-- bodies are whole pngs and ttfs, and every caller gates on isfile, so a cached body is only ever
-- re-read inside a retry loop. keep the last few for that and evict the oldest, rather than pinning
-- a session's worth of assets in memory for readers that never come back
local contentCacheLimit = 8

function assetResolver.new(useCache: boolean?, assetContentDownloadUrl: AssetDownloadUrl?): AssetResolver
    local contentCache: { [CacheKey]: string }? = if useCache then {} else nil
    local self = setmetatable(
        {
            contentCache = contentCache,
            contentCacheOrder = if useCache then {} :: { CacheKey } else nil,
            contentDownloadUrl = assetContentDownloadUrl or assetResolver.Enum.AssetDownloadUrl.RobloxDownloadUrl,
        } :: AssetResolverState,
        assetResolver
    ) :: any
    return self
end

function assetResolver.resolve(_self: AssetResolver, value: unknown): ResolvedAsset?
    if type(value) == "number" then
        return value
    end

    if type(value) ~= "string" then
        return nil
    end

    if string.sub(value, 1, 11) == "rbxasset://" or string.sub(value, 1, 11) == "rbxthumb://" then
        return value
    end

    local id = tonumber(string.match(value, "^rbxassetid://(%d+)$"))
    if id then
        return id
    end

    return nil
end

-- executors disagree on response shape, so trust the body only when whatever status
-- info the executor does give us says the request actually succeeded
local function isGoodResponse(response: unknown): boolean
    if type(response) ~= "table" then
        return false
    end
    local shaped = response :: { Body: unknown, StatusCode: unknown, Success: unknown }
    local body = shaped.Body
    if type(body) ~= "string" or #body == 0 then
        return false
    end
    if type(shaped.StatusCode) == "number" then
        local statusCode = shaped.StatusCode :: number
        return statusCode >= 200 and statusCode < 300
    end
    if type(shaped.Success) == "boolean" then
        return shaped.Success :: boolean
    end
    -- no status of any kind: a shape we dont know, so we cant say the body is the asset
    return false
end

function assetResolver.getAssetContentFromUrl(
    self: AssetResolver,
    url: string,
    cacheKey: CacheKey?,
    forced: boolean?
): string?
    -- forced skips the session cache, so retry loops see fresh responses
    local contentCache = self.contentCache
    if cacheKey ~= nil and contentCache and not forced then
        local cachedContent = contentCache[cacheKey]
        if cachedContent then
            return cachedContent
        end
    end

    local requestFn = network.getRequestFn()
    if not requestFn then
        log.warn("No request function available to download asset content.")
        return nil
    end

    local success, response = pcall(
        requestFn,
        {
            Url = url,
            Method = "GET",
        } :: AssetRequestPayload
    )
    local content: string? = nil
    if success and isGoodResponse(response) then
        local body = (response :: { Body: string }).Body
        content = body
        if cacheKey ~= nil and contentCache then
            local order = self.contentCacheOrder
            if order and contentCache[cacheKey] == nil then
                table.insert(order, cacheKey)
                local oldest = if #order > contentCacheLimit then table.remove(order, 1) else nil
                if oldest ~= nil then
                    contentCache[oldest] = nil
                end
            end
            contentCache[cacheKey] = body
        end
    elseif not forced then
        log.warn("Failed to download asset content for url: " .. tostring(url))
    end
    return content
end

function assetResolver.getAssetContentFromId(self: AssetResolver, id: AssetId, forced: boolean?): string?
    local resolvedId = self:resolve(id)
    -- we can only download content for valid asset ids
    if not resolvedId or type(resolvedId) ~= "number" then
        log.warn("Invalid asset id: " .. tostring(resolvedId))
        return nil
    end

    local downloadUrl = string.format(self.contentDownloadUrl, resolvedId)
    return self:getAssetContentFromUrl(downloadUrl, resolvedId, forced)
end

return assetResolver
]=====]

sources["utility/autoTranslate"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Live machine-translation engine backing locale.autoTranslate (see locale.luau's own use of
-- this). Tries Google Translate's public keyless endpoint first, then MyMemory's free API as a
-- second attempt (see tryGoogle/tryMyMemory below for why two) - no signup, no API key, works
-- the moment autoTranslate is turned on. Every result is cached forever, both in memory and on
-- disk (same Rayfield/ folder configs already live in), so a given string only ever actually
-- gets translated once per locale on a given client - every use after that (this session or a
-- later one) is a plain table read, no network involved.
--
-- Deliberately its own file rather than folded into locale.luau: locale.luau owns the
-- *resolution policy* (which source wins - dev hook, live cache, built-in table, raw text); this
-- is just one *source* it can ask, the same separation assetResolver/fontManager already keep
-- from the modules that call them.

local network = require(script.Parent.network)
local variables = require(script.Parent.variables)
local filesystem = require(script.Parent.filesystem)
local path = require(script.Parent.path)
local log = require(script.Parent.log)

local autoTranslate = {}

-- in-memory: { [locale] = { [source] = translated } }. Loaded from/flushed to disk lazily, one
-- file per locale, so a cold session only ever reads the locales it actually ends up using.
local memoryCache: { [string]: { [string]: string } } = {}
local loadedFromDisk: { [string]: boolean } = {}
-- in-flight requests, deduped by "locale|source" - a whole tab's worth of toggles built in the
-- same frame, all asking to translate their own name, fires exactly one request between them
-- instead of one each.
local pending: { [string]: boolean } = {}

local function cacheDir(): string
    return variables.fileSystemManager:getPath("Translations")
end

local function cacheFile(localeId: string): string
    return path.join(cacheDir(), path.sanitizeFile(localeId) .. ".json")
end

local function ensureLoaded(localeId: string)
    if loadedFromDisk[localeId] then
        return
    end
    loadedFromDisk[localeId] = true
    memoryCache[localeId] = memoryCache[localeId] or {}

    local file = cacheFile(localeId)
    if not filesystem.isfile(file) then
        return
    end
    local ok, contents = pcall(filesystem.readfile, file)
    if not ok or type(contents) ~= "string" then
        return
    end
    local decodeOk, parsed = pcall(variables.httpService.JSONDecode, variables.httpService, contents)
    if not decodeOk or type(parsed) ~= "table" then
        return
    end
    for source, translated in parsed :: { [string]: unknown } do
        if type(source) == "string" and type(translated) == "string" then
            memoryCache[localeId][source] = translated
        end
    end
end

local function persist(localeId: string)
    pcall(filesystem.ensureFolder, cacheDir())
    local ok, encoded = pcall(variables.httpService.JSONEncode, variables.httpService, memoryCache[localeId] or {})
    if ok and type(encoded) == "string" then
        pcall(filesystem.writefile, cacheFile(localeId), encoded)
    end
end

-- Returns a cached translation if one already exists (disk or memory) - never blocks, never
-- makes a request. This is what locale.resolve() checks first, every call.
function autoTranslate.peek(source: string, localeId: string): string?
    ensureLoaded(localeId)
    local forLocale = memoryCache[localeId]
    return forLocale and forLocale[source]
end

-- %s, %d, %-5.2f and friends need to survive the round trip untouched - swap each one for a
-- short numbered token before sending, put the real specifier back after. Google generally
-- leaves a bare %s alone, but this makes sure "%d itens" can't come back "% d itens" or
-- reordered somewhere a target language's own word order would otherwise move it.
local specifierPattern = "%%[%-%+ #0]*%d*%.?%d*[diouxXeEfgGqscp%%]"

local function protectSpecifiers(text: string): (string, { string })
    local tokens = {}
    local protectedText = text:gsub(specifierPattern, function(specifier)
        table.insert(tokens, specifier)
        return "{{" .. #tokens .. "}}"
    end)
    return protectedText, tokens
end

local function restoreSpecifiers(text: string, tokens: { string }): string
    for i, specifier in tokens do
        -- a translation can pick up stray spaces inside the braces ("{{ 1 }}") - tolerate that
        text = text:gsub("{{%s*" .. i .. "%s*}}", specifier)
    end
    return text
end

local function httpGet(url: string): string?
    local fn = network.getRequestFn()
    if fn then
        local ok, response = pcall(fn, { Url = url, Method = "GET" })
        if ok and type(response) == "table" then
            local body = (response :: any).Body
            local status = (response :: any).StatusCode
            if type(body) == "string" and #body > 0 and (type(status) ~= "number" or (status >= 200 and status < 300)) then
                return body
            end
        end
    end
    -- falls back to the plain client HTTP call - no advanced request table needed for a simple
    -- unauthenticated GET, and this exact call is what this whole project's own dev-reload
    -- workflow already relies on working.
    local ok2, body2 = pcall(function()
        return game:HttpGet(url)
    end)
    if ok2 and type(body2) == "string" and #body2 > 0 then
        return body2
    end
    return nil
end

-- Two providers, tried in order, both free and keyless. Google generally wins on quality and is
-- tried first, but its answer depends on the executor's outbound IP not already being flagged by
-- Google's own abuse detection - confirmed hitting exactly that live while building this (a clean
-- 429 "Sorry..." page, no account to appeal it with). MyMemory is the second attempt: a genuinely
-- documented free API, lower quality on long sentences (it leans on a translation-memory database
-- more than pure MT) but perfectly fine for short UI copy, and it's what actually answered during
-- that same test. Only once *both* fail does resolve() fall back to the built-in/registered table.
local function tryGoogle(protectedText: string, targetLang: string): string?
    local url = ("https://translate.googleapis.com/translate_a/single?client=gtx&sl=auto&tl=%s&dt=t&q=%s")
        :format(variables.httpService:UrlEncode(targetLang), variables.httpService:UrlEncode(protectedText))
    local body = httpGet(url)
    if not body then
        return nil
    end
    -- response shape: [[[translatedChunk, sourceChunk, ...], ...], ...] - a long sentence comes
    -- back split into several chunks that need stitching back together.
    local ok, decoded = pcall(variables.httpService.JSONDecode, variables.httpService, body)
    if not ok or type(decoded) ~= "table" or type(decoded[1]) ~= "table" then
        return nil
    end
    local parts = {}
    for _, chunk in decoded[1] :: { any } do
        if type(chunk) == "table" and type(chunk[1]) == "string" then
            table.insert(parts, chunk[1])
        end
    end
    if #parts == 0 then
        return nil
    end
    return table.concat(parts)
end

local function tryMyMemory(protectedText: string, targetLang: string): string?
    -- MyMemory wants an explicit source language rather than an auto-detect flag - every source
    -- string in this project is written in English (see locale.luau's own header comment: "English
    -- is canonical"), so that's a safe fixed value rather than something worth detecting.
    local url = ("https://api.mymemory.translated.net/get?q=%s&langpair=en|%s")
        :format(variables.httpService:UrlEncode(protectedText), variables.httpService:UrlEncode(targetLang))
    local body = httpGet(url)
    if not body then
        return nil
    end
    local ok, decoded = pcall(variables.httpService.JSONDecode, variables.httpService, body)
    if not ok or type(decoded) ~= "table" then
        return nil
    end
    local data = (decoded :: any).responseData
    if type(data) ~= "table" or type(data.translatedText) ~= "string" or data.translatedText == "" then
        return nil
    end
    return data.translatedText
end

-- Both providers accept a region-qualified code ("pt-BR") and it matters for quality, not just
-- pickiness - live-caught requesting the same word both ways: a bare "pt" came back "Secções"
-- (European Portuguese), "pt-BR" came back "Seções" (Brazilian) for the exact same input. Roblox
-- locale ids are already lowercase-hyphenated ("pt-br"); this just fixes the region's casing to
-- what the APIs expect. Falls back to the bare language when there's no region at all.
local function apiLangCode(localeId: string): string
    local lang, region = string.match(localeId, "^(%a+)-(%a+)$")
    if lang and region then
        return lang .. "-" .. string.upper(region)
    end
    return string.match(localeId, "^(%a+)") or localeId
end

-- Fires (or joins) a live translation request. Never yields the caller - the actual HTTP calls
-- run on their own thread; `onDone()` (if given) fires once a result lands in the cache,
-- success or not, so a caller can re-resolve whatever was showing the fallback text meanwhile.
function autoTranslate.request(source: string, localeId: string, onDone: (() -> ())?)
    ensureLoaded(localeId)
    if memoryCache[localeId] and memoryCache[localeId][source] then
        return -- already cached, nothing to do
    end
    local key = localeId .. "|" .. source
    if pending[key] then
        return -- already in flight - the call that started it will notify everyone once it lands
    end
    pending[key] = true

    task.spawn(function()
        local protectedText, tokens = protectSpecifiers(source)
        local targetLang = apiLangCode(localeId)

        local translated = tryGoogle(protectedText, targetLang)
        local usedFallbackProvider = false
        if not translated then
            translated = tryMyMemory(protectedText, targetLang)
            usedFallbackProvider = translated ~= nil
        end

        pending[key] = nil

        if translated and translated ~= "" then
            translated = restoreSpecifiers(translated, tokens)
            memoryCache[localeId] = memoryCache[localeId] or {}
            memoryCache[localeId][source] = translated
            persist(localeId)
            if usedFallbackProvider then
                log.print("Rayfield: auto-translate used the MyMemory fallback for '" .. localeId .. "' (Google unavailable).")
            end
            if onDone then
                onDone()
            end
        else
            log.warn(
                "Rayfield: auto-translate couldn't reach either provider for locale '"
                    .. localeId
                    .. "' - falling back to the built-in table/source text."
            )
        end
    end)
end

return autoTranslate
]=====]

sources["utility/builtinLocales"] = [=====[
--!strict

-- Copyright (c) 2026 Corridon Capital
-- This Source Code Form is subject to the terms of the Mozilla Public
-- License, v. 2.0. If a copy of the MPL was not distributed with this
-- file, You can obtain one at https://mozilla.org/MPL/2.0/.

-- Built-in translations for the library's own chrome - every source string wrapped in
-- locale.t() across src/, in English (the canonical source text and also its own lookup key -
-- see locale.luau). English itself has no table here; missing a locale entirely already falls
-- back to the source string unchanged, so an "en" table would just be a copy of every key onto
-- itself. Covers Portuguese and Spanish only, the two explicitly asked for alongside English -
-- a dev can layer more languages on top with their own Window:RegisterTranslations() call, or
-- override any entry here the same way (a registered table always wins over these).
--
-- Element/control *names* a dev supplies (a toggle's "name", a button's "name", and so on)
-- aren't covered here - those are dev content, not library chrome, and were never routed through
-- locale.t() to begin with. Deliberately out of scope for the same reason element values, slider
-- readouts and keybind keys already are (see locale.luau's own header comment): translating a
-- dev's own labels for them would be guessing at meaning the library doesn't have.

